@Composable
private fun SectionTitle(title: String) {
    Text(
        text = title,
        color = LevyraText,
        style = LevyraType.sectionTitle,
        maxLines = 1,
        overflow = TextOverflow.Ellipsis,
        modifier = Modifier.semantics { heading() }
    )
}

private val HomeSectionEdgeSymbols = Regex(
    "^[\\p{So}\\p{Sk}\\u200D\\uFE0E\\uFE0F\\s]+|[\\p{So}\\p{Sk}\\u200D\\uFE0E\\uFE0F\\s]+$"
)

private fun cleanHomeSectionTitle(title: String): String {
    val cleaned = title.replace(HomeSectionEdgeSymbols, "").trim()
    return cleaned.ifBlank { title.trim() }
}

@Composable
private fun HomeSectionHeader(
    title: String,
    subtitle: String? = null,
    onPlayAll: (() -> Unit)? = null,
    onShowAll: (() -> Unit)? = null,
    modifier: Modifier = Modifier
) {
    val displayTitle = remember(title) { cleanHomeSectionTitle(title) }
    LevyraSectionHeader(
        title = displayTitle,
        subtitle = subtitle,
        modifier = modifier
    ) {
        onShowAll?.let { action -> LevyraSectionShowAll(onClick = action) }
        onPlayAll?.let { action -> LevyraSectionPlayAll(onClick = action) }
    }
}

@Composable
private fun ChartMarketHeader(
    title: String,
    refreshing: Boolean,
    onChangeMarket: () -> Unit,
    onPlayAll: (() -> Unit)?
) {
    val strings = LocalLevyraStrings.current
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .heightIn(min = LevyraPlayerDesign.MinimumTouchTarget),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        Box(modifier = Modifier.weight(1f), contentAlignment = Alignment.CenterStart) {
            Row(
                modifier = Modifier
                    .heightIn(min = LevyraPlayerDesign.MinimumTouchTarget)
                    .levyraPressable(
                        onClick = onChangeMarket,
                        pressedScale = LevyraPressScale.Control,
                        role = Role.Button,
                        onClickLabel = strings.chartMarketChange
                    ),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp)
            ) {
                Text(
                    text = title,
                    color = LevyraText,
                    style = LevyraType.sectionTitle,
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis,
                    modifier = Modifier.weight(1f, fill = false)
                )
                Box(
                    modifier = Modifier
                        .size(26.dp)
                        .clip(CircleShape)
                        .background(LevyraAdaptiveChipSelected),
                    contentAlignment = Alignment.Center
                ) {
                    if (refreshing) {
                        CircularProgressIndicator(
                            modifier = Modifier.size(14.dp),
                            strokeWidth = 1.75.dp,
                            color = LevyraCyan
                        )
                    } else {
                        Icon(
                            Icons.Rounded.KeyboardArrowDown,
                            contentDescription = null,
                            tint = LevyraText,
                            modifier = Modifier.size(20.dp)
                        )
                    }
                }
            }
        }
        onPlayAll?.let { action ->
            LevyraSectionPlayAll(onClick = action)
        }
    }
}

@Composable
private fun HomeChip(
    label: String,
    selected: Boolean,
    onClick: () -> Unit,
    exposeSelectionState: Boolean = true
) {
    val background = when {
        selected && LevyraIsLight -> Color(0xFF11131F)
        selected -> Color.White
        LevyraIsLight -> Color(0x1411131F)
        else -> Color.White.copy(alpha = 0.10f)
    }
    val content = when {
        selected && LevyraIsLight -> Color.White
        selected -> Color(0xFF07080C)
        else -> LevyraText
    }
    Box(
        modifier = Modifier
            .height(LevyraHomeDesign.MoodChipHeight)
            .pressable(onClick = onClick)
            .then(
                if (exposeSelectionState) Modifier.semantics { this.selected = selected } else Modifier
            ),
        contentAlignment = Alignment.Center
    ) {
        Row(
            modifier = Modifier
                .height(LevyraHomeDesign.MoodChipVisualHeight)
                .background(background, LevyraHomeDesign.MoodChipShape)
                .padding(horizontal = 14.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(6.dp)
        ) {
            Text(
                text = label,
                color = content,
                fontSize = 14.sp,
                lineHeight = LevyraTypeRhythm.lineHeight(14.sp),
                fontWeight = FontWeight.Medium,
                maxLines = 1
            )
        }
    }
}

private val LevyraWideArtworkAlignment = BiasAlignment(0f, -0.35f)

@Composable
internal fun CoverImage(
    track: Track,
    modifier: Modifier,
    highRes: Boolean = false,
    zoom: Float = 1f,
    alignment: Alignment = Alignment.Center,
    onImageLoaded: ((CoilImage) -> Unit)? = null
) {
    val context = LocalContext.current
    val models = remember(
        context,
        track.id,
        track.title,
        track.artist,
        track.videoUrl,
        track.thumbnailUrl,
        track.largeThumbnailUrl,
        highRes
    ) {
        LevyraArtworkCache.models(context, track, highRes)
    }
    var modelIndex by remember(models) { mutableStateOf(0) }
    val model = models.getOrNull(modelIndex)
    val crossfadeMs = if (LocalAnimationsEnabled.current && highRes && model !is File) 120 else 0
    var artworkLoaded by remember(track.id, highRes, model) { mutableStateOf(false) }
    var artworkSucceeded by remember(track.id, highRes, model) { mutableStateOf(false) }
    LaunchedEffect(artworkSucceeded, crossfadeMs) {
        if (artworkSucceeded) {
            if (crossfadeMs > 0) delay(crossfadeMs.toLong())
            artworkLoaded = true
        }
    }
    val artworkKey = remember(track.id, highRes) { "${track.id}:${if (highRes) "large" else "small"}" }
    val modelIdentity = remember(model) {
        when (model) {
            is File -> "file:${model.absolutePath}"
            null -> "missing"
            else -> "remote:${model}"
        }
    }
    val requestSource = remember(model) {
        when (model) {
            is File -> ArtworkRequestSource.PersistentFile
            null -> ArtworkRequestSource.Missing
            else -> ArtworkRequestSource.Remote
        }
    }
    if (BuildConfig.DEBUG) {
        LaunchedEffect(artworkKey, modelIdentity, requestSource) {
            LevyraArtworkStartupMetrics.recordArtworkRequest(artworkKey, modelIdentity, requestSource)
            if (model == null) LevyraArtworkStartupMetrics.recordArtworkLoading(artworkKey)
        }
    }
    val background = remember(track.accentStart, track.accentEnd) {
        Brush.linearGradient(listOf(Color(track.accentStart), Color(track.accentEnd)))
    }
    Box(modifier = modifier, contentAlignment = Alignment.Center) {
        if (!artworkLoaded) {
            InstantArtworkPlaceholder(
                track = track,
                modifier = Modifier.fillMaxSize().background(background)
            )
        }
        if (model != null) {
            val request = remember(context, model, crossfadeMs) {
                ImageRequest.Builder(context)
                    .data(model)
                    .memoryCachePolicy(CachePolicy.ENABLED)
                    .diskCachePolicy(CachePolicy.ENABLED)
                    .networkCachePolicy(CachePolicy.ENABLED)
                    .crossfade(crossfadeMs)
                    .build()
            }
            AsyncImage(
                model = request,
                contentDescription = track.title,
                contentScale = ContentScale.Crop,
                alignment = alignment,
                onLoading = { LevyraArtworkStartupMetrics.recordArtworkLoading(artworkKey) },
                onSuccess = { state ->
                    artworkSucceeded = true
                    LevyraArtworkStartupMetrics.recordArtworkDisplayed(artworkKey)
                    onImageLoaded?.invoke(state.result.image)
                },
                onError = {
                    LevyraArtworkStartupMetrics.recordArtworkFailure(artworkKey)
                    if (modelIndex < models.lastIndex) modelIndex += 1
                },
                modifier = Modifier.fillMaxSize().scale(zoom)
            )
        }
    }
}

@Composable
internal fun InstantArtworkPlaceholder(track: Track, modifier: Modifier) {
    val initials = remember(track.title, track.artist) {
        listOf(track.title, track.artist)
            .mapNotNull { value -> value.trim().firstOrNull()?.uppercaseChar()?.toString() }
            .take(2)
            .joinToString("")
            .ifBlank { "♪" }
    }
    Box(
        modifier = modifier
            .background(
                Brush.radialGradient(
                    listOf(
                        Color.White.copy(alpha = 0.22f),
                        Color(track.accentStart).copy(alpha = 0.46f),
                        Color(track.accentEnd).copy(alpha = 0.64f)
                    )
                )
            ),
        contentAlignment = Alignment.Center
    ) {
        Text(
            text = initials,
            color = LevyraText.copy(alpha = 0.88f),
            fontSize = 24.sp,
            fontWeight = FontWeight.Black,
            maxLines = 1,
            overflow = TextOverflow.Clip
        )
    }
}
