@Composable
private fun HomeTrackRow(
    track: Track,
    isCurrent: Boolean,
    isPlaying: Boolean,
    isResolving: Boolean,
    onPlay: () -> Unit,
    modifier: Modifier = Modifier,
    leadingContent: (@Composable () -> Unit)? = null,
    trailingContent: (@Composable () -> Unit)? = null,
    onActions: (() -> Unit)? = null
) {
    Row(
        modifier = modifier
            .fillMaxWidth()
            .height(LevyraHomeDesign.TrackRowHeight)
            .clip(LevyraCardDesign.ThumbShape)
            .pressable(onClick = onPlay)
            .padding(horizontal = 4.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        leadingContent?.invoke()
        Box(
            modifier = Modifier
                .size(LevyraHomeDesign.TrackThumbSize)
                .clip(LevyraHomeDesign.ThumbShape)
                .background(LevyraPanel),
            contentAlignment = Alignment.Center
        ) {
            CoverImage(
                track = track,
                modifier = Modifier.fillMaxSize(),
                highRes = false
            )
            if (isCurrent) {
                HomeNowPlayingScrim(
                    isPlaying = isPlaying,
                    isResolving = isResolving
                )
            }
        }
        LevyraRowText(
            title = track.title,
            subtitle = track.artist,
            titleColor = if (isCurrent) LevyraCyan else LevyraText,
            modifier = Modifier
                .weight(1f)
                .padding(start = 12.dp, end = 8.dp)
        )
        when {
            trailingContent != null -> trailingContent()
            onActions != null -> {
                IconButton(
                    onClick = onActions,
                    modifier = Modifier.size(36.dp)
                ) {
                    Icon(
                        imageVector = Icons.Rounded.MoreVert,
                        contentDescription = "${LocalLevyraStrings.current.songOptions}, ${track.title}",
                        tint = LevyraMuted,
                        modifier = Modifier.size(20.dp)
                    )
                }
            }
        }
    }
}

