@Composable
internal fun Modifier.pressable(
    enabled: Boolean = true,
    interactionSource: MutableInteractionSource? = null,
    pressedScale: Float = LevyraPressScale.Control,
    onLongClickLabel: String? = null,
    onLongClick: (() -> Unit)? = null,
    haptic: LevyraHapticAction? = null,
    onClick: () -> Unit
): Modifier = levyraPressable(
    onClick = onClick,
    enabled = enabled,
    pressedScale = pressedScale,
    interactionSource = interactionSource,
    onLongClickLabel = onLongClickLabel,
    onLongClick = onLongClick,
    haptic = haptic
)

private fun Modifier.blockTouchesBehind(): Modifier = pointerInput(Unit) {
    awaitPointerEventScope {
        while (true) awaitPointerEvent()
    }
}

private fun Modifier.consumeOverlayTouches(): Modifier = pointerInput(Unit) {
    awaitPointerEventScope {
        while (true) {
            val event = awaitPointerEvent(PointerEventPass.Final)
            event.changes.forEach { change ->
                if (!change.isConsumed) change.consume()
            }
        }
    }
}

@Composable
fun LevyraApp(
    viewModel: LevyraViewModel,
    onExitApplication: () -> Unit = {},
    isInPictureInPicture: Boolean = false,
    onRetryPreUpdateBackup: () -> Unit = {},
    onContinueUpdateWithoutBackup: () -> Unit = {}
) {
    val youtubeMusicViewModel = androidx.lifecycle.viewmodel.compose.viewModel<com.luc4n3x.levyra.viewmodel.youtubemusic.YoutubeMusicAccountViewModel>()
    val screenViewModelFactory = remember(viewModel, youtubeMusicViewModel) {
        LevyraScreenViewModelFactory(viewModel, youtubeMusicViewModel.homeSource)
    }
    val youtubeMusicState by youtubeMusicViewModel.state.collectAsStateWithLifecycle()
    var showYoutubeMusic by rememberSaveable { mutableStateOf(false) }

    val state by viewModel.state.collectAsStateWithLifecycle()
    val musicRegionId by viewModel.musicRegionId.collectAsStateWithLifecycle()
    val homeComposition by viewModel.homeComposition.collectAsStateWithLifecycle()
    val preferredAudioLanguage by viewModel.preferredAudioLanguage.collectAsStateWithLifecycle()
    val miniPlayerStudio by viewModel.miniPlayerStudio.collectAsStateWithLifecycle()
    val customThemes by viewModel.customThemes.collectAsStateWithLifecycle()
    val navigationStudio by viewModel.navigationStudio.collectAsStateWithLifecycle()
    LevyraKeepScreenOnEffect(viewModel.state)
    com.luc4n3x.levyra.ui.smartmusic.AdaptiveListeningAutostart(state.audioSettings)
    LaunchedEffect(youtubeMusicState.active?.id, state.languageCode) {
        youtubeMusicViewModel.loadHome(state.languageCode)
    }
    LaunchedEffect(state.isDeviceOffline) {
        if (!state.isDeviceOffline) youtubeMusicViewModel.onNetworkRestored(state.languageCode)
    }
    val currentStrings = LevyraStrings.forCode(state.languageCode)
    val layoutDirection = if (LevyraLanguageCatalog.isRtl(currentStrings.code)) LayoutDirection.Rtl else LayoutDirection.Ltr
    LaunchedEffect(state.isVideoMode, state.isPlaying) {
        val currentPipState = LevyraPipBridge.current()
        LevyraPipBridge.updatePlayback(
            videoMode = state.isVideoMode,
            playing = state.isPlaying,
            aspectRatio = currentPipState.aspectRatio
        )
    }
    if (isInPictureInPicture) {
        LevyraPictureInPictureSurface(state)
        return
    }
    val toastContext = LocalContext.current
    val downloadLocationScope = rememberCoroutineScope()
    LaunchedEffect(viewModel) {
        viewModel.integrationAuthorizationUrls.collect { url ->
            openExternalUrl(toastContext, url, currentStrings)
        }
    }
    val activity = toastContext as? Activity
    var showLanguageRestartDialog by remember { mutableStateOf(false) }
    var showPlaybackDiagnostics by remember { mutableStateOf(false) }
    var showDownloadsFolder by remember { mutableStateOf(false) }
    var musicExperience by rememberSaveable { mutableStateOf<String?>(null) }
    var liveRadioOpen by rememberSaveable { mutableStateOf(false) }
    var discoveryOpen by rememberSaveable { mutableStateOf(false) }
    var trackActionTarget by remember { mutableStateOf<Track?>(null) }
    var queueRemovalTarget by remember { mutableStateOf<QueueRemovalTarget?>(null) }
    var trackActionPlaylistTarget by remember { mutableStateOf<Track?>(null) }
    val profilePhotoLauncher = rememberLauncherForActivityResult(ActivityResultContracts.PickVisualMedia()) { uri ->
        uri?.let(viewModel::setProfilePhoto)
    }
    val createBackupLauncher = rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/zip")) { uri ->
        uri?.let(viewModel::createBackup)
    }
    val restoreBackupLauncher = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()) { uri ->
        uri?.let(viewModel::previewRestore)
    }
    val restoreMediaPermissionLauncher = rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()) { granted ->
        if (granted) viewModel.confirmRestore()
    }
    val manageBackupsLauncher = rememberLauncherForActivityResult(ActivityResultContracts.StartActivityForResult()) { result ->
        if (result.resultCode == Activity.RESULT_OK) {
            result.data?.data?.let(viewModel::previewRestore)
        }
    }
    val openManageBackups = {
        val initialUri = state.backupLocationUri
            ?.let { raw -> try { Uri.parse(raw) } catch (_: Throwable) { null } }
            ?: DocumentsContract.buildRootUri(
                "${toastContext.packageName}.automatic-backups",
                "levyra-automatic-backups"
            )
        manageBackupsLauncher.launch(
            Intent(Intent.ACTION_OPEN_DOCUMENT)
                .addCategory(Intent.CATEGORY_OPENABLE)
                .setType("application/zip")
                .putExtra(DocumentsContract.EXTRA_INITIAL_URI, initialUri)
        )
    }
    val backupLocationLauncher = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocumentTree()) { uri ->
        uri?.let(viewModel::setBackupLocation)
    }
    val downloadLocationLauncher = rememberLauncherForActivityResult(ActivityResultContracts.OpenDocumentTree()) { uri ->
        if (uri != null) {
            downloadLocationScope.launch {
                val persisted = withContext(Dispatchers.IO) {
                    DownloadFolderAccess.persist(toastContext, uri)
                }
                if (persisted) {
                    viewModel.setDownloadSettings(
                        viewModel.state.value.downloadSettings.copy(destinationTreeUri = uri.toString())
                    )
                } else {
                    Toast.makeText(
                        toastContext,
                        currentStrings.downloadLocationPermissionFailed,
                        Toast.LENGTH_LONG
                    ).show()
                }
            }
        }
    }
    val accent = if (state.dynamicColor) state.currentTrack ?: state.tracks.firstOrNull() else null
    val overlayEnter = LevyraMotion.overlayEnter(state.animationsEnabled)
    val overlayExit = LevyraMotion.overlayExit(state.animationsEnabled)
    val panelEnter = LevyraMotion.panelEnter(state.animationsEnabled)
    val panelExit = LevyraMotion.panelExit(state.animationsEnabled)
    val pageEnter = LevyraMotion.pageEnter(state.animationsEnabled)
    val pageExit = LevyraMotion.pageExit(state.animationsEnabled)
    val detailUnderPlayer = state.selectedTab == LevyraTab.Player
    val detailEnter = if (detailUnderPlayer) EnterTransition.None else pageEnter
    val miniEnter = if (state.animationsEnabled) {
        slideInVertically(animationSpec = tween(260, easing = FastOutSlowInEasing), initialOffsetY = { it / 2 }) + fadeIn(animationSpec = tween(180, easing = LinearOutSlowInEasing))
    } else {
        EnterTransition.None
    }
    val miniExit = if (state.animationsEnabled) {
        slideOutVertically(animationSpec = tween(180, easing = FastOutSlowInEasing), targetOffsetY = { it / 3 }) + fadeOut(animationSpec = tween(140, easing = FastOutSlowInEasing))
    } else {
        ExitTransition.None
    }
    val visualCapabilities = rememberLevyraVisualCapabilities(
        selected = state.interfaceSettings.visualPerformance,
        animationsEnabled = state.animationsEnabled
    )
    val accentTrack = state.currentTrack ?: state.tracks.firstOrNull()
    when (state.interfaceSettings.skin) {
        LevyraSkin.Prism -> PrismThemeEffect(state.interfaceSettings)
        LevyraSkin.Torque -> TorqueThemeEffect(state.interfaceSettings, state.currentTrack)
        LevyraSkin.Ivory -> IvoryThemeEffect(state.interfaceSettings)
        LevyraSkin.AppleMusicStyle -> AppleMusicThemeEffect()
        LevyraSkin.YouTubeMusicStyle -> YouTubeMusicThemeEffect()
        LevyraSkin.QobuzStyle -> QobuzThemeEffect()
        LevyraSkin.Atelier -> AtelierThemeEffect(state.currentTrack)
        else -> Unit
    }
    val pureBlack = state.interfaceSettings.pureBlack
    LaunchedEffect(
        state.themePreset,
        state.themeAccent,
        state.interfaceSettings.skin,
        accentTrack?.accentStart,
        accentTrack?.accentEnd,
        state.selectedMood?.id,
        pureBlack,
        customThemes
    ) {
        if (state.interfaceSettings.skin == LevyraSkin.Prism || state.interfaceSettings.skin == LevyraSkin.Torque || state.interfaceSettings.skin == LevyraSkin.Ivory || state.interfaceSettings.skin == LevyraSkin.AppleMusicStyle || state.interfaceSettings.skin == LevyraSkin.YouTubeMusicStyle || state.interfaceSettings.skin == LevyraSkin.QobuzStyle || state.interfaceSettings.skin == LevyraSkin.Atelier) return@LaunchedEffect
        LevyraThemeController.apply(
            state.themePreset,
            accentTrack?.accentStart,
            accentTrack?.accentEnd,
            state.selectedMood?.accentStart,
            state.selectedMood?.accentEnd,
            pureBlack,
            state.themeAccent.takeIf { it != 0 },
            state.interfaceSettings.skin
        )
    }
    val rootView = LocalView.current
    LaunchedEffect(state.themePreset, pureBlack, customThemes, state.interfaceSettings.skin, LevyraActivePalette.isLight) {
        val nocturne = state.interfaceSettings.skin == LevyraSkin.Nocturne78
        val base = when (state.interfaceSettings.skin) {
            LevyraSkin.Nocturne78 -> Nocturne78Palette
            LevyraSkin.Prism, LevyraSkin.Torque, LevyraSkin.Ivory, LevyraSkin.AppleMusicStyle, LevyraSkin.YouTubeMusicStyle, LevyraSkin.QobuzStyle, LevyraSkin.Atelier -> LevyraActivePalette
            LevyraSkin.SpotifyStyle -> spotifyPalette()
            LevyraSkin.Default -> LevyraThemes.byId(state.themePreset)
        }
        val palette = if (pureBlack && state.interfaceSettings.skin == LevyraSkin.Default) LevyraThemeController.asPureBlack(base) else base
        (rootView.context as? Activity)?.window?.let { window ->
            window.decorView.setBackgroundColor(palette.black.toArgb())
            WindowCompat.getInsetsController(window, rootView).apply {
                isAppearanceLightStatusBars = palette.isLight
                isAppearanceLightNavigationBars = palette.isLight
            }
        }
    }
    val pendingShortcut by LevyraLaunchActions.pendingShortcut
    LaunchedEffect(pendingShortcut) {
        when (pendingShortcut) {
            LevyraLaunchActions.SHORTCUT_FAVORITES -> viewModel.selectTab(LevyraTab.Library)
            LevyraLaunchActions.SHORTCUT_OFFLINE -> viewModel.selectTab(LevyraTab.Library)
            LevyraLaunchActions.SHORTCUT_SEARCH -> viewModel.selectTab(LevyraTab.Search)
            LevyraLaunchActions.SHORTCUT_LIBRARY -> viewModel.selectTab(LevyraTab.Library)
            LevyraLaunchActions.SHORTCUT_FLOW -> viewModel.playDailyFlow()
            LevyraLaunchActions.SHORTCUT_LYRICS -> {
                viewModel.selectTab(LevyraTab.Player)
                viewModel.openLyrics()
            }
            LevyraLaunchActions.SHORTCUT_RECOGNITION -> {
                viewModel.selectTab(LevyraTab.Search)
                viewModel.startMusicRecognition()
            }
            LevyraLaunchActions.SHORTCUT_AMBIENT -> viewModel.openAmbient()
            LevyraLaunchActions.SHORTCUT_RESUME -> viewModel.resumePlaybackFromShortcut()
            LevyraLaunchActions.SHORTCUT_PLAYER -> viewModel.selectTab(LevyraTab.Player)
            LevyraLaunchActions.SHORTCUT_QUEUE -> {
                viewModel.selectTab(LevyraTab.Player)
                viewModel.openQueue()
            }
        }
        if (pendingShortcut != null) LevyraLaunchActions.pendingShortcut.value = null
