            else if (youtubeMusicState.detail != null) youtubeMusicViewModel.closeDetail()
            else showYoutubeMusic = false
        } else if (showLanguageRestartDialog) {
            showLanguageRestartDialog = false
        } else if (state.showRecognition) {
            viewModel.closeRecognition()
        } else if (state.showThemeStudio) {
            viewModel.closeThemeStudio()
        } else if (state.showLyricsStudio) {
            viewModel.closeLyricsStudio()
        } else if (state.showHomeStudio) {
            viewModel.closeHomeStudio()
        } else if (miniPlayerStudio.visible) {
            viewModel.closeMiniPlayerStudio()
        } else if (navigationStudio.visible) {
            viewModel.closeNavigationStudio()
        } else if (state.showJam) {
            viewModel.closeJam()
        } else if (state.showListeningInsights) {
            viewModel.closeListeningInsights()
        } else if (state.showListeningRecap) {
            viewModel.closeListeningRecap()
        } else if (state.showYourSound) {
            viewModel.closeYourSound()
        } else if (state.sharedMediaPreview != null) {
            viewModel.dismissSharedMedia()
        } else if (showDownloadsFolder) {
            showDownloadsFolder = false
        } else if (state.showAudioQualityPanel) {
            viewModel.closeAudioQualityPanel()
        } else if (state.playlistHitPreview != null) {
            viewModel.closePlaylistHit()
        } else if (state.openPlaylist != null) {
            viewModel.closePlaylist()
        } else if (!viewModel.navigateBack()) {
            activity?.finish()
        }
    }
    val navArtworkSeed = rememberNavArtworkSeed(
        track = state.currentTrack,
        enabled = navigationStudio.visible ||
            navigationStudio.settings.activeTuning().colorSource == NavColorSource.Artwork
