            AnimatedVisibility(
                visible = state.showAmbient,
                modifier = Modifier.zIndex(50f),
                enter = fadeIn(tween(320)),
                exit = fadeOut(tween(240))
            ) {
                LevyraAmbientOverlay(state = state, viewModel = viewModel)
            }

            AnimatedVisibility(visible = showDownloadsFolder, enter = overlayEnter, exit = overlayExit) {
                DownloadsFolderOverlay(state = state, viewModel = viewModel, onClose = { showDownloadsFolder = false })
            }

            AnimatedVisibility(visible = state.showRecognition, enter = overlayEnter, exit = overlayExit) {
                LevyraRecognitionOverlay(
                    state = state.recognitionState,
                    history = state.recognitionHistory,
                    match = state.recognitionMatch,
                    matching = state.recognitionMatching,
                    deviceCaptureSupported = state.recognitionDeviceCaptureSupported,
                    onListenMicrophone = viewModel::startMusicRecognition,
                    onListenDevice = viewModel::startDeviceRecognition,
                    onCancel = viewModel::cancelMusicRecognition,
                    onPlayMatch = viewModel::playRecognitionMatch,
                    onSearchResult = viewModel::searchRecognitionResult,
                    onTrackActions = { track ->
                        queueRemovalTarget = null
                        trackActionTarget = track
                    },
                    onOpenHistoryEntry = viewModel::openRecognitionResult,
                    onDeleteHistoryEntry = viewModel::deleteRecognitionEntry,
                    onClearHistory = viewModel::clearRecognitionHistory,
                    onClose = viewModel::closeRecognition
                )
            }

            AnimatedVisibility(visible = state.showJam, enter = overlayEnter, exit = overlayExit) {
                LevyraJamOverlay(
                    jam = state.jam,
                    displayName = state.jamDisplayName,
                    onDisplayNameChange = viewModel::setJamDisplayName,
                    onCreate = viewModel::createJam,
                    onJoin = viewModel::joinJam,
                    onLeave = viewModel::leaveJam,
                    onEnd = viewModel::endJam,
                    onPermissionChange = viewModel::setJamPermission,
                    onApprovalRequiredChange = viewModel::setJamApprovalRequired,
                    onLockedChange = viewModel::setJamSessionLocked,
                    onApproveParticipant = viewModel::approveJamParticipant,
                    onRejectParticipant = viewModel::rejectJamParticipant,
                    onRemoveParticipant = { participantId, ban ->
                        viewModel.removeJamParticipant(participantId, ban)
                    },
                    onClearBans = viewModel::clearJamBans,
                    onShare = { payload -> shareJamInvite(toastContext, payload, currentStrings) },
                    onDismissFailure = viewModel::clearJamFailure,
                    onClose = viewModel::closeJam
                )
            }

            AnimatedVisibility(visible = state.showThemeStudio, enter = overlayEnter, exit = overlayExit) {
                LevyraThemeStudioOverlay(
                    selectedPresetId = state.themePreset,
                    accent = state.themeAccent,
                    pureBlack = state.interfaceSettings.pureBlack,
                    previewTitle = state.currentTrack?.title.orEmpty(),
                    previewArtist = state.currentTrack?.artist.orEmpty(),
                    onSelectPreset = viewModel::setThemePreset,
                    onSelectAccent = viewModel::setThemeAccent,
                    onClose = viewModel::closeThemeStudio,
                    customThemes = customThemes,
                    onSaveCustomTheme = viewModel::saveCustomTheme,
                    onDuplicateCustomTheme = viewModel::duplicateCustomTheme,
                    onDeleteCustomTheme = viewModel::deleteCustomTheme,
                    onRestoreDefault = viewModel::restoreDefaultTheme,
                    glassEnabled = state.interfaceSettings.liquidGlassEnabled,
                    glassStyle = LevyraGlassStyle(
                        blur = state.interfaceSettings.glassBlur,
                        transparency = state.interfaceSettings.glassTransparency,
                        tint = state.interfaceSettings.glassTint,
                        refraction = state.interfaceSettings.glassRefraction
                    ),
                    onGlassStyleChange = { glass ->
                        viewModel.setInterfaceSettings(
                            state.interfaceSettings.copy(
                                glassBlur = glass.blur,
                                glassTransparency = glass.transparency,
                                glassTint = glass.tint,
                                glassRefraction = glass.refraction
                            )
                        )
                    }
                )
            }

            AnimatedVisibility(visible = state.showLyricsStudio, enter = overlayEnter, exit = overlayExit) {
                LyricsStudioOverlay(
                    settings = state.lyricsStudioSettings,
                    currentTrack = state.currentTrack,
                    liveLyrics = state.lyrics,
                    lyricsSynced = state.lyricsSynced,
                    positionMs = state.positionMs,
                    isPlaying = state.isPlaying,
                    onUpdateSettings = viewModel::setLyricsStudioSettings,
                    onResetSettings = viewModel::resetLyricsStudioSettings,
                    onClose = viewModel::closeLyricsStudio
                )
            }

            AnimatedVisibility(visible = state.showHomeStudio, enter = overlayEnter, exit = overlayExit) {
                HomeStudioOverlay(
                    settings = state.homeStudioSettings,
                    composition = homeComposition,
                    onComposition = viewModel::setHomeCompositionSettings,
                    interfaceSettings = state.interfaceSettings,
                    onUpdate = viewModel::setHomeStudioSettings,
                    onInterfaceSettings = viewModel::setInterfaceSettings,
                    onClose = viewModel::closeHomeStudio
                )
            }

            AnimatedVisibility(visible = miniPlayerStudio.visible, enter = overlayEnter, exit = overlayExit) {
                MiniPlayerStudioOverlay(
                    settings = miniPlayerStudio.settings,
                    track = state.currentTrack,
                    isPlaying = state.isPlaying,
                    progress = progressOf(state.positionMs, state.durationMs),
                    animated = state.animationsEnabled,
                    onUpdate = viewModel::setMiniPlayerStudioSettings,
                    onClose = viewModel::closeMiniPlayerStudio,
                    scrollEffect = state.interfaceSettings.dockScrollEffect,
                    onScrollEffect = { viewModel.setInterfaceSettings(state.interfaceSettings.copy(dockScrollEffect = it)) }
                )
            }

            AnimatedVisibility(visible = navigationStudio.visible, enter = overlayEnter, exit = overlayExit) {
                NavigationStudioOverlay(
                    settings = navigationStudio.settings,
                    onUpdate = viewModel::setNavigationStudioSettings,
                    onClose = viewModel::closeNavigationStudio
                )
            }

            AnimatedVisibility(visible = state.showYourSound, enter = overlayEnter, exit = overlayExit) {
                LevyraYourSoundOverlay(
                    dna = state.listeningDna,
                    period = state.listeningDnaPeriod,
                    loading = state.listeningDnaLoading,
                    accent = yourSoundAccent,
                    onSelectPeriod = viewModel::selectListeningDnaPeriod,
                    onStartArtistMix = { artist ->
                        viewModel.closeYourSound()
                        viewModel.startLevyraMix(
                            kind = LevyraMixKind.SimilarArtist,
                            seedQuery = artist.name,
                            label = artist.name
                        )
                    },
                    onDiscoverArtist = { artist ->
                        viewModel.closeYourSound()
                        viewModel.openArtistByName(artist.name)
                    },
                    onPlayTrack = viewModel::playListeningDnaTrack,
                    onClose = viewModel::closeYourSound
                )
            }

            AnimatedVisibility(visible = state.showListeningRecap, enter = overlayEnter, exit = overlayExit) {
                LevyraListeningRecapOverlay(
                    recap = state.listeningRecap,
                    period = state.listeningRecapPeriod,
                    loading = state.listeningRecapLoading,
                    onSelectPeriod = viewModel::selectListeningRecapPeriod,
                    onPlayTrack = viewModel::playListeningRecapTrack,
                    onOpenArtist = { artistName ->
                        viewModel.closeListeningRecap()
                        viewModel.openArtistByName(artistName)
                    },
                    onClose = viewModel::closeListeningRecap
                )
            }

            AnimatedVisibility(visible = state.showListeningInsights, enter = overlayEnter, exit = overlayExit) {
                ListeningInsightsScreen(
                    accent = yourSoundAccent,
                    onPlayTrack = viewModel::playListeningInsightsTrack,
                    onOpenArtist = { artist ->
                        viewModel.closeListeningInsights()
                        viewModel.openArtistByName(artist.name)
                    },
                    onOpenRecap = {
                        viewModel.closeListeningInsights()
                        viewModel.openListeningRecap()
                    },
                    onClose = viewModel::closeListeningInsights
                )
            }

            if (showPlaybackDiagnostics) {
                PlaybackDiagnosticsDialog(
                    capture = viewModel::capturePlaybackDiagnostics,
                    onDismiss = { showPlaybackDiagnostics = false }
                )
            }

            if (musicExperience == "rewind") {
                RewindScreen(onClose = { musicExperience = null })
            } else if (musicExperience == "health") {
                DownloadHealthScreen(onClose = { musicExperience = null }, onSettings = {
                    musicExperience = null
                    showDownloadsFolder = false
                    viewModel.openSettings()
                })
            }

            if (showLanguageRestartDialog) {
                LanguageRestartDialog(
                    onRestart = {
                        showLanguageRestartDialog = false
                        restartLevyra(activity)
                    },
                    onLater = { showLanguageRestartDialog = false }
                )
            }

            if (state.pendingQueueAddTracks.isNotEmpty()) {
                QueueSpaceDestinationDialog(
                    spaces = state.queueSpaces,
                    activeSpaceId = state.activeQueueSpaceId,
                    onDismiss = viewModel::dismissQueueDestinationPicker,
                    onSelect = viewModel::addPendingTrackToQueueSpace
                )
            }

            trackActionTarget?.let { target ->
                val download = remember(state.downloads, target.id) {
                    state.downloads.firstOrNull { it.trackId == target.id }
                }
                LevyraTrackActionSheet(
                    track = target,
                    isFavorite = target.id in state.favoriteIds,
                    isDownloaded = download != null,
                    isDownloading = target.id in state.downloadingTrackIds,
                    canRemoveFromHistory = remember(state.recentSearches, target.id) {
                        val identity = LevyraPersonalOrbit.identityKey(target)
                        state.recentSearches.any {
                            it.id == target.id || LevyraPersonalOrbit.identityKey(it) == identity
                        }
                    },
                    animationsEnabled = state.animationsEnabled,
                    feedbackKind = state.recommendationFeedback.kindFor(target),
                    canExcludeArtist = isExcludableArtist(target.artistBrowseIds.firstOrNull().orEmpty(), target.artist),
                    isArtistExcluded = state.artistExclusions.excludesTrack(target),
                    onDismiss = {
                        trackActionTarget = null
                        queueRemovalTarget = null
                    },
                    onPlayNext = { viewModel.playNext(target) },
                    onAddToQueue = {
                        viewModel.addTracksToQueueSpace(state.activeQueueSpaceId, listOf(target))
                    },
                    queueSpaces = state.queueSpaces,
                    activeQueueSpaceId = state.activeQueueSpaceId,
                    onAddToQueueSpace = { spaceId -> viewModel.addTracksToQueueSpace(spaceId, listOf(target)) },
                    onAddToPlaylist = { trackActionPlaylistTarget = target },
                    onRemoveFromQueue = queueRemovalTarget?.takeIf { it.removable }?.let { removal ->
                        {
                            viewModel.removeFromQueue(
                                removal.track,
                                removal.spaceId
                            )
                        }
                    },
                    onToggleFavorite = { viewModel.toggleFavorite(target) },
                    onDownload = { viewModel.exportTrack(target) },
                    onDeleteDownload = { download?.let(viewModel::deleteDownload) },
                    onKeepOffline = download?.takeIf { it.ownership == DownloadOwnership.SMART_OFFLINE }?.let {
                        { viewModel.exportTrack(target) }
                    },
                    onOpenAlbum = { viewModel.openAlbum(trackAlbumHit(target)) },
                    onOpenArtist = { viewModel.openArtist(target) },
                    onRemoveFromHistory = { viewModel.removeRecentSearch(target) },
                    onMoreLikeThis = {
                        viewModel.setTrackFeedback(target, RecommendationFeedbackKind.MORE_LIKE_THIS)
                    },
                    onLessLikeThis = {
                        viewModel.setTrackFeedback(target, RecommendationFeedbackKind.LESS_LIKE_THIS)
                    },
                    onToggleExcludeArtist = {
                        viewModel.toggleExcludeArtist(
                            target.artistBrowseIds.firstOrNull().orEmpty(),
                            target.artist
                        )
                    },
                    isPinnedToHome = SpeedDial.songKey(target)?.let { key -> state.speedDialPins.any { it.key == key } } == true,
                    onTogglePinToHome = { viewModel.toggleSpeedDialTrack(target) }
                )
            }

            trackActionPlaylistTarget?.let { track ->
                AddToPlaylistDialog(
                    track = track,
                    playlists = state.playlists,
                    onDismiss = { trackActionPlaylistTarget = null },
                    onAddTo = { playlistId ->
                        viewModel.addToPlaylist(playlistId, track)
                        trackActionPlaylistTarget = null
                    },
                    onCreateWith = { name ->
                        viewModel.createPlaylist(name, track)
                        trackActionPlaylistTarget = null
                    }
                )
            }
            }
        }
    }
}

@Composable
private fun SharedMediaPreviewDialog(
    preview: SharedMediaPreview,
    languageCode: String,
    onPlay: () -> Unit,
    onPlayNext: () -> Unit,
    onQueue: () -> Unit,
    onDownload: () -> Unit,
    onImport: () -> Unit,
    onSavePlaylist: () -> Unit,
    onDismiss: () -> Unit
) {
    val italian = languageCode.equals("it", ignoreCase = true)
    val bulkCopy = remember(languageCode) { bulkLinkCaptureCopy(languageCode) }
    val bulkSummary = preview.bulkSummary
    Dialog(
        onDismissRequest = onDismiss,
        properties = DialogProperties(usePlatformDefaultWidth = false)
    ) {
        Surface(
            color = LevyraInk.copy(alpha = 0.98f),
            shape = RoundedCornerShape(30.dp),
            border = BorderStroke(1.dp, Color.White.copy(alpha = 0.12f)),
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 18.dp)
        ) {
            Column(
                modifier = Modifier.padding(20.dp),
                verticalArrangement = Arrangement.spacedBy(16.dp)
            ) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(14.dp)
                ) {
                    if (preview.thumbnailUrl.isNotBlank()) {
                        AsyncImage(
                            model = preview.thumbnailUrl,
                            contentDescription = null,
                            contentScale = ContentScale.Crop,
                            modifier = Modifier
                                .size(78.dp)
                                .clip(RoundedCornerShape(18.dp))
                        )
                    } else {
                        EmptyCover(
                            Modifier
                                .size(78.dp)
                                .clip(RoundedCornerShape(18.dp))
                        )
                    }
                    Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(5.dp)) {
                        Text(
                            text = if (italian) "Condiviso con Levyra" else "Shared with Levyra",
                            color = LevyraCyan,
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Black
                        )
                        Text(
                            text = preview.title.ifBlank { bulkCopy.title.takeIf { bulkSummary != null }.orEmpty() },
                            color = LevyraText,
                            fontSize = 19.sp,
                            fontWeight = FontWeight.Black,
                            maxLines = 2,
                            overflow = TextOverflow.Ellipsis
                        )
                        if (preview.subtitle.isNotBlank()) Text(
                            text = preview.subtitle,
                            color = LevyraMuted,
                            fontSize = 12.sp,
                            fontWeight = FontWeight.SemiBold,
                            maxLines = 2,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                    CircleIconButton(
                        icon = Icons.Rounded.Close,
                        tint = LevyraText,
                        background = Color.White.copy(alpha = 0.08f),
                        onClick = onDismiss
                    )
                }
                when {
                    preview.loading -> {
                        Row(
                            modifier = Modifier.fillMaxWidth().padding(vertical = 12.dp),
                            horizontalArrangement = Arrangement.Center,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            CircularProgressIndicator(modifier = Modifier.size(24.dp), strokeWidth = 2.5.dp, color = LevyraCyan)
                        }
                    }
                    preview.error.isNotBlank() -> {
                        Text(
                            text = preview.error,
                            color = LevyraOrange,
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                    bulkSummary != null && !preview.playable -> {
                        BulkLinkCaptureSummaryText(bulkSummary, bulkCopy)
                        Text(
                            text = bulkCopy.noTracks,
                            color = LevyraOrange,
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                    preview.playable -> {
                        bulkSummary?.let { BulkLinkCaptureSummaryText(it, bulkCopy) }
                        if (bulkSummary == null) Text(
                            text = if (italian) "${preview.tracks.size} ${if (preview.tracks.size == 1) "brano pronto" else "brani pronti"}" else "${preview.tracks.size} ${if (preview.tracks.size == 1) "track ready" else "tracks ready"}",
                            color = LevyraMuted,
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold
                        )
                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                            SharedMediaAction(
                                modifier = Modifier.weight(1f),
                                icon = Icons.Rounded.PlayArrow,
                                title = if (italian) "Riproduci" else "Play",
                                primary = true,
                                onClick = onPlay
                            )
                            SharedMediaAction(
                                modifier = Modifier.weight(1f),
                                icon = Icons.Rounded.Download,
                                title = if (italian) "Scarica" else "Download",
                                primary = false,
                                onClick = onDownload
                            )
                        }
                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                            SharedMediaAction(
                                modifier = Modifier.weight(1f),
                                icon = Icons.Rounded.SkipNext,
                                title = if (italian) "Dopo" else "Play next",
                                primary = false,
                                onClick = onPlayNext
                            )
                            SharedMediaAction(
                                modifier = Modifier.weight(1f),
                                icon = Icons.AutoMirrored.Rounded.QueueMusic,
                                title = if (italian) "In coda" else "Queue",
                                primary = false,
                                onClick = onQueue
                            )
                        }
                        if (preview.request.kind == SharedMediaKind.LevyraPlaylist) {
                            Row(modifier = Modifier.fillMaxWidth()) {
                                SharedMediaAction(
                                    modifier = Modifier.weight(1f),
                                    icon = Icons.Rounded.LibraryAdd,
                                    title = if (italian) "Importa" else "Import",
                                    primary = false,
                                    onClick = onImport
                                )
                            }
                        }
                        if (preview.request.kind == SharedMediaKind.BulkLinks) {
                            Row(modifier = Modifier.fillMaxWidth()) {
                                SharedMediaAction(
                                    modifier = Modifier.weight(1f),
                                    icon = Icons.Rounded.LibraryAdd,
                                    title = bulkCopy.savePlaylist,
                                    primary = false,
                                    onClick = onSavePlaylist
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}

@Composable
private fun BulkLinkCaptureSummaryText(summary: BulkLinkCaptureSummary, copy: BulkLinkCaptureCopy) {
    val lines = buildList {
        add(copy.detected(summary.detectedLinks))
        add(copy.found(summary.resolvedTracks))
        if (summary.duplicates > 0) add(copy.duplicates(summary.duplicates))
        if (summary.unrecognized > 0) add(copy.unrecognized(summary.unrecognized))
    }
    Column(
        modifier = Modifier.semantics(mergeDescendants = true) {},
        verticalArrangement = Arrangement.spacedBy(3.dp)
    ) {
        lines.forEach { line ->
            Text(
                text = line,
                color = LevyraMuted,
                fontSize = 12.sp,
                fontWeight = FontWeight.Bold
            )
        }
    }
}

@Composable
private fun SharedMediaAction(
    modifier: Modifier,
    icon: ImageVector,
    title: String,
    primary: Boolean,
    onClick: () -> Unit
) {
    Surface(
        color = if (primary) LevyraCyan else Color.White.copy(alpha = 0.08f),
        contentColor = if (primary) LevyraBlack else LevyraText,
        shape = RoundedCornerShape(16.dp),
        border = if (primary) null else BorderStroke(1.dp, Color.White.copy(alpha = 0.10f)),
        modifier = modifier.pressable(onClick = onClick)
    ) {
        Row(
            modifier = Modifier.padding(horizontal = 12.dp, vertical = 12.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.Center
        ) {
            Icon(icon, contentDescription = null, modifier = Modifier.size(18.dp))
            Spacer(Modifier.width(7.dp))
            Text(title, fontSize = 12.sp, fontWeight = FontWeight.Black, maxLines = 1)
        }
    }
}

private data class DownloadHudItem(
    val taskKey: String,
    val progress: Int,
    val title: String,
    val count: Int
)

private fun LevyraUiState.activeDownloadHudItem(strings: LevyraStrings): DownloadHudItem? {
    val ids = downloadingTrackIds.toList()
    if (ids.isEmpty()) return null
    val primaryId = ids.maxByOrNull { downloadProgressByTrackId[it] ?: 1 } ?: return null
    val progress = (downloadProgressByTrackId[primaryId] ?: 1).coerceIn(1, 99)
    val rawTitle = downloadTitleByTrackId[primaryId].orEmpty().ifBlank { strings.song }
    val title = if (ids.size > 1) "$rawTitle +${ids.size - 1}" else rawTitle
    return DownloadHudItem(taskKey = primaryId, progress = progress, title = title, count = ids.size)
}

private fun downloadHudBottomPadding(state: LevyraUiState, dockSideBySide: Boolean): Dp {
    return when {
        state.currentTrack != null && !dockSideBySide -> 154.dp
        else -> 96.dp
    }
}

@Composable
private fun tabBarBottomContentInset(miniPlayerVisible: Boolean, animationsEnabled: Boolean): Dp {
    val navigationBarInset = WindowInsets.navigationBars.asPaddingValues().calculateBottomPadding()
    val navigationHeight = when {
        LevyraIsNocturne -> (LocalNocturneNavigationHeight.current?.value ?: 64.dp) + 1.dp
        LevyraIsPrism -> LocalNocturneNavigationHeight.current?.value ?: 80.dp
        else -> LevyraTabBarCompactHeight
    }
    val collapsed = navigationHeight + navigationBarInset + LevyraBottomContentGap + LocalNavDockExtraClearance.current
    val miniPlayerExtra = if (LevyraIsPrism) {
        84.dp
    } else if (LocalDockMiniMerged.current()) {
        0.dp
    } else if (levyraWindowIsCompactLandscape()) {
        (LevyraMiniPlayerHeight - LevyraTabBarHeight).coerceAtLeast(0.dp)
    } else {
        LevyraMiniPlayerHeight
    }
    return animatedBottomContentInset(
        collapsed = collapsed,
        expanded = collapsed + miniPlayerExtra,
        miniPlayerVisible = miniPlayerVisible,
        animationsEnabled = animationsEnabled
    )
}

@Composable
internal fun levyraTabContentBottomPadding(miniPlayerVisible: Boolean): Dp =
    tabBarBottomContentInset(miniPlayerVisible, LocalAnimationsEnabled.current) + 16.dp

@Composable
private fun animatedBottomContentInset(
    collapsed: Dp,
    expanded: Dp,
    miniPlayerVisible: Boolean,
    animationsEnabled: Boolean
): Dp {
    val effectiveAnimationsEnabled = animationsEnabled && LocalAnimationsEnabled.current
    val inset by animateDpAsState(
        targetValue = if (miniPlayerVisible) expanded else collapsed,
        animationSpec = if (effectiveAnimationsEnabled) {
            tween(durationMillis = 260, easing = FastOutSlowInEasing)
        } else {
            snap()
        },
        label = "bottomContentInset"
    )
    return inset
}

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
private fun DownloadProgressHud(
    state: LevyraUiState,
    minimized: Boolean,
    onMinimizedChange: (Boolean) -> Unit,
    onDismiss: () -> Unit
) {
    val strings = LocalLevyraStrings.current
    val item = state.activeDownloadHudItem(strings) ?: return
    val colors = MaterialTheme.colorScheme
    val progress by animateFloatAsState(
        targetValue = item.progress / 100f,
        animationSpec = spring(dampingRatio = Spring.DampingRatioNoBouncy, stiffness = Spring.StiffnessLow),
        label = "downloadHudProgress"
    )
    AnimatedContent(
        targetState = minimized,
        transitionSpec = {
            fadeIn(tween(180)) + scaleIn(spring(dampingRatio = 0.7f, stiffness = 500f), initialScale = 0.85f) togetherWith
                fadeOut(tween(120)) using SizeTransform(clip = false)
        },
        modifier = Modifier.fillMaxWidth(),
        contentAlignment = Alignment.CenterEnd,
        label = "downloadHudMode"
    ) { compact ->
        if (compact) {
            Surface(
                onClick = { onMinimizedChange(false) },
                shape = CircleShape,
                color = colors.primaryContainer,
                contentColor = colors.onPrimaryContainer,
                shadowElevation = 6.dp,
                modifier = Modifier
                    .wrapContentWidth(Alignment.End)
                    .size(52.dp)
                    .semantics { contentDescription = "${strings.downloadInProgress} ${item.progress}%" }
            ) {
                Box(contentAlignment = Alignment.Center) {
                    CircularWavyProgressIndicator(
                        progress = { progress },
                        modifier = Modifier.size(44.dp),
                        color = colors.primary,
                        trackColor = colors.primary.copy(alpha = 0.18f)
                    )
                    Icon(Icons.Rounded.Download, contentDescription = null, modifier = Modifier.size(20.dp))
                }
            }
        } else {
            Surface(
                shape = RoundedCornerShape(28.dp),
                color = colors.surfaceContainerHigh,
                contentColor = colors.onSurface,
                shadowElevation = 6.dp,
                modifier = Modifier.fillMaxWidth()
            ) {
                Row(
                    modifier = Modifier.padding(start = 10.dp, end = 4.dp, top = 8.dp, bottom = 8.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Box(
                        modifier = Modifier
                            .size(44.dp)
                            .clip(CircleShape)
                            .background(colors.primaryContainer),
                        contentAlignment = Alignment.Center
                    ) {
                        CircularWavyProgressIndicator(
                            progress = { progress },
                            modifier = Modifier.size(40.dp),
                            color = colors.primary,
                            trackColor = colors.primary.copy(alpha = 0.18f)
                        )
                        Icon(
                            Icons.Rounded.Download,
                            contentDescription = null,
                            tint = colors.onPrimaryContainer,
                            modifier = Modifier.size(18.dp)
                        )
                    }
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = item.title,
                            style = MaterialTheme.typography.titleSmall,
                            fontWeight = FontWeight.SemiBold,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                        Text(
                            text = "${if (item.count > 1) strings.downloadsInProgress else strings.downloadInProgress} · ${item.progress}%",
                            style = MaterialTheme.typography.labelMedium,
                            color = colors.onSurfaceVariant,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                    IconButton(onClick = { onMinimizedChange(true) }) {
                        Icon(Icons.Rounded.KeyboardArrowDown, contentDescription = strings.showLess, tint = colors.onSurfaceVariant)
                    }
                    IconButton(onClick = onDismiss) {
                        Icon(Icons.Rounded.Close, contentDescription = strings.close, tint = colors.onSurfaceVariant)
                    }
                }
            }
        }
    }
}

