private fun formatBedtimeStart(startMinuteOfDay: Int): String {
    val hour = (startMinuteOfDay / 60).coerceIn(0, 23)
    val minute = (startMinuteOfDay % 60).coerceIn(0, 59)
    return "${hour.toString().padStart(2, '0')}:${minute.toString().padStart(2, '0')}"
}

@Composable
private fun SleepTimerOption(label: String, onClick: () -> Unit) {
    TextButton(onClick = onClick, modifier = Modifier.fillMaxWidth()) {
        Text(label, color = LevyraText, fontWeight = FontWeight.SemiBold)
    }
}

private fun formatTimerRemaining(totalSeconds: Long): String {
    val minutes = totalSeconds / 60L
    val seconds = totalSeconds % 60L
    return "${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}"
}


@Composable
private fun AlbumOverlay(
    state: LevyraUiState,
    onPlayAll: () -> Unit,
    onShuffleAll: () -> Unit,
    onPlay: (Track) -> Unit,
    onTogglePlayback: () -> Unit,
    onFavorite: (Track) -> Unit,
    onToggleAlbumFavorite: () -> Unit,
    onDownload: (Track) -> Unit,
    onDownloadAlbum: () -> Unit,
    onRetry: () -> Unit,
    onTogglePinToHome: (AlbumHit) -> Unit,
    onAddToPlaylist: (String, Track) -> Unit,
    onCreatePlaylistWithTrack: (String, Track) -> Unit,
    onPlayTracksNext: (List<Track>) -> Unit,
    onAddTracksToQueue: (List<Track>) -> Unit,
    onToggleFavorites: (List<Track>) -> Unit,
    onDislikeTracks: (List<Track>) -> Unit,
    onExportTracks: (List<Track>) -> Unit,
    onAddTracksToPlaylist: (String, List<Track>) -> Unit,
    onCreatePlaylistWithTracks: (String, List<Track>) -> Unit,
    onAddAlbumToPlaylist: (String) -> Unit,
    onCreatePlaylistWithAlbum: (String) -> Unit,
    onOpenAlbumArtist: () -> Unit,
    onOpenTrackArtist: (Track) -> Unit,
    onOpenPlayer: () -> Unit,
    onClose: () -> Unit
) {
    val detail = state.albumDetail
    var albumPlaylistPicker by remember(detail?.album?.browseId, detail?.album?.title, detail?.album?.artist) { mutableStateOf(false) }
    val album = detail?.album
    val tracks = detail?.tracks.orEmpty()
    val description = detail?.description.orEmpty()
    val cover = album?.thumbnailUrl.orEmpty()
    val context = LocalContext.current
    val strings = LocalLevyraStrings.current
    val density = LocalDensity.current
    val listState = rememberSaveable(album?.browseId, album?.title, saver = LazyListState.Saver) {
        LazyListState()
    }
    var addTarget by remember { mutableStateOf<Track?>(null) }
    var batchAddTargets by remember { mutableStateOf<List<Track>>(emptyList()) }
    val selection = rememberTrackSelectionState()
    val selectableIds = remember(tracks) { tracks.map(::trackSelectionKey) }
    val selectedTracks = remember(tracks, selection.selectedIds) {
        selection.resolveSelected(tracks, ::trackSelectionKey)
    }
    LaunchedEffect(selectableIds) { selection.retainAvailable(selectableIds) }
    BackHandler(enabled = selection.isActive) { selection.exit() }
    val albumCurrentTrack = remember(tracks, state.currentTrack) {
        tracks.firstOrNull { candidate -> uiTrackMatches(state.currentTrack, candidate) }
    }
    val albumIsActive = albumCurrentTrack != null
    val albumIsPlaying = albumIsActive && state.isPlaying
    val albumIsResolving = albumIsActive && state.isResolving
    val trackLoadFailed = album != null && tracks.isEmpty() && !state.albumLoading
    val tracksLoading = state.albumLoading && tracks.isEmpty()
    val albumSaved = remember(tracks, state.favorites) {
        areAllFavoriteTracks(state.favorites, tracks)
    }
    val albumBottomInset = animatedBottomContentInset(
        collapsed = 112.dp,
        expanded = 232.dp,
        miniPlayerVisible = state.currentTrack != null,
        animationsEnabled = state.animationsEnabled
    )
    val paletteKey = remember(album?.browseId, album?.title, album?.artist, cover) {
        if (album == null || cover.isBlank()) {
            ""
        } else {
            ArtworkPaletteCache.key(
                trackId = "album:" + album.browseId.ifBlank { album.title + "|" + album.artist },
                thumbnailUrl = cover,
                largeThumbnailUrl = cover
            )
        }
    }
    val fallbackPalette = remember {
        ArtworkPalette(AlbumNeutralPaletteStart.toArgb(), AlbumNeutralPaletteEnd.toArgb())
    }
    val albumPalette by rememberArtworkPalette(
        paletteKey = paletteKey,
        artworkUrl = cover,
        fallback = fallbackPalette
    )
    val lightTheme = LevyraIsLight
    val nocturne = LevyraIsNocturne
    val stageTarget = remember(albumPalette, lightTheme, nocturne) {
        albumStageColors(Color(albumPalette.start), Color(albumPalette.end), lightTheme)
    }
    val stage = animatedImmersiveMediaColors(
        target = stageTarget,
        animated = state.animationsEnabled,
        labelPrefix = "album"
    )
    val motionEnabled = state.animationsEnabled && state.motionArtworkEnabled
    var albumMenuExpanded by rememberSaveable(album?.browseId, album?.title) { mutableStateOf(false) }
    var albumDescriptionExpanded by rememberSaveable(album?.browseId, album?.title) { mutableStateOf(false) }
    var albumDescriptionOverflows by remember(description) { mutableStateOf(false) }
    val albumOverline = remember(album?.year, strings) {
        listOf(strings.speedDialCopy().album, album?.year.orEmpty())
            .filter { it.isNotBlank() }
            .joinToString(" · ")
    }
    val albumMetadata = remember(tracks, strings) {
        val totalMs = tracks.sumOf { it.durationMs.coerceAtLeast(0L) }
        listOf(
            tracks.takeIf { it.isNotEmpty() }?.let { strings.formatTrackCount(it.size) }.orEmpty(),
            if (totalMs > 0L) strings.formatLibraryDuration(totalMs) else ""
        )
            .filter { it.isNotBlank() }
            .joinToString(" · ")
    }
    val albumPinned = album?.let { SpeedDial.albumKey(it) }
        ?.let { key -> state.speedDialPins.any { it.key == key } } == true
    val shareAlbum: () -> Unit = {
        album?.let { currentAlbum ->
            val shareText = buildString {
                append(currentAlbum.title)
                if (currentAlbum.artist.isNotBlank()) append(" - ").append(currentAlbum.artist)
                if (currentAlbum.browseId.isNotBlank()) {
                    append("\nhttps://music.youtube.com/browse/").append(currentAlbum.browseId)
                }
            }
            val intent = Intent(Intent.ACTION_SEND).apply {
                type = "text/plain"
                putExtra(Intent.EXTRA_TEXT, shareText)
            }
            context.startActivity(Intent.createChooser(intent, strings.share))
        }
    }
    val albumTrackItems: LazyListScope.(Dp) -> Unit = { gutter ->
        when {
            tracksLoading -> items(
                count = ALBUM_SKELETON_ROWS,
                key = { index -> "album-skeleton-$index" },
                contentType = { "album-skeleton" }
            ) {
                AlbumTrackSkeleton(stage = stage, modifier = Modifier.padding(horizontal = gutter))
            }
            tracks.isNotEmpty() -> itemsIndexed(
                items = tracks,
                key = { index, track -> "album-track-$index-${track.id}" },
                contentType = { _, _ -> "album-track" }
            ) { index, track ->
                val selectionKey = trackSelectionKey(track)
                AlbumTrackRow(
                    index = index,
                    count = tracks.size,
                    track = track,
                    albumArtist = album?.artist.orEmpty(),
                    stage = stage,
                    presentation = AlbumTrackRowPresentation(
                        isCurrent = uiTrackMatches(state.currentTrack, track),
                        isPlaying = state.isPlaying,
                        isFavorite = track.id in state.favoriteIds,
                        isDownloading = track.id in state.downloadingTrackIds,
                        isDownloaded = track.id in state.downloadedTrackIds,
                        downloadProgress = state.downloadProgressByTrackId[track.id],
                        selected = selection.isSelected(selectionKey),
                        selectionActive = selection.isActive
                    ),
                    actions = AlbumTrackRowActions(
                        onLongClick = { selection.start(selectionKey) },
                        onPlay = {
                            if (selection.isActive) {
                                selection.toggle(selectionKey)
                            } else if (uiTrackMatches(state.currentTrack, track)) {
                                onOpenPlayer()
                            } else {
                                onPlay(track)
                            }
                        },
                        onFavorite = { onFavorite(track) },
                        onDownload = { onDownload(track) },
                        onAddToPlaylist = { addTarget = track },
                        onArtist = { onOpenTrackArtist(track) }
                    ),
                    modifier = Modifier.padding(horizontal = gutter)
                )
            }
            album != null && !state.albumLoading -> item(key = "album-no-tracks") {
                Box(modifier = Modifier.padding(horizontal = gutter, vertical = 8.dp)) {
                    AlbumTracksUnavailableState(state.albumError ?: strings.albumTracksUnavailable)
                }
            }
        }
    }

    BoxWithConstraints(
        modifier = Modifier
            .fillMaxSize()
            .background(stage.base)
            .windowInsetsPadding(LevyraHorizontalSafeInsets)
    ) {
        val split = resolvePlayerPane(maxWidth.value, maxHeight.value) == LevyraPlayerPane.SideBySide
        val statusTop = WindowInsets.statusBars.asPaddingValues().calculateTopPadding()
        val topBarHeight = statusTop + ALBUM_TOP_BAR_HEIGHT
        val topBarPx = with(density) { topBarHeight.toPx() }
        val heroHeight = immersiveHeroHeight(split, maxWidth, maxHeight, topBarHeight)
        val heroPx = with(density) { heroHeight.toPx() }
        val collapsedState = remember(listState, heroPx, topBarPx) {
            derivedStateOf {
                val threshold = (heroPx - topBarPx).coerceAtLeast(0f)
                listState.firstVisibleItemIndex > 0 || listState.firstVisibleItemScrollOffset > threshold
            }
        }

        when {
            album == null -> {
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(top = topBarHeight, start = 20.dp, end = 20.dp)
                ) {
                    if (state.albumLoading) {
                        LevyraLoadingIndicator(
                            color = stage.accent,
                            modifier = Modifier
                                .align(Alignment.TopCenter)
                                .padding(top = 48.dp)
                        )
                    } else {
                        GlassMessage(strings.albumUnavailable, LevyraOrange)
                    }
                }
            }
            else -> {
                val gutter = albumContentGutter(maxWidth)
                ArtworkBackdropWash(
                    artworkUrl = cover,
                    tint = stage.fieldTop,
                    base = stage.base,
                    modifier = Modifier.fillMaxSize()
                )
                LazyColumn(
                    state = listState,
                    modifier = Modifier.fillMaxSize(),
                    contentPadding = PaddingValues(bottom = selection.listBottomPadding(albumBottomInset))
                ) {
                    item(key = "album-hero", contentType = "album-hero") {
                        ImmersiveMediaHero(
                            title = album.title,
                            overline = albumOverline,
                            subtitle = album.artist,
                            metadata = albumMetadata,
                            colors = stage,
                            wide = split,
                            viewportWidth = maxWidth,
                            viewportHeight = maxHeight,
                            topBarHeight = topBarHeight,
                            onSubtitleClick = onOpenAlbumArtist.takeIf { album.artist.isNotBlank() },
                            actions = {
                                ImmersiveMediaActionRow(
                                    primary = ImmersiveMediaPrimaryAction(
                                        enabled = tracks.isNotEmpty() || trackLoadFailed,
                                        label = when {
                                            trackLoadFailed -> strings.exploreSamplesRetry
                                            albumIsPlaying -> strings.pause
                                            else -> strings.play
                                        },
                                        contentDescription = when {
                                            trackLoadFailed -> strings.exploreSamplesRetry
                                            albumIsPlaying -> strings.pause
                                            else -> strings.play
                                        },
                                        icon = when {
                                            trackLoadFailed -> Icons.Rounded.Refresh
                                            albumIsPlaying -> Icons.Rounded.Pause
                                            else -> Icons.Rounded.PlayArrow
                                        },
                                        loading = albumIsResolving,
                                        onClick = when {
                                            trackLoadFailed -> onRetry
                                            albumIsActive -> onTogglePlayback
                                            else -> onPlayAll
                                        }
                                    ),
                                    shuffleLabel = strings.shuffle,
                                    downloadLabel = strings.download,
                                    colors = stage,
                                    shuffleEnabled = tracks.size > 1 && !trackLoadFailed,
                                    downloadEnabled = tracks.isNotEmpty(),
                                    onShuffle = onShuffleAll,
                                    onDownload = onDownloadAlbum,
                                    secondary = {
                                        ImmersiveMediaQuietAction(
                                            icon = if (albumSaved) Icons.Rounded.Favorite else Icons.Rounded.FavoriteBorder,
                                            label = if (albumSaved) strings.removeFromFavorites else strings.addToFavorites,
                                            enabled = tracks.isNotEmpty(),
                                            colors = stage,
                                            active = albumSaved,
                                            activeTint = LevyraPink,
                                            toggleable = true,
                                            onClick = onToggleAlbumFavorite
                                        )
                                    }
                                )
                            },
                            artwork = {
                                AlbumArtworkLayer(
                                    cover = cover,
                                    title = album.title,
                                    motionArtwork = state.albumMotionArtwork,
                                    motionEnabled = motionEnabled,
                                    canvasQuality = state.interfaceSettings.canvasQuality,
                                    modifier = Modifier.fillMaxSize()
                                )
                            }
                        )
                    }
                    if (description.isNotBlank()) {
                        item(key = "album-description", contentType = "album-description") {
                            val canToggleDescription = albumDescriptionExpanded || albumDescriptionOverflows
                            Column(
                                modifier = Modifier
                                    .padding(start = gutter, end = gutter, top = 4.dp, bottom = 16.dp)
                                    .fillMaxWidth()
                                    .clip(LevyraPlayerDesign.ShapeSm)
                                    .clickable(enabled = canToggleDescription, role = Role.Button) {
                                        albumDescriptionExpanded = !albumDescriptionExpanded
                                    }
                                    .padding(horizontal = LevyraPlayerDesign.SpaceXs, vertical = LevyraPlayerDesign.SpaceSm),
                                verticalArrangement = Arrangement.spacedBy(LevyraPlayerDesign.SpaceXs)
                            ) {
                                Text(
                                    text = description,
                                    color = stage.contentMuted,
                                    fontSize = 14.sp,
                                    lineHeight = 21.sp,
                                    letterSpacing = (-0.1).sp,
                                    maxLines = if (albumDescriptionExpanded) Int.MAX_VALUE else 3,
                                    overflow = TextOverflow.Ellipsis,
                                    onTextLayout = { result ->
                                        if (!albumDescriptionExpanded) {
                                            albumDescriptionOverflows = result.hasVisualOverflow
                                        }
                                    }
                                )
                                if (canToggleDescription) {
                                    ArtistTonalPill(
                                        text = if (albumDescriptionExpanded) strings.showLess else strings.readAll,
                                        icon = if (albumDescriptionExpanded) Icons.Rounded.KeyboardArrowUp else Icons.Rounded.KeyboardArrowDown,
                                        onClick = { albumDescriptionExpanded = !albumDescriptionExpanded }
                                    )
                                }
                            }
                        }
                    }
                    albumTrackItems(gutter)
                }
            }
        }

        ImmersiveMediaTopBar(
            title = album?.title.orEmpty(),
            colors = stage,
            collapsedState = collapsedState,
            height = topBarHeight,
            animated = state.animationsEnabled,
            backLabel = strings.back,
            onBack = onClose,
            actions = {
                if (album != null) {
                    Box {
                        PlayerGlassIconButton(
                            icon = Icons.Rounded.MoreVert,
                            contentDescription = strings.more,
                            onClick = { albumMenuExpanded = true },
                            size = ImmersiveTopBarButtonSize,
                            tint = Color.White,
                            fill = ImmersiveTopBarButtonFill,
                            borderTop = Color.Transparent,
                            borderBottom = Color.Transparent
                        )
                        DropdownMenu(
                            expanded = albumMenuExpanded,
                            onDismissRequest = { albumMenuExpanded = false },
                            modifier = Modifier.background(stage.fieldTop)
                        ) {
                            DropdownMenuItem(
                                text = { Text(strings.search) },
                                leadingIcon = { Icon(Icons.Rounded.Search, null) },
                                onClick = {
                                    albumMenuExpanded = false
                                    val query = listOf(album.title, album.artist).filter { it.isNotBlank() }.joinToString(" ")
                                    if (query.isNotBlank()) {
                                        openExternalUrl(
                                            context,
                                            "https://music.youtube.com/search?q=${java.net.URLEncoder.encode(query, "UTF-8")}",
                                            strings
                                        )
                                    }
                                }
                            )
                            DropdownMenuItem(
                                text = { Text(strings.playlistAlbumCopy().addAlbumToPlaylist) },
                                leadingIcon = { Icon(Icons.AutoMirrored.Rounded.PlaylistAdd, null) },
                                enabled = tracks.isNotEmpty(),
                                onClick = { albumMenuExpanded = false; albumPlaylistPicker = true }
                            )
                            DropdownMenuItem(
                                text = { Text(strings.share) },
                                leadingIcon = { Icon(Icons.Rounded.Share, null) },
                                onClick = { albumMenuExpanded = false; shareAlbum() }
                            )
                            DropdownMenuItem(
                                text = {
                                    val copy = strings.speedDialCopy()
                                    Text(
                                        if (albumPinned) copy.removeFromHome else copy.addToHome
                                    )
                                },
                                leadingIcon = { Icon(Icons.Rounded.PushPin, null) },
                                onClick = {
                                    albumMenuExpanded = false
                                    onTogglePinToHome(album)
                                }
                            )
                        }
                    }
                }
            }
        )
        if (state.albumLoading && album != null && tracks.isNotEmpty()) {
            LinearMiniLoading(modifier = Modifier.align(Alignment.TopCenter).padding(top = topBarHeight))
        }
        state.currentTrack?.takeUnless { selection.isActive }?.let { current ->
            AlbumNowPlayingDock(
                track = current,
                isPlaying = state.isPlaying,
                isResolving = state.isResolving,
                progress = progressOf(state.positionMs, state.durationMs),
                animated = state.animationsEnabled,
                onToggle = onTogglePlayback,
                onOpenPlayer = onOpenPlayer,
                modifier = Modifier
                    .align(Alignment.BottomCenter)
                    .navigationBarsPadding()
                    .padding(start = 18.dp, end = 18.dp, bottom = 14.dp)
            )
        }

        TrackSelectionBar(
            state = selection,
            allVisibleIds = selectableIds,
            actions = trackSelectionActions(
                state = selection,
                selectedTracks = selectedTracks,
                onPlayNext = onPlayTracksNext,
                onAddToQueue = onAddTracksToQueue,
                onAddToPlaylist = { batchAddTargets = it },
                onFavorite = onToggleFavorites,
                onDownload = onExportTracks,
                onDislike = onDislikeTracks
            ),
            modifier = Modifier
                .align(Alignment.BottomCenter)
                .padding(horizontal = 12.dp)
        )

        addTarget?.let { track ->
            AddToPlaylistDialog(
                track = track,
                playlists = state.playlists,
                onDismiss = { addTarget = null },
                onAddTo = { playlistId ->
                    onAddToPlaylist(playlistId, track)
                    addTarget = null
                },
                onCreateWith = { name ->
                    onCreatePlaylistWithTrack(name, track)
                    addTarget = null
                }
            )
        }

        if (albumPlaylistPicker && album != null && tracks.isNotEmpty()) {
            val albumCopy = strings.playlistAlbumCopy()
            val containing = remember(state.playlists, album) {
                state.playlists.filter { it.containsAlbum(album) }.mapTo(hashSetOf()) { it.id }
            }
            com.luc4n3x.levyra.ui.library.AddTracksToPlaylistDialog(
                tracks = tracks,
                playlists = state.playlists,
                title = albumCopy.addAlbumToPlaylist,
                unavailablePlaylistIds = containing,
                unavailableLabel = albumCopy.inPlaylist,
                onDismiss = { albumPlaylistPicker = false },
                onAdd = { playlistId ->
                    onAddAlbumToPlaylist(playlistId)
                    albumPlaylistPicker = false
                },
                onCreate = { name ->
                    onCreatePlaylistWithAlbum(name)
                    albumPlaylistPicker = false
                }
            )
        }

        if (batchAddTargets.isNotEmpty()) {
            com.luc4n3x.levyra.ui.library.AddTracksToPlaylistDialog(
                tracks = batchAddTargets,
                playlists = state.playlists,
                onDismiss = { batchAddTargets = emptyList() },
                onAdd = { playlistId ->
                    onAddTracksToPlaylist(playlistId, batchAddTargets)
                    batchAddTargets = emptyList()
                    selection.exit()
                },
                onCreate = { name ->
                    onCreatePlaylistWithTracks(name, batchAddTargets)
                    batchAddTargets = emptyList()
                    selection.exit()
                }
            )
        }
    }
}

private const val ALBUM_SKELETON_ROWS = 6
private val ALBUM_TOP_BAR_HEIGHT = 64.dp

@Composable
private fun AlbumTracksUnavailableState(message: String) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 4.dp, vertical = 2.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(10.dp)
    ) {
        Box(
            modifier = Modifier
                .size(32.dp)
                .background(LevyraOrange.copy(alpha = 0.12f), CircleShape),
            contentAlignment = Alignment.Center
        ) {
            Icon(
                imageVector = Icons.Rounded.Info,
                contentDescription = null,
                tint = LevyraOrange,
                modifier = Modifier.size(17.dp)
            )
        }
        Text(
            text = message,
            color = LevyraMuted,
            fontSize = 13.sp,
            lineHeight = 18.sp,
            fontWeight = FontWeight.Medium,
            modifier = Modifier.weight(1f)
        )
    }
}

private fun uiTrackMatches(current: Track?, candidate: Track): Boolean {
    if (current == null) return false
    if (current.id.isNotBlank() && candidate.id.isNotBlank() && current.id == candidate.id) return true
    val currentTitle = current.title.trim().lowercase()
    val candidateTitle = candidate.title.trim().lowercase()
    val currentArtist = current.artist.trim().lowercase()
    val candidateArtist = candidate.artist.trim().lowercase()
    return currentTitle.isNotBlank() && currentTitle == candidateTitle && currentArtist == candidateArtist
}

@Composable
private fun AlbumArtworkLayer(
    cover: String,
    title: String,
    motionArtwork: com.luc4n3x.levyra.feature.motion.MotionArtwork?,
    motionEnabled: Boolean,
    canvasQuality: LevyraCanvasQuality,
    modifier: Modifier = Modifier
) {
    MotionArtworkLayer(
        artwork = motionArtwork,
        enabled = motionEnabled,
        isPlaying = false,
        pageMode = true,
        cornerRadius = 0.dp,
        presentation = MotionArtworkPresentation.Cinematic,
        quality = canvasQuality,
        modifier = modifier
    ) {
        SeamlessArtworkImage(
            url = cover,
            contentDescription = title,
            modifier = Modifier.fillMaxSize()
        ) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(Brush.linearGradient(listOf(AlbumNeutralPaletteStart, AlbumNeutralPaletteEnd))),
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    Icons.Rounded.Album,
                    contentDescription = null,
                    tint = Color.White.copy(alpha = 0.82f),
                    modifier = Modifier.size(72.dp)
                )
            }
        }
    }
}

@Composable
private fun LinearMiniLoading(modifier: Modifier = Modifier) {
    Surface(color = Color.White.copy(alpha = 0.08f), shape = CircleShape, modifier = modifier.width(92.dp).height(4.dp)) {
        Box(modifier = Modifier.fillMaxSize().background(Brush.horizontalGradient(listOf(LevyraCyan.copy(alpha = 0.2f), LevyraCyan, LevyraViolet, LevyraCyan.copy(alpha = 0.2f)))))
    }
}

private data class AlbumTrackRowPresentation(
    val isCurrent: Boolean,
    val isPlaying: Boolean,
    val isFavorite: Boolean,
    val isDownloading: Boolean,
    val isDownloaded: Boolean,
    val downloadProgress: Int?,
    val selected: Boolean,
    val selectionActive: Boolean
)

private data class AlbumTrackRowActions(
    val onLongClick: () -> Unit,
    val onPlay: () -> Unit,
    val onFavorite: () -> Unit,
    val onDownload: () -> Unit,
    val onAddToPlaylist: () -> Unit,
    val onArtist: () -> Unit
)

@Composable
private fun AlbumTrackRow(
    index: Int,
    count: Int,
    track: Track,
    albumArtist: String,
    stage: AlbumStageColors,
    presentation: AlbumTrackRowPresentation,
    actions: AlbumTrackRowActions,
    modifier: Modifier = Modifier
) {
    if (LevyraIsAtelier) return com.luc4n3x.levyra.ui.media.AtelierAlbumTrackRow(index, track, albumTrackSubtitle(track.artist.takeIf { albumTrackShowsArtist(it, albumArtist, false) }.orEmpty(), albumTrackDownloadStatus(presentation, LocalLevyraStrings.current)), presentation.isCurrent, presentation.isPlaying, presentation.selected, presentation.isDownloaded, presentation.downloadProgress.takeIf { presentation.isDownloading && !presentation.isDownloaded }, actions.onPlay, actions.onLongClick, modifier) { AlbumTrackTrailing(track, stage, presentation, actions) }
    if (SkinAlbumTrackRow(
            index, index == count - 1, track,
            track.artist.takeIf { albumTrackShowsArtist(track.artist, albumArtist, true) }.orEmpty(),
            presentation.isCurrent, presentation.selected, actions.onPlay, actions.onLongClick, modifier
        )
    ) return
    val strings = LocalLevyraStrings.current
    val spotify = LevyraIsSpotify
    val showArtist = remember(track.artist, albumArtist, spotify) { albumTrackShowsArtist(track.artist, albumArtist, spotify) }
    val subtitle = albumTrackSubtitle(track.artist.takeIf { showArtist }.orEmpty(), albumTrackDownloadStatus(presentation, strings))
    val duration = albumTrackDuration(track, spotify)
    Row(
        modifier = modifier
            .fillMaxWidth()
            .padding(vertical = 1.dp)
            .heightIn(min = ALBUM_TRACK_ROW_HEIGHT)
            .clip(levyraGroupedListShape(index, count))
            .background(albumTrackRowBackground(presentation, stage, spotify))
            .semantics { this.selected = presentation.selected }
            .combinedClickable(onClick = actions.onPlay, onLongClick = actions.onLongClick)
            .padding(start = LevyraCardDesign.RowHorizontalPadding, top = 8.dp, bottom = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(LevyraPlayerDesign.SpaceMd)
    ) {
        if (!spotify || presentation.isCurrent) AlbumTrackIndex(
            index = index,
            isCurrent = presentation.isCurrent,
            isPlaying = presentation.isPlaying,
            stage = stage
        )
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(LevyraCardDesign.RowLineGap)) {
            Text(
                text = track.title,
                color = if (presentation.isCurrent) stage.accent else stage.content,
                style = LevyraType.contentTitle,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
            if (subtitle.isNotBlank() || presentation.isDownloaded) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(5.dp)
                ) {
                    if (presentation.isDownloaded) {
                        Icon(
                            imageVector = Icons.Rounded.DownloadDone,
                            contentDescription = strings.offline,
                            tint = stage.accent,
                            modifier = Modifier.size(LevyraCardDesign.StatusGlyph)
                        )
                    }
                    if (subtitle.isNotBlank()) {
                        Text(
                            text = subtitle,
                            color = stage.contentMuted,
                            style = LevyraType.metadata,
                            maxLines = 1,
                            overflow = TextOverflow.Ellipsis
                        )
                    }
                }
            }
        }
        if (duration.isNotBlank()) {
            Text(
                text = duration,
                color = stage.contentMuted,
                style = LevyraType.metadata.copy(fontFeatureSettings = "tnum"),
                maxLines = 1
            )
        }
        AlbumTrackTrailing(
            track = track,
            stage = stage,
            presentation = presentation,
            actions = actions
        )
    }
}

@Composable
private fun AlbumTrackTrailing(
    track: Track,
    stage: AlbumStageColors,
    presentation: AlbumTrackRowPresentation,
    actions: AlbumTrackRowActions
) {
    if (presentation.selectionActive) {
        Icon(
            imageVector = if (presentation.selected) {
                Icons.Rounded.CheckCircle
            } else {
                Icons.Rounded.RadioButtonUnchecked
            },
            contentDescription = null,
            tint = if (presentation.selected) stage.accent else stage.contentMuted,
            modifier = Modifier.size(28.dp)
        )
    } else {
        AlbumTrackMenu(
            track = track,
            isFavorite = presentation.isFavorite,
            isDownloaded = presentation.isDownloaded,
            isDownloading = presentation.isDownloading,
            tint = stage.contentMuted,
            onFavorite = actions.onFavorite,
            onDownload = actions.onDownload,
            onAddToPlaylist = actions.onAddToPlaylist,
            onArtist = actions.onArtist
        )
    }
}

@Composable
private fun AlbumTrackIndex(index: Int, isCurrent: Boolean, isPlaying: Boolean, stage: AlbumStageColors) {
    Box(modifier = Modifier.width(ALBUM_TRACK_INDEX_WIDTH), contentAlignment = Alignment.Center) {
        if (isCurrent) {
            ActiveTrackEqualizer(color = stage.accent, isPlaying = isPlaying, width = 18.dp, height = 14.dp)
        } else {
            Text(
                text = "${index + 1}",
                color = stage.content.copy(alpha = 0.72f),
                style = LevyraType.contentTitle.copy(fontWeight = FontWeight.Bold, fontFeatureSettings = "tnum")
            )
        }
    }
}

@Composable
private fun AlbumTrackMenu(
    track: Track,
    isFavorite: Boolean,
    isDownloaded: Boolean,
    isDownloading: Boolean,
    tint: Color,
    onFavorite: () -> Unit,
    onDownload: () -> Unit,
    onAddToPlaylist: () -> Unit,
    onArtist: () -> Unit
) {
    var expanded by remember { mutableStateOf(false) }
    val context = LocalContext.current
    val strings = LocalLevyraStrings.current
    Box {
        IconButton(onClick = { expanded = true }) {
            Icon(Icons.Rounded.MoreVert, contentDescription = strings.options, tint = tint)
        }
        DropdownMenu(expanded = expanded, onDismissRequest = { expanded = false }) {
            DropdownMenuItem(text = { Text(if (isFavorite) strings.removeFromFavorites else strings.addToFavorites) }, leadingIcon = { Icon(if (isFavorite) Icons.Rounded.Favorite else Icons.Rounded.FavoriteBorder, null) }, onClick = { expanded = false; onFavorite() })
            DropdownMenuItem(text = { Text(strings.addToPlaylist) }, leadingIcon = { Icon(Icons.AutoMirrored.Rounded.PlaylistAdd, null) }, onClick = { expanded = false; onAddToPlaylist() })
            DropdownMenuItem(text = { Text(if (isDownloaded) strings.alreadyOffline else strings.download) }, leadingIcon = { Icon(if (isDownloaded) Icons.Rounded.DownloadDone else Icons.Rounded.Download, null) }, enabled = !isDownloading, onClick = { expanded = false; if (!isDownloaded && !isDownloading) onDownload() })
            DropdownMenuItem(text = { Text(strings.openArtist) }, leadingIcon = { Icon(Icons.Rounded.Person, null) }, onClick = { expanded = false; onArtist() })
            DropdownMenuItem(text = { Text(strings.share) }, leadingIcon = { Icon(Icons.Rounded.Share, null) }, onClick = {
                expanded = false
                val shareText = buildString {
                    append(track.title)
                    if (track.artist.isNotBlank()) append(" - ").append(track.artist)
                    if (track.videoUrl.isNotBlank()) append("\n").append(track.videoUrl)
                }
                val intent = Intent(Intent.ACTION_SEND).apply {
                    type = "text/plain"
                    putExtra(Intent.EXTRA_TEXT, shareText)
                }
                context.startActivity(Intent.createChooser(intent, strings.shareSong))
            })
        }
    }
}

@Composable
private fun AlbumTrackSkeleton(stage: AlbumStageColors, modifier: Modifier = Modifier) {
    Row(
        modifier = modifier
            .fillMaxWidth()
            .height(ALBUM_TRACK_ROW_HEIGHT)
            .padding(start = LevyraPlayerDesign.SpaceXs),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(LevyraPlayerDesign.SpaceMd)
    ) {
        Spacer(modifier = Modifier.width(ALBUM_TRACK_INDEX_WIDTH))
        Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(LevyraPlayerDesign.SpaceSm)) {
            Box(
                modifier = Modifier
                    .fillMaxWidth(0.62f)
                    .height(12.dp)
                    .clip(LevyraPlayerDesign.ShapePill)
                    .background(stage.content.copy(alpha = 0.10f))
            )
            Box(
                modifier = Modifier
                    .fillMaxWidth(0.36f)
                    .height(10.dp)
                    .clip(LevyraPlayerDesign.ShapePill)
                    .background(stage.content.copy(alpha = 0.06f))
            )
        }
    }
}

private val ALBUM_TRACK_ROW_HEIGHT = LevyraCardDesign.RowHeight
private val ALBUM_TRACK_INDEX_WIDTH = 30.dp

@Composable
private fun ArtistOverlay(
    state: LevyraUiState,
    onPlay: (Track) -> Unit,
    onPlayFrom: (List<Track>, Track) -> Unit,
    onPlayAll: (List<Track>) -> Unit,
    onToggleFavorite: (Track) -> Unit,
    onPlayTracksNext: (List<Track>) -> Unit,
    onAddTracksToQueue: (List<Track>) -> Unit,
    onToggleFavorites: (List<Track>) -> Unit,
    onDislikeTracks: (List<Track>) -> Unit,
    onExportTracks: (List<Track>) -> Unit,
    onAddTracksToPlaylist: (String, List<Track>) -> Unit,
    onCreatePlaylistWithTracks: (String, List<Track>) -> Unit,
    onToggleFollow: () -> Unit,
    onToggleExclude: (String, String) -> Unit,
    onTogglePinToHome: (ArtistProfile) -> Unit,
    onOpenArtist: (ArtistHit) -> Unit,
    onOpenRelease: (ArtistRelease, String) -> Unit,
    onOpenPlaylist: (PlaylistHit) -> Unit,
    onTogglePlayback: () -> Unit,
    onOpenPlayer: () -> Unit,
    onClose: () -> Unit,
    appleArtist: AppleArtistPage? = null,
    onOpenAlbum: (AlbumHit) -> Unit = {},
    onOpenApplePlaylist: (PlaylistHit) -> Unit = {},
    onOpenArtistByName: (String) -> Unit = {}
) {
    val profile = state.artistProfile
    val likedTracks = remember(state.favorites, profile) {
        profile?.let { com.luc4n3x.levyra.domain.likedTracksByArtist(state.favorites, it) }.orEmpty()
    }
    val selection = rememberTrackSelectionState()
    var batchAddTargets by remember { mutableStateOf<List<Track>>(emptyList()) }
    val artistSelectionScopeKey = profile?.browseId?.ifBlank { profile.name }.orEmpty()
    var favoritesExpanded by rememberSaveable(artistSelectionScopeKey, "favorites", likedTracks.size) {
        mutableStateOf(false)
    }
    val rankedPopularTracks = remember(profile?.topSongs) {
        profile?.topSongs.orEmpty()
            .distinctBy { track -> track.id.ifBlank { track.artist + "|" + track.title } }
            .take(ARTIST_POPULAR_MAX_COUNT)
    }
    var popularVisibleCount by rememberSaveable(artistSelectionScopeKey, "popular", rankedPopularTracks.size) {
        mutableIntStateOf(ARTIST_POPULAR_COLLAPSED_COUNT)
    }
    val selectableTracks = remember(
        likedTracks,
        rankedPopularTracks,
        favoritesExpanded,
        popularVisibleCount
    ) {
        val visibleFavorites = likedTracks
            .distinctBy(::trackSelectionKey)
            .let { tracks ->
                if (favoritesExpanded) tracks else tracks.take(ARTIST_FAVORITES_COLLAPSED_COUNT)
            }
        val visiblePopular = rankedPopularTracks.take(popularVisibleCount)
        (visibleFavorites + visiblePopular).distinctBy(::trackSelectionKey)
    }
    val selectableIds = remember(selectableTracks) { selectableTracks.map(::trackSelectionKey) }
    val selectedTracks = remember(selectableTracks, selection.selectedIds) {
        selection.resolveSelected(selectableTracks, ::trackSelectionKey)
    }
    LaunchedEffect(selectableIds) { selection.retainAvailable(selectableIds) }
    BackHandler(enabled = selection.isActive) { selection.exit() }
    val pinnedToHome = profile != null && SpeedDial.artistKey(profile.name, profile.browseId)
        ?.let { key -> state.speedDialPins.any { it.key == key } } == true
    val isFollowed = profile != null && (
        (profile.browseId.isNotBlank() && profile.browseId in state.followedArtistKeys) ||
            profile.name.trim().lowercase() in state.followedArtistKeys
        )
    val isExcluded = profile != null && state.artistExclusions.let { exclusions ->
        exclusions.excludesBrowseId(profile.browseId) || exclusions.excludesArtistName(profile.name)
    }
    val accentStart = profile?.let { Color(it.accentStart) } ?: LevyraCyan
    val accentEnd = profile?.let { Color(it.accentEnd) } ?: LevyraViolet
    val strings = LocalLevyraStrings.current
    val animated = state.animationsEnabled
    val showArtistError = shouldShowArtistError(
        hasError = state.artistError != null,
        hasProfile = profile != null
    )
    val artistListState = rememberSaveable(
        state.artistListStateKey,
        saver = LazyListState.Saver
    ) {
        LazyListState()
    }
    val heroArtwork = profile?.let { it.thumbnailUrl.ifBlank { it.bannerUrl } }.orEmpty()
    val fallbackPalette = remember(accentStart, accentEnd) {
        ArtworkPalette(accentStart.toArgb(), accentEnd.toArgb())
    }
    val artistPalette by rememberArtworkPalette(
        paletteKey = profile?.let { "artist:" + it.browseId.ifBlank { it.name.trim().lowercase() } }.orEmpty(),
        artworkUrl = heroArtwork,
        fallback = fallbackPalette
    )
    val nocturne = LevyraIsNocturne
    val atmosphereTargets = remember(artistPalette, nocturne) {
        if (nocturne) Nocturne78Palette.black to Nocturne78Palette.cyan else {
        val pair = harmonizePlayerAccents(Color(artistPalette.start), Color(artistPalette.end))
        playerAmbienceOf(pair.primary, pair.secondary).tint to playerHighlightOf(pair.primary, pair.secondary)
        }
    }
    val atmosphere by animateColorAsState(
        targetValue = atmosphereTargets.first,
        animationSpec = LevyraMotion.spec(animated, LevyraMotion.palette()),
        label = "artist-atmosphere"
    )
    val highlight by animateColorAsState(
        targetValue = atmosphereTargets.second,
        animationSpec = LevyraMotion.spec(animated, LevyraMotion.palette()),
        label = "artist-highlight"
    )
    val heroEntranceKey = profile?.let { it.browseId.ifBlank { it.name } }.orEmpty()
    val heroEntrance = remember(heroEntranceKey) { Animatable(if (animated) 0f else 1f) }
    LaunchedEffect(heroEntranceKey, animated) {
        if (!animated) {
            heroEntrance.snapTo(1f)
            return@LaunchedEffect
        }
        heroEntrance.animateTo(
            1f,
            tween(LevyraMotion.Durations.Long + 280, easing = LevyraMotion.Easings.Decelerate)
        )
    }

    BoxWithConstraints(
        modifier = Modifier
            .fillMaxSize()
            .background(LevyraBlack)
            .windowInsetsPadding(LevyraHorizontalSafeInsets)
    ) {
        val density = LocalDensity.current
        val heroCap = minOf(ArtistHeroMaxHeight, maxHeight * ArtistHeroViewportShare)
        val heroHeight = if (LevyraIsAppleMusic) (maxWidth / AppleMusicDesign.artistHeroAspect).coerceAtMost(heroCap) else (maxWidth * ArtistHeroAspect).coerceAtMost(heroCap).coerceAtLeast(minOf(ArtistHeroMinHeight, heroCap))
        val heroHeightPx = with(density) { heroHeight.toPx() }
        val heroWidthPx = with(density) { maxWidth.roundToPx() }
        var appleHeroTimedOut by remember(state.artistListStateKey) { mutableStateOf(false) }
        val appleHeroEnabled = LevyraUsesAppleArtistHero
        val heroVisible = profile != null
        LaunchedEffect(state.artistListStateKey, appleHeroEnabled, heroVisible) {
            if (!appleHeroEnabled || !heroVisible) return@LaunchedEffect
            delay(AppleHeroWaitMs)
            appleHeroTimedOut = true
        }
        val awaitingAppleHero = appleHeroEnabled && appleArtist == null && !appleHeroTimedOut
        val fittedHeroArtwork = remember(heroArtwork, heroWidthPx, heroHeightPx, appleArtist, awaitingAppleHero) {
            when {
                awaitingAppleHero -> ""
                else -> appleArtist?.heroArtworkUrl(heroWidthPx.coerceAtMost(AppleHeroArtworkMaxPx))?.takeIf(String::isNotBlank)
                    ?: LevyraPersonalOrbit.croppedArtworkUrl(heroArtwork, heroWidthPx, heroHeightPx.roundToInt())
            }
        }
        val heroMotion = when {
            awaitingAppleHero -> null
            else -> remember(appleArtist) { appleArtist?.heroMotion() } ?: state.artistMotionArtwork
        }
        val topBarPx = with(density) { (WindowInsets.statusBars.asPaddingValues().calculateTopPadding() + ArtistTopBarHeight).toPx() }
        val heroScroll: () -> Float = {
            if (artistListState.firstVisibleItemIndex == 0) {
                artistListState.firstVisibleItemScrollOffset.toFloat()
            } else {
                heroHeightPx
            }
        }
        val collapse: () -> Float = {
            (heroScroll() / (heroHeightPx - topBarPx).coerceAtLeast(1f)).coerceIn(0f, 1f)
        }
        val titleDocked by remember(artistListState, heroHeightPx, topBarPx) {
            derivedStateOf { collapse() >= ArtistTitleDockStart }
        }

        val artistBottomPadding = levyraTabContentBottomPadding(state.currentTrack != null)
        val appleClosingOwnsBottom = LevyraIsAppleMusic && profile != null
        LazyColumn(
            state = artistListState,
            modifier = Modifier.fillMaxSize(),
            contentPadding = PaddingValues(bottom = selection.listBottomPadding(if (appleClosingOwnsBottom) 0.dp else artistBottomPadding)),
            verticalArrangement = Arrangement.spacedBy(18.dp)
        ) {
            when {
                state.artistLoading && profile == null -> {
                    item {
                        Spacer(modifier = Modifier.statusBarsPadding().height(56.dp))
                        Box(modifier = Modifier.fillMaxWidth().padding(top = 150.dp), contentAlignment = Alignment.Center) {
                            LevyraLoadingIndicator(color = LevyraCyan)
                        }
                    }
                }
                showArtistError -> {
                    item {
                        Column(
                            modifier = Modifier.fillMaxWidth().statusBarsPadding().padding(horizontal = 20.dp, vertical = 60.dp),
                            verticalArrangement = Arrangement.spacedBy(20.dp)
                        ) {
                            Text(strings.artistProfileUnavailable, color = LevyraMuted, fontSize = 15.sp, fontWeight = FontWeight.SemiBold)
                        }
                    }
                }
                else -> {
                    val artist = requireNotNull(profile) { "Artist profile required outside loading and error states" }
                    item(key = "artist-hero", contentType = "artist-hero") {
                        Column(modifier = Modifier.fillMaxWidth()) {
                            ArtistHero(
                                profile = artist,
                                artworkUrl = fittedHeroArtwork,
                                height = heroHeight,
                                motionArtwork = heroMotion,
                                motionEnabled = state.animationsEnabled && state.motionArtworkEnabled,
                                animated = animated,
                                entrance = { heroEntrance.value },
                                canvasQuality = state.interfaceSettings.canvasQuality,
                                scroll = heroScroll,
                                collapse = collapse,
                                onPlay = artist.topSongs.firstOrNull()?.let { track -> { onPlay(track) } },
                                awaitingArtwork = awaitingAppleHero
                            )
                            if (LevyraIsAppleMusic) {
                                val appleRelease = appleArtist?.latestRelease
                                if (appleRelease != null) {
                                    AppleMusicArtistLatestRelease(
                                        caption = appleRelease.headline,
                                        title = appleRelease.item.title,
                                        detail = appleRelease.detail,
                                        artworkUrl = appleRelease.item.artworkUrl(AppleReleaseArtworkPx),
                                        explicit = appleRelease.item.explicit,
                                        onOpen = { onOpenAlbum(appleRelease.item.toArtistAlbumHit(artist.name)) },
                                        modifier = Modifier.padding(top = 20.dp)
                                    )
                                } else {
                                    appleMusicLatestRelease(artist)?.let { release ->
                                        AppleMusicArtistLatestRelease(
                                            caption = release.appleLatestCaption(),
                                            title = release.title,
                                            detail = "",
                                            artworkUrl = release.thumbnailUrl,
                                            explicit = release.explicit,
                                            onOpen = { onOpenRelease(release, artist.name) },
                                            modifier = Modifier.padding(top = 20.dp)
                                        )
                                    }
                                }
                            } else ArtistActionBar(
                                profile = artist,
                                isFollowed = isFollowed,
                                highlight = highlight,
                                onPlay = artist.topSongs.firstOrNull()?.let { track -> { onPlay(track) } },
                                onShuffle = artist.topSongs
                                    .takeIf { it.size > 1 }
                                    ?.let { songs -> { onPlayAll(songs.shuffled()) } },
                                onToggleFollow = onToggleFollow,
                                isExcluded = isExcluded,
                                onToggleExclude = { onToggleExclude(artist.browseId, artist.name) },
                                isPinnedToHome = pinnedToHome,
                                onTogglePinToHome = { onTogglePinToHome(artist) }
                            )
                            if (artist.hasBio && !LevyraIsSpotify && !LevyraIsAppleMusic) {
                                ArtistBio(
                                    biography = requireNotNull(artist.biography),
                                    accentStart = accentStart,
                                    accentEnd = accentEnd,
                                    modifier = Modifier.padding(start = 16.dp, end = 16.dp, top = 20.dp, bottom = 8.dp)
                                )
                            }
                        }
                    }
                    if (state.artistLoading && artist.topSongs.isEmpty()) {
                        item(key = "artist-loading", contentType = "artist-loading") {
                            Box(modifier = Modifier.fillMaxWidth().padding(top = 28.dp), contentAlignment = Alignment.Center) {
                                LevyraLoadingIndicator(
                                    modifier = Modifier.size(24.dp),
                                    color = highlight
                                )
                            }
                        }
                    }
                    if (likedTracks.isNotEmpty()) {
                        item(
                            key = "artist-liked-tracks",
                            contentType = "artist-liked-tracks"
                        ) {
                            ArtistFavoriteTracksShelf(
                                tracks = likedTracks,
                                currentId = state.currentTrack?.id,
                                isPlaying = state.isPlaying,
                                isResolving = state.isResolving,
                                expanded = favoritesExpanded,
                                onExpandedChange = { favoritesExpanded = it },
                                selection = selection,
                                onPlay = { track -> onPlayFrom(likedTracks, track) }
                            )
                        }
                    }
                    if (artist.topSongs.isNotEmpty()) {
                        item(
                            key = "artist-popular-tracks",
                            contentType = "artist-popular-tracks"
                        ) {
                            ArtistPopularTracksShelf(
                                tracks = artist.topSongs,
                                currentId = state.currentTrack?.id,
                                isPlaying = state.isPlaying,
                                isResolving = state.isResolving,
                                visibleCount = popularVisibleCount,
                                onVisibleCountChange = { popularVisibleCount = it },
                                selection = selection,
                                onPlay = onPlay,
                                onPlayAll = onPlayAll
                            )
                        }
                    }
                    val videoTitle = if (LevyraIsAppleMusic) appleArtistInfoCopy(strings.code).topVideos else strings.video
                    val videoItems: LazyListScope.() -> Unit = {
                        if (artist.videos.isNotEmpty()) {
                            item(key = "artist-videos-title", contentType = "artist-section-title") { Box(modifier = Modifier.padding(horizontal = 20.dp)) { ArtistSectionTitle(videoTitle) } }
                            item(key = "artist-videos", contentType = "artist-video-row") {
                                LazyRow(
                                    horizontalArrangement = Arrangement.spacedBy(12.dp),
                                    contentPadding = PaddingValues(start = 20.dp, end = 20.dp)
                                ) {
                                    val shownVideos = artist.videos.take(20)
                                    items(shownVideos, key = { "artist-video-${it.id}" }) { track ->
                                        VideoGlassCard(
                                            track = track,
                                            isCurrent = track.id == state.currentTrack?.id,
                                            isPlaying = state.isPlaying && track.id == state.currentTrack?.id,
                                            onClick = { onPlayFrom(shownVideos, track) }
                                        )
                                    }
                                }
                            }
                        }
                    }
                    val applePage = appleArtist?.takeIf { page -> page.shelves.any { it.style != AppleArtistShelfStyle.Artists } }
                    if (LevyraIsAppleMusic && applePage != null) {
                        appleMusicArtistShelves(
                            applePage,
                            AppleArtistActions(
                                openAlbum = { item -> onOpenAlbum(item.toArtistAlbumHit(artist.name)) },
                                openPlaylist = { item -> onOpenApplePlaylist(item.toApplePlaylistHit()) },
                                playVideo = { item ->
                                    val match = artist.videos.firstOrNull { video -> appleVideoTitleMatches(video.title, item.title) }
                                    if (match != null) {
                                        onPlayFrom(artist.videos.take(20), match)
                                    } else {
                                        AppleCatalogTracks.track(item.title, item.subtitle.ifBlank { artist.name })?.let { track -> onPlayFrom(listOf(track), track) }
                                    }
                                },
                                openArtist = onOpenArtistByName
                            )
                        )
                    } else if (LevyraIsAppleMusic) {
                        artistReleaseSection("artist-albums", strings.albumsPlain, artist.albums, artist.name, onOpenRelease)
                        videoItems()
                        artistPlaylistSection("artist-playlists", strings.playlists, artist.artistPlaylists, onOpenPlaylist)
                        artistReleaseSection("artist-singles", strings.singlesAndEps, artist.singles, artist.name, onOpenRelease)
                        artistReleaseSection("artist-compilations", strings.compilations, artist.compilations, artist.name, onOpenRelease)
                        artistPlaylistSection("artist-featured-on", searchDiscographyCopy(strings.code).featuredOn, artist.featuredPlaylists, onOpenPlaylist)
                    } else {
                        artistReleaseItems(artist, strings, onOpenRelease)
                        artistPlaylistItems(artist, strings, onOpenPlaylist)
                        videoItems()
                    }
                    artistClosingItems(artist, heroArtwork, strings, onOpenArtist, appleArtist, onOpenArtistByName, artistBottomPadding)
                }
            }
        }

        state.currentTrack?.takeUnless { selection.isActive }?.let { current ->
            AlbumNowPlayingDock(
                track = current,
                isPlaying = state.isPlaying,
                isResolving = state.isResolving,
                progress = progressOf(state.positionMs, state.durationMs),
                animated = state.animationsEnabled,
                onToggle = onTogglePlayback,
                onOpenPlayer = onOpenPlayer,
                modifier = Modifier
                    .align(Alignment.BottomCenter)
                    .navigationBarsPadding()
                    .padding(start = 18.dp, end = 18.dp, bottom = 14.dp)
            )
        }

        TrackSelectionBar(
            state = selection,
            allVisibleIds = selectableIds,
            actions = trackSelectionActions(
                state = selection,
                selectedTracks = selectedTracks,
                onPlayNext = onPlayTracksNext,
                onAddToQueue = onAddTracksToQueue,
                onAddToPlaylist = { batchAddTargets = it },
                onFavorite = onToggleFavorites,
                onDownload = onExportTracks,
                onDislike = onDislikeTracks
            ),
            modifier = Modifier
                .align(Alignment.BottomCenter)
                .padding(horizontal = 12.dp)
        )

        if (batchAddTargets.isNotEmpty()) {
            com.luc4n3x.levyra.ui.library.AddTracksToPlaylistDialog(
                tracks = batchAddTargets,
                playlists = state.playlists,
                onDismiss = { batchAddTargets = emptyList() },
                onAdd = { playlistId ->
                    onAddTracksToPlaylist(playlistId, batchAddTargets)
                    batchAddTargets = emptyList()
                    selection.exit()
                },
                onCreate = { name ->
                    onCreatePlaylistWithTracks(name, batchAddTargets)
                    batchAddTargets = emptyList()
                    selection.exit()
                }
            )
        }

        ArtistTopBar(
            title = profile?.name,
            atmosphere = atmosphere,
            collapse = collapse,
            titleDocked = titleDocked,
            onClose = onClose,
            modifier = Modifier.align(Alignment.TopCenter),
            actions = {
                if (LevyraIsAppleMusic && profile != null) {
                    var appleMenuExpanded by remember(profile.browseId, profile.name) { mutableStateOf(false) }
                    AppleMusicArtistTopActions(
                        isFollowed = isFollowed,
                        onToggleFollow = onToggleFollow,
                        onMore = { appleMenuExpanded = true }
                    ) {
                        ArtistOptionsMenu(
                            expanded = appleMenuExpanded,
                            onDismiss = { appleMenuExpanded = false },
                            isExcluded = isExcluded,
                            onToggleExclude = { onToggleExclude(profile.browseId, profile.name) },
                            isPinnedToHome = pinnedToHome,
                            onTogglePinToHome = { onTogglePinToHome(profile) },
                            onShuffle = profile.topSongs.takeIf { it.size > 1 }?.let { songs -> { onPlayAll(songs.shuffled()) } }
                        )
                    }
                }
            }
        )
    }
}

private fun LazyListScope.artistClosingItems(
    artist: ArtistProfile,
    heroArtwork: String,
    strings: LevyraStrings,
    onOpenArtist: (ArtistHit) -> Unit,
    appleArtist: AppleArtistPage? = null,
    onOpenArtistByName: (String) -> Unit = {},
    bottomPadding: Dp = 0.dp
) {
    if (LevyraIsSpotify) {
        item(key = "spotify-artist-about", contentType = "spotify-artist-about") {
            SpotifyArtistAbout(
                imageUrl = heroArtwork,
                name = artist.name,
                audience = artist.monthlyListeners.ifBlank { artist.subscribers },
                biography = artist.biography?.text.orEmpty(),
                modifier = Modifier.padding(top = 12.dp)
            )
        }
        item(key = "spotify-artist-fans", contentType = "spotify-artist-fans") {
            SpotifyFansAlsoLike(artist.relatedArtists, onOpenArtist, Modifier.padding(top = 12.dp))
        }
        return
    }
    if (LevyraIsAppleMusic) {
        appleMusicArtistClosingItems(artist, appleArtist, strings, onOpenArtistByName, bottomPadding)
        return
    }
    if (artist.relatedArtists.isNotEmpty()) {
        item { Box(modifier = Modifier.padding(horizontal = 20.dp)) { ArtistSectionTitle(strings.similarArtists) } }
        item { Box(modifier = Modifier.padding(start = 20.dp)) { ArtistHitRow(artist.relatedArtists, onClick = onOpenArtist) } }
    }
}

private const val ARTIST_FAVORITES_COLLAPSED_COUNT = 4
private const val ARTIST_POPULAR_COLLAPSED_COUNT = 5
private const val ARTIST_POPULAR_MAX_COUNT = 50
private const val ARTIST_POPULAR_REVEAL_STEP = 10

@Composable
private fun ArtistFavoriteTracksShelf(
    tracks: List<Track>,
    currentId: String?,
    isPlaying: Boolean,
    isResolving: Boolean,
    expanded: Boolean,
    onExpandedChange: (Boolean) -> Unit,
    selection: TrackSelectionState,
    onPlay: (Track) -> Unit
) {
    val strings = LocalLevyraStrings.current
    val distinctTracks = remember(tracks) { tracks.distinctBy(::trackSelectionKey) }
    if (distinctTracks.isEmpty()) return
    val visibleTracks = remember(distinctTracks, expanded) {
        if (expanded) distinctTracks else distinctTracks.take(ARTIST_FAVORITES_COLLAPSED_COUNT)
    }

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 14.dp),
        verticalArrangement = Arrangement.spacedBy(2.dp)
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 6.dp, vertical = 2.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    text = strings.favoritesPlain,
                    color = LevyraText,
                    fontSize = 22.sp,
                    lineHeight = LevyraTypeRhythm.lineHeight(22.sp),
                    fontWeight = FontWeight.Bold,
                    letterSpacing = (-0.45).sp
                )
                Text(
                    text = strings.formatTrackCount(distinctTracks.size),
                    color = LevyraMuted,
                    fontSize = 12.5.sp,
                    fontWeight = FontWeight.Medium
                )
            }
            if (distinctTracks.size > ARTIST_FAVORITES_COLLAPSED_COUNT) {
                TextButton(onClick = { onExpandedChange(!expanded) }) {
                    Text(
                        text = if (expanded) strings.showLess else strings.showAll,
                        color = LevyraCyan,
                        fontWeight = FontWeight.Bold
                    )
                }
            }
        }

        visibleTracks.forEachIndexed { index, track ->
            val key = trackSelectionKey(track)
            val current = track.id == currentId
            ArtistPopularTrackRow(
                rank = index + 1,
                track = track,
                isCurrent = current,
                isPlaying = isPlaying && current,
                isResolving = isResolving && current,
                selected = selection.isSelected(key),
                selectionActive = selection.isActive,
                onLongClick = { selection.start(key) },
                onPlay = {
                    if (selection.isActive) selection.toggle(key) else onPlay(track)
                }
            )
        }
    }
}

@Composable
private fun ArtistPopularTracksShelf(
    tracks: List<Track>,
    currentId: String?,
    isPlaying: Boolean,
    isResolving: Boolean,
    visibleCount: Int,
    onVisibleCountChange: (Int) -> Unit,
    selection: TrackSelectionState,
    onPlay: (Track) -> Unit,
    onPlayAll: (List<Track>) -> Unit
) {
    val strings = LocalLevyraStrings.current
    val distinctTracks = remember(tracks) {
        tracks.distinctBy { track -> track.id.ifBlank { track.artist + "|" + track.title } }
    }
    if (distinctTracks.isEmpty()) return
    val rankedTracks = remember(distinctTracks) { distinctTracks.take(ARTIST_POPULAR_MAX_COUNT) }

    val shownCount = visibleCount.coerceIn(ARTIST_POPULAR_COLLAPSED_COUNT, ARTIST_POPULAR_MAX_COUNT)
        .coerceAtMost(rankedTracks.size)
    val visibleTracks = remember(rankedTracks, shownCount) { rankedTracks.take(shownCount) }
    val animationsEnabled = LocalAnimationsEnabled.current
    if (LevyraIsAppleMusic) {
        Column(Modifier.fillMaxWidth()) {
            AppleMusicSectionHeader(strings.popularTracks, onSeeAll = { onPlayAll(distinctTracks) })
            AppleMusicSongColumns(
                rankedTracks, 4, currentId, com.luc4n3x.levyra.ui.i18n.LevyraAppleMusicStrings.forCode(strings.code).explicit,
                { track -> if (selection.isActive) selection.toggle(trackSelectionKey(track)) else onPlay(track) },
                { track -> selection.start(trackSelectionKey(track)) }
            )
        }
        return
    }

    Column(modifier = Modifier.fillMaxWidth()) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 20.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            ArtistPopularHeader(strings, onPlayAll = { onPlayAll(distinctTracks) })
        }

        Spacer(modifier = Modifier.height(8.dp))

        Column(
            modifier = Modifier
                .fillMaxWidth()
                .then(
                    if (animationsEnabled) {
                        Modifier.animateContentSize(animationSpec = LevyraMotion.emphasized())
                    } else {
                        Modifier
                    }
                )
                .padding(horizontal = 12.dp)
        ) {
            visibleTracks.forEachIndexed { index, track ->
                val isCurrent = track.id == currentId
                val selectionKey = trackSelectionKey(track)
                ArtistPopularTrackRow(
                    rank = index + 1,
                    track = track,
                    isCurrent = isCurrent,
                    isPlaying = isPlaying && isCurrent,
                    isResolving = isResolving && isCurrent,
                    selected = selection.isSelected(selectionKey),
                    selectionActive = selection.isActive,
                    onLongClick = { selection.start(selectionKey) },
                    onPlay = {
                        if (selection.isActive) selection.toggle(selectionKey) else onPlay(track)
                    }
                )
            }
        }

        if (rankedTracks.size > ARTIST_POPULAR_COLLAPSED_COUNT) {
            Spacer(modifier = Modifier.height(12.dp))
            ArtistPopularReveal(
                shown = shownCount,
                total = rankedTracks.size,
                onShowMore = {
                    onVisibleCountChange(
                        (shownCount + ARTIST_POPULAR_REVEAL_STEP).coerceAtMost(rankedTracks.size)
                    )
                },
                onShowLess = { onVisibleCountChange(ARTIST_POPULAR_COLLAPSED_COUNT) }
            )
        }
    }
}

@Composable
private fun RowScope.ArtistPopularHeader(strings: LevyraStrings, onPlayAll: () -> Unit) {
    val spotify = LevyraIsSpotify
    Text(
        text = if (spotify) LevyraSpotifySkinStrings.forCode(strings.code).popular else strings.popularTracks,
        color = LevyraText,
        style = LevyraType.sectionTitle,
        modifier = Modifier
            .weight(1f)
            .semantics { heading() }
    )
    if (!spotify) LevyraPlayAllButton(onClick = onPlayAll)
}

@Composable
private fun ArtistPopularReveal(shown: Int, total: Int, onShowMore: () -> Unit, onShowLess: () -> Unit) {
    if (!LevyraIsSpotify) {
        ArtistPopularRevealBar(shown, total, onShowMore, onShowLess)
        return
    }
    val strings = LocalLevyraStrings.current
    val more = shown < total
    SpotifyOutlinePill(if (more) strings.showMore else strings.showLess, onClick = if (more) onShowMore else onShowLess)
}

@Composable
private fun ArtistPopularRevealBar(
    shown: Int,
    total: Int,
    onShowMore: () -> Unit,
    onShowLess: () -> Unit
) {
    val strings = LocalLevyraStrings.current
    val animationsEnabled = LocalAnimationsEnabled.current
    val fraction by animateFloatAsState(
        targetValue = if (total > 0) shown.toFloat() / total else 0f,
        animationSpec = if (animationsEnabled) LevyraMotion.emphasized() else snap(),
        label = "artist-popular-reveal"
    )
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 20.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(10.dp)
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(10.dp)
        ) {
            Box(
                modifier = Modifier
                    .weight(1f)
                    .height(3.dp)
                    .clip(CircleShape)
                    .background(LevyraText.copy(alpha = 0.08f))
            ) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth(fraction)
                        .fillMaxHeight()
                        .clip(CircleShape)
                        .background(LevyraCyan.copy(alpha = 0.72f))
                )
            }
            Text(
                text = "$shown / $total",
                color = LevyraMuted,
                style = LevyraType.caption,
                maxLines = 1
            )
        }
        Row(
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            if (shown < total) {
                ArtistTonalPill(
                    text = strings.showMore,
                    icon = Icons.Rounded.KeyboardArrowDown,
                    onClick = onShowMore
                )
            }
            if (shown > ARTIST_POPULAR_COLLAPSED_COUNT) {
                ArtistTonalPill(
                    text = strings.showLess,
                    icon = Icons.Rounded.KeyboardArrowUp,
                    onClick = onShowLess
                )
            }
        }
    }
}

@Composable
private fun ArtistTonalPill(
    text: String,
    icon: ImageVector,
    onClick: () -> Unit
) {
    val interaction = remember { MutableInteractionSource() }
    val corner = levyraExpressiveCorner(
        interactionSource = interaction,
        rest = 20.dp,
        pressed = 12.dp,
        label = "artist-pill-corner"
    )
    Row(
        modifier = Modifier
            .heightIn(min = 40.dp)
            .clip(RoundedCornerShape(corner))
            .background(LevyraText.copy(alpha = 0.08f))
            .levyraPressable(
                onClick = onClick,
                pressedScale = LevyraPressScale.Control,
                interactionSource = interaction,
                role = Role.Button
            )
            .padding(start = 12.dp, end = 16.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(6.dp)
    ) {
        Icon(imageVector = icon, contentDescription = null, tint = LevyraText, modifier = Modifier.size(18.dp))
        Text(text = text, color = LevyraText, style = LevyraType.metadata.copy(fontWeight = FontWeight.Bold), maxLines = 1)
    }
}

@Composable
private fun ArtistPopularTrackRow(
    rank: Int,
    track: Track,
    isCurrent: Boolean,
    isPlaying: Boolean,
    isResolving: Boolean,
    selected: Boolean,
    selectionActive: Boolean,
    onLongClick: () -> Unit,
    onPlay: () -> Unit
) {
    val strings = LocalLevyraStrings.current
    val subtitle = remember(track.youtubeViewCount, track.durationMs, strings.code) {
        val plays = formatSearchViewCount(track.youtubeViewCount, strings.code)
        plays.ifBlank { formatDuration(track.durationMs).takeIf { it != "--:--" }.orEmpty() }
    }
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clip(LevyraCardDesign.ArtworkShape)
            .background(artistPopularRowBackground(selected, isCurrent))
            .semantics { this.selected = selected }
            .heightIn(min = LevyraCardDesign.RowHeight)
            .combinedClickable(onClick = onPlay, onLongClick = onLongClick)
            .padding(horizontal = 8.dp, vertical = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(LevyraCardDesign.RowTextGap)
    ) {
        ArtistPopularRank(rank, isCurrent)

        Box(
            modifier = Modifier
                .size(LevyraCardDesign.RowThumb)
                .clip(LevyraCardDesign.ThumbShape)
                .background(LevyraPanelSoft),
            contentAlignment = Alignment.Center
        ) {
            CoverImage(
                track = track,
                modifier = Modifier.fillMaxSize()
            )
        }

        LevyraRowText(
            title = track.title,
            subtitle = subtitle,
            titleColor = if (isCurrent) LevyraCyan else LevyraText,
            modifier = Modifier.weight(1f)
        )

        Box(
            modifier = Modifier.size(32.dp),
            contentAlignment = Alignment.Center
        ) {
            when {
                selectionActive -> Icon(
                    imageVector = if (selected) Icons.Rounded.CheckCircle else Icons.Rounded.RadioButtonUnchecked,
                    contentDescription = null,
                    tint = if (selected) LevyraCyan else LevyraMuted,
                    modifier = Modifier.size(26.dp)
                )
                isResolving -> LevyraLoadingIndicator(
                    modifier = Modifier.size(18.dp),
                    color = LevyraCyan
                )
                isCurrent -> LevyraPlayingIndicator(
                    playing = isPlaying,
                    color = LevyraCyan,
                    size = 18.dp,
                    contentDescription = strings.playing
                )
            }
        }
    }
}

@Composable
private fun ArtistPopularRank(rank: Int, isCurrent: Boolean) {
    if (LevyraIsSpotify) {
        SpotifyArtistRank(rank, isCurrent)
        return
    }
    Text(
        text = rank.toString(),
        color = if (isCurrent) LevyraCyan else LevyraText.copy(alpha = 0.86f),
        style = LevyraType.sectionTitle.copy(
            fontSize = 21.sp,
            lineHeight = 23.sp,
            fontWeight = FontWeight.Black,
            letterSpacing = (-0.8).sp,
            fontFeatureSettings = "tnum"
        ),
        textAlign = TextAlign.Center,
        maxLines = 1,
        modifier = Modifier.width(30.dp)
    )
}

private fun artistPopularRowBackground(selected: Boolean, isCurrent: Boolean): Color = when {
    selected -> LevyraCyan.copy(alpha = 0.16f)
    isCurrent && !LevyraIsSpotify -> LevyraText.copy(alpha = 0.06f)
    else -> Color.Transparent
}

@Composable
internal fun ArtistSectionTitle(title: String) {
    Text(
        text = title,
        color = LevyraText,
        style = LevyraType.sectionTitle,
        modifier = Modifier.semantics { heading() }
    )
}

private const val ArtistHeroAspect = 1.08f
private val ArtistHeroMinHeight = 340.dp
private val ArtistHeroMaxHeight = 520.dp
private const val ArtistHeroViewportShare = 0.62f
private val ArtistTopBarHeight = 64.dp
private const val ArtistHeroParallax = 0.45f
private const val ArtistTitleDockStart = 0.82f
private val ArtistNameRise = 14.dp

@Composable
private fun ArtistFollowButton(isFollowed: Boolean, onClick: () -> Unit) {
    val strings = LocalLevyraStrings.current
    if (SkinFollowPill(isFollowed, strings.followArtist, strings.followingArtist, onClick)) return
    val animated = LocalAnimationsEnabled.current
    val followProgress by animateFloatAsState(
        targetValue = if (isFollowed) 1f else 0f,
        animationSpec = LevyraMotion.spec(animated, LevyraMotion.standard()),
        label = "artist-follow-progress"
    )
    val container by animateColorAsState(
        targetValue = if (isFollowed) Color.Transparent else LevyraText.copy(alpha = 0.10f),
        animationSpec = LevyraMotion.spec(animated, LevyraMotion.standard()),
        label = "artist-follow-container"
    )
    val outline by animateColorAsState(
        targetValue = LevyraText.copy(alpha = if (isFollowed) 0.24f else 0f),
        animationSpec = LevyraMotion.spec(animated, LevyraMotion.standard()),
        label = "artist-follow-outline"
    )
    val interaction = remember { MutableInteractionSource() }
    val corner = levyraExpressiveToggleCorner(
        checked = isFollowed,
        unchecked = 24.dp,
        checkedCorner = 14.dp,
        label = "artist-follow-corner"
    )
    val pressedCorner = levyraExpressiveCorner(
        interactionSource = interaction,
        rest = corner,
        pressed = 12.dp,
        label = "artist-follow-press"
    )
    Surface(
        color = container,
        shape = RoundedCornerShape(pressedCorner),
        border = BorderStroke(1.dp, outline),
        modifier = Modifier
            .heightIn(min = 48.dp)
            .levyraPressable(
                onClick = onClick,
                pressedScale = LevyraPressScale.Control,
                interactionSource = interaction,
                role = Role.Switch,
                haptic = LevyraHapticAction.Confirm
            )
            .clearAndSetSemantics {
                contentDescription = strings.followArtist
                toggleableState = ToggleableState(isFollowed)
                role = Role.Switch
            }
    ) {
        Box(
            modifier = Modifier.padding(horizontal = 20.dp, vertical = 12.dp),
            contentAlignment = Alignment.Center
        ) {
            ArtistFollowLabel(
                icon = Icons.Rounded.PersonAdd,
                text = strings.followArtist,
                color = LevyraText,
                visibility = { 1f - followProgress }
            )
            ArtistFollowLabel(
                icon = Icons.Rounded.Check,
                text = strings.followingArtist,
                color = LevyraText,
                visibility = { followProgress }
            )
        }
    }
}

@Composable
private fun ArtistFollowLabel(
    icon: ImageVector,
    text: String,
    color: Color,
    visibility: () -> Float
) {
    Row(
        modifier = Modifier.graphicsLayer {
            val shown = visibility()
            alpha = shown
            val scale = 0.92f + 0.08f * shown
            scaleX = scale
            scaleY = scale
        },
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        Icon(imageVector = icon, contentDescription = null, tint = color, modifier = Modifier.size(18.dp))
        Text(text = text, color = color, style = LevyraType.metadata.copy(fontWeight = FontWeight.Bold), maxLines = 1)
    }
}

@Composable
private fun ArtistHero(
    profile: ArtistProfile,
    artworkUrl: String,
    height: Dp,
    motionArtwork: com.luc4n3x.levyra.feature.motion.MotionArtwork?,
    motionEnabled: Boolean,
    animated: Boolean,
    entrance: () -> Float,
    canvasQuality: LevyraCanvasQuality,
    scroll: () -> Float,
    collapse: () -> Float,
    onPlay: (() -> Unit)? = null,
    awaitingArtwork: Boolean = false
) {
    val heroContext = LocalContext.current
    val applePlay = onPlay?.takeIf { LevyraIsAppleMusic }
    val density = LocalDensity.current
    val nameRisePx = with(density) { ArtistNameRise.toPx() }
    val heroScrim = artistHeroScrim()
    val scrim = heroScrim.color
    val statusProtection = if (LevyraIsLight) scrim.copy(alpha = 0.62f) else Color.Black.copy(alpha = 0.46f)
    val nameSize = artistHeroNameSize(profile.name)
    val audience = remember(profile.monthlyListeners, profile.subscribers) {
        listOf(profile.monthlyListeners, profile.subscribers)
            .map(String::trim)
            .filter(String::isNotBlank)
            .joinToString("  ·  ")
    }
    val heroIdentity = remember(profile.browseId, profile.name) {
        profile.browseId.ifBlank { profile.name.trim().lowercase() }
    }
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .height(height)
            .clipToBounds()
            .drawBehind {
                drawRect(
                    Brush.verticalGradient(
                        0f to Color(0xFF111214),
                        0.58f to Color(0xFF08090B),
                        1f to scrim
                    )
                )
            }
    ) {
        Box(
            modifier = Modifier
                .matchParentSize()
                .then(artistPortraitFrame())
                .graphicsLayer {
                    translationY = scroll() * ArtistHeroParallax
                }
        ) {
            key(heroIdentity) {
                MotionArtworkLayer(
                    artwork = motionArtwork,
                    enabled = motionEnabled,
                    isPlaying = false,
                    pageMode = true,
                    cornerRadius = 0.dp,
                    presentation = MotionArtworkPresentation.Cinematic,
                    quality = canvasQuality,
                    staticArtworkMotionEnabled = false,
                    modifier = Modifier.matchParentSize()
                ) {
                    if (artworkUrl.isNotBlank()) {
                        Box(modifier = Modifier.fillMaxSize()) {
                            ArtworkBackdropWash(
                                artworkUrl = artworkUrl,
                                tint = Color(profile.accentStart),
                                base = scrim,
                                washFraction = 0.28f,
                                modifier = Modifier.matchParentSize()
                            )
                            AsyncImage(
                                model = ImageRequest.Builder(heroContext).data(artworkUrl).crossfade(true).build(),
                                contentDescription = profile.name,
                                contentScale = ContentScale.Crop,
                                alignment = Alignment.Center,
                                modifier = Modifier.matchParentSize()
                            )
                        }
                    } else if (!awaitingArtwork) {
                        Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                            Icon(
                                Icons.Rounded.Person,
                                contentDescription = null,
                                tint = LevyraText.copy(alpha = 0.42f),
                                modifier = Modifier.size(96.dp)
                            )
                        }
                    }
                }
            }
        }
        Box(
            modifier = Modifier
                .matchParentSize()
                .drawBehind {
                    drawRect(
                        Brush.verticalGradient(
                            colorStops = arrayOf(
                                0f to statusProtection,
                                0.18f to Color.Transparent,
                                0.46f to Color.Transparent,
                                0.68f to scrim.copy(alpha = heroScrim.middle),
                                0.88f to scrim.copy(alpha = heroScrim.deep),
                                1f to scrim.copy(alpha = heroScrim.end)
                            )
                        )
                    )
                    drawRect(scrim, alpha = collapse() * 0.55f)
                }
        )
        if (LevyraIsTorque) Box(
            Modifier.align(Alignment.BottomStart).fillMaxWidth().height(190.dp)
                .graphicsLayer { alpha = (1f - collapse() * 1.35f).coerceIn(0f, 1f) }
                .clip(TorqueRiseShape).background(LevyraActivePalette.blue)
        )
        val heroOverlay: GraphicsLayerScope.() -> Unit = {
            val progress = collapse()
            val reveal = entrance()
            alpha = (1f - progress * 1.35f).coerceIn(0f, 1f) * reveal
            translationY = (1f - reveal) * nameRisePx - scroll() * 0.12f
        }
        if (applePlay != null) {
            AppleMusicArtistHeroPlay(
                onPlay = applePlay,
                modifier = Modifier
                    .align(Alignment.BottomEnd)
                    .padding(end = 20.dp, bottom = 16.dp)
                    .graphicsLayer(heroOverlay)
            )
        }
        Column(
            modifier = Modifier
                .align(Alignment.BottomStart)
                .fillMaxWidth()
                .padding(start = 20.dp, end = if (applePlay != null) 80.dp else 20.dp, bottom = 14.dp)
                .graphicsLayer {
                    heroOverlay()
                    val scale = 1f - collapse() * 0.06f
                    scaleX = scale
                    scaleY = scale
                    transformOrigin = TransformOrigin(0f, 1f)
                },
            verticalArrangement = Arrangement.spacedBy(4.dp)
        ) {
            if (artistHeroShowsOverline()) Text(
                text = LocalLevyraStrings.current.artistLabel.uppercase(),
                color = artistHeroOverlineColor(),
                style = LevyraType.overline.copy(letterSpacing = if (LevyraSkinManagesLayout) 2.4.sp else LevyraType.overline.letterSpacing),
                maxLines = 1
            )
            Text(
                text = if (LevyraIsTorque) profile.name.uppercase() else profile.name,
                color = artistHeroNameColor(),
                style = artistHeroNameStyle(nameSize),
                maxLines = 2,
                overflow = TextOverflow.Ellipsis,
                modifier = Modifier.semantics { heading() }
            )
            if (audience.isNotBlank() && !LevyraIsAppleMusic) {
                Text(
                    text = audience,
                    color = artistHeroAudienceColor(),
                    style = LevyraType.metadata,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
            }
        }
    }
}

@Composable
private fun ArtistActionBar(
    profile: ArtistProfile,
    isFollowed: Boolean,
    highlight: Color,
    onPlay: (() -> Unit)?,
    onShuffle: (() -> Unit)?,
    onToggleFollow: () -> Unit,
    isExcluded: Boolean,
    onToggleExclude: () -> Unit,
    isPinnedToHome: Boolean,
    onTogglePinToHome: () -> Unit
) {
    val strings = LocalLevyraStrings.current
    var artistMenuExpanded by remember(profile.browseId, profile.name) { mutableStateOf(false) }
    val playContainer = remember(highlight) { lerp(highlight, Color.White, 0.58f) }
    val playContent = remember(highlight) { lerp(highlight, Color.Black, 0.82f) }
    val playShape = artistPlayShape()
    val shuffleInteraction = remember { MutableInteractionSource() }
    val shuffleCorner = levyraExpressiveCorner(
        interactionSource = shuffleInteraction,
        rest = 24.dp,
        pressed = 14.dp,
        label = "artist-shuffle-corner"
    )
    val playInteraction = remember { MutableInteractionSource() }
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(start = 20.dp, end = 16.dp, top = 6.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(10.dp)
    ) {
        ArtistFollowButton(isFollowed = isFollowed, onClick = onToggleFollow)
        Spacer(modifier = Modifier.weight(1f))
        Box {
            Box(
                modifier = Modifier
                    .size(48.dp)
                    .clip(CircleShape)
                    .levyraPressable(onClick = { artistMenuExpanded = true }, pressedScale = LevyraPressScale.Control),
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    imageVector = Icons.Rounded.MoreVert,
                    contentDescription = strings.options,
                    tint = LevyraText.copy(alpha = 0.82f),
                    modifier = Modifier.size(24.dp)
                )
            }
            ArtistOptionsMenu(
                expanded = artistMenuExpanded,
                onDismiss = { artistMenuExpanded = false },
                isExcluded = isExcluded,
                onToggleExclude = onToggleExclude,
                isPinnedToHome = isPinnedToHome,
                onTogglePinToHome = onTogglePinToHome
            )
        }
        if (onShuffle != null) {
            Box(
                modifier = Modifier
                    .size(48.dp)
                    .clip(if (LevyraSkinManagesLayout) SkinChrome.chipShape else RoundedCornerShape(shuffleCorner))
                    .background(artistShuffleBackground(highlight))
                    .levyraPressable(
                        onClick = onShuffle,
                        pressedScale = LevyraPressScale.Control,
                        interactionSource = shuffleInteraction,
                        role = Role.Button,
                        haptic = LevyraHapticAction.Transport
                    ),
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    imageVector = Icons.Rounded.Shuffle,
                    contentDescription = strings.shuffle,
                    tint = artistShuffleTint(),
                    modifier = Modifier.size(artistShuffleIconSize())
                )
            }
        }
        if (onPlay != null) {
            Box(
                modifier = Modifier
                    .size(artistPlaySize())
                    .then(
                        artistPlayBackground(playContainer, playShape)
                    )
                    .levyraPressable(
                        onClick = onPlay,
                        pressedScale = LevyraPressScale.Control,
                        interactionSource = playInteraction,
                        role = Role.Button,
                        haptic = LevyraHapticAction.Transport
                    ),
                contentAlignment = Alignment.Center
            ) {
                LevyraPlayPauseGlyph(
                    playing = false,
                    color = artistPlayContent(playContent),
                    contentDescription = strings.play,
                    modifier = Modifier.size(30.dp)
                )
            }
        }
    }
}

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
private fun artistPlayShape(): Shape = MaterialShapes.Cookie9Sided.toShape()

@Composable
private fun ArtistTopBar(
    title: String?,
    atmosphere: Color,
    collapse: () -> Float,
    titleDocked: Boolean,
    onClose: () -> Unit,
    modifier: Modifier = Modifier,
    actions: @Composable () -> Unit = {}
) {
    val strings = LocalLevyraStrings.current
    val density = LocalDensity.current
    val titleDropPx = with(density) { 10.dp.toPx() }
    val barColor = LevyraBlack.playerMix(atmosphere, 0.04f)
    val hairline = LevyraText.copy(alpha = 0.08f)
    Row(
        modifier = modifier
            .fillMaxWidth()
            .drawBehind {
                val shown = ((collapse() - 0.55f) / 0.40f).coerceIn(0f, 1f)
                drawRect(barColor, alpha = shown)
                drawRect(
                    color = hairline,
                    topLeft = Offset(0f, size.height - 1.dp.toPx()),
                    size = Size(size.width, 1.dp.toPx()),
                    alpha = shown
                )
            }
            .statusBarsPadding()
            .heightIn(min = ArtistTopBarHeight)
            .padding(horizontal = 14.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        LevyraBackButton(onClick = onClose, contentDescription = strings.back)
        if (title != null) {
            Text(
                text = title,
                color = LevyraText,
                fontSize = 18.sp,
                fontWeight = FontWeight.Bold,
                letterSpacing = (-0.4).sp,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                modifier = Modifier
                    .weight(1f)
                    .graphicsLayer {
                        val shown = ((collapse() - ArtistTitleDockStart) / (1f - ArtistTitleDockStart)).coerceIn(0f, 1f)
                        alpha = shown
                        translationY = (1f - shown) * titleDropPx
                    }
                    .then(if (titleDocked) Modifier else Modifier.clearAndSetSemantics {})
            )
        } else {
            Spacer(modifier = Modifier.weight(1f))
        }
        actions()
    }
}

private fun normalizeBiographyPreview(
    text: String,
    paragraphs: List<String>,
    summary: String
): String {
    val source = text.takeIf { it.isNotBlank() }
        ?: paragraphs.joinToString(" ").takeIf { it.isNotBlank() }
        ?: summary
    return source.replace(BiographyWhitespacePattern, " ").trim()
}

internal data class ArtistBiographyPresentation(
    val previewText: String,
    val paragraphs: List<String>,
    val sourceText: String,
    val showSource: Boolean
)

internal fun buildArtistBiographyPresentation(
    biography: ArtistBiography,
    paragraphs: List<String>,
    summary: String
): ArtistBiographyPresentation {
    val previewText = normalizeBiographyPreview(
        text = biography.text,
        paragraphs = paragraphs,
        summary = summary
    )
    val sourceLabel = biography.sourceLabel.trim()
    val wikipediaSource = sourceLabel.equals("Wikipedia", ignoreCase = true)
    return ArtistBiographyPresentation(
        previewText = previewText,
        paragraphs = paragraphs.ifEmpty { listOf(previewText) },
        sourceText = if (wikipediaSource) "Wikipedia" else sourceLabel,
        showSource = sourceLabel.isNotBlank() && !sourceLabel.startsWith("YouTube", ignoreCase = true)
    )
}

@Composable
private fun ArtistBio(
    biography: ArtistBiography,
    accentStart: Color,
    accentEnd: Color,
    modifier: Modifier = Modifier
) {
    val strings = LocalLevyraStrings.current
    val editorial = remember(biography.text, biography.description, biography.languageCode) {
        artistBiographyEditorial(
            text = biography.text,
            description = biography.description,
            languageCode = biography.languageCode
        )
    }
    val presentation = remember(
        biography.text,
        biography.sourceLabel,
        editorial.paragraphs,
        editorial.summary
    ) {
        buildArtistBiographyPresentation(
            biography = biography,
            paragraphs = editorial.paragraphs,
            summary = editorial.summary
        )
    }
    val biographyText = remember(presentation.paragraphs, presentation.previewText) {
        presentation.paragraphs
            .filter { it.isNotBlank() }
            .joinToString("\n\n")
            .ifBlank { presentation.previewText }
    }
    var expanded by rememberSaveable(biography.pageId, biography.languageCode, biography.text) {
        mutableStateOf(false)
    }
    var hasOverflow by remember(biographyText) { mutableStateOf(false) }
    val accentBrush = remember(accentStart, accentEnd) {
        Brush.linearGradient(
            listOf(
                accentStart.copy(alpha = 0.16f),
                accentEnd.copy(alpha = 0.04f)
            )
        )
    }

    val animationsEnabled = LocalAnimationsEnabled.current
    val badgeShape = artistBiographyBadgeShape()
    Column(
        modifier = modifier
            .fillMaxWidth()
            .then(artistBiographyBackground(accentBrush))
            .then(
                if (animationsEnabled) {
                    Modifier.animateContentSize(animationSpec = LevyraMotion.emphasized())
                } else {
                    Modifier
                }
            )
            .padding(start = 18.dp, end = 14.dp, top = 16.dp, bottom = 14.dp),
        verticalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(12.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Box(
                modifier = Modifier
                    .size(40.dp)
                    .clip(badgeShape)
                    .background(accentStart.copy(alpha = 0.32f)),
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    imageVector = Icons.Rounded.FormatQuote,
                    contentDescription = null,
                    tint = LevyraText,
                    modifier = Modifier.size(20.dp)
                )
            }
            Text(
                text = strings.biography,
                color = LevyraText,
                style = LevyraType.sectionTitle,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                modifier = Modifier
                    .weight(1f)
                    .semantics { heading() }
            )
            if (presentation.showSource) {
                BiographyInlineSource(
                    sourceText = presentation.sourceText,
                    sourceUrl = biography.sourceUrl
                )
            }
        }

        Text(
            text = biographyText,
            color = LevyraText.copy(alpha = 0.86f),
            style = LevyraType.metadata.copy(fontSize = 15.sp, lineHeight = 23.sp),
            maxLines = if (expanded) Int.MAX_VALUE else 4,
            overflow = TextOverflow.Ellipsis,
            onTextLayout = { result ->
                if (!expanded) hasOverflow = result.hasVisualOverflow
            },
            modifier = Modifier
                .fillMaxWidth()
                .padding(end = 4.dp)
        )

        if (expanded || hasOverflow) {
            ArtistTonalPill(
                text = if (expanded) strings.showLess else strings.readAll,
                icon = if (expanded) Icons.Rounded.KeyboardArrowUp else Icons.Rounded.KeyboardArrowDown,
                onClick = { expanded = !expanded }
            )
        }
    }
}

