private fun compactReleaseNotes(notes: String): String {
    val clean = notes
        .lineSequence()
        .map { it.trim().trimStart('-', '*', '•').trim() }
        .filter { it.isNotBlank() }
        .take(3)
        .joinToString(" · ")
    return clean.ifBlank { "General improvements and bug fixes." }
}

internal fun isLaunchableUpdateTarget(url: String): Boolean =
    AppUpdateContract.matches(Intent.ACTION_VIEW, url) || url.startsWith("https://", ignoreCase = true)

private fun shareJamInvite(
    context: android.content.Context,
    payload: String,
    strings: LevyraStrings
) {
    if (payload.isBlank()) return
    runCatching {
        val intent = Intent(Intent.ACTION_SEND).apply {
            type = "text/plain"
            putExtra(Intent.EXTRA_SUBJECT, strings.jamTitle)
            putExtra(Intent.EXTRA_TEXT, payload)
        }
        context.startActivity(
            Intent.createChooser(intent, strings.share).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        )
    }.onFailure {
        Toast.makeText(context, strings.cannotOpenExternalLink, Toast.LENGTH_LONG).show()
    }
}

private fun openExternalUrl(
    context: android.content.Context,
    url: String,
    strings: LevyraStrings = LevyraStrings.forCode("en")
) {
    if (url.isBlank()) {
        Toast.makeText(context, strings.externalLinkUnavailable, Toast.LENGTH_LONG).show()
        return
    }
    runCatching {
        val intent = Intent(Intent.ACTION_VIEW, Uri.parse(url)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        context.startActivity(intent)
    }.onFailure {
        Toast.makeText(context, strings.cannotOpenExternalLink, Toast.LENGTH_LONG).show()
    }
}

