internal enum class LyricsViewMode {
    PAGE,
    CINEMA,
    COMPACT
}

@OptIn(ExperimentalLayoutApi::class, ExperimentalMaterial3Api::class)
@Composable
private fun LyricsOverlay(
    state: LevyraUiState,
    onTranslation: (Boolean) -> Unit,
    onLoadVersions: () -> Unit,
    onSelectVersion: (com.luc4n3x.levyra.data.LyricsRepository.LyricsVersion) -> Unit,
    onAutomatic: () -> Unit,
    onAdjustTrackOffset: (String, Long) -> Unit,
    onSetTrackOffset: (String, Long) -> Unit,
    onAdjustLatencyOffset: (String?, Boolean, Long) -> Unit,
    onClearLatencyOffset: (String) -> Unit,
    onSeekToMs: (Long) -> Unit,
    onPrevious: () -> Unit,
    onTogglePlay: () -> Unit,
    onNext: () -> Unit,
    onOpenLyricsStudio: () -> Unit = {},
    onUpdateLyricsStudio: (com.luc4n3x.levyra.domain.LevyraLyricsStudioSettings) -> Unit = {},
    onSeekFraction: (Float) -> Unit = {},
    onClose: () -> Unit
) {
    val strings = LocalLevyraStrings.current
    val track = state.currentTrack
    val appleLyrics = state.lyricsStudioSettings.usesAppleMusicLyrics(LevyraIsAppleMusic)
    val overlayConfiguration = LocalConfiguration.current
    val landscapeLayout = !appleLyrics && lyricsLandscapeLayoutActive(overlayConfiguration)
    val landscapeMetrics = if (landscapeLayout) {
        lyricsLandscapeMetrics(
            widthDp = overlayConfiguration.screenWidthDp.toFloat(),
            heightDp = overlayConfiguration.screenHeightDp.toFloat()
        )
    } else {
        null
    }
    LyricsImmersiveSystemBars(active = landscapeLayout)
    val accentStart = if (track != null) Color(track.accentStart) else LevyraCyan
    val accentEnd = if (track != null) Color(track.accentEnd) else LevyraViolet
    val listState = rememberLazyListState()
    val haptics = LocalLevyraHaptics.current
    val clipboard = LocalClipboard.current
    val clipboardScope = rememberCoroutineScope()
    val latencyProfiles = state.lyricsLatencyProfiles
    val audioOutputRoute = rememberLyricsAudioOutputRoute()
    val latencyOffsetMs = latencyProfiles.resolve(
        routeKey = audioOutputRoute?.stableKey,
        bluetooth = audioOutputRoute?.bluetooth == true
    )
    val trackLyricsOffsetMs = latencyProfiles.trackOffsetMs(track?.id)
    val lyricsOffsetMs = latencyOffsetMs + trackLyricsOffsetMs
    var viewMode by remember(track?.id) { mutableStateOf(LyricsViewMode.CINEMA) }
    var showRomanization by rememberSaveable { mutableStateOf(true) }
    val showTranslation = state.lyricsTranslationEnabled
    val translationContext = LocalContext.current
    var awaitingTranslationLanguage by rememberSaveable { mutableStateOf(false) }
    var translationSettingsUnavailable by rememberSaveable { mutableStateOf(false) }
    LifecycleEventEffect(Lifecycle.Event.ON_RESUME) {
        if (awaitingTranslationLanguage) {
            awaitingTranslationLanguage = false
            if (state.lyricsTranslationEnabled) onTranslation(true)
        }
    }
    val feedbackState = when {
        !translationSettingsUnavailable -> state.lyricsTranslationState
        state.lyricsTranslationState == LyricsTranslationState.MODEL_DOWNLOAD_REQUIRED ||
            state.lyricsTranslationState == LyricsTranslationState.MODEL_DOWNLOADING -> LyricsTranslationState.UNAVAILABLE
        else -> state.lyricsTranslationState
    }
    val translationFeedback = if (showTranslation) lyricsTranslationFeedback(strings, feedbackState) else null
    val onTranslationFeedback: () -> Unit = {
        when (feedbackState) {
            LyricsTranslationState.PENDING -> Unit
            LyricsTranslationState.MODEL_DOWNLOAD_REQUIRED,
            LyricsTranslationState.MODEL_DOWNLOADING -> {
                awaitingTranslationLanguage = openTranslationLanguageSettings(translationContext)
                translationSettingsUnavailable = !awaitingTranslationLanguage
            }
            else -> onTranslation(true)
        }
    }
    var showSecondaryVoices by remember(track?.id) { mutableStateOf(true) }
    var autoScrollEnabled by remember(track?.id) { mutableStateOf(true) }
    val lyricsAnimationsEnabled = LocalAnimationsEnabled.current
    var lyricsFocusMode by remember(track?.id) { mutableStateOf(lyricsAnimationsEnabled) }
    var userScrollGeneration by remember { mutableIntStateOf(0) }
    var showLyricsOptions by remember(track?.id) { mutableStateOf(false) }
    var initialLyricsPositioned by remember(track?.id) { mutableStateOf(false) }
    var selectionMode by remember(track?.id) { mutableStateOf(false) }
    var selectedRange by remember(track?.id) { mutableStateOf<IntRange?>(null) }
    var shareSnapshot by remember(track?.id) { mutableStateOf<LyricsShareSnapshot?>(null) }
    var showVersions by remember(track?.id) { mutableStateOf(false) }
    var calibrateMode by remember(track?.id) { mutableStateOf(false) }
    var showSyncBar by rememberSaveable { mutableStateOf(false) }
    var showSyncSheet by remember(track?.id) { mutableStateOf(false) }
    val visibleLyrics = remember(state.lyrics, showSecondaryVoices) {
        if (showSecondaryVoices) {
            state.lyrics
        } else {
            state.lyrics.filter { line -> line.role == LyricVocalRole.MAIN }
        }
    }
    LaunchedEffect(state.lyrics, showSecondaryVoices) {
        selectedRange = null
        selectionMode = false
    }
    val selectedLines = remember(visibleLyrics, selectedRange) {
        lyricsShareSelectedLines(selectedRange, visibleLyrics)
    }
    fun selectedLyricsText(): String = selectedLines.joinToString("\n") { line ->
        buildString {
            append(line.text)
            if (showTranslation && line.translated.isNotBlank()) append("\n").append(line.translated)
        }
    }
    val syncedLyrics = state.lyricsSynced
    val lyricsClock = rememberLyricsPlaybackClock(
        trackKey = track?.id.orEmpty(),
        reportedPositionMs = state.positionMs,
        isPlaying = state.isPlaying,
        speed = state.audioSettings.playbackSpeed,
        smoothingEnabled = syncedLyrics && lyricsAnimationsEnabled
    )
    val currentLyricsOffsetMs by rememberUpdatedState(lyricsOffsetMs)
    val lyricsPositionProvider: () -> Long = remember(lyricsClock) {
        { lyricsOffsetPosition(lyricsClock.positionMs, currentLyricsOffsetMs) }
    }
    val backgroundLineIndices = remember(visibleLyrics) {
        visibleLyrics.withIndex()
            .filter { (_, line) -> line.role == LyricVocalRole.BACKGROUND }
            .map { (index, _) -> index }
    }
    val timedActiveIndex = remember(visibleLyrics, syncedLyrics, lyricsPositionProvider) {
        derivedStateOf {
            if (syncedLyrics) activeLyricIndex(lyricsPositionProvider(), visibleLyrics) else -1
        }
    }.value
    val canShareLyrics = remember(visibleLyrics) { visibleLyrics.any(::isLyricsShareSelectable) }
    fun toggleShareMode() {
        selectionMode = !selectionMode
        if (selectionMode) {
            calibrateMode = false
            selectedRange = timedActiveIndex
                .takeIf { syncedLyrics && it >= 0 }
                ?.let { toggleLyricsShareSelection(null, it, visibleLyrics) }
        } else {
            selectedRange = null
        }
    }
    fun onLyricLineClick(index: Int, line: LyricLine) {
        if (selectionMode) {
            selectedRange = toggleLyricsShareSelection(selectedRange, index, visibleLyrics)
            haptics.perform(LevyraHapticAction.TrackSwipe)
        } else if (calibrateMode && state.lyricsSynced) {
            track?.id?.let { trackId ->
                onSetTrackOffset(trackId, calibratedLyricsTrackOffset(lyricsClock.positionMs, line.startMs, latencyOffsetMs))
            }
            calibrateMode = false
            haptics.perform(LevyraHapticAction.TrackSwipe)
        } else if (state.lyricsSynced) {
            onSeekToMs((line.startMs + lyricsOffsetMs).coerceAtLeast(0L))
        }
    }
    fun onLyricLineLongClick(index: Int, line: LyricLine) {
        if (isLyricsShareSelectable(line)) {
            selectionMode = true
            calibrateMode = false
            selectedRange = toggleLyricsShareSelection(selectedRange, index, visibleLyrics)
            haptics.perform(LevyraHapticAction.TrackSwipe)
        }
    }
    val backgroundActiveIndex = remember(visibleLyrics, backgroundLineIndices, syncedLyrics, lyricsPositionProvider) {
        derivedStateOf {
            if (!syncedLyrics || backgroundLineIndices.isEmpty()) {
                -1
            } else {
                val position = lyricsPositionProvider()
                backgroundLineIndices.firstOrNull { index ->
                    val line = visibleLyrics[index]
                    position >= line.startMs && position <= line.endMs
                } ?: -1
            }
        }
    }.value
    val instrumentalGaps = remember(visibleLyrics, syncedLyrics) {
        lyricsInstrumentalGaps(visibleLyrics, syncedLyrics)
    }
    val instrumentalGap = remember(instrumentalGaps, lyricsPositionProvider) {
        derivedStateOf { activeLyricsInstrumentalGap(lyricsPositionProvider(), instrumentalGaps) }
    }.value
    val lyricsStartIndex = 3
    val hasRomanization = state.lyrics.any { it.romanized.isNotBlank() || it.words.any { word -> word.romanized.isNotBlank() } }
    val hasMultipleVoices = state.lyrics.any { it.role != LyricVocalRole.MAIN }
    val sectionStarts = remember(state.lyricsSections, visibleLyrics) {
        val mapped = LinkedHashMap<Int, LyricSection>()
        state.lyricsSections.forEach { section ->
            val exactIndex = visibleLyrics.indexOfFirst { line ->
                line.role != LyricVocalRole.BACKGROUND && line.startMs >= section.startMs
            }
            val fallbackIndex = visibleLyrics.indexOfLast { line ->
                line.role != LyricVocalRole.BACKGROUND && line.startMs <= section.startMs
            }
            val index = if (exactIndex >= 0) exactIndex else fallbackIndex
            if (index >= 0 && mapped[index] == null) mapped[index] = section
        }
        mapped
    }
    val activeSection = remember(state.lyricsSections, lyricsPositionProvider) {
        derivedStateOf {
            val position = lyricsPositionProvider()
            state.lyricsSections.lastOrNull { section -> position >= section.startMs }
        }
    }.value
    val chorusPhrase = state.intelligenceSummary.repeatedPhrases.firstOrNull()
    val chorusIndex = remember(visibleLyrics, chorusPhrase, state.lyricsSections) {
        val sectionStart = state.lyricsSections.firstOrNull { it.type == LyricSectionType.CHORUS }?.startMs
        if (sectionStart != null) {
            visibleLyrics.indexOfFirst { line -> line.role != LyricVocalRole.BACKGROUND && line.startMs >= sectionStart }
        } else if (chorusPhrase.isNullOrBlank()) {
            -1
        } else {
            visibleLyrics.indexOfFirst { line -> line.text.contains(chorusPhrase, ignoreCase = true) }
        }
    }
    var requestedLyricIndex by remember { mutableStateOf<Int?>(null) }
    var showIntelligenceDialog by remember(track?.id) { mutableStateOf(false) }
    val anchorFraction = when (viewMode) {
        LyricsViewMode.CINEMA -> 0.36f
        LyricsViewMode.PAGE -> 0.42f
        LyricsViewMode.COMPACT -> 0.50f
    }

    val userScrollConnection = remember {
        object : NestedScrollConnection {
            override fun onPostScroll(consumed: Offset, available: Offset, source: NestedScrollSource): Offset {
                if (source == NestedScrollSource.UserInput) {
                    autoScrollEnabled = false
                    userScrollGeneration++
                }
                return Offset.Zero
            }

            override suspend fun onPostFling(consumed: Velocity, available: Velocity): Velocity {
                userScrollGeneration++
                return Velocity.Zero
            }
        }
    }

    LaunchedEffect(userScrollGeneration, listState.isScrollInProgress, selectionMode) {
        if (!autoScrollEnabled && !listState.isScrollInProgress && !selectionMode) {
            delay(LYRICS_AUTO_SCROLL_RESUME_MS)
            autoScrollEnabled = true
        }
    }

    val scrollFocusIndex = instrumentalGap?.nextLineIndex ?: timedActiveIndex

    val followActiveLine = lyricsShouldFollowActiveLine(autoScrollEnabled, selectionMode)

    LaunchedEffect(scrollFocusIndex, lyricsStartIndex, followActiveLine, viewMode, visibleLyrics.size, landscapeLayout, appleLyrics) {
        if (scrollFocusIndex >= 0 && followActiveLine && !appleLyrics) {
            runCatching {
                val targetIndex = lyricsStartIndex + scrollFocusIndex
                val targetVisible = listState.layoutInfo.visibleItemsInfo.any { it.index == targetIndex }
                centerLyricsItem(
                    listState = listState,
                    index = targetIndex,
                    animate = lyricsAnimationsEnabled && initialLyricsPositioned && targetVisible,
                    anchorFraction = anchorFraction
                )
                initialLyricsPositioned = true
            }
        }
    }

    LaunchedEffect(requestedLyricIndex, lyricsStartIndex, viewMode) {
        val requested = requestedLyricIndex ?: return@LaunchedEffect
        runCatching {
            centerLyricsItem(
                listState = listState,
                index = lyricsStartIndex + requested,
                animate = lyricsAnimationsEnabled,
                anchorFraction = anchorFraction
            )
        }
        requestedLyricIndex = null
    }

    val lyricsActionRow: @Composable (Modifier, Boolean) -> Unit = { rowModifier, includeClose ->
        Row(
            modifier = rowModifier,
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Box(modifier = Modifier.weight(1f)) {
                if (translationFeedback != null && visibleLyrics.isNotEmpty()) {
                    LyricsTranslationStatus(
                        label = translationFeedback,
                        working = state.lyricsTranslationState == LyricsTranslationState.PENDING,
                        onClick = onTranslationFeedback
                    )
                } else if (visibleLyrics.isNotEmpty() && viewMode != LyricsViewMode.COMPACT) {
                    LyricsSyncStatus(
                        synced = state.lyricsSynced,
                        syncedLabel = strings.lyricsSyncedStatus,
                        unsyncedLabel = strings.lyricsUnsyncedStatus
                    )
                } else if (activeSection != null) {
                    Text(
                        text = lyricSectionLabel(strings, activeSection),
                        color = accentEnd.copy(alpha = 0.90f),
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Black,
                        letterSpacing = 0.7.sp,
                        maxLines = 1
                    )
                }
            }
            if (canShareLyrics) {
                CircleIconButton(
                    icon = Icons.Rounded.Share,
                    tint = if (selectionMode) LevyraCyan else Color.White,
                    background = if (selectionMode) LevyraCyan.copy(alpha = 0.22f) else Color.White.copy(alpha = 0.10f),
                    onClick = { toggleShareMode() },
                    contentDescription = strings.shareLyrics
                )
            }
            if (state.lyricsSynced && track != null) {
                val syncActive = showSyncBar || trackLyricsOffsetMs != 0L
                CircleIconButton(
                    icon = Icons.Rounded.Timer,
                    tint = if (syncActive) LevyraCyan else Color.White,
                    background = if (syncActive) LevyraCyan.copy(alpha = 0.22f) else Color.White.copy(alpha = 0.10f),
                    onClick = { showSyncBar = !showSyncBar },
                    contentDescription = lyricsSyncCopy(strings.code).title
                )
            }
            CircleIconButton(
                icon = Icons.Rounded.Tune,
                tint = if (calibrateMode) LevyraCyan else Color.White,
                background = if (calibrateMode) LevyraCyan.copy(alpha = 0.22f) else Color.White.copy(alpha = 0.10f),
                onClick = { showLyricsOptions = true },
                contentDescription = strings.options
            )
            if (includeClose) {
                CircleIconButton(
                    icon = Icons.Rounded.Close,
                    tint = Color.White,
                    background = Color.White.copy(alpha = 0.13f),
                    onClick = onClose,
                    contentDescription = strings.closeLyrics
                )
            }
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .consumeOverlayTouches()
    ) {
        val studioSettings = state.lyricsStudioSettings
        val lyricsDepthBlur = lyricsAnimationsEnabled &&
            studioSettings.blurEnabled &&
            LocalLevyraVisualCapabilities.current.heavyBlur
        if (appleLyrics) {
            AppleLyricsOverlayScreen(
                state = state,
                lines = visibleLyrics,
                position = lyricsPositionProvider,
                showTranslation = showTranslation,
                showSecondaryVoices = showSecondaryVoices,
                animations = lyricsAnimationsEnabled,
                heavyBlur = LocalLevyraVisualCapabilities.current.heavyBlur,
                selectionMode = selectionMode,
                selectedRange = selectedRange,
                onLineClick = { index, line -> onLyricLineClick(index, line) },
                onLineLongClick = { index, line -> onLyricLineLongClick(index, line) },
                onSeekFraction = onSeekFraction,
                onPrevious = onPrevious,
                onTogglePlay = onTogglePlay,
                onNext = onNext,
                onTranslation = onTranslation,
                onOptions = { showLyricsOptions = true },
                onClose = onClose
            )
        } else if (LevyraIsAtelier && track != null) {
            AtelierLyricsScreen(
                state, track, visibleLyrics, lyricsPositionProvider, lyricsAnimationsEnabled, ::onLyricLineClick, onTogglePlay,
                { showLyricsOptions = true }, onClose, selectionMode, selectedRange, ::onLyricLineLongClick,
                if (canShareLyrics) ::toggleShareMode else null
            )
        } else if (LevyraIsQobuz && track != null) {
            QobuzLyricsScreen(state, track, visibleLyrics, lyricsPositionProvider, lyricsAnimationsEnabled, ::onLyricLineClick, onTogglePlay, onClose)
        } else if (LevyraIsSpotify && studioSettings.spotifyLyricsApplies() && track != null) {
            SpotifyLyricsOverlayScreen(
                state, track, visibleLyrics, lyricsPositionProvider, selectionMode, selectedRange, lyricsAnimationsEnabled,
                ::onLyricLineClick, onSeekFraction, onTogglePlay, if (canShareLyrics) ::toggleShareMode else null,
                { showLyricsOptions = true }, onClose
            )
        } else {
        if (studioSettings.spotifyLyricsApplies()) {
            SpotifyLyricsBackdrop(track)
        } else if (landscapeLayout && studioSettings.backgroundMode !in setOf(
                LyricsBackgroundMode.AMOLED, LyricsBackgroundMode.SOLID, LyricsBackgroundMode.GRADIENT
            )) {
            LyricsLandscapeBackdrop(
                track = track,
                accentStart = accentStart,
                accentEnd = accentEnd,
                artworkAlpha = lyricsBackdropAlpha(lyricsFocusMode, cinema = true)
            )
        } else if (studioSettings.backgroundMode == LyricsBackgroundMode.AMOLED) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(Color.Black)
            )
        } else if (studioSettings.backgroundMode == LyricsBackgroundMode.SOLID) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(Color(0xFF16161A))
            )
        } else if (studioSettings.backgroundMode == LyricsBackgroundMode.GRADIENT) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(
                        Brush.verticalGradient(
                            listOf(
                                accentStart.copy(alpha = 0.35f),
                                Color(0xFF0F0F14),
                                Color(0xFF0A0A0E)
                            )
                        )
                    )
            )
        } else if (lyricsAmbientSkinActive() && studioSettings.backgroundMode == LyricsBackgroundMode.ORIGINAL) {
            LyricsAmbientBackdrop(
                artworkUrl = track?.let { it.largeThumbnailUrl.ifBlank { it.thumbnailUrl } },
                trackKey = track?.id.orEmpty(),
                accentStart = accentStart,
                accentEnd = accentEnd,
                motionEnabled = lyricsAnimationsEnabled &&
                    LocalLevyraVisualCapabilities.current.decorativeMotion &&
                    state.isPlaying
            )
        } else {
            LevyraBackground()
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(
                        Color.Black.copy(
                            alpha = when {
                                studioSettings.backgroundMode == LyricsBackgroundMode.BLURRED_ARTWORK -> 0.55f
                                studioSettings.backgroundMode == LyricsBackgroundMode.CINEMATIC -> 0.60f
                                viewMode == LyricsViewMode.CINEMA -> 0.68f
                                viewMode == LyricsViewMode.PAGE -> 0.76f
                                else -> 0.86f
                            }
                        )
                    )
            )
            if (viewMode == LyricsViewMode.CINEMA || studioSettings.backgroundMode == LyricsBackgroundMode.BLURRED_ARTWORK || studioSettings.backgroundMode == LyricsBackgroundMode.CINEMATIC) {
                val backdropAlpha = lyricsBackdropAlpha(lyricsFocusMode, cinema = true)
                if (track != null && backdropAlpha > 0f) {
                    val backdropContext = LocalContext.current
                    val backdropRequest = remember(backdropContext, track.id, track.largeThumbnailUrl, track.thumbnailUrl) {
                        ImageRequest.Builder(backdropContext)
                            .data(track.largeThumbnailUrl.ifBlank { track.thumbnailUrl })
                            .size(LYRICS_BACKDROP_DECODE_PX, LYRICS_BACKDROP_DECODE_PX)
                            .crossfade(false)
                            .build()
                    }
                    AsyncImage(
                        model = backdropRequest,
                        contentDescription = null,
                        contentScale = ContentScale.Crop,
                        filterQuality = FilterQuality.High,
                        modifier = Modifier
                            .fillMaxSize()
                            .graphicsLayer {
                                alpha = backdropAlpha
                                scaleX = 1.22f
                                scaleY = 1.22f
                            }
                    )
                    Box(
                        modifier = Modifier
                            .fillMaxSize()
                            .background(
                                Brush.verticalGradient(
                                    listOf(
                                        Color.Black.copy(alpha = 0.62f),
                                        Color.Black.copy(alpha = 0.40f),
                                        Color.Black.copy(alpha = 0.78f)
                                    )
                                )
                            )
                    )
                }
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(
                            Brush.radialGradient(
                                colors = listOf(accentStart.copy(alpha = 0.12f), Color.Transparent),
                                radius = 1_250f
                            )
                        )
                )
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(
                            Brush.verticalGradient(
                                colors = listOf(Color.Black.copy(alpha = 0.18f), Color.Transparent, Color.Black.copy(alpha = 0.55f))
                            )
                        )
                )
            }
        }

        if (landscapeMetrics != null) {
            LyricsLandscapeArtworkPane(
                track = track,
                fallbackTitle = strings.lyrics,
                artworkSize = landscapeMetrics.artworkSizeDp.dp,
                motionArtwork = state.motionArtwork,
                motionEnabled = state.animationsEnabled && state.motionArtworkEnabled && !state.isVideoMode,
                isPlaying = state.isPlaying,
                canvasQuality = state.interfaceSettings.canvasQuality,
                accent = accentStart,
                animationsEnabled = lyricsAnimationsEnabled,
                onPrevious = onPrevious,
                onTogglePlay = onTogglePlay,
                onNext = onNext,
                modifier = Modifier
                    .align(Alignment.CenterStart)
                    .windowInsetsPadding(WindowInsets.displayCutout.only(WindowInsetsSides.Start))
                    .width(landscapeMetrics.artworkPaneWidthDp.dp)
            )
        }
        LazyColumn(
            state = listState,
            modifier = Modifier
                .fillMaxSize()
                .then(
                    if (landscapeMetrics != null) {
                        Modifier
                            .windowInsetsPadding(WindowInsets.displayCutout.only(WindowInsetsSides.Horizontal))
                            .padding(start = landscapeMetrics.artworkPaneWidthDp.dp)
                    } else {
                        Modifier.statusBarsPadding()
                    }
                )
                .nestedScroll(userScrollConnection),
            contentPadding = when {
                landscapeMetrics != null -> PaddingValues(
                    start = LYRICS_LANDSCAPE_PANE_GAP_DP.dp,
                    end = 28.dp,
                    top = LYRICS_LANDSCAPE_CHROME_HEIGHT_DP.dp,
                    bottom = 120.dp
                )
                else -> PaddingValues(
                    start = if (viewMode == LyricsViewMode.COMPACT) 18.dp else 22.dp,
                    end = if (viewMode == LyricsViewMode.COMPACT) 18.dp else 22.dp,
                    top = if (viewMode == LyricsViewMode.COMPACT) 8.dp else 14.dp,
                    bottom = if (viewMode == LyricsViewMode.COMPACT) 96.dp else 150.dp
                )
            },
            verticalArrangement = Arrangement.spacedBy(
                when (viewMode) {
                    LyricsViewMode.CINEMA -> 14.dp
                    LyricsViewMode.PAGE -> 11.dp
                    LyricsViewMode.COMPACT -> 6.dp
                } + studioSettings.lineSpacing.spacingDp - LyricsLineSpacing.STANDARD.spacingDp
            )
        ) {
            item {
                if (!landscapeLayout) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(if (viewMode == LyricsViewMode.COMPACT) 9.dp else 12.dp)
                    ) {
                        if (track != null) {
                            AsyncImage(
                                model = track.largeThumbnailUrl.ifBlank { track.thumbnailUrl },
                                contentDescription = null,
                                contentScale = ContentScale.Crop,
                                modifier = Modifier
                                    .size(
                                        when (viewMode) {
                                            LyricsViewMode.CINEMA -> 62.dp
                                            LyricsViewMode.PAGE -> 52.dp
                                            LyricsViewMode.COMPACT -> 44.dp
                                        }
                                    )
                                    .clip(RoundedCornerShape(if (viewMode == LyricsViewMode.COMPACT) 12.dp else 16.dp))
                            )
                        }
                        Column(modifier = Modifier.weight(1f)) {
                            Text(
                                text = track?.title ?: strings.lyrics,
                                color = Color.White,
                                fontSize = when (viewMode) {
                                    LyricsViewMode.CINEMA -> 23.sp
                                    LyricsViewMode.PAGE -> 21.sp
                                    LyricsViewMode.COMPACT -> 18.sp
                                },
                                fontWeight = FontWeight.Black,
                                maxLines = if (viewMode == LyricsViewMode.COMPACT) 1 else 2,
                                overflow = TextOverflow.Ellipsis
                            )
                            Text(
                                text = track?.artist.orEmpty(),
                                color = Color.White.copy(alpha = 0.67f),
                                fontSize = if (viewMode == LyricsViewMode.COMPACT) 12.sp else 14.sp,
                                fontWeight = FontWeight.SemiBold,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis
                            )
                        }
                        CircleIconButton(
                            icon = Icons.Rounded.Close,
                            tint = Color.White,
                            background = Color.White.copy(alpha = 0.13f),
                            onClick = onClose,
                            contentDescription = strings.closeLyrics
                        )
                    }
                }
            }
            item {
                if (!landscapeLayout) lyricsActionRow(Modifier.fillMaxWidth(), false)
            }
            item {
                Spacer(
                    modifier = Modifier.height(
                        when {
                            landscapeLayout -> 4.dp
                            viewMode == LyricsViewMode.CINEMA -> 30.dp
                            viewMode == LyricsViewMode.PAGE -> 6.dp
                            else -> 2.dp
                        }
                    )
                )
            }
            if (visibleLyrics.isEmpty()) {
                item {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(top = 28.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        if (state.lyricsLoading) {
                            LevyraLoadingIndicator(
                                modifier = Modifier.size(20.dp),
                                color = Color.White.copy(alpha = 0.82f)
                            )
                        }
                        Text(
                            text = if (state.lyricsLoading) strings.searchingLyrics else strings.lyricsUnavailable,
                            color = Color.White.copy(alpha = 0.68f),
                            fontSize = 15.sp,
                            fontWeight = FontWeight.SemiBold
                        )
                    }
                }
            } else {
                itemsIndexed(
                    items = visibleLyrics,
                    key = { index, line -> "${line.startMs}-${line.role.name}-$index" }
                ) { index, line ->
                    val selected = selectedRange?.contains(index) == true && isLyricsShareSelectable(line)
                    val timedActive = syncedLyrics && (index == timedActiveIndex || index == backgroundActiveIndex)
                    val lineInstrumentalGap = instrumentalGap?.takeIf { it.nextLineIndex == index }
                    KaraokeLyricLine(
                        line = line,
                        positionProvider = lyricsPositionProvider,
                        instrumentalGap = lineInstrumentalGap,
                        isActive = timedActive,
                        isPrimaryActive = index == timedActiveIndex,
                        synced = state.lyricsSynced,
                        viewMode = viewMode,
                        distanceFromActive = when {
                            !followActiveLine -> 0
                            lineInstrumentalGap != null -> 0
                            timedActiveIndex >= 0 -> kotlin.math.abs(index - timedActiveIndex)
                            else -> 0
                        },
                        focusMode = lyricsFocusMode,
                        layoutWidthDp = landscapeMetrics?.lyricsPaneWidthDp?.toInt(),
                        blurEnabled = lyricsDepthBlur,
                        animationsEnabled = lyricsAnimationsEnabled,
                        sectionLabel = sectionStarts[index]?.let { lyricSectionLabel(strings, it) },
                        showRomanization = showRomanization,
                        showTranslation = showTranslation,
                        accentEnd = accentEnd,
                        selectionMode = selectionMode,
                        selected = selected,
                        selectable = isLyricsShareSelectable(line),
                        studioSettings = studioSettings,
                        onClick = {
                            if (selectionMode) {
                                selectedRange = toggleLyricsShareSelection(selectedRange, index, visibleLyrics)
                                haptics.perform(LevyraHapticAction.TrackSwipe)
                            } else if (calibrateMode && state.lyricsSynced) {
                                track?.id?.let { trackId ->
                                    onSetTrackOffset(
                                        trackId,
                                        calibratedLyricsTrackOffset(lyricsClock.positionMs, line.startMs, latencyOffsetMs)
                                    )
                                }
                                calibrateMode = false
                                haptics.perform(LevyraHapticAction.TrackSwipe)
                                autoScrollEnabled = true
                            } else if (state.lyricsSynced) {
                                onSeekToMs((line.startMs + lyricsOffsetMs).coerceAtLeast(0L))
                                autoScrollEnabled = true
                            }
                        },
                        onLongClick = {
                            if (isLyricsShareSelectable(line)) {
                                selectionMode = true
                                calibrateMode = false
                                selectedRange = toggleLyricsShareSelection(selectedRange, index, visibleLyrics)
                                haptics.perform(LevyraHapticAction.TrackSwipe)
                            }
                        }
                    )
                }
            }
        }
        if (landscapeMetrics != null) {
            Box(
                modifier = Modifier
                    .align(Alignment.TopEnd)
                    .windowInsetsPadding(WindowInsets.displayCutout.only(WindowInsetsSides.End))
                    .width(landscapeMetrics.lyricsPaneWidthDp.dp)
                    .height((LYRICS_LANDSCAPE_CHROME_HEIGHT_DP + 18).dp)
            ) {
                LyricsLandscapeChromeScrim(modifier = Modifier.matchParentSize())
                lyricsActionRow(
                    Modifier
                        .fillMaxWidth()
                        .padding(start = LYRICS_LANDSCAPE_PANE_GAP_DP.dp, end = 20.dp, top = 8.dp),
                    true
                )
            }
        }
        }
        AnimatedVisibility(
            visible = showSyncBar && state.lyricsSynced && track != null && !selectionMode,
            enter = fadeIn() + slideInVertically { it / 2 },
            exit = fadeOut() + slideOutVertically { it / 2 },
            modifier = Modifier
                .align(Alignment.BottomCenter)
                .navigationBarsPadding()
                .padding(start = landscapeMetrics?.artworkPaneWidthDp?.dp ?: 0.dp)
                .padding(horizontal = 16.dp, vertical = 14.dp)
        ) {
            LyricsSyncQuickBar(
                offsetMs = trackLyricsOffsetMs,
                accent = LevyraCyan,
                onAdjust = { delta -> track?.id?.let { trackId -> onAdjustTrackOffset(trackId, delta) } },
                onReset = { track?.id?.let { trackId -> onSetTrackOffset(trackId, 0L) } },
                onOpenAdvanced = { showSyncSheet = true }
            )
        }
        AnimatedVisibility(
            visible = selectionMode,
            enter = fadeIn() + slideInVertically { it / 2 },
            exit = fadeOut() + slideOutVertically { it / 2 },
            modifier = Modifier
                .align(Alignment.BottomCenter)
                .navigationBarsPadding()
                .padding(start = landscapeMetrics?.artworkPaneWidthDp?.dp ?: 0.dp)
                .padding(horizontal = 16.dp, vertical = 14.dp)
        ) {
            LyricsShareBar(
                selectedCount = selectedLines.size,
                maxCount = LYRICS_SHARE_MAX_LINES,
                canContinue = selectedLines.isNotEmpty() && !state.lyricsLoading,
                accent = accentEnd,
                onCopy = {
                    val text = selectedLyricsText()
                    clipboardScope.launch {
                        clipboard.setClipEntry(ClipEntry(ClipData.newPlainText("lyrics", text)))
                    }
                },
                onCancel = {
                    selectedRange = null
                    selectionMode = false
                },
                onContinue = { shareSnapshot = lyricsShareSnapshot(track, selectedLines) }
            )
        }
    }

    if (showIntelligenceDialog) {
        LyricsIntelligenceDialog(
            summary = state.intelligenceSummary,
            onDismiss = { showIntelligenceDialog = false },
            onJumpToChorus = if (chorusIndex >= 0) {
                {
                    showIntelligenceDialog = false
                    requestedLyricIndex = chorusIndex
                    val chorusStartMs = visibleLyrics.getOrNull(chorusIndex)?.startMs ?: 0L
                    if (state.lyricsSynced) onSeekToMs((chorusStartMs + lyricsOffsetMs).coerceAtLeast(0L))
                }
            } else {
                null
            }
        )
    }
    if (showLyricsOptions && appleLyrics) {
        AppleLyricsOverlayOptions(
            state = state,
            lines = visibleLyrics,
            hasRomanization = hasRomanization,
            hasMultipleVoices = hasMultipleVoices,
            showSecondaryVoices = showSecondaryVoices,
            canShareLyrics = canShareLyrics,
            trackOffsetMs = trackLyricsOffsetMs,
            capabilities = LocalLevyraVisualCapabilities.current,
            onTranslation = onTranslation,
            onUpdateStudio = onUpdateLyricsStudio,
            onSecondaryVoices = { showSecondaryVoices = it },
            onAction = { action ->
                showLyricsOptions = false
                when (action) {
                    AppleLyricsOverlayAction.CHANGE_LYRICS -> {
                        showVersions = true
                        onLoadVersions()
                    }
                    AppleLyricsOverlayAction.SHARE -> toggleShareMode()
                    AppleLyricsOverlayAction.SYNC -> showSyncSheet = true
                    AppleLyricsOverlayAction.CALIBRATE -> {
                        calibrateMode = !calibrateMode
                        if (calibrateMode) {
                            selectionMode = false
                            selectedRange = null
                        }
                    }
                    AppleLyricsOverlayAction.ANALYSIS -> showIntelligenceDialog = true
                    AppleLyricsOverlayAction.STUDIO -> onOpenLyricsStudio()
                }
            },
            onDismiss = { showLyricsOptions = false }
        )
    } else if (showLyricsOptions) {
        ModalBottomSheet(
            onDismissRequest = { showLyricsOptions = false },
            sheetState = rememberBottomSheetState(
                initialValue = SheetValue.Hidden,
                enabledValues = setOf(SheetValue.Hidden, SheetValue.Expanded)
            )
        ) {
            Text(
                text = strings.options,
                color = LevyraText,
                fontSize = 20.sp,
                fontWeight = FontWeight.Black,
                modifier = Modifier.padding(horizontal = 20.dp)
            )
            lyricsProviderDisplayName(state.lyricsProvider).takeIf(String::isNotBlank)?.let { source ->
                Text(
                    text = "${strings.lyricsSource} · $source",
                    color = LevyraMuted,
                    fontSize = 12.sp,
                    fontWeight = FontWeight.SemiBold,
                    modifier = Modifier.padding(start = 20.dp, end = 20.dp, top = 2.dp)
                )
            }
            FlowRow(
                modifier = Modifier
                    .fillMaxWidth()
                    .navigationBarsPadding()
                    .padding(horizontal = 20.dp, vertical = 16.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp),
                verticalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                val modeLabel = when (viewMode) {
                    LyricsViewMode.CINEMA -> strings.lyricsCinema
                    LyricsViewMode.PAGE -> strings.lyricsPage
                    LyricsViewMode.COMPACT -> strings.lyricsCompact
                }
                val modeIcon = when (viewMode) {
                    LyricsViewMode.CINEMA -> Icons.Rounded.GraphicEq
                    LyricsViewMode.PAGE -> Icons.AutoMirrored.Rounded.Subject
                    LyricsViewMode.COMPACT -> Icons.Rounded.ViewCompact
                }
                LyricsControlChip(
                    label = modeLabel,
                    selected = true,
                    icon = modeIcon,
                    onClick = {
                        viewMode = when (viewMode) {
                            LyricsViewMode.CINEMA -> LyricsViewMode.PAGE
                            LyricsViewMode.PAGE -> LyricsViewMode.COMPACT
                            LyricsViewMode.COMPACT -> LyricsViewMode.CINEMA
                        }
                        initialLyricsPositioned = false
                    }
                )
                LyricsControlChip(
                    label = strings.lyricsStudio,
                    selected = false,
                    icon = Icons.Rounded.AutoAwesome,
                    onClick = {
                        showLyricsOptions = false
                        onOpenLyricsStudio()
                    }
                )
                LyricsControlChip(
                    label = appleLyricsStyleChipLabel(strings.code),
                    selected = false,
                    icon = Icons.Rounded.FormatQuote,
                    onClick = {
                        showLyricsOptions = false
                        onUpdateLyricsStudio(state.lyricsStudioSettings.withAppleMusicViewer())
                    }
                )
                LyricsControlChip(
                    label = strings.lyricsFocus,
                    selected = lyricsFocusMode,
                    icon = Icons.Rounded.Visibility,
                    onClick = { lyricsFocusMode = !lyricsFocusMode }
                )
                val translationLabel = when (state.lyricsTranslationState) {
                    LyricsTranslationState.ON_DEVICE -> "${strings.automaticTranslation} · ${strings.offline}"
                    LyricsTranslationState.MODEL_DOWNLOAD_REQUIRED -> "${strings.automaticTranslation} · ${strings.download}"
                    LyricsTranslationState.MODEL_DOWNLOADING -> "${strings.automaticTranslation} · ${strings.updateDownloading}"
                    LyricsTranslationState.UNAVAILABLE,
                    LyricsTranslationState.FAILED,
                    LyricsTranslationState.DISABLED,
                    LyricsTranslationState.PENDING,
                    LyricsTranslationState.PROVIDER,
                    LyricsTranslationState.SAME_LANGUAGE -> strings.automaticTranslation
                }
                LyricsControlChip(
                    label = translationLabel,
                    selected = state.lyricsTranslationEnabled,
                    icon = Icons.Rounded.Translate,
                    onClick = { onTranslation(!state.lyricsTranslationEnabled) }
                )
                LyricsControlChip(
                    label = strings.changeLyrics,
                    selected = state.lyricsManualSelection,
                    icon = Icons.Rounded.LibraryMusic,
                    onClick = {
                        showLyricsOptions = false
                        showVersions = true
                        onLoadVersions()
                    }
                )
                if (state.lyricsSynced) {
                    LyricsControlChip(
                        label = strings.lyricsCalibrate,
                        selected = calibrateMode,
                        icon = Icons.Rounded.Schedule,
                        onClick = {
                            calibrateMode = !calibrateMode
                            if (calibrateMode) {
                                selectionMode = false
                                selectedRange = null
                                showLyricsOptions = false
                            }
                        }
                    )
                }
                if (hasRomanization) {
                    LyricsControlChip(
                        label = strings.lyricsRomanization,
                        selected = showRomanization,
                        icon = Icons.Rounded.Language,
                        onClick = { showRomanization = !showRomanization }
                    )
                }
                if (hasMultipleVoices) {
                    LyricsControlChip(
                        label = strings.lyricsDuet,
                        selected = showSecondaryVoices,
                        icon = Icons.Rounded.GraphicEq,
                        onClick = { showSecondaryVoices = !showSecondaryVoices }
                    )
                }
                if (state.intelligenceSummary.available) {
                    LyricsControlChip(
                        label = strings.lyricsAnalysis,
                        selected = false,
                        icon = Icons.Rounded.Insights,
                        onClick = {
                            showLyricsOptions = false
                            showIntelligenceDialog = true
                        }
                    )
                }
                if (state.lyricsSynced && track != null) {
                    LyricsControlChip(
                        label = "${lyricsSyncCopy(strings.code).title} · ${lyricsOffsetIsolated(trackLyricsOffsetMs)}",
                        selected = trackLyricsOffsetMs != 0L,
                        icon = Icons.Rounded.Timer,
                        onClick = {
                            showLyricsOptions = false
                            showSyncSheet = true
                        }
                    )
                }
            }
        }
    }
    if (showSyncSheet && track != null) {
        val bluetoothRoute = audioOutputRoute?.takeIf { route -> route.bluetooth && route.stableKey != null }
        val deviceProfileKey = bluetoothRoute?.stableKey?.takeIf(latencyProfiles.deviceOffsetsMs::containsKey)
        LyricsSyncSheet(
            trackOffsetMs = trackLyricsOffsetMs,
            latencyOffsetMs = latencyOffsetMs,
            latencyDeviceName = bluetoothRoute?.displayName?.ifBlank { strings.connected },
            latencyResettable = latencyOffsetMs != 0L,
            onAdjustTrack = { delta -> onAdjustTrackOffset(track.id, delta) },
            onSetTrack = { value -> onSetTrackOffset(track.id, value) },
            onAdjustLatency = { delta ->
                onAdjustLatencyOffset(audioOutputRoute?.stableKey, audioOutputRoute?.bluetooth == true, delta)
            },
            onResetLatency = {
                if (deviceProfileKey != null && latencyProfiles.globalOffsetMs == 0L) {
                    onClearLatencyOffset(deviceProfileKey)
                } else {
                    onAdjustLatencyOffset(audioOutputRoute?.stableKey, audioOutputRoute?.bluetooth == true, -latencyOffsetMs)
                }
            },
            onDismiss = { showSyncSheet = false }
        )
    }
    shareSnapshot?.let { snapshot ->
        LyricsShareSheet(
            snapshot = snapshot,
            onDismiss = { shareSnapshot = null }
        )
    }
    if (showVersions) {
        LyricsVersionDialog(
            versions = state.lyricsVersions,
            loading = state.lyricsVersionsLoading,
            strings = strings,
            onAutomatic = {
                showVersions = false
                onAutomatic()
            },
            onSelect = { version ->
                showVersions = false
                onSelectVersion(version)
            },
            onDismiss = { showVersions = false }
        )
    }
}

private const val LYRICS_AUTO_SCROLL_RESUME_MS = 3_500L
private const val LYRICS_BACKDROP_DECODE_PX = 96

private suspend fun centerLyricsItem(
    listState: LazyListState,
    index: Int,
    animate: Boolean,
    anchorFraction: Float
) {
    if (index < 0) return
    var itemInfo = listState.layoutInfo.visibleItemsInfo.firstOrNull { it.index == index }
    if (itemInfo == null) {
        val layoutInfo = listState.layoutInfo
        val viewportHeight = layoutInfo.viewportEndOffset - layoutInfo.viewportStartOffset
        val desiredOffset = if (viewportHeight > 0) {
            -(viewportHeight * anchorFraction.coerceIn(0.25f, 0.70f)).toInt()
        } else {
            0
        }
        listState.scrollToItem(index, scrollOffset = desiredOffset)
        withFrameNanos { }
        itemInfo = listState.layoutInfo.visibleItemsInfo.firstOrNull { it.index == index }
    }
    val item = itemInfo ?: return
    val layoutInfo = listState.layoutInfo
    val viewportHeight = layoutInfo.viewportEndOffset - layoutInfo.viewportStartOffset
    if (viewportHeight <= 0) return
    val desiredCenter = layoutInfo.viewportStartOffset + viewportHeight * anchorFraction.coerceIn(0.25f, 0.70f)
    val currentCenter = item.offset + item.size / 2f
    val delta = currentCenter - desiredCenter
    val hysteresis = maxOf(8f, viewportHeight * 0.018f)
    if (kotlin.math.abs(delta) <= hysteresis) return
    if (animate && kotlin.math.abs(delta) <= viewportHeight * 0.55f) {
        listState.animateScrollBy(
            value = delta,
            animationSpec = LevyraMotion.spatial.spec()
        )
    } else {
        listState.scrollBy(delta)
    }
}

private fun lyricSectionLabel(strings: LevyraStrings, section: LyricSection): String {
    val base = when (section.type) {
        LyricSectionType.INTRO -> strings.lyricsSectionIntro
        LyricSectionType.VERSE -> strings.lyricsSectionVerse
        LyricSectionType.PRE_CHORUS -> strings.lyricsSectionPreChorus
        LyricSectionType.CHORUS -> strings.lyricsSectionChorus
        LyricSectionType.BRIDGE -> strings.lyricsSectionBridge
        LyricSectionType.INSTRUMENTAL -> strings.lyricsSectionInstrumental
        LyricSectionType.OUTRO -> strings.lyricsSectionOutro
    }
    return if (section.ordinal > 1 && section.type in setOf(LyricSectionType.VERSE, LyricSectionType.CHORUS, LyricSectionType.BRIDGE)) {
        "$base ${section.ordinal}"
    } else {
        base
    }
}

