@Composable
private fun HomeStudioHost(
    viewModel: HomeViewModel,
    renderSnapshot: HomeRenderSnapshot,
    homeListState: LazyListState,
    deferredSectionsRevealed: MutableState<Boolean>,
    accountAvatarUrl: String,
    youtubeMusicHome: com.luc4n3x.levyra.ui.youtubemusic.YoutubeMusicHomeShelfUi?,
    homeStudio: LevyraHomeStudioSettings,
    homeComposition: com.luc4n3x.levyra.domain.LevyraHomeCompositionSettings,
    onPullRefresh: () -> Unit,
    onTrackActions: (Track) -> Unit
) {
    val radioStations by viewModel.favoriteRadioStations.collectAsStateWithLifecycle(initialValue = emptyList())
    val skin = renderSnapshot.state.interfaceSettings.skin
    val composition = homeComposition
    val composedBlocks = remember(composition, skin, homeStudio) { composition.resolvedBlocks(skin, homeStudio) }
    val radioVisible = composedBlocks?.contains(com.luc4n3x.levyra.domain.HomeBlock.Section(HomeSectionId.FavoriteRadio))
        ?: !homeStudio.activeLayout().isHidden(HomeSectionId.FavoriteRadio)
    val homeRadio = HomeRadioState(radioStations, renderSnapshot.state.liveRadioStation?.uuid, renderSnapshot.state.isPlaying,
        radioVisible, viewModel::playLiveRadio)
    CompositionLocalProvider(LocalHomeRadio provides homeRadio) {
        val effectiveStudio = remember(composedBlocks, composition, skin, homeStudio) {
            composedStudioSettings(skin, composedBlocks, composition.modeFor(skin), homeStudio)
        }
        if (effectiveStudio.usesClassicOriginalHome() && !LevyraSkinManagesLayout) {
            HomeScreen(
                viewModel = viewModel,
                renderSnapshot = renderSnapshot,
                homeListState = homeListState,
                deferredSectionsRevealed = deferredSectionsRevealed,
                accountAvatarUrl = accountAvatarUrl,
                youtubeMusicHome = youtubeMusicHome,
                onPullRefresh = onPullRefresh,
                onTrackActions = onTrackActions
            )
        } else {
            StudioHomeScreen(
                viewModel = viewModel,
                renderSnapshot = renderSnapshot,
                homeListState = homeListState,
                deferredSectionsRevealed = deferredSectionsRevealed,
                accountAvatarUrl = accountAvatarUrl,
                youtubeMusicHome = youtubeMusicHome,
                homeStudio = effectiveStudio,
                composedBlocks = composedBlocks,
                onPullRefresh = onPullRefresh,
                onTrackActions = onTrackActions
            )
        }
    }
}

@Composable
private fun PersonalListeningShelf(
    tracks: List<Track>,
    userName: String,
    profilePhotoPath: String,
    profilePhotoVersion: Long,
    accountAvatarUrl: String,
    currentId: String?,
    isPlaying: Boolean,
    isResolving: Boolean,
    onPlay: (Track) -> Unit,
    onPlayAll: () -> Unit,
    onTrackActions: (Track) -> Unit
) {
    if (LevyraSkinManagesLayout) {
        Column(verticalArrangement = Arrangement.spacedBy(if (LevyraIsSpotify) 8.dp else 14.dp)) {
            if (LevyraIsSpotify) SpotifyOrbitHeader(onPlayAll)
            else Box(Modifier.padding(horizontal = 20.dp)) {
                StudioHomeOrbitHeader(userName = userName, profilePhotoPath = profilePhotoPath,
                    profilePhotoVersion = profilePhotoVersion, accountAvatarUrl = accountAvatarUrl, onPlayAll = onPlayAll)
            }
            SkinOrbitTracks(tracks, currentId, isPlaying, isResolving, onPlay, onTrackActions)
        }
        return
    }
    val pages = remember(tracks) { homePersonalOrbitPages(tracks) }
    if (pages.isEmpty()) return
    val pagerState = rememberPagerState(pageCount = { pages.size })
    LaunchedEffect(pages.size) {
        if (pagerState.currentPage > pages.lastIndex) pagerState.scrollToPage(pages.lastIndex)
    }
    val pageKey: (Int) -> String = { pageIndex ->
        pages.getOrNull(pageIndex)?.firstOrNull()?.firstOrNull()
            ?.let(LevyraPersonalOrbit::identityKey)
            ?.takeIf(String::isNotBlank)
            ?.let { "orbit-page-$it" }
            ?: "orbit-page-index-$pageIndex"
    }
    val orbitPage: @Composable (Int, Modifier) -> Unit = { pageIndex, pageModifier ->
        Column(
            modifier = pageModifier.padding(
                start = LevyraHomeDesign.HorizontalInset,
                end = LevyraHomeDesign.OrbitPageEndInset
            ),
            verticalArrangement = Arrangement.spacedBy(LevyraHomeDesign.OrbitTileGap)
        ) {
            val pageRows = pages.getOrNull(pageIndex).orEmpty()
            pageRows.forEachIndexed { rowIndex, rowTracks ->
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(LevyraHomeDesign.OrbitTileGap)
                ) {
                    rowTracks.forEachIndexed { columnIndex, track ->
                        key(LevyraPersonalOrbit.identityKey(track)) {
                            PersonalOrbitTile(
                                shape = levyraGroupedGridShape(
                                    row = rowIndex,
                                    column = columnIndex,
                                    rows = pageRows.size,
                                    columns = HOME_PERSONAL_ORBIT_GRID_COLUMNS
                                ),
                                track = track,
                                isCurrent = track.id == currentId,
                                isPlaying = isPlaying && track.id == currentId,
                                isResolving = isResolving && track.id == currentId,
                                onPlay = { onPlay(track) },
                                onActions = { onTrackActions(track) },
                                modifier = Modifier.weight(1f)
                            )
                        }
                    }
                    repeat(HOME_PERSONAL_ORBIT_GRID_COLUMNS - rowTracks.size) {
                        Spacer(modifier = Modifier.weight(1f))
                    }
                }
            }
        }
    }

    val bubbleHandle = LocalHomeDiscovery.current
    Column(verticalArrangement = Arrangement.spacedBy(homeHeaderContentGap())) {
        HomeSectionInset {
            HomeOrbitHeader(
                userName = userName,
                profilePhotoPath = profilePhotoPath,
                profilePhotoVersion = profilePhotoVersion,
                accountAvatarUrl = accountAvatarUrl,
                onPlayAll = onPlayAll
            )
        }
        BoxWithConstraints(modifier = Modifier.fillMaxWidth()) {
            val wall = maxWidth >= LevyraHomeDesign.OrbitWallMinWidth
            if (wall) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .horizontalScroll(rememberScrollState())
                ) {
                    pages.indices.forEach { pageIndex ->
                        key(pageKey(pageIndex)) {
                            orbitPage(pageIndex, Modifier.width(LevyraHomeDesign.OrbitWallPageWidth))
                        }
                    }
                }
            } else {
                Column(verticalArrangement = Arrangement.spacedBy(LevyraHomeDesign.OrbitDotsTopGap)) {
                    HorizontalPager(
                        state = pagerState,
                        modifier = Modifier.fillMaxWidth(),
                        key = pageKey
                    ) { pageIndex ->
                        orbitPage(pageIndex, Modifier.fillMaxWidth())
                    }
                    if (pages.size > 1) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.spacedBy(
                                LevyraHomeDesign.OrbitDotGap,
                                Alignment.CenterHorizontally
                            ),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            pages.indices.forEach { index ->
                                Box(
                                    modifier = Modifier
                                        .size(LevyraHomeDesign.OrbitDotSize)
                                        .background(
                                            if (pagerState.currentPage == index) {
                                                LevyraText
                                            } else {
                                                LevyraText.copy(alpha = 0.30f)
                                            },
                                            CircleShape
                                        )
                                )
                            }
                        }
                    }
                }
            }
        }
        if (bubbleHandle != null) {
            val strings = LocalLevyraStrings.current
            val bubbleArtworks = remember(tracks) {
                tracks.mapNotNull { track -> track.thumbnailUrl.ifBlank { track.largeThumbnailUrl }.takeIf(String::isNotBlank) }.distinct().take(3)
            }
            HomeSectionInset {
                com.luc4n3x.levyra.ui.discovery.BubbleOrbitEntry(
                    copy = com.luc4n3x.levyra.ui.i18n.smartMusicCopy(strings.code),
                    animated = LocalAnimationsEnabled.current,
                    artworks = bubbleArtworks,
                    onOpen = { bubbleHandle.onOpenBubble(com.luc4n3x.levyra.feature.discovery.BubbleLevel.Adventurous) }
                )
            }
        }
    }
}

