private fun homeSoundtrackPrimaryArtist(rawArtist: String): String {
    var value = rawArtist.trim()
    if (value.isBlank()) return value
    val separators = listOf(",", " & ", " feat. ", " feat ", " featuring ", " x ")
    separators.forEach { separator ->
        val index = value.indexOf(separator, ignoreCase = true)
        if (index > 0) value = value.substring(0, index).trim()
    }
    return value
}

private data class HomeSpotlightHero(
    val candidate: HomeSpotlightCandidate,
    val artistArtworkUrl: String,
    val artists: List<String>,
    val companionArtworkUrls: List<String>
)

private fun homeSoundtrackCompanions(
    tracks: List<Track>,
    artistPool: List<Triple<String, String, String>>,
    heroArtistName: String
): List<String> {
    val heroKey = heroArtistName.trim().lowercase(Locale.ROOT)
    return artistPool.asSequence()
        .filter { artist -> homeArtistPortraitUrlEligible(artist.third) }
        .filter { artist -> homeSoundtrackPrimaryArtist(artist.first).lowercase(Locale.ROOT) != heroKey }
        .filter { artist -> tracks.any { track -> homeSoundtrackMatchesArtist(track, artist.first, artist.second) } }
        .distinctBy { artist -> homeSoundtrackPrimaryArtist(artist.first).lowercase(Locale.ROOT) }
        .map { artist -> artist.third.trim() }
        .take(HOME_HERO_COMPANION_LIMIT)
        .toList()
}

private fun homeSoundtrackArtists(tracks: List<Track>, heroTrack: Track): List<String> {
    return sequenceOf(heroTrack)
        .plus(tracks.asSequence())
        .map { homeSoundtrackPrimaryArtist(it.artist) }
        .filter(String::isNotBlank)
        .distinctBy { it.lowercase(Locale.ROOT) }
        .take(3)
        .toList()
}

private fun homeArtistPortraitUrlEligible(url: String): Boolean {
    val clean = url.trim()
    if (!clean.startsWith("https://", ignoreCase = true)) return false
    if (LevyraPersonalOrbit.isVideoFrameArtworkUrl(clean)) return false
    val lower = clean.lowercase(Locale.ROOT)
    if (lower.contains("i.scdn.co/")) {
        return lower.contains("ab676161")
    }
    return true
}

private fun homeArtistPortraitSourceRank(url: String): Int {
    val lower = url.trim().lowercase(Locale.ROOT)
    return when {
        lower.contains("i.scdn.co/") && lower.contains("ab676161") -> 0
        lower.contains("mzstatic.com/") -> 1
        lower.contains("googleusercontent.com/") || lower.contains("ggpht.com/") -> 2
        else -> 3
    }
}

private fun highResolutionHomeArtistArtworkUrl(url: String): String {
    val upgraded = highResolutionPlayerArtworkUrl(url)
    if (!upgraded.contains("i.scdn.co/", ignoreCase = true)) return upgraded
    return upgraded
        .replace("ab67616100005174", "ab6761610000e5eb", ignoreCase = true)
        .replace("ab6761610000f178", "ab6761610000e5eb", ignoreCase = true)
}

@Composable
private fun rememberHomeHeroPortrait(hero: HomeSpotlightHero?): HomeSpotlightHero? {
    val context = LocalContext.current
    val spotifyRepository = remember(context) { SpotifyArtistArtworkRepository.get(context) }
    val appleRepository = remember(context) { AppleArtistArtworkRepository.get(context) }
    val artistName = hero?.artists?.firstOrNull().orEmpty().trim()
    val fallbackUrl = hero?.artistArtworkUrl.orEmpty()
    var externalPortraitUrl by rememberSaveable(artistName) {
        mutableStateOf(
            spotifyRepository.cachedArtistPortrait(artistName)
                .takeIf(String::isNotBlank)
                ?.let(::highResolutionHomeArtistArtworkUrl)
                .orEmpty()
        )
    }
    var portraitLookupComplete by rememberSaveable(artistName) {
        mutableStateOf(artistName.isBlank() || externalPortraitUrl.isNotBlank())
    }
    var lockedFallbackUrl by rememberSaveable(artistName) { mutableStateOf("") }
    LaunchedEffect(artistName, spotifyRepository, appleRepository) {
        if (portraitLookupComplete) return@LaunchedEffect
        val portrait = spotifyRepository.resolveArtistPortrait(artistName)
            .ifBlank { appleRepository.resolveArtistPortrait(artistName) }
        externalPortraitUrl = portrait.takeIf(String::isNotBlank)
            ?.let(::highResolutionHomeArtistArtworkUrl)
            .orEmpty()
        portraitLookupComplete = true
    }
    LaunchedEffect(portraitLookupComplete, externalPortraitUrl, fallbackUrl) {
        if (portraitLookupComplete && externalPortraitUrl.isBlank() && lockedFallbackUrl.isBlank()) {
            lockedFallbackUrl = fallbackUrl
        }
    }
    val portraitUrl = when {
        !portraitLookupComplete -> ""
        externalPortraitUrl.isNotBlank() -> externalPortraitUrl
        else -> lockedFallbackUrl.ifBlank { fallbackUrl }
    }
    return remember(hero, portraitUrl) { hero?.copy(artistArtworkUrl = portraitUrl) }
}

private fun homeSoundtrackMatchesArtist(track: Track, artistName: String, browseId: String): Boolean {
    if (artistName.isBlank()) return false
    if (browseId.isNotBlank() && track.artistBrowseIds.any { it.equals(browseId, ignoreCase = true) }) return true
    val primary = homeSoundtrackPrimaryArtist(track.artist)
    return primary.equals(artistName.trim(), ignoreCase = true)
}

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
private fun HomeEditorialSpotlight(
    candidate: HomeSpotlightCandidate,
    artistArtworkUrl: String,
    soundtrackArtists: List<String>,
    companionArtworkUrls: List<String>,
    isCurrent: Boolean,
    isPlaying: Boolean,
    isResolving: Boolean,
    onPaletteChanged: (Color, Color) -> Unit,
    onOpen: () -> Unit,
    header: (@Composable () -> Unit)? = null,
    backdropBleed: Dp = 0.dp
) {
    val track = candidate.track
    val strings = LocalLevyraStrings.current
    val interaction = remember { MutableInteractionSource() }
    val context = LocalContext.current
    val resolvedArtistArtworkUrl = artistArtworkUrl
    val fallbackPalette = remember(track.accentStart, track.accentEnd) {
        ArtworkPalette(track.accentStart, track.accentEnd)
    }
    val paletteKey = remember(track.id, track.thumbnailUrl, track.largeThumbnailUrl) {
        ArtworkPaletteCache.key(
            trackId = track.id,
            thumbnailUrl = track.thumbnailUrl,
            largeThumbnailUrl = track.largeThumbnailUrl
        )
    }
    val memoryPalette = remember(paletteKey) {
        ArtworkPaletteCache.peek(paletteKey)
    }
    val artworkPaletteState = remember(paletteKey) {
        mutableStateOf(memoryPalette ?: fallbackPalette)
    }
    var cacheLookupComplete by remember(paletteKey) {
        mutableStateOf(memoryPalette != null)
    }
    var paletteExtractionStarted by remember(paletteKey) {
        mutableStateOf(memoryPalette != null)
    }
    var loadedArtworkBitmap by remember(paletteKey) {
        mutableStateOf<android.graphics.Bitmap?>(null)
    }
    LaunchedEffect(paletteKey) {
        if (memoryPalette == null) {
            val persistedPalette = ArtworkPaletteCache.load(context, paletteKey)
            if (persistedPalette != null) {
                artworkPaletteState.value = persistedPalette
                paletteExtractionStarted = true
                loadedArtworkBitmap = null
            }
            cacheLookupComplete = true
        }
    }
    LaunchedEffect(paletteKey, cacheLookupComplete, loadedArtworkBitmap) {
        val sourceBitmap = loadedArtworkBitmap ?: return@LaunchedEffect
        if (!cacheLookupComplete || paletteExtractionStarted) return@LaunchedEffect
        paletteExtractionStarted = true
        val extracted = withContext(Dispatchers.Default) {
            runCatching<ArtworkPalette> {
                val resizedBitmap = if (sourceBitmap.width == 96 && sourceBitmap.height == 96) {
                    sourceBitmap
                } else {
                    android.graphics.Bitmap.createScaledBitmap(sourceBitmap, 96, 96, true)
                }
                val paletteBitmap = if (resizedBitmap.config == android.graphics.Bitmap.Config.ARGB_8888) {
                    resizedBitmap
                } else {
                    resizedBitmap.copy(android.graphics.Bitmap.Config.ARGB_8888, false) ?: resizedBitmap
                }
                try {
                    ArtworkPaletteCache.extract(
                        bitmap = paletteBitmap,
                        fallbackStart = fallbackPalette.start,
                        fallbackEnd = fallbackPalette.end
                    )
                } finally {
                    if (paletteBitmap !== resizedBitmap) paletteBitmap.recycle()
                    if (resizedBitmap !== sourceBitmap) resizedBitmap.recycle()
                }
            }.getOrNull()
        }
        if (extracted != null) {
            artworkPaletteState.value = extracted
            ArtworkPaletteCache.store(context, paletteKey, extracted)
        }
        loadedArtworkBitmap = null
    }
    val accentStart by animateColorAsState(
        targetValue = Color(artworkPaletteState.value.start),
        animationSpec = if (LocalAnimationsEnabled.current) tween(durationMillis = 420, easing = FastOutSlowInEasing) else snap(),
        label = "homeSpotlightAccentStart"
    )
    val accentEnd by animateColorAsState(
        targetValue = Color(artworkPaletteState.value.end),
        animationSpec = if (LocalAnimationsEnabled.current) tween(durationMillis = 420, easing = FastOutSlowInEasing) else snap(),
        label = "homeSpotlightAccentEnd"
    )
    LaunchedEffect(accentStart, accentEnd) {
        onPaletteChanged(accentStart, accentEnd)
    }
    val portraitPalette by rememberArtworkPalette(
        paletteKey = remember(resolvedArtistArtworkUrl) {
            if (resolvedArtistArtworkUrl.isBlank()) {
                ""
            } else {
                ArtworkPaletteCache.key(
                    trackId = "home-hero-portrait",
                    thumbnailUrl = resolvedArtistArtworkUrl,
                    largeThumbnailUrl = resolvedArtistArtworkUrl
                )
            }
        },
        artworkUrl = resolvedArtistArtworkUrl,
        fallback = artworkPaletteState.value
    )
    val heroSeed by animateColorAsState(
        targetValue = homeSoundtrackHeroSeed(
            portrait = if (resolvedArtistArtworkUrl.isBlank()) accentStart else Color(portraitPalette.start),
            fallback = MaterialTheme.colorScheme.primary
        ),
        animationSpec = if (LocalAnimationsEnabled.current) tween(durationMillis = 420, easing = FastOutSlowInEasing) else snap(),
        label = "homeSpotlightHeroSeed"
    )
    val soundtrackTitle = strings.homeSoundtrackTitle
    val soundtrackLead = remember(strings, soundtrackArtists) { strings.homeSoundtrackLead(soundtrackArtists) }
    val visibleCompanionArtworkUrls = companionArtworkUrls.ifEmpty {
        resolvedArtistArtworkUrl.takeIf(String::isNotBlank)?.let { listOf(it) }.orEmpty()
    }
    val isLight = LevyraIsLight
    val canvasColor = homeCanvasColor(isLight)
    val heroInk = if (isLight) LevyraText else Color.White
    val heroInkSoft = if (isLight) LevyraText.copy(alpha = 0.80f) else Color.White.copy(alpha = 0.90f)
    val staged = header != null
    val heroBodyHeight = levyraCompactLandscapeHeight(
        preferred = if (staged) HOME_HERO_STAGE_BODY_HEIGHT else LevyraHomeDesign.HeroHeight,
        viewportShare = HOME_HERO_LANDSCAPE_VIEWPORT_SHARE,
        minimum = HOME_HERO_LANDSCAPE_MIN_HEIGHT
    )

    val heroBlur = LocalLevyraVisualCapabilities.current.heavyBlur &&
        android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.S
    val heroTones = remember(heroSeed, isLight) { homeSoundtrackHeroTones(heroSeed, isLight) }
    val chipFill = heroTones.chip
    val playFill = heroTones.action
    val playInk = heroTones.onAction

    Box(modifier = Modifier.fillMaxWidth()) {
        Box(
            modifier = Modifier
                .matchParentSize()
                .homeHeroBleed(backdropBleed)
                .homeHeroBottomDissolve()
                .drawBehind {
                    drawRect(
                        Brush.radialGradient(
                            colors = listOf(accentStart.copy(alpha = if (isLight) 0.10f else 0.14f), Color.Transparent),
                            center = Offset(size.width * 0.86f, size.height * 0.42f),
                            radius = size.width
                        )
                    )
                }
        ) {
            if (resolvedArtistArtworkUrl.isNotBlank()) {
                if (heroBlur) {
                    StableRemoteArtwork(
                        url = resolvedArtistArtworkUrl,
                        contentDescription = null,
                        modifier = Modifier
                            .fillMaxSize()
                            .graphicsLayer { alpha = if (isLight) 0.56f else 0.58f }
                            .blur(64.dp, BlurredEdgeTreatment.Rectangle),
                        contentScale = ContentScale.Crop
                    )
                }
                StableRemoteArtwork(
                    url = resolvedArtistArtworkUrl,
                    contentDescription = soundtrackTitle,
                    modifier = Modifier
                        .align(Alignment.TopEnd)
                        .fillMaxHeight()
                        .fillMaxWidth(HOME_HERO_PORTRAIT_SHARE)
                        .graphicsLayer { compositingStrategy = CompositingStrategy.Offscreen }
                        .drawWithContent {
                            drawContent()
                            drawRect(
                                brush = Brush.horizontalGradient(
                                    0f to Color.Transparent,
                                    0.30f to Color.Black.copy(alpha = 0.62f),
                                    0.56f to Color.Black
                                ),
                                blendMode = BlendMode.DstIn
                            )
                        },
                    contentScale = ContentScale.Crop,
                    alignment = BiasAlignment(0f, -0.3f),
                    highRes = true
                )
            }
            Box(
                modifier = Modifier
                    .matchParentSize()
                    .homeHeroBlend(
                        canvas = canvasColor,
                        accent = { accentStart },
                        isLight = isLight,
                        fadeTop = !staged
                    )
            )
        }
        Column(modifier = Modifier.fillMaxWidth()) {
            if (header != null) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .homeHeroHeaderScrim(canvasColor, isLight, backdropBleed)
                ) {
                    header()
                }
            }
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(heroBodyHeight)
                    .clickable(
                        interactionSource = interaction,
                        indication = null,
                        onClick = onOpen
                    )
            ) {
                Column(
                    modifier = Modifier
                        .align(Alignment.BottomStart)
                        .fillMaxWidth(0.66f)
                        .padding(start = 20.dp, end = 8.dp, bottom = 30.dp),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        Row(
                            modifier = Modifier
                                .clip(CircleShape)
                                .background(chipFill)
                                .padding(start = 6.dp, end = 12.dp, top = 5.dp, bottom = 5.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(7.dp)
                        ) {
                            Box(
                                modifier = Modifier
                                    .size(14.dp)
                                    .clip(homeHeroChipBadgeShape())
                                    .background(heroTones.badge)
                            )
                            Text(
                                text = strings.homeSoundtrackRadio,
                                color = heroTones.onChip,
                                style = LevyraType.overline,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis
                            )
                        }
                    }
                    Text(
                        text = soundtrackTitle,
                        color = heroInk,
                        style = LevyraType.heroTitle,
                        maxLines = 3,
                        overflow = TextOverflow.Ellipsis,
                        modifier = Modifier.semantics { heading() }
                    )
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        if (visibleCompanionArtworkUrls.isNotEmpty()) {
                            HomeSoundtrackCompanionStack(
                                artworkUrls = visibleCompanionArtworkUrls,
                                ring = canvasColor,
                                accent = heroTones.badge
                            )
                        }
                        Text(
                            text = soundtrackLead,
                            color = heroInkSoft,
                            fontSize = 15.sp,
                            lineHeight = 20.5.sp,
                            fontWeight = FontWeight.Medium,
                            maxLines = 2,
                            overflow = TextOverflow.Ellipsis,
                            modifier = Modifier.weight(1f, fill = false)
                        )
                    }
                }

                Surface(
                    color = playFill,
                    shape = rememberLevyraPlayMorphShape(
                        playing = isCurrent && isPlaying,
                        animated = LocalAnimationsEnabled.current,
                        spinWhilePlaying = !isResolving
                    ),
                    modifier = Modifier
                        .align(Alignment.BottomEnd)
                        .padding(end = 20.dp, bottom = 32.dp)
                        .size(68.dp)
                ) {
                    Box(contentAlignment = Alignment.Center) {
                        when {
                            isResolving -> DiscoveryLoadingIndicator(
                                modifier = Modifier.size(24.dp),
                                color = playInk
                            )
                            isCurrent && isPlaying -> Icon(
                                imageVector = Icons.Rounded.Pause,
                                contentDescription = strings.pause,
                                tint = playInk,
                                modifier = Modifier.size(24.dp)
                            )
                            else -> Icon(
                                imageVector = Icons.Rounded.PlayArrow,
                                contentDescription = strings.playNow,
                                tint = playInk,
                                modifier = Modifier.size(26.dp)
                            )
                        }
                    }
                }

                if (isCurrent && isPlaying) {
                    Surface(
                        color = Color.Black.copy(alpha = 0.48f),
                        shape = CircleShape,
                        border = BorderStroke(Dp.Hairline, Color.White.copy(alpha = 0.14f)),
                        modifier = Modifier
                            .align(Alignment.TopEnd)
                            .padding(14.dp)
                    ) {
                        Row(
                            modifier = Modifier.padding(horizontal = 10.dp, vertical = 7.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                        ) {
                            ActiveTrackEqualizer(
                                color = accentStart,
                                isPlaying = true,
                                width = 13.dp,
                                height = 9.dp
                            )
                            Text(
                                text = strings.playing,
                                color = Color.White.copy(alpha = 0.90f),
                                fontSize = 10.5.sp,
                                fontWeight = FontWeight.Bold,
                                maxLines = 1
                            )
                        }
                    }
                }
            }
        }
    }
}

private const val HOME_HERO_PORTRAIT_SHARE = 0.84f
private const val HOME_HERO_COMPANION_LIMIT = 3
private val HOME_HERO_COMPANION_SIZE = 30.dp
private val HOME_HERO_COMPANION_OVERLAP = 10.dp

@Composable
private fun HomeSoundtrackCompanionStack(
    artworkUrls: List<String>,
    ring: Color,
    accent: Color
) {
    val animate = LocalAnimationsEnabled.current
    Row(horizontalArrangement = Arrangement.spacedBy(-HOME_HERO_COMPANION_OVERLAP)) {
        artworkUrls.forEachIndexed { index, url ->
            val reveal = remember(url) { Animatable(if (animate) 0f else 1f) }
            LaunchedEffect(url, animate) {
                if (!animate) {
                    reveal.snapTo(1f)
                    return@LaunchedEffect
                }
                delay(HOME_HERO_COMPANION_STAGGER_MS * index)
                reveal.animateTo(
                    targetValue = 1f,
                    animationSpec = spring(
                        dampingRatio = Spring.DampingRatioMediumBouncy,
                        stiffness = Spring.StiffnessMediumLow
                    )
                )
            }
            Box(
                modifier = Modifier
                    .size(HOME_HERO_COMPANION_SIZE)
                    .graphicsLayer {
                        val progress = reveal.value
                        alpha = progress.coerceIn(0f, 1f)
                        scaleX = 0.6f + 0.4f * progress
                        scaleY = 0.6f + 0.4f * progress
                        rotationZ = (1f - progress) * -24f
                    }
                    .zIndex((artworkUrls.size - index).toFloat())
                    .clip(CircleShape)
                    .background(ring)
                    .padding(2.dp)
                    .clip(CircleShape)
                    .background(accent)
            ) {
                StableRemoteArtwork(
                    url = url,
                    contentDescription = null,
                    modifier = Modifier.fillMaxSize(),
                    contentScale = ContentScale.Crop
                )
            }
        }
    }
}

private const val HOME_HERO_COMPANION_STAGGER_MS = 70L

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
private fun homeHeroChipBadgeShape(): Shape = MaterialShapes.Cookie6Sided.toShape()

@Composable
private fun HomeStatusBarScrim(listState: LazyListState, height: Dp, canvas: Color) {
    if (height <= 0.dp) return
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .height(height + 12.dp)
            .graphicsLayer {
                alpha = if (listState.firstVisibleItemIndex > 0) {
                    1f
                } else {
                    (listState.firstVisibleItemScrollOffset / HOME_STATUS_SCRIM_FADE_DISTANCE.toPx()).coerceIn(0f, 1f)
                }
            }
            .background(
                Brush.verticalGradient(
                    colorStops = arrayOf(
                        0f to canvas.copy(alpha = 0.94f),
                        0.72f to canvas.copy(alpha = 0.86f),
                        1f to canvas.copy(alpha = 0f)
                    )
                )
            )
    )
}

private const val HomeChartPodiumSize = 10

internal fun chartRowsPerColumn(trackCount: Int): Int = when {
    trackCount <= 0 -> 4
    trackCount % 4 == 0 -> 4
    trackCount % 5 == 0 -> 5
    else -> 4
}
private val HOME_HERO_STAGE_BODY_HEIGHT = LevyraHomeDesign.HeroHeight - 48.dp
private const val HOME_HERO_LANDSCAPE_VIEWPORT_SHARE = 0.62f
private val HOME_HERO_LANDSCAPE_MIN_HEIGHT = 236.dp
private val HOME_HERO_FADE_LENGTH = 360.dp
private val HOME_HERO_DISSOLVE_LENGTH = 140.dp
private val HOME_HERO_TOP_FADE = 72.dp
private val HOME_HERO_HEADER_SCRIM_TAIL = 72.dp
private val HOME_STATUS_SCRIM_FADE_DISTANCE = 96.dp

private fun Modifier.homeHeroBleed(bleed: Dp): Modifier = layout { measurable, constraints ->
    val bleedPx = bleed.roundToPx().coerceAtLeast(0)
    if (bleedPx == 0 || !constraints.hasBoundedHeight) {
        val placeable = measurable.measure(constraints)
        return@layout layout(placeable.width, placeable.height) { placeable.place(0, 0) }
    }
    val placeable = measurable.measure(
        Constraints.fixed(constraints.maxWidth, constraints.maxHeight + bleedPx)
    )
    layout(constraints.maxWidth, constraints.maxHeight) { placeable.place(0, -bleedPx) }
}

private fun Modifier.homeHeroBlend(
    canvas: Color,
    accent: () -> Color,
    isLight: Boolean,
    fadeTop: Boolean
): Modifier = drawWithCache {
    val fadeLength = minOf(size.height * 0.72f, HOME_HERO_FADE_LENGTH.toPx() * 1.15f)
    val fadeStart = size.height - fadeLength
    val tint = lerp(canvas, accent(), if (isLight) 0.03f else 0.06f)
    val bottomFade = Brush.verticalGradient(
        colorStops = arrayOf(
            0f to tint.copy(alpha = 0f),
            0.22f to tint.copy(alpha = 0.18f),
            0.44f to tint.copy(alpha = 0.48f),
            0.64f to canvas.copy(alpha = 0.76f),
            0.82f to canvas.copy(alpha = 0.92f),
            1f to canvas
        ),
        startY = fadeStart,
        endY = size.height
    )
    val textScrim = Brush.radialGradient(
        colorStops = arrayOf(
            0f to canvas.copy(alpha = if (isLight) 0.24f else 0.32f),
            0.55f to canvas.copy(alpha = if (isLight) 0.10f else 0.16f),
            1f to canvas.copy(alpha = 0f)
        ),
        center = Offset(0f, size.height),
        radius = maxOf(size.width * 0.95f, fadeLength)
    )
    val topFadeHeight = HOME_HERO_TOP_FADE.toPx().coerceAtMost(size.height)
    val topFade = Brush.verticalGradient(
        colorStops = arrayOf(
            0f to canvas,
            1f to canvas.copy(alpha = 0f)
        ),
        startY = 0f,
        endY = topFadeHeight
    )
    onDrawBehind {
        drawRect(brush = bottomFade, topLeft = Offset(0f, fadeStart), size = Size(size.width, fadeLength))
        drawRect(brush = textScrim)
        if (fadeTop) drawRect(brush = topFade, size = Size(size.width, topFadeHeight))
    }
}

private fun Modifier.homeHeroBottomDissolve(): Modifier = graphicsLayer {
    compositingStrategy = CompositingStrategy.Offscreen
}.drawWithCache {
    val dissolveLength = minOf(size.height * 0.42f, HOME_HERO_DISSOLVE_LENGTH.toPx())
    val dissolveStart = size.height - dissolveLength
    val mask = Brush.verticalGradient(
        colorStops = arrayOf(
            0f to Color.Black,
            0.30f to Color.Black.copy(alpha = 0.86f),
            0.58f to Color.Black.copy(alpha = 0.48f),
            0.82f to Color.Black.copy(alpha = 0.14f),
            1f to Color.Transparent
        ),
        startY = dissolveStart,
        endY = size.height
    )
    onDrawWithContent {
        drawContent()
        drawRect(brush = mask, blendMode = BlendMode.DstIn)
    }
}

private fun Modifier.homeHeroHeaderScrim(canvas: Color, isLight: Boolean, bleed: Dp): Modifier = drawWithCache {
    val top = -bleed.toPx()
    val bottom = size.height + HOME_HERO_HEADER_SCRIM_TAIL.toPx()
    val scrim = if (isLight) canvas else Color.Black
    val brush = Brush.verticalGradient(
        colorStops = arrayOf(
            0f to scrim.copy(alpha = if (isLight) 0.72f else 0.78f),
            0.58f to scrim.copy(alpha = if (isLight) 0.38f else 0.52f),
            1f to scrim.copy(alpha = 0f)
        ),
        startY = top,
        endY = bottom
    )
    onDrawBehind {
        drawRect(brush = brush, topLeft = Offset(0f, top), size = Size(size.width, bottom - top))
    }
}

private fun homeCollectionTitle(strings: LevyraStrings, collection: HomeEditorialCollection): String {
    if (collection.titleOverride.isNotBlank()) return cleanHomeSectionTitle(collection.titleOverride)
    val title = when (collection.kind) {
        HomeCollectionKind.Fresh -> strings.collectionFresh
        HomeCollectionKind.Local -> strings.collectionLocal
        HomeCollectionKind.Workout -> strings.collectionWorkout
        HomeCollectionKind.Chill -> strings.collectionChill
        HomeCollectionKind.Focus -> strings.collectionFocus
        HomeCollectionKind.Party -> strings.collectionParty
        HomeCollectionKind.Rap -> strings.collectionRap
        HomeCollectionKind.Pop -> strings.collectionPop
        HomeCollectionKind.Discovery -> strings.collectionDiscovery
        HomeCollectionKind.Editorial -> strings.collectionEditorial
        HomeCollectionKind.Charts -> strings.collectionCharts
        HomeCollectionKind.Repeat -> strings.collectionRepeat
        HomeCollectionKind.Throwback -> strings.collectionThrowback
        HomeCollectionKind.Gems -> strings.collectionGems
    }
    return cleanHomeSectionTitle(title)
}

private fun buildHomeCollectionAccents(collections: List<HomeEditorialCollection>): Map<String, Pair<Color, Color>> {
    val seeds = collections.map { collection ->
        if (collection.accentStart != 0 && collection.accentEnd != 0) {
            Color(collection.accentStart)
        } else {
            exploreEditorialPalette(collection.id).first
        }
    }
    return collections.map { it.id }.zip(distinctEditorialAccents(seeds)).toMap()
}

private fun exploreEditorialPalette(identity: String): Pair<Color, Color> {
    val palette = listOf(
        Color(0xFF7C3AED) to Color(0xFF4C1D95),
        Color(0xFFD81B60) to Color(0xFF7A1538),
        Color(0xFF0F8A78) to Color(0xFF075E54),
        Color(0xFF246BCE) to Color(0xFF173F7A),
        Color(0xFFB96A16) to Color(0xFF70400F),
        Color(0xFF238636) to Color(0xFF145325),
        Color(0xFFB335B5) to Color(0xFF64236C),
        Color(0xFFD9571C) to Color(0xFF7B3215)
    )
    return palette[(identity.hashCode() and Int.MAX_VALUE) % palette.size]
}

@Composable
private fun HomeEditorialCollectionsShelf(
    collections: List<HomeEditorialCollection>,
    accents: Map<String, Pair<Color, Color>>,
    onOpen: (HomeEditorialCollection) -> Unit
) {
    val strings = LocalLevyraStrings.current
    Column(verticalArrangement = Arrangement.spacedBy(homeHeaderContentGap())) {
        HomeSectionHeader(
            title = strings.collectionsTitle,
            modifier = Modifier.padding(horizontal = HomeHorizontalInset)
        )
        BoxWithConstraints(modifier = Modifier.fillMaxWidth()) {
            val cardWidth = (maxWidth - LevyraHomeDesign.EditorialPeek)
                .coerceAtMost(LevyraHomeDesign.EditorialMaxWidth)
            val cardHeight = if (LocalDensity.current.fontScale > 1.4f) {
                LevyraHomeDesign.EditorialLargeTextHeight
            } else {
                LevyraHomeDesign.EditorialHeight
            }
            val collectionArtworks = remember(collections) {
                val usedTrackIds = mutableSetOf<String>()
                collections.associate { collection ->
                    val nonVideoTracks = collection.tracks.filter { track ->
                        !YoutubeMusicVideoType.isVideo(track.videoType) &&
                            !track.thumbnailUrl.contains("/vi/", ignoreCase = true) &&
                            !track.thumbnailUrl.contains("vi_webp", ignoreCase = true) &&
                            !track.largeThumbnailUrl.contains("/vi/", ignoreCase = true) &&
                            !track.largeThumbnailUrl.contains("vi_webp", ignoreCase = true) &&
                            track.thumbnailUrl.isNotBlank()
                    }
                    val selectedTrack = nonVideoTracks.firstOrNull { it.id !in usedTrackIds }
                        ?: nonVideoTracks.firstOrNull()
                        ?: collection.tracks.firstOrNull { it.id !in usedTrackIds && !YoutubeMusicVideoType.isVideo(it.videoType) }
                        ?: collection.tracks.firstOrNull { !YoutubeMusicVideoType.isVideo(it.videoType) }
                        ?: collection.tracks.firstOrNull()
                    if (selectedTrack != null) {
                        usedTrackIds += selectedTrack.id
                    }
                    collection.id to selectedTrack
                }
            }
            LazyRow(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(LevyraHomeDesign.ShelfItemGap),
                contentPadding = PaddingValues(horizontal = HomeHorizontalInset)
            ) {
                items(
                    items = collections,
                    key = { collection -> "home-collection-${collection.id}" },
                    contentType = { "home-editorial-wide" }
                ) { collection ->
                    val artistLine = remember(collection.tracks) {
                        collection.tracks.asSequence()
                            .map { it.artist.trim() }
                            .filter(String::isNotBlank)
                            .distinct()
                            .take(2)
                            .joinToString(" · ")
                    }
                    val artworkTrack = collectionArtworks[collection.id]
                    val (accentStart, accentEnd) = accents[collection.id]
                        ?: exploreEditorialPalette(collection.id)
                    DiscoveryEditorialCard(
                        title = homeCollectionTitle(strings, collection),
                        subtitle = artistLine,
                        artwork = artworkTrack,
                        accentStart = accentStart,
                        accentEnd = accentEnd,
                        artworkShape = homeCollectionArtworkShape(collections.indexOf(collection)),
                        onOpen = { onOpen(collection) },
                        modifier = Modifier
                            .width(cardWidth)
                            .height(cardHeight)
                    )
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
private fun homeCollectionArtworkShape(index: Int): Shape {
    val polygons = listOf(
        MaterialShapes.Cookie9Sided,
        MaterialShapes.Clover4Leaf,
        MaterialShapes.Sunny,
        MaterialShapes.Cookie12Sided,
        MaterialShapes.SoftBurst,
        MaterialShapes.Cookie7Sided,
        MaterialShapes.Clover8Leaf,
        MaterialShapes.Cookie6Sided
    )
    return polygons[index.coerceAtLeast(0) % polygons.size].toShape()
}

@Composable
private fun HomeEditorialArtworkStack(
    track: Track?,
    modifier: Modifier = Modifier
) {
    Box(modifier = modifier, contentAlignment = Alignment.BottomEnd) {
        if (track != null) {
            CoverImage(
                track = track,
                modifier = Modifier
                    .size(92.dp)
                    .offset(x = 14.dp, y = 12.dp)
                    .graphicsLayer { rotationZ = 12f }
                    .clip(RoundedCornerShape(8.dp)),
                highRes = false,
                zoom = 1.02f
            )
        }
    }
}

internal fun homeQuickAccessColumns(tracks: List<Track>): List<List<Track>> {
    return tracks
        .distinctBy(LevyraPersonalOrbit::identityKey)
        .take(HOME_QUICK_ACCESS_LIMIT)
        .chunked(HOME_QUICK_ACCESS_PAGE_SIZE)
        .flatMap { page ->
            listOf(
                page.filterIndexed { index, _ -> index % 2 == 0 },
                page.filterIndexed { index, _ -> index % 2 != 0 }
            ).filter { it.isNotEmpty() }
        }
}

@Composable
private fun HomeQuickPicksShelf(
    title: String,
    tracks: List<Track>,
    currentId: String?,
    isPlaying: Boolean,
    isResolving: Boolean,
    onPlay: (Track) -> Unit,
