                FilledIconButton(onClick = onPlayAll, modifier = Modifier.size(LevyraPlayerDesign.MinimumTouchTarget)) {
                    Icon(Icons.Rounded.PlayArrow, contentDescription = strings.playAll)
                }
            } else {
