        ) {
            StudioPersonalOrbitArtwork(
                style = style,
                index = index,
                shape = shape,
                track = track,
                isCurrent = isCurrent,
                isPlaying = isPlaying,
                isResolving = isResolving,
                titleInside = false,
                modifier = Modifier.fillMaxWidth()
            )
            Text(
                text = track.title,
                color = if (isCurrent) MaterialTheme.colorScheme.primary else LevyraText,
                fontSize = LevyraHomeDesign.OrbitTileTitleSize,
