@Composable
private fun StudioPersonalOrbitArtwork(
    style: HomeStyle,
    index: Int,
    shape: Shape,
    track: Track,
    isCurrent: Boolean,
    isPlaying: Boolean,
    isResolving: Boolean,
    titleInside: Boolean,
    modifier: Modifier,
    pressModifier: Modifier = Modifier
) {
    val ratio = when (style) {
        HomeStyle.Editorial -> 1.18f
        HomeStyle.Immersive -> 0.86f
        else -> 1f
    }
    val tilt = if (style == HomeStyle.ExpressiveMax) {
        when (index % 3) { 0 -> -2.5f; 1 -> 2f; else -> 0f }
    } else 0f
    Box(
        modifier = modifier
            .aspectRatio(ratio)
            .graphicsLayer { rotationZ = tilt }
            .clip(shape)
            .background(LevyraPanel)
            .then(pressModifier)
    ) {
        CoverImage(
            track = track,
            modifier = Modifier.fillMaxSize(),
            highRes = true
        )
        if (titleInside) {
            StudioPersonalOrbitOverlayTitle(track = track, isCurrent = isCurrent)
        }
        if (isCurrent) {
            LevyraNowPlayingBadge(
                isPlaying = isPlaying,
                isResolving = isResolving,
                modifier = Modifier
                    .align(Alignment.TopEnd)
                    .padding(6.dp)
            )
        }
    }
}

