@Composable
private fun SearchScreen(
    viewModel: SearchViewModel,
    state: LevyraUiState,
    appleExploreViewModel: ExploreViewModel? = null,
    backEnabled: Boolean = false,
    onTrackActions: (Track) -> Unit = {}
) {
    if (LevyraIsAtelier) {
        AtelierSearchEntry(viewModel, state, onTrackActions)
        return
    }
    if (LevyraIsQobuz) {
        QobuzSearchEntry(viewModel, state, onTrackActions)
        return
    }
    val strings = LocalLevyraStrings.current
    val focusManager = LocalFocusManager.current
    val keyboardController = LocalSoftwareKeyboardController.current
    var addTarget by remember { mutableStateOf<Track?>(null) }
    var batchAddTargets by remember { mutableStateOf<List<Track>>(emptyList()) }
    val selection = rememberTrackSelectionState()
    val personalized = remember(
        state.favorites,
        state.recentListens,
        state.recentSearches,
        state.personalOrbitTracks,
        state.smartProfile.topArtists
    ) {
        buildPersonalizedSearchSnapshot(
            favorites = state.favorites,
            recentListens = state.recentListens,
            recentSearches = state.recentSearches,
            personalOrbitTracks = state.personalOrbitTracks,
            topArtists = state.smartProfile.topArtists
        )
    }
    val personalizedCopy = personalizedSearchCopy(state.languageCode)
    val personalizedArtists = remember(state.homeArtists, personalized.artistNames) {
        rankPersonalizedSearchArtists(state.homeArtists, personalized.artistNames)
    }
    val personalizedPlaceholders = remember(
        state.languageCode,
        personalized.prompts,
        strings.searchPlaceholder,
        strings.searchSongsArtists,
        strings.emptySearchPrompt
    ) {
        buildSearchPlaceholderCycle(
            personalized = personalized.prompts.mapNotNull { prompt ->
                personalizedSearchPromptText(state.languageCode, prompt)
            },
            fallbacks = listOf(strings.searchPlaceholder, strings.searchSongsArtists, strings.emptySearchPrompt)
        )
    }
    val tasteHintQueries = remember(personalized.prompts, state.languageCode) {
        buildSearchTasteHints(
            prompts = personalized.prompts,
            fallbacks = LevyraContentLocales.quickSearches(state.languageCode) +
                LevyraContentLocales.artistSuggestions(state.languageCode),
            limit = SEARCH_TASTE_HINT_LIMIT
        )
    }
    var placeholderIndex by remember(personalizedPlaceholders) { mutableIntStateOf(0) }
    val activePlaceholder = personalizedPlaceholders[placeholderIndex % personalizedPlaceholders.size]
    val queryClean = state.query.trim()
    val querySuggestions = remember(state.query, state.searchSuggestions) {
        refineSearchQuerySuggestions(state.query, state.searchSuggestions)
    }
    LaunchedEffect(queryClean.isEmpty(), state.animationsEnabled, personalizedPlaceholders) {
        placeholderIndex = placeholderIndex.coerceIn(personalizedPlaceholders.indices)
        if (queryClean.isNotEmpty() || !state.animationsEnabled || personalizedPlaceholders.size < 2) return@LaunchedEffect
        while (true) {
            delay(10_000L)
            placeholderIndex = (placeholderIndex + 1) % personalizedPlaceholders.size
        }
    }

    LaunchedEffect(state.languageCode) {
        viewModel.refreshArtistSuggestions()
    }
    val spotifySearchFocus = remember { mutableStateOf(false) }
    val appleCatalog = appleExploreViewModel?.let { rememberAppleMusicSearchCatalog(state, viewModel::ensureExplore) }
    var appleDestination by rememberSaveable { mutableStateOf<String?>(null) }
    val appleLanding = appleCatalog != null && queryClean.isEmpty() && !spotifySearchFocus.value
    val appleColumns = appleMusicSearchColumns()

    Column(
        modifier = Modifier
            .fillMaxSize()
            .statusBarsPadding()
            .padding(horizontal = if (LevyraIsSpotify) SpotifyDesign.gutter else if (appleCatalog != null) AppleMusicDesign.gutter else 18.dp),
        verticalArrangement = Arrangement.spacedBy(if (appleCatalog != null) 0.dp else 8.dp)
    ) {
        SearchHeader(
            query = state.query,
            placeholder = activePlaceholder,
            animatePlaceholder = state.animationsEnabled,
            isSearching = state.isSearching,
            recognitionAvailable = state.recognitionAvailable,
            recognitionBusy = state.recognitionState is RecognitionState.Listening ||
                state.recognitionState is RecognitionState.Identifying,
            onRecognize = viewModel::startMusicRecognition,
            onCancelRecognition = viewModel::cancelMusicRecognition,
            onQuery = viewModel::setQuery,
            onSearch = { query ->
                focusManager.clearFocus()
                keyboardController?.hide()
                viewModel.searchNow(query)
            },
            onClear = {
                viewModel.setQuery("")
            },
            onBack = { viewModel.navigateBack() },
            userName = state.userName,
            onSettings = viewModel::openSettings,
            spotifyFocus = spotifySearchFocus
        )
        if (queryClean.isEmpty() && !spotifySearchFocus.value) {
            LyricsSearchEntry(onOpen = viewModel::openLyricsPhraseSearch)
        }

        val data = state.searchData
        val filter = state.searchFilter
        val topResultTracks = remember(data.topTrack, data.songs, filter) {
            if (filter == SearchFilter.All) selectSearchTopResultTracks(data.topTrack, data.songs) else emptyList()
        }
        val topResultArtist = remember(data.artists, topResultTracks, queryClean) {
            findVerifiedTopResultArtist(data.artists, topResultTracks.firstOrNull(), queryClean)
        }
        if (LevyraUsesAppleArtistHero) {
            PrefetchAppleArtistHero(topResultArtist?.name, remember(state.selectedChartId) { ChartsCatalog.region(state.selectedChartId).country })
        }
        val visibleSongs = remember(data.songs, topResultTracks, filter) {
            if (filter == SearchFilter.All) filterSearchSongsExcludingTopResult(data.songs, topResultTracks) else data.songs
        }
        val youTubeMusicEntries = remember(LevyraIsYouTubeMusic, filter, visibleSongs, data, topResultArtist) {
            if (!LevyraIsYouTubeMusic) emptyList()
            else youTubeMusicFilteredEntries(filter, visibleSongs, data, topResultArtist)
        }
        val openTopResult: () -> Unit = {
            focusManager.clearFocus()
            keyboardController?.hide()
            val heroTrack = topResultTracks.firstOrNull()
            if (topResultArtist != null) {
                viewModel.openArtistFromHit(topResultArtist)
            } else if (heroTrack != null) {
                viewModel.openArtist(heroTrack)
            }
        }
        val shuffleTopResult: () -> Unit = {
            focusManager.clearFocus()
            keyboardController?.hide()
            val artistName = topResultArtist?.name ?: topResultTracks.firstOrNull()?.artist
            val candidatePool = deduplicateSearchSongs(topResultTracks + data.songs)
            val pool = if (!artistName.isNullOrBlank()) {
                candidatePool.filter { it.artist.contains(artistName, ignoreCase = true) }.ifEmpty { topResultTracks }
            } else {
                topResultTracks
            }
            val shuffled = pool.shuffled()
            shuffled.firstOrNull()?.let { first -> viewModel.playFrom(shuffled, first) }
        }
        val mixTopResult: () -> Unit = {
            focusManager.clearFocus()
            keyboardController?.hide()
            topResultTracks.firstOrNull()?.let { track -> viewModel.startSongRadioFrom(track) }
        }
        val discographyCopy = searchDiscographyCopy(strings.code)
        var albumKind by rememberSaveable(queryClean) { mutableStateOf(SearchAlbumKind.All) }
        val albumKinds = remember(data.albums) { availableSearchAlbumKinds(data.albums) }
        val effectiveAlbumKind = if (albumKind in albumKinds) albumKind else SearchAlbumKind.All
        val visibleAlbums = remember(data.albums, effectiveAlbumKind) {
            data.albums.filter { effectiveAlbumKind.accepts(it.releaseType) }
        }
        val searchGridColumnCount = searchGridColumns(LocalConfiguration.current.screenWidthDp - 36)
        val selectableTracks = remember(topResultTracks, visibleSongs, data.videos, filter) {
            buildList {
                if (filter == SearchFilter.All) addAll(topResultTracks.take(3))
                if (filter == SearchFilter.All || filter == SearchFilter.Songs) addAll(visibleSongs)
                if (filter == SearchFilter.All || filter == SearchFilter.Videos) addAll(data.videos)
            }.distinctBy(::trackSelectionKey)
        }
        val selectableIds = remember(selectableTracks) { selectableTracks.map(::trackSelectionKey) }
        val selectedTracks = remember(selectableTracks, selection.selectedIds) {
            selection.resolveSelected(selectableTracks, ::trackSelectionKey)
        }
        LaunchedEffect(selectableIds) { selection.retainAvailable(selectableIds) }
        BackHandler(enabled = selection.isActive) { selection.exit() }

        val searchActions = YouTubeMusicSearchActions(
            selection = selection,
            playSong = { context, track ->
                if (selection.isActive) {
                    selection.toggle(trackSelectionKey(track))
                } else {
                    focusManager.clearFocus()
                    keyboardController?.hide()
                    viewModel.playFrom(deduplicateSearchSongs(listOf(track) + context), track)
                }
            },
            openArtist = { hit ->
                focusManager.clearFocus()
                keyboardController?.hide()
                viewModel.openArtistFromHit(hit)
            },
            openTopResult = openTopResult,
            shuffle = shuffleTopResult,
            mix = mixTopResult,
            openPlaylist = { playlist ->
                focusManager.clearFocus()
                keyboardController?.hide()
                viewModel.openPlaylistHit(playlist)
            },
            openAlbum = { album ->
                focusManager.clearFocus()
                keyboardController?.hide()
                viewModel.openAlbum(album)
            },
            trackActions = onTrackActions
        )
        val appleFilters = remember(data) { appleSearchFilters(data) }
        val appleFilter = filter.takeIf { it in appleFilters } ?: SearchFilter.All
        val appleResults = remember(appleFilter, visibleSongs, topResultTracks, topResultArtist, data, appleCatalog != null) {
            if (appleCatalog == null) emptyList() else appleSearchResults(appleFilter, deduplicateSearchSongs(topResultTracks + visibleSongs), topResultArtist, data)
        }
        Box(
            modifier = Modifier
                .weight(1f)
                .fillMaxWidth()
        ) {
        LazyColumn(
            modifier = Modifier.fillMaxSize(),
            contentPadding = PaddingValues(
                bottom = selection.listBottomPadding(levyraTabContentBottomPadding(state.currentTrack != null))
            ),
            verticalArrangement = Arrangement.spacedBy(if (appleLanding) AppleSearchGridGap else if (appleCatalog != null && !data.isEmpty) 0.dp else 3.dp)
        ) {
            if (queryClean.isEmpty() && LevyraIsSpotify && !spotifySearchFocus.value) {
                spotifySearchBrowseItem(state, viewModel)
            } else if (appleLanding && appleCatalog != null) {
                appleMusicSearchLanding(
                    appleCatalog, appleColumns,
                    onOpen = { tile -> appleDestination = tile.destination },
                    onRequestArtwork = { params -> appleExploreViewModel?.ensureExploreCategoryArtwork(params, false) }
                )
            } else if (queryClean.isEmpty()) {
                item(key = "search-taste-hints", contentType = "search-taste-hints") {
                    SearchTasteHints(
                        suggestions = tasteHintQueries,
                        onClick = { suggestion ->
                            focusManager.clearFocus()
                            keyboardController?.hide()
                            viewModel.setQuery(suggestion)
                            viewModel.searchNow(suggestion)
                        }
                    )
                }

                if (state.recentSearches.isNotEmpty()) {
                    item(key = "search-recent", contentType = "search-recent") {
                        SearchSectionGap()
                        RecentSearchesRow(
                            title = strings.recentSearches,
                            tracks = state.recentSearches,
                            allowRemove = true,
                            favoriteIds = state.favoriteIds,
                            downloadedTrackIds = state.downloadedTrackIds,
                            onTrackClick = { track ->
                                focusManager.clearFocus()
                                keyboardController?.hide()
                                viewModel.play(track)
                            },
                            onRemove = viewModel::removeRecentSearch,
                            onFavorite = viewModel::toggleFavorite,
                            onAddToPlaylist = { addTarget = it },
                            onPlayNext = viewModel::playNext,
                            onAddToQueue = viewModel::addToQueue,
                            onDownload = viewModel::exportTrack,
                            onArtist = viewModel::openArtist
                        )
                    }
                }

                item(key = "search-artist-suggestions", contentType = "search-artist-suggestions") {
                    SearchSectionGap()
                    val fallbackSuggestions = LevyraContentLocales.artistSuggestions(state.languageCode)
                    SearchArtistSuggestions(
                        title = if (personalized.artistNames.isEmpty()) {
                            LevyraContentLocales.artistSuggestionsTitle(state.languageCode)
                        } else {
                            personalizedCopy.artistsForYou
                        },
                        artists = personalizedArtists,
                        fallbackNames = (personalized.artistNames + fallbackSuggestions).distinct(),
                        loading = state.homeArtistsLoading,
                        onArtistClick = { hit ->
                            focusManager.clearFocus()
                            keyboardController?.hide()
                            viewModel.openArtistFromHit(hit)
                        },
                        onFallbackClick = { query ->
                            focusManager.clearFocus()
                            keyboardController?.hide()
                            viewModel.setQuery(query)
                            viewModel.searchNow(query)
                        }
                    )
                }
            } else {
                if (querySuggestions.isNotEmpty() && !((LevyraIsYouTubeMusic || appleCatalog != null) && !data.isEmpty)) {
                    item(key = "search-query-suggestions", contentType = "search-query-suggestions") {
                        SearchQueryChips(
                            query = state.query,
                            suggestions = querySuggestions,
                            onClick = { suggestion ->
                                focusManager.clearFocus()
                                keyboardController?.hide()
                                viewModel.setQuery(suggestion)
                                viewModel.searchNow(suggestion)
                            }
                        )
                    }
                }
                when {
                    !data.isEmpty && appleCatalog != null -> {
                        appleMusicSearchResults(
                            filters = appleFilters,
                            selected = appleFilter,
                            results = appleResults,
                            currentTrackId = state.currentTrack?.id,
                            onSelect = viewModel::setSearchFilter,
                            actions = searchActions
                        )
                        if (appleFilter != SearchFilter.All) {
                            item(key = "search-section-footer", contentType = "search-section-footer") {
                                SearchSectionGap()
                                SearchSectionFooter(
                                    loading = appleFilter in state.searchSectionLoading,
                                    failed = appleFilter in data.failedSections,
                                    canLoadMore = state.searchSectionContinuations[appleFilter].orEmpty().isNotBlank(),
                                    autoLoadKey = data.sectionSize(appleFilter),
                                    onLoadMore = { viewModel.loadMoreSearchSection(appleFilter) }
                                )
                            }
                        }
                    }
                    !data.isEmpty && LevyraIsYouTubeMusic -> {
                        item(key = "search-filters", contentType = "search-filters") {
                            SearchSectionGap()
                            SearchFilterChips(
                                selected = filter,
                                hasArtists = data.artists.isNotEmpty(),
                                hasAlbums = data.albums.isNotEmpty(),
                                hasPlaylists = data.playlists.isNotEmpty(),
                                hasVideos = data.videos.isNotEmpty(),
                                onSelect = viewModel::setSearchFilter
                            )
                        }
                        youTubeMusicSearchResults(
                            topTracks = topResultTracks,
                            topArtist = topResultArtist,
                            entries = youTubeMusicEntries,
                            songs = visibleSongs,
                            videos = data.videos,
                            currentTrackId = state.currentTrack?.id,
                            rowModifier = Modifier.recentSearchesBleed(RecentSearchGutter),
                            playsLabel = { track ->
                                formatSearchViewCount(track.youtubeViewCount, strings.code).takeIf(String::isNotBlank)?.let { "$it ${strings.pulsePlays}" }.orEmpty()
                            },
                            actions = searchActions
                        )
                        if (filter != SearchFilter.All) {
                            item(key = "search-section-footer", contentType = "search-section-footer") {
                                SearchSectionGap()
                                SearchSectionFooter(
                                    loading = filter in state.searchSectionLoading,
                                    failed = filter in data.failedSections,
                                    canLoadMore = state.searchSectionContinuations[filter].orEmpty().isNotBlank(),
                                    autoLoadKey = data.sectionSize(filter),
                                    onLoadMore = { viewModel.loadMoreSearchSection(filter) }
                                )
                            }
                        }
                    }
                    !data.isEmpty -> {
                        item(key = "search-filters", contentType = "search-filters") {
                            SearchSectionGap()
                            SearchFilterChips(
                                selected = filter,
                                hasArtists = data.artists.isNotEmpty(),
                                hasAlbums = data.albums.isNotEmpty(),
                                hasPlaylists = data.playlists.isNotEmpty(),
                                hasVideos = data.videos.isNotEmpty(),
                                onSelect = viewModel::setSearchFilter
                            )
                        }
                        if (filter == SearchFilter.All && topResultTracks.isNotEmpty()) {
                            val heroTrack = topResultTracks.firstOrNull()
                            val matchedArtist = topResultArtist
                            item(key = "search-top-result", contentType = "search-top-result") {
                                SearchSectionGap()
                                TopResultCard(
                                    tracks = topResultTracks,
                                    artist = matchedArtist,
                                    currentTrackId = state.currentTrack?.id,
                                    isPlaying = state.isPlaying,
                                    isResolving = state.isResolving,
                                    favoriteIds = state.favoriteIds,
                                    selection = selection,
                                    onPlay = { track ->
                                        focusManager.clearFocus()
                                        keyboardController?.hide()
                                        val playbackContext = deduplicateSearchSongs(listOf(track) + data.songs)
                                        viewModel.playFrom(playbackContext, track)
                                    },
                                    onFavorite = viewModel::toggleFavorite,
                                    onAddToPlaylist = { track -> addTarget = track },
                                    onPlayNext = viewModel::playNext,
                                    onAddToQueue = viewModel::addToQueue,
                                    onArtist = openTopResult,
                                    onShuffle = shuffleTopResult,
                                    onMix = mixTopResult
                                )
                            }
                        }
                        val discography = data.discography
                        if (filter == SearchFilter.All && discography != null) {
                            item(key = "search-discography", contentType = "search-discography") {
                                SearchSectionGap()
                                SearchDiscographySection(
                                    discography = discography,
                                    onOpenRelease = { album ->
                                        focusManager.clearFocus()
                                        keyboardController?.hide()
                                        viewModel.openAlbum(album)
                                    },
                                    onOpenPlaylist = { playlist ->
                                        focusManager.clearFocus()
                                        keyboardController?.hide()
                                        viewModel.openPlaylistHit(playlist)
                                    },
                                    onOpenArtist = { hit ->
                                        focusManager.clearFocus()
                                        keyboardController?.hide()
                                        viewModel.openArtistFromHit(hit)
                                    }
                                )
                            }
                        }
                        if ((filter == SearchFilter.All || filter == SearchFilter.Artists) && data.artists.isNotEmpty()) {
                            item(key = "search-artists-header", contentType = "search-section-header") {
                                SearchSectionGap()
                                SearchSectionHeader(
                                    title = strings.artists,
                                    showAll = filter == SearchFilter.All,
                                    onShowAll = { viewModel.setSearchFilter(SearchFilter.Artists) }
                                )
                            }
                            val openArtistHit: (ArtistHit) -> Unit = { hit ->
                                focusManager.clearFocus()
                                keyboardController?.hide()
                                viewModel.openArtistFromHit(hit)
                            }
                            if (filter == SearchFilter.Artists) {
                                itemsIndexed(
                                    data.artists,
                                    key = { index, hit -> "search-artist-row-$index-${hit.browseId.ifBlank { hit.name.trim().lowercase(Locale.ROOT) }}" },
                                    contentType = { _, _ -> "search-artist-row" }
                                ) { _, hit ->
                                    Box(modifier = Modifier.padding(vertical = 3.dp)) {
                                        SearchArtistListRow(artist = hit, onClick = { openArtistHit(hit) })
                                    }
                                }
                            } else {
                                item(key = "search-artists", contentType = "search-artists") {
                                    SearchSectionGap()
                                    ArtistHitRow(artists = data.artists, onClick = openArtistHit)
                                }
                            }
                        }
                        if (filter == SearchFilter.Albums && data.albums.isNotEmpty()) {
                            item(key = "search-albums-grid-header", contentType = "search-section-header") {
                                Column {
                                    SearchSectionGap()
                                    SearchSectionHeader(title = strings.albumsPlain, showAll = false, onShowAll = {})
                                    if (albumKinds.isNotEmpty()) {
                                        Spacer(Modifier.height(4.dp))
                                        SearchAlbumKindChips(kinds = albumKinds, selected = effectiveAlbumKind, onSelect = { albumKind = it })
                                        Spacer(Modifier.height(12.dp))
                                    }
                                }
                            }
                            val albumRows = visibleAlbums
                                .map { it.searchCardModel(discographyCopy.album, discographyCopy.single) }
                                .chunked(searchGridColumnCount)
                            itemsIndexed(
                                albumRows,
                                key = { rowIndex, row -> "search-album-grid-${effectiveAlbumKind.name}-$rowIndex-${row.first().key}" },
                                contentType = { _, _ -> "search-card-grid" }
                            ) { rowIndex, row ->
                                Box(modifier = Modifier.padding(vertical = 8.dp)) {
                                    SearchCardGridRow(
                                        cards = row,
                                        firstIndex = rowIndex * searchGridColumnCount,
                                        columns = searchGridColumnCount,
                                        actionsFor = { index ->
                                            visibleAlbums.getOrNull(index)?.let { album ->
                                                listOf(SearchCardAction(Icons.Rounded.Download, strings.download) { viewModel.exportAlbumHit(album) })
                                            }.orEmpty()
                                        },
                                        onClick = { index ->
                                            visibleAlbums.getOrNull(index)?.let { album ->
                                                focusManager.clearFocus()
                                                keyboardController?.hide()
                                                viewModel.openAlbum(album)
                                            }
                                        }
                                    )
                                }
                            }
                        }
                        if (filter == SearchFilter.Playlists && data.playlists.isNotEmpty()) {
                            item(key = "search-playlists-grid-header", contentType = "search-section-header") {
                                Column {
                                    SearchSectionGap()
                                    SearchSectionHeader(title = strings.playlistsPlain, showAll = false, onShowAll = {})
                                }
                            }
                            val playlistRows = data.playlists.map { it.searchCardModel() }.chunked(searchGridColumnCount)
                            itemsIndexed(
                                playlistRows,
                                key = { rowIndex, row -> "search-playlist-grid-$rowIndex-${row.first().key}" },
                                contentType = { _, _ -> "search-card-grid" }
                            ) { rowIndex, row ->
                                Box(modifier = Modifier.padding(vertical = 8.dp)) {
                                    SearchCardGridRow(
                                        cards = row,
                                        firstIndex = rowIndex * searchGridColumnCount,
                                        columns = searchGridColumnCount,
                                        actionsFor = { index ->
                                            data.playlists.getOrNull(index)?.let { playlist ->
                                                listOf(
                                                    SearchCardAction(Icons.Rounded.PlayArrow, strings.play) {
                                                        focusManager.clearFocus()
                                                        keyboardController?.hide()
                                                        viewModel.playPlaylistHit(playlist)
                                                    },
                                                    SearchCardAction(Icons.Rounded.Download, strings.downloadPlaylist) {
                                                        viewModel.exportPlaylistHit(playlist)
                                                    }
                                                )
                                            }.orEmpty()
                                        },
                                        onClick = { index ->
                                            data.playlists.getOrNull(index)?.let { playlist ->
                                                focusManager.clearFocus()
                                                keyboardController?.hide()
                                                viewModel.openPlaylistHit(playlist)
                                            }
                                        }
                                    )
                                }
                            }
                        }
                        if (filter == SearchFilter.All && discography == null && data.albums.isNotEmpty()) {
                            item(key = "search-albums-header", contentType = "search-section-header") {
                                SearchSectionGap()
                                SearchSectionHeader(
                                    title = strings.albumsPlain,
                                    showAll = true,
                                    onShowAll = { viewModel.setSearchFilter(SearchFilter.Albums) }
                                )
                            }
                            item(key = "search-albums", contentType = "search-albums") {
                                SearchSectionGap()
                                AlbumHitRow(
                                    albums = data.albums,
                                    onClick = { album ->
                                        focusManager.clearFocus()
                                        keyboardController?.hide()
                                        viewModel.openAlbum(album)
                                    },
                                    onDownload = { album -> viewModel.exportAlbumHit(album) }
                                )
                            }
                        }
                        if (filter == SearchFilter.All && data.playlists.isNotEmpty()) {
                            item(key = "search-playlists-header", contentType = "search-section-header") {
                                SearchSectionGap()
                                SearchSectionHeader(
                                    title = strings.playlistsPlain,
                                    showAll = true,
                                    onShowAll = { viewModel.setSearchFilter(SearchFilter.Playlists) }
                                )
                            }
                            item(key = "search-playlists", contentType = "search-playlists") {
                                SearchSectionGap()
                                PlaylistHitRow(
                                    playlists = data.playlists,
                                    onOpen = { playlist ->
                                        focusManager.clearFocus()
                                        keyboardController?.hide()
                                        viewModel.openPlaylistHit(playlist)
                                    },
                                    onPlay = { playlist ->
                                        focusManager.clearFocus()
                                        keyboardController?.hide()
                                        viewModel.playPlaylistHit(playlist)
                                    },
                                    onDownload = { playlist -> viewModel.exportPlaylistHit(playlist) }
                                )
                            }
                        }
                        if ((filter == SearchFilter.All || filter == SearchFilter.Videos) && data.videos.isNotEmpty()) {
                            item(key = "search-videos-header", contentType = "search-section-header") {
                                SearchSectionGap()
                                SearchSectionHeader(
                                    title = strings.video,
                                    showAll = filter == SearchFilter.All,
                                    onShowAll = { viewModel.setSearchFilter(SearchFilter.Videos) }
                                )
                            }
                            itemsIndexed(data.videos, key = { _, track -> "search-video-${track.id}" }, contentType = { _, _ -> "search-track" }) { rowIndex, track ->
                                SearchGroupedRow(rowIndex, data.videos.size) {
                                SearchTrackCard(
                                    track = track,
                                    isCurrent = track.id == state.currentTrack?.id,
                                    isPlaying = state.isPlaying && track.id == state.currentTrack?.id,
                                    isResolving = state.isResolving && track.id == state.currentTrack?.id,
                                    isFavorite = track.id in state.favoriteIds,
                                    isDownloading = track.id in state.downloadingTrackIds,
                                    isDownloaded = track.id in state.downloadedTrackIds,
                                    downloadProgress = state.downloadProgressByTrackId[track.id],
                                    selected = selection.isSelected(trackSelectionKey(track)),
                                    selectionActive = selection.isActive,
                                    onLongClick = { selection.start(trackSelectionKey(track)) },
                                    onClick = {
                                        if (selection.isActive) {
                                            selection.toggle(trackSelectionKey(track))
                                        } else {
                                            focusManager.clearFocus()
                                            keyboardController?.hide()
                                            viewModel.playFrom(data.videos, track)
                                        }
                                    },
                                    onFavorite = { viewModel.toggleFavorite(track) },
                                    onAddToPlaylist = { addTarget = track },
                                    onDownload = { viewModel.exportTrack(track) }
                                )
                                }
                            }
                        }
                        if (filter == SearchFilter.All || filter == SearchFilter.Songs) {
                            val songs = visibleSongs
                            if (songs.isNotEmpty()) {
                                item(key = "search-songs-header", contentType = "search-section-header") {
                                    SearchSectionGap()
                                    SearchSectionHeader(
                                        title = strings.songs,
                                        showAll = filter == SearchFilter.All,
                                        onShowAll = { viewModel.setSearchFilter(SearchFilter.Songs) }
                                    )
                                }
                                itemsIndexed(songs, key = { _, track -> "search-song-${track.id}" }, contentType = { _, _ -> "search-track" }) { rowIndex, track ->
                                    SearchGroupedRow(rowIndex, songs.size) {
                                    SearchTrackCard(
                                        track = track,
                                        isCurrent = track.id == state.currentTrack?.id,
                                        isPlaying = state.isPlaying && track.id == state.currentTrack?.id,
                                        isResolving = state.isResolving && track.id == state.currentTrack?.id,
                                        isFavorite = track.id in state.favoriteIds,
                                        isDownloading = track.id in state.downloadingTrackIds,
                                        isDownloaded = track.id in state.downloadedTrackIds,
                                        downloadProgress = state.downloadProgressByTrackId[track.id],
                                        selected = selection.isSelected(trackSelectionKey(track)),
                                        selectionActive = selection.isActive,
                                        onLongClick = { selection.start(trackSelectionKey(track)) },
                                        onClick = {
                                            if (selection.isActive) {
                                                selection.toggle(trackSelectionKey(track))
                                            } else {
                                                focusManager.clearFocus()
                                                keyboardController?.hide()
                                                viewModel.playFrom(data.songs, track)
                                            }
                                        },
                                        onFavorite = { viewModel.toggleFavorite(track) },
                                        onAddToPlaylist = { addTarget = track },
                                        onDownload = { viewModel.exportTrack(track) }
                                    )
                                    }
                                }
                            }
                        }
                        if (filter != SearchFilter.All) {
                            item(key = "search-section-footer", contentType = "search-section-footer") {
                                SearchSectionGap()
                                SearchSectionFooter(
                                    loading = filter in state.searchSectionLoading,
                                    failed = filter in data.failedSections,
                                    canLoadMore = state.searchSectionContinuations[filter].orEmpty().isNotBlank(),
                                    autoLoadKey = data.sectionSize(filter),
                                    onLoadMore = { viewModel.loadMoreSearchSection(filter) }
                                )
                            }
                        }
                    }
                    state.searchError != null -> item(key = "search-error", contentType = "search-message") {
                        SearchSectionGap()
     SearchSectionGap()
                        GlassMessage(state.searchError, LevyraOrange)
                    }
                    state.isSearching || state.searchPending -> item(key = "search-skeleton", contentType = "search-skeleton") {
                        SearchSectionGap()
     SearchSectionGap()
                        SearchLoadingSkeleton()
                    }
                    else -> item(key = "search-quick-chips", contentType = "search-quick-chips") {
                        SearchSectionGap()
     SearchSectionGap()
                        QuickChips(
                            languageCode = state.languageCode,
                            onClick = { query ->
                                focusManager.clearFocus()
                                keyboardController?.hide()
                                viewModel.setQuery(query)
                                viewModel.searchNow(query)
                            }
                        )
                    }
                }
            }
        }

            TrackSelectionBar(
                state = selection,
                aboveRootDock = true,
                allVisibleIds = selectableIds,
                actions = trackSelectionActions(
                    state = selection,
                    selectedTracks = selectedTracks,
                    onPlayNext = viewModel::playTracksNext,
                    onAddToQueue = viewModel::addTracksToQueue,
                    onAddToPlaylist = { batchAddTargets = it },
                    onFavorite = viewModel::toggleFavorites,
                    onDownload = { tracks -> viewModel.exportTracks(tracks, strings.offline) },
                    onDislike = viewModel::dislikeTracks
                ),
                modifier = Modifier
                    .align(Alignment.BottomCenter)
                    .padding(horizontal = 12.dp)
            )
        }
    }

    appleExploreViewModel?.let { exploreViewModel ->
        AppleMusicSearchDestination(appleDestination, exploreViewModel, backEnabled, onTrackActions) { appleDestination = null }
    }

    addTarget?.let { track ->
        AddToPlaylistDialog(
            track = track,
            playlists = state.playlists,
            onDismiss = { addTarget = null },
            onAddTo = { playlistId ->
                viewModel.addToPlaylist(playlistId, track)
                addTarget = null
            },
            onCreateWith = { name ->
                viewModel.createPlaylist(name, track)
                addTarget = null
            }
        )
    }
    if (batchAddTargets.isNotEmpty()) {
        com.luc4n3x.levyra.ui.library.AddTracksToPlaylistDialog(
            tracks = batchAddTargets,
            playlists = state.playlists,
            onDismiss = { batchAddTargets = emptyList() },
            onAdd = { playlistId ->
                viewModel.addTracksToPlaylist(playlistId, batchAddTargets)
                batchAddTargets = emptyList()
                selection.exit()
            },
            onCreate = { name ->
                viewModel.createPlaylistWithTracks(name, batchAddTargets)
                batchAddTargets = emptyList()
                selection.exit()
            }
        )
    }
}

@Composable
private fun RecentSearchesRow(
    title: String,
    tracks: List<Track>,
    allowRemove: Boolean,
    favoriteIds: Set<String>,
    downloadedTrackIds: Set<String>,
    onTrackClick: (Track) -> Unit,
    onRemove: (Track) -> Unit,
    onFavorite: (Track) -> Unit,
    onAddToPlaylist: (Track) -> Unit,
    onPlayNext: (Track) -> Unit,
    onAddToQueue: (Track) -> Unit,
    onDownload: (Track) -> Unit,
    onArtist: (Track) -> Unit
) {
    val strings = LocalLevyraStrings.current
    val scheme = MaterialTheme.colorScheme
    val artworkShapes = recentSearchArtworkShapes()

    Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
        SectionTitle(title)
        val recentState = rememberLazyListState()
        val recentDepth = carouselDepthEnabled()
        LazyRow(
            state = recentState,
            modifier = Modifier.recentSearchesBleed(RecentSearchGutter),
            horizontalArrangement = Arrangement.spacedBy(12.dp),
            contentPadding = PaddingValues(horizontal = RecentSearchGutter)
        ) {
            itemsIndexed(tracks, key = { _, track -> "recent-${track.id}" }) { index, track ->
                var menuExpanded by remember(track.id) { mutableStateOf(false) }
                val isFavorite = track.id in favoriteIds
                val isDownloaded = track.id in downloadedTrackIds

                Box(
                    modifier = Modifier
                        .levyraCarouselDepth(recentState, "recent-${track.id}", recentDepth)
                        .width(RecentSearchCardWidth)
                ) {
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clip(if (LevyraSkinManagesLayout) RoundedCornerShape(SkinChrome.outerCorner) else RecentSearchCardShape)
                            .background(if (LevyraIsPrism && !LevyraIsTorque) Color.Transparent else if (LevyraSkinManagesLayout) LevyraPanel else scheme.secondaryContainer.copy(alpha = if (LevyraIsLight) 0.62f else 0.34f))
                            .levyraPressable(
                                onClick = { onTrackClick(track) },
                                onLongClick = { menuExpanded = true },
                                onLongClickLabel = strings.actions,
                                pressedScale = LevyraPressScale.Control,
                                role = Role.Button
                            )
                            .padding(10.dp),
                        verticalArrangement = Arrangement.spacedBy(10.dp)
                    ) {
                        Box(modifier = Modifier.fillMaxWidth().aspectRatio(1f)) {
                            CoverImage(
                                track = track,
                                modifier = Modifier
                                    .fillMaxSize()
                                    .clip(if (LevyraSkinManagesLayout) RoundedCornerShape(SkinChrome.innerCorner.coerceAtLeast(PrismDesign.tileCorner.takeIf { LevyraIsPrism } ?: 2.dp)) else artworkShapes[index % artworkShapes.size])
                                    .background(scheme.surfaceContainerHighest)
                            )
                            Box(
                                modifier = Modifier
                                    .align(Alignment.BottomEnd)
                                    .size(RecentSearchPlayBadge)
                                    .clip(if (LevyraSkinManagesLayout) CircleShape else artworkShapes[(index + 1) % artworkShapes.size])
                                    .background(if (LevyraIsPrism) PrismAccent.gradient() else SolidColor(scheme.primary)),
                                contentAlignment = Alignment.Center
                            ) {
                                Icon(
                                    imageVector = Icons.Rounded.PlayArrow,
                                    contentDescription = null,
                                    tint = scheme.onPrimary,
                                    modifier = Modifier.size(22.dp)
                                )
                            }
                        }
                        Column(
                            modifier = Modifier.padding(start = 4.dp, end = 4.dp, bottom = 4.dp),
                            verticalArrangement = Arrangement.spacedBy(2.dp)
                        ) {
                            Text(
                                text = track.title,
                                color = LevyraText,
                                fontSize = 14.sp,
                                lineHeight = LevyraTypeRhythm.lineHeight(14.sp),
                                fontWeight = FontWeight.Black,
                                letterSpacing = (-0.2).sp,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis
                            )
                            Text(
                                text = track.artist,
                                color = LevyraMuted,
                                fontSize = 12.sp,
                                lineHeight = LevyraTypeRhythm.lineHeight(12.sp),
                                fontWeight = FontWeight.SemiBold,
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis
                            )
                        }
                    }
                    SearchTrackActionsMenu(
                        track = track,
                        expanded = menuExpanded,
                        isFavorite = isFavorite,
                        isDownloaded = isDownloaded,
                        allowRemove = allowRemove,
                        onDismiss = { menuExpanded = false },
                        onRemove = onRemove,
                        onFavorite = onFavorite,
                        onAddToPlaylist = onAddToPlaylist,
                        onPlayNext = onPlayNext,
                        onAddToQueue = onAddToQueue,
                        onDownload = onDownload,
                        onArtist = onArtist
                    )
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
private fun recentSearchArtworkShapes(): List<Shape> {
    val cookie9 = MaterialShapes.Cookie9Sided.toShape()
    val clover = MaterialShapes.Clover4Leaf.toShape()
    val cookie6 = MaterialShapes.Cookie6Sided.toShape()
    val softBurst = MaterialShapes.SoftBurst.toShape()
    val cookie4 = MaterialShapes.Cookie4Sided.toShape()
    return remember(cookie9, clover, cookie6, softBurst, cookie4) {
        listOf(cookie9, clover, cookie6, softBurst, cookie4)
    }
}

internal fun Modifier.recentSearchesBleed(gutter: Dp): Modifier = layout { measurable, constraints ->
    val gutterPx = gutter.roundToPx()
    val width = constraints.maxWidth + gutterPx * 2
    val placeable = measurable.measure(constraints.copy(minWidth = width, maxWidth = width))
    layout(constraints.maxWidth, placeable.height) {
        placeable.place(-gutterPx, 0)
    }
}

private const val SEARCH_TASTE_HINT_LIMIT = 10
internal val RecentSearchGutter = 18.dp
internal val SettingsStudioGutter = 18.dp
private val RecentSearchCardWidth = 148.dp
private val RecentSearchCardShape = RoundedCornerShape(32.dp)
private val RecentSearchPlayBadge = 44.dp

@Composable
private fun SearchTrackActionsMenu(
    track: Track,
    expanded: Boolean,
    isFavorite: Boolean,
    isDownloaded: Boolean,
    allowRemove: Boolean,
    onDismiss: () -> Unit,
    onRemove: (Track) -> Unit,
    onFavorite: (Track) -> Unit,
    onAddToPlaylist: (Track) -> Unit,
    onPlayNext: (Track) -> Unit,
    onAddToQueue: (Track) -> Unit,
    onDownload: (Track) -> Unit,
    onArtist: (Track) -> Unit
) {
    val context = LocalContext.current
    val strings = LocalLevyraStrings.current
    DropdownMenu(
        expanded = expanded,
        onDismissRequest = onDismiss
    ) {
        DropdownMenuItem(
            text = { Text(if (isFavorite) strings.removeFromFavorites else strings.addToFavorites) },
            leadingIcon = { Icon(if (isFavorite) Icons.Rounded.Favorite else Icons.Rounded.FavoriteBorder, null) },
            onClick = {
                onDismiss()
                onFavorite(track)
            }
        )
        DropdownMenuItem(
            text = { Text(strings.playNext) },
            leadingIcon = { Icon(Icons.AutoMirrored.Rounded.PlaylistPlay, null) },
            onClick = {
                onDismiss()
                onPlayNext(track)
            }
        )
        DropdownMenuItem(
            text = { Text(strings.addToQueue) },
            leadingIcon = { Icon(Icons.AutoMirrored.Rounded.QueueMusic, null) },
            onClick = {
                onDismiss()
                onAddToQueue(track)
            }
        )
        DropdownMenuItem(
            text = { Text(strings.addToPlaylist) },
            leadingIcon = { Icon(Icons.AutoMirrored.Rounded.PlaylistAdd, null) },
            onClick = {
                onDismiss()
                onAddToPlaylist(track)
            }
        )
        DropdownMenuItem(
            text = { Text(if (isDownloaded) strings.alreadyOffline else strings.download) },
            leadingIcon = { Icon(if (isDownloaded) Icons.Rounded.DownloadDone else Icons.Rounded.Download, null) },
            onClick = {
                onDismiss()
                if (!isDownloaded) onDownload(track)
            }
        )
        DropdownMenuItem(
            text = { Text(strings.openArtist) },
            leadingIcon = { Icon(Icons.Rounded.Person, null) },
            onClick = {
                onDismiss()
                onArtist(track)
            }
        )
        DropdownMenuItem(
            text = { Text(strings.share) },
            leadingIcon = { Icon(Icons.Rounded.Share, null) },
            onClick = {
                onDismiss()
                val shareText = buildString {
                    append(track.title)
                    if (track.artist.isNotBlank()) append(" - ").append(track.artist)
                    val link = track.videoUrl.ifBlank { track.streamUrl }
                    if (link.isNotBlank()) append("\n").append(link)
                }
                val intent = Intent(Intent.ACTION_SEND).apply {
                    type = "text/plain"
                    putExtra(Intent.EXTRA_TEXT, shareText)
                }
                context.startActivity(Intent.createChooser(intent, strings.shareSong))
            }
        )
        if (allowRemove) {
            DropdownMenuItem(
                text = { Text(strings.removeFromRecentSearches) },
                leadingIcon = { Icon(Icons.Rounded.Delete, null) },
                onClick = {
                    onDismiss()
                    onRemove(track)
                }
            )
        }
    }
}

@Composable
private fun SearchQueryChips(
    query: String,
    suggestions: List<String>,
    onClick: (String) -> Unit
) {
    LazyRow(
        modifier = Modifier.recentSearchesBleed(RecentSearchGutter),
        horizontalArrangement = Arrangement.spacedBy(8.dp),
        verticalAlignment = Alignment.CenterVertically,
        contentPadding = PaddingValues(horizontal = RecentSearchGutter)
    ) {
        items(
            items = suggestions,
            key = { suggestion -> suggestion }
        ) { suggestion ->
            SearchQuerySuggestionChip(
                query = query,
                suggestion = suggestion,
                onClick = { onClick(suggestion) }
            )
        }
    }
}

@Composable
private fun SearchQuerySuggestionChip(
    query: String,
    suggestion: String,
    onClick: () -> Unit
) {
    val scheme = MaterialTheme.colorScheme
    val interaction = remember { MutableInteractionSource() }
    val corner = levyraExpressiveCorner(
        interactionSource = interaction,
        rest = 20.dp,
        pressed = 10.dp,
        label = "search-query-suggestion-corner"
    )
    val knownColor = scheme.onSurfaceVariant
    val novelColor = scheme.onSurface
    val label = remember(query, suggestion, knownColor, novelColor) {
        buildAnnotatedString {
            searchSuggestionSegments(query, suggestion).forEach { segment ->
                withStyle(
                    if (segment.novel) {
                        SpanStyle(color = novelColor, fontWeight = FontWeight.ExtraBold)
                    } else {
                        SpanStyle(color = knownColor, fontWeight = FontWeight.Medium)
                    }
                ) {
                    append(segment.text)
                }
            }
        }
    }
    Box(
        modifier = Modifier
            .heightIn(min = 48.dp)
            .levyraPressable(
                onClick = onClick,
                interactionSource = interaction,
                role = Role.Button,
                pressedScale = LevyraPressScale.Control
            ),
        contentAlignment = Alignment.Center
    ) {
        Row(
            modifier = Modifier
                .widthIn(max = 280.dp)
                .clip(RoundedCornerShape(corner))
                .background(scheme.surfaceContainerHigh)
                .padding(start = 12.dp, end = 16.dp, top = 9.dp, bottom = 9.dp),
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Icon(
                imageVector = Icons.Rounded.Search,
                contentDescription = null,
                tint = scheme.primary,
                modifier = Modifier.size(18.dp)
            )
            Text(
                text = label,
                fontSize = 13.sp,
                lineHeight = 18.sp,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
        }
    }
}

