@Composable
private fun PlaylistDetailOverlay(viewModel: LevyraViewModel, state: LevyraUiState) {
    val playlist = state.openPlaylist ?: return
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(LevyraInk)
    ) {
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .statusBarsPadding(),
            contentPadding = PaddingValues(start = 16.dp, end = 16.dp, top = 8.dp, bottom = levyraTabContentBottomPadding(state.currentTrack != null)),
            verticalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            item {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    LevyraBackButton(onClick = { viewModel.closePlaylist() }, contentDescription = LocalLevyraStrings.current.back)
                    Spacer(Modifier.width(4.dp))
                    Column(modifier = Modifier.weight(1f)) {
                        Text(playlist.name, color = LevyraText, fontSize = 26.sp, fontWeight = FontWeight.Black, maxLines = 1, overflow = TextOverflow.Ellipsis)
                        Text(LocalLevyraStrings.current.formatTrackCount(playlist.playableTrackCount), color = LevyraMuted, fontSize = 14.sp)
                    }
                    if (playlist.tracks.isNotEmpty()) {
                        val shareContext = LocalContext.current
                        val shareStrings = LocalLevyraStrings.current
                        IconButton(
                            onClick = {
                                val link = viewModel.playlistShareLink(playlist)
                                if (link != null) {
                                    val intent = Intent(Intent.ACTION_SEND).apply {
                                        type = "text/plain"
                                        putExtra(Intent.EXTRA_SUBJECT, playlist.name)
                                        putExtra(Intent.EXTRA_TEXT, playlist.name + "\n" + link)
                                    }
                                    shareContext.startActivity(Intent.createChooser(intent, shareStrings.sharePlaylist))
                                }
                            }
                        ) {
                            Icon(
                                Icons.Rounded.Share,
                                contentDescription = shareStrings.sharePlaylist,
                                tint = LevyraCyan,
                                modifier = Modifier.size(25.dp)
                            )
                        }
                        IconButton(onClick = { viewModel.exportOpenPlaylist() }) {
                            Icon(Icons.Rounded.DownloadDone, contentDescription = LocalLevyraStrings.current.downloadPlaylist, tint = LevyraViolet, modifier = Modifier.size(27.dp))
                        }
                        LevyraPlayAllIconButton(onClick = { viewModel.playPlaylist(playlist.id) })
                    }
                }
            }
            if (playlist.tracks.isEmpty()) {
                item { EmptyState(LocalLevyraStrings.current.playlistEmpty) }
            } else {
                itemsIndexed(playlist.tracks, key = { _, track -> "pldetail-${track.id}" }) { index, track ->
                    val current = track.id == state.currentTrack?.id
                    Box(
                        modifier = Modifier
                            .padding(vertical = 1.dp)
                            .clip(levyraGroupedListShape(index, playlist.tracks.size))
                            .background(if (current) LevyraCyan.copy(alpha = 0.14f) else LevyraText.copy(alpha = 0.05f))
                    ) {
                        TrackRow(
                            track = track,
                            isCurrent = track.id == state.currentTrack?.id,
                            isPlaying = state.isPlaying && track.id == state.currentTrack?.id,
                            isResolving = state.isResolving && track.id == state.currentTrack?.id,
                            isFavorite = track.id in state.favoriteIds,
                            onClick = { viewModel.playPlaylist(playlist.id, track.id) },
                            onFavorite = { viewModel.toggleFavorite(track) },
                            isDownloading = track.id in state.downloadingTrackIds,
                            isDownloaded = track.id in state.downloadedTrackIds,
                            downloadProgress = state.downloadProgressByTrackId[track.id],
                            onDownload = { viewModel.exportTrack(track) },
                            onArtist = { viewModel.openArtist(track) },
                            onRemove = { viewModel.removeFromPlaylist(playlist.id, track.id) }
                        )
                    }
                }
            }
        }
        state.currentTrack?.let { current ->
            AlbumNowPlayingDock(
                track = current,
                isPlaying = state.isPlaying,
                isResolving = state.isResolving,
                progress = progressOf(state.positionMs, state.durationMs),
                animated = state.animationsEnabled,
                onToggle = viewModel::togglePlay,
                onOpenPlayer = viewModel::openPlayerScreen,
                modifier = Modifier
                    .align(Alignment.BottomCenter)
                    .navigationBarsPadding()
                    .padding(start = 16.dp, end = 16.dp, bottom = 14.dp)
            )
        }
    }
}

@Composable
private fun PlayerImmersiveBackdrop(
    artworkUrl: String,
    ambience: PlayerAmbience,
    isPlaying: Boolean,
    animationsEnabled: Boolean,
    modifier: Modifier = Modifier
) {
    val context = LocalContext.current
    val primary = animateColorAsState(
        targetValue = ambience.primary,
        animationSpec = if (animationsEnabled) tween(900, easing = LinearOutSlowInEasing) else snap(),
        label = "player-backdrop-primary"
    )
    val secondary = animateColorAsState(
        targetValue = ambience.secondary,
        animationSpec = if (animationsEnabled) tween(900, easing = LinearOutSlowInEasing) else snap(),
        label = "player-backdrop-secondary"
    )
    val base = animateColorAsState(
        targetValue = ambience.base,
        animationSpec = if (animationsEnabled) tween(900, easing = LinearOutSlowInEasing) else snap(),
        label = "player-backdrop-base"
    )
    val imageAlpha by animateFloatAsState(
        targetValue = if (isPlaying) 0.72f else 0.58f,
        animationSpec = if (animationsEnabled) tween(500, easing = FastOutSlowInEasing) else snap(),
        label = "player-backdrop-image-alpha"
    )
    val ambientMatrix = remember { createPlayerAmbientColorMatrix() }
    val ambientColorFilter = remember(ambientMatrix) { ColorFilter.colorMatrix(ambientMatrix) }

    Box(modifier = modifier) {
        Box(modifier = Modifier.fillMaxSize().background(base.value))
        if (artworkUrl.isNotBlank()) {
            AnimatedContent(
                targetState = artworkUrl,
                transitionSpec = {
                    if (animationsEnabled) {
                        fadeIn(tween(440, easing = LinearOutSlowInEasing)) togetherWith
                            fadeOut(tween(300, easing = FastOutSlowInEasing))
                    } else {
                        EnterTransition.None togetherWith ExitTransition.None
                    }
                },
                label = "player-backdrop-artwork"
            ) { url ->
                val ambientImageRequest = remember(context, url) {
                    ImageRequest.Builder(context)
                        .data(LevyraArtworkCache.large(url))
                        .size(512, 512)
                        .diskCachePolicy(CachePolicy.ENABLED)
                        .memoryCachePolicy(CachePolicy.ENABLED)
                        .crossfade(false)
                        .build()
                }
                AsyncImage(
                    model = ambientImageRequest,
                    contentDescription = null,
                    contentScale = ContentScale.Crop,
                    colorFilter = ambientColorFilter,
                    modifier = Modifier
                        .fillMaxSize()
                        .blur(52.dp)
                        .graphicsLayer {
                            scaleX = 1.12f
                            scaleY = 1.12f
                            alpha = imageAlpha
                        }
                )
            }
        }
        Box(
            modifier = Modifier
                .fillMaxSize()
                .drawBehind {
                    val animatedPrimary = primary.value
                    val animatedSecondary = secondary.value
                    val animatedBase = base.value
                    drawRect(
                        Brush.verticalGradient(
                            colorStops = arrayOf(
                                0.00f to animatedBase.copy(alpha = 0.90f),
                                0.18f to animatedPrimary.copy(alpha = 0.26f),
                                0.54f to Color.Transparent,
                                0.78f to animatedSecondary.copy(alpha = 0.22f),
                                1.00f to Color.Black.copy(alpha = 0.88f)
                            )
                        )
                    )
                    drawRect(
                        Brush.radialGradient(
                            colors = listOf(
                                animatedPrimary.copy(alpha = 0.20f),
                                Color.Transparent
                            ),
                            center = Offset(size.width * 0.20f, size.height * 0.16f),
                            radius = size.maxDimension * 0.82f
                        )
                    )
                }
        )
    }
}

@Composable
private fun PlayerArtworkCanvas(
    track: Track,
    artworkUrl: String,
    motionArtwork: com.luc4n3x.levyra.feature.motion.MotionArtwork?,
    livingArtwork: LivingArtworkColors?,
    animationsEnabled: Boolean,
    isPlaying: Boolean,
    cornerRadius: Dp,
    canvasQuality: LevyraCanvasQuality,
    modifier: Modifier = Modifier
) {
    val context = LocalContext.current
    val artworkShadow by animateDpAsState(
        targetValue = if (isPlaying) 26.dp else 14.dp,
        animationSpec = if (animationsEnabled) tween(420, easing = FastOutSlowInEasing) else snap(),
        label = "player-artwork-shadow"
    )
    val primary = Color(track.accentStart)
    val artworkShape = RoundedCornerShape(cornerRadius)

    Box(modifier = modifier, contentAlignment = Alignment.Center) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .shadow(
                    elevation = artworkShadow,
                    shape = artworkShape,
                    clip = false,
                    ambientColor = primary.copy(alpha = 0.42f),
                    spotColor = Color.Black.copy(alpha = 0.80f)
                )
                .clip(artworkShape)
                .background(Color.Black.copy(alpha = 0.24f), artworkShape)
        ) {
            MotionArtworkLayer(
                artwork = motionArtwork,
                enabled = animationsEnabled,
                isPlaying = isPlaying,
                cornerRadius = cornerRadius,
                presentation = MotionArtworkPresentation.Card,
                quality = canvasQuality,
                livingArtwork = livingArtwork,
                modifier = Modifier.fillMaxSize()
            ) {
                if (artworkUrl.isNotBlank()) {
                    AsyncImage(
                        model = ImageRequest.Builder(context)
                            .data(artworkUrl)
                            .crossfade(true)
                            .diskCachePolicy(CachePolicy.ENABLED)
                            .memoryCachePolicy(CachePolicy.ENABLED)
                            .build(),
                        contentDescription = null,
                        contentScale = ContentScale.Crop,
                        modifier = Modifier.fillMaxSize()
                    )
                } else {
                    InstantArtworkPlaceholder(track = track, modifier = Modifier.fillMaxSize())
                }
            }
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .border(
                        width = LevyraPlayerDesign.Hairline,
                        color = Color.White.copy(alpha = 0.12f),
                        shape = artworkShape
                    )
            )
        }
    }
}

@Composable
private fun PlayerImmersiveMotionCanvas(
    track: Track,
    artworkUrl: String,
    motionArtwork: com.luc4n3x.levyra.feature.motion.MotionArtwork?,
    livingArtwork: LivingArtworkColors?,
    ambience: PlayerAmbience,
    animationsEnabled: Boolean,
