}

@Composable
private fun PlayerCanvasFusionScrim(
    ambience: PlayerAmbience,
    modifier: Modifier = Modifier
) {
    val animationsEnabled = LocalAnimationsEnabled.current
    val base = animateColorAsState(
        targetValue = ambience.base,
        animationSpec = if (animationsEnabled) tween(700, easing = LinearOutSlowInEasing) else snap(),
        label = "player-canvas-fusion-base"
    )
    val control = animateColorAsState(
        targetValue = ambience.control,
        animationSpec = if (animationsEnabled) tween(700, easing = LinearOutSlowInEasing) else snap(),
        label = "player-canvas-fusion-control"
    )
    Box(
        modifier = modifier.drawBehind {
            if (size.minDimension <= 0f) return@drawBehind
            val baseColor = base.value
            val controlColor = control.value
            drawRect(
                Brush.verticalGradient(
                    colorStops = arrayOf(
                        0.00f to Color.Black.copy(alpha = 0.50f),
                        0.08f to Color.Black.copy(alpha = 0.25f),
                        0.16f to Color.Transparent,
                        0.48f to Color.Transparent,
                        0.60f to controlColor.copy(alpha = 0.35f),
                        0.72f to controlColor.copy(alpha = 0.72f),
                        0.84f to controlColor.copy(alpha = 0.94f),
                        0.94f to controlColor.playerAmbienceMix(baseColor, 0.45f),
                        1.00f to baseColor
                    )
                )
            )
        }
    )
}

@Composable
private fun PlayerModeSwitch(
    isVideoMode: Boolean,
    onSong: () -> Unit,
    onVideo: () -> Unit
) {
    val strings = LocalLevyraStrings.current
    if (LevyraIsQobuz) return com.luc4n3x.levyra.ui.player.QobuzModeSwitch(isVideoMode, strings.song, strings.video, onSong, onVideo)
    val animationsEnabled = LocalAnimationsEnabled.current
    val springSpec = if (animationsEnabled) LevyraPlayerDesign.expressiveSpring<Dp>() else snap()
    val indicatorOffset by animateDpAsState(
        targetValue = if (isVideoMode) PlayerModeCollapsedWidth else 0.dp,
        animationSpec = springSpec,
        label = "player-mode-indicator"
    )
    Box(
        modifier = Modifier
            .selectableGroup()
            .clip(CircleShape)
            .background(Color.Black.copy(alpha = 0.26f))
            .padding(PlayerModeInset)
    ) {
        Box(
            modifier = Modifier
                .offset { IntOffset(indicatorOffset.roundToPx(), 0) }
                .size(PlayerModeExpandedWidth, PlayerModeSegmentHeight)
                .clip(CircleShape)
                .background(
                    Brush.verticalGradient(
                        listOf(Color.White.copy(alpha = 0.26f), Color.White.copy(alpha = 0.16f))
                    )
                )
        )
        Row {
            PlayerModeSwitchIconTab(
                icon = LevyraIonicons.AudioMode,
                label = strings.song,
                selected = !isVideoMode,
                animationsEnabled = animationsEnabled,
                onClick = onSong
            )
            PlayerModeSwitchIconTab(
                icon = LevyraIonicons.VideoMode,
                label = strings.video,
                selected = isVideoMode,
                animationsEnabled = animationsEnabled,
                onClick = onVideo
            )
        }
    }
}

@Composable
private fun PlayerModeSwitchIconTab(
    icon: ImageVector,
    label: String,
    selected: Boolean,
    animationsEnabled: Boolean,
    onClick: () -> Unit
) {
    val tint by animateColorAsState(
        targetValue = if (selected) Color.White else Color.White.copy(alpha = 0.5f),
        animationSpec = if (animationsEnabled) LevyraPlayerDesign.standardTween(200) else snap(),
        label = "player-mode-tab-tint"
    )
    val width by animateDpAsState(
        targetValue = if (selected) PlayerModeExpandedWidth else PlayerModeCollapsedWidth,
        animationSpec = if (animationsEnabled) LevyraPlayerDesign.expressiveSpring() else snap(),
        label = "player-mode-tab-width"
    )
    Row(
        modifier = Modifier
            .size(width, PlayerModeSegmentHeight)
            .clip(CircleShape)
            .selectable(selected = selected, role = Role.Tab, onClick = onClick)
            .semantics { contentDescription = label },
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.Center
    ) {
        Icon(
            imageVector = icon,
            contentDescription = null,
            tint = tint,
            modifier = Modifier.size(18.dp)
        )
    }
}

private val PlayerModeExpandedWidth = 60.dp
private val PlayerModeCollapsedWidth = 44.dp
private val PlayerModeSegmentHeight = 34.dp
private val PlayerModeInset = 3.dp

@Composable
private fun LevyraControlPulseHandle(
    expanded: Boolean,
    compact: Boolean,
    activeColor: Color,
    secondaryColor: Color,
    hasActiveState: Boolean,
    onToggle: () -> Unit
) {
    val strings = LocalLevyraStrings.current
    val animationsEnabled = LocalAnimationsEnabled.current
    val width = if (compact) 82.dp else 88.dp
    val height = if (compact) 26.dp else 28.dp
    val rotation by animateFloatAsState(
        targetValue = if (expanded) 180f else 0f,
        animationSpec = if (animationsEnabled) tween(durationMillis = 200, easing = FastOutSlowInEasing) else snap(),
        label = "player-shelf-chevron"
    )

    Box(
        modifier = Modifier.fillMaxWidth(),
        contentAlignment = Alignment.Center
    ) {
        Surface(
            color = Color.Black.copy(alpha = 0.30f),
            border = BorderStroke(
                1.dp,
                Color.White.copy(alpha = if (expanded) 0.20f else 0.10f)
            ),
            shape = CircleShape,
            modifier = Modifier
                .width(width)
                .height(height)
                .shadow(
                    elevation = 4.dp,
                    shape = CircleShape,
                    ambientColor = Color.Black.copy(alpha = 0.25f),
                    spotColor = Color.Black.copy(alpha = 0.45f)
                )
                .pressable(pressedScale = 0.94f, onClick = onToggle)
        ) {
            Box(
                modifier = Modifier.fillMaxSize(),
                contentAlignment = Alignment.Center
            ) {
                Icon(
                    imageVector = Icons.Rounded.KeyboardArrowDown,
                    contentDescription = strings.options,
