                .background(
                    Brush.linearGradient(
                        listOf(
                            accent.copy(alpha = if (active) 0.42f else 0.24f),
                            Color.White.copy(alpha = 0.06f)
                        )
                    )
                )
                .border(
                    LevyraPlayerDesign.Hairline,
                    if (active) accent.copy(alpha = 0.55f) else LevyraPlayerDesign.GlassBorderTop,
                    LevyraPlayerDesign.ShapeSm
                ),
            contentAlignment = Alignment.Center
        ) {
            Icon(
                Icons.Rounded.Radio,
                null,
                tint = LevyraPlayerDesign.TextPrimary,
                modifier = Modifier.size(28.dp)
            )
        }
        Text(
            text = label,
            color = LevyraPlayerDesign.TextPrimary,
            fontSize = 12.sp,
            fontWeight = FontWeight.Bold,
            maxLines = 2,
            overflow = TextOverflow.Ellipsis
        )
    }
}

@Composable
private fun PlayerSimilarSongCard(
    track: Track,
    queued: Boolean,
    canPlay: Boolean,
    canAddToQueue: Boolean,
    accent: Color,
    playLabel: String,
    addLabel: String,
    onPlay: () -> Unit,
    onAddToQueue: () -> Unit
) {
    Column(
        modifier = Modifier
            .width(SimilarSongCardWidth)
            .graphicsLayer { alpha = if (canPlay) 1f else SimilarSongDisabledAlpha }
            .pressable(enabled = canPlay, onClick = onPlay),
        verticalArrangement = Arrangement.spacedBy(LevyraPlayerDesign.SpaceSm)
    ) {
        Box(
            modifier = Modifier
                .size(SimilarSongCardWidth)
                .clip(LevyraPlayerDesign.ShapeSm)
                .background(LevyraPanelSoft)
        ) {
            val artworkUrl = track.thumbnailUrl.ifBlank { track.largeThumbnailUrl }
            if (artworkUrl.isNotBlank()) {
                StableRemoteArtwork(
                    url = artworkUrl,
                    contentDescription = playLabel,
                    modifier = Modifier.matchParentSize(),
                    contentScale = ContentScale.Crop
                )
            } else {
                Icon(
                    Icons.Rounded.MusicNote,
                    null,
                    tint = LevyraMuted,
                    modifier = Modifier
                        .align(Alignment.Center)
                        .size(30.dp)
                )
            }
            Box(
                modifier = Modifier
                    .align(Alignment.BottomEnd)
                    .size(LevyraPlayerDesign.MinimumTouchTarget)
                    .pressable(enabled = canAddToQueue, onClick = onAddToQueue),
                contentAlignment = Alignment.Center
            ) {
                Box(
                    modifier = Modifier
                        .padding(6.dp)
                        .size(SimilarSongBadgeSize)
                        .clip(CircleShape)
                        .background(Color.Black.copy(alpha = 0.62f)),
                    contentAlignment = Alignment.Center
                ) {
                    Icon(
                        if (queued) Icons.Rounded.Check else Icons.Rounded.Add,
                        addLabel,
                        tint = if (queued) accent else LevyraPlayerDesign.TextPrimary,
                        modifier = Modifier.size(18.dp)
                    )
                }
            }
        }
        Column(verticalArrangement = Arrangement.spacedBy(2.dp)) {
            Text(
                text = track.title,
                color = LevyraPlayerDesign.TextPrimary,
                fontSize = 12.sp,
                fontWeight = FontWeight.Bold,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
            Text(
                text = track.artist,
                color = LevyraPlayerDesign.TextTertiary,
                fontSize = 11.sp,
                fontWeight = FontWeight.Medium,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
        }
    }
}

@Composable
private fun PlayerInlineLyricsSection(
    trackId: String,
    lyrics: List<com.luc4n3x.levyra.domain.LyricLine>,
    lyricsLoading: Boolean,
    positionMs: Long,
    isPlaying: Boolean,
    playbackSpeed: Float,
    synced: Boolean,
    durationMs: Long,
    primaryContent: Color,
    compact: Boolean,
    strings: LevyraStrings,
    onSeek: (Float) -> Unit
) {
    var showInlineLyrics by remember(trackId) { mutableStateOf(false) }

    when {
        lyrics.isNotEmpty() && !showInlineLyrics -> {
            Surface(
                color = Color.Black.copy(alpha = 0.20f),
                border = BorderStroke(1.dp, Color.White.copy(alpha = 0.10f)),
                shape = RoundedCornerShape(20.dp),
                modifier = Modifier
                    .fillMaxWidth()
                    .pressable { showInlineLyrics = true }
            ) {
                Row(
                    modifier = Modifier.padding(
                        horizontal = 18.dp,
                        vertical = if (compact) 12.dp else 13.dp
                    ),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceBetween
                ) {
                    Row(verticalAlignment = Alignment.CenterVertically) {
                        Icon(
                            Icons.AutoMirrored.Rounded.Subject,
                            null,
                            tint = primaryContent,
                            modifier = Modifier.size(19.dp)
                        )
                        Spacer(modifier = Modifier.width(9.dp))
                        Text(
                            strings.showLyrics,
                            color = Color.White,
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                    Icon(
                        Icons.AutoMirrored.Rounded.KeyboardArrowRight,
                        null,
                        tint = Color.White.copy(alpha = 0.55f),
                        modifier = Modifier.size(20.dp)
                    )
                }
            }
        }

        lyrics.isNotEmpty() -> {
            val listState = rememberLazyListState()
            val lyricsAnimationsEnabled = LocalAnimationsEnabled.current
            val inlineClock = rememberLyricsPlaybackClock(
                trackKey = trackId,
                reportedPositionMs = positionMs,
                isPlaying = isPlaying,
                speed = playbackSpeed,
                smoothingEnabled = synced && lyricsAnimationsEnabled
            )
            val visualActiveIndex by remember(lyrics, inlineClock) {
                derivedStateOf { activeLyricIndex(inlineClock.positionMs, lyrics) }
            }
            var inlineAutoScroll by remember(trackId) { mutableStateOf(true) }
            var inlineAutoScrolling by remember(trackId) { mutableStateOf(false) }

            LaunchedEffect(listState.isScrollInProgress, inlineAutoScrolling) {
                if (listState.isScrollInProgress && !inlineAutoScrolling) {
                    inlineAutoScroll = false
                } else if (!listState.isScrollInProgress && !inlineAutoScrolling && !inlineAutoScroll) {
                    delay(INLINE_LYRICS_AUTOSCROLL_RESUME_MS)
                    inlineAutoScroll = true
                }
            }

            LaunchedEffect(visualActiveIndex, inlineAutoScroll, lyricsAnimationsEnabled) {
                if (visualActiveIndex >= 0 && inlineAutoScroll) {
                    inlineAutoScrolling = true
                    runCatching {
                        val target = maxOf(0, visualActiveIndex - 1)
                        if (lyricsAnimationsEnabled) {
                            listState.animateScrollToItem(target)
                        } else {
                            listState.scrollToItem(target)
                        }
                    }
                    inlineAutoScrolling = false
                }
            }

            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(400.dp)
                    .padding(vertical = 8.dp)
                    .background(Color.Black.copy(alpha = 0.26f), RoundedCornerShape(28.dp))
                    .border(BorderStroke(1.dp, Color.White.copy(alpha = 0.11f)), RoundedCornerShape(28.dp))
            ) {
                LazyColumn(
                    state = listState,
                    modifier = Modifier.fillMaxSize(),
                    contentPadding = PaddingValues(start = 22.dp, end = 22.dp, top = 52.dp, bottom = 28.dp),
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    itemsIndexed(
                        items = lyrics,
                        key = { index, line -> "${line.startMs}-${line.role.name}-$index" }
                    ) { index, line ->
                        val isActive = index == visualActiveIndex
                        val lineColor by animateColorAsState(
                            targetValue = if (isActive) primaryContent else Color.White.copy(alpha = 0.48f),
                            animationSpec = LevyraMotion.spec(lyricsAnimationsEnabled, tween(LevyraMotion.Durations.Short, easing = LevyraMotion.Easings.Decelerate)),
                            label = "inline-lyrics-color"
                        )
                        val lineScale by animateFloatAsState(
                            targetValue = if (isActive) 1.02f else 1f,
                            animationSpec = LevyraMotion.physics(lyricsAnimationsEnabled, LevyraMotion.spatial),
                            label = "inline-lyrics-scale"
                        )
                        Text(
                            text = line.text,
                            color = lineColor,
                            fontSize = if (isActive) 24.sp else 19.sp,
                            lineHeight = if (isActive) 29.sp else 24.sp,
                            fontWeight = if (isActive) FontWeight.Black else FontWeight.Medium,
                            modifier = Modifier
                                .graphicsLayer {
                                    scaleX = lineScale
                                    scaleY = lineScale
                                    transformOrigin = TransformOrigin(0f, 0.5f)
                                }
                                .clickable {
                                    onSeek(progressOf(line.startMs, durationMs))
                                }
                        )
                    }
                }
                IconButton(
                    onClick = { showInlineLyrics = false },
                    modifier = Modifier
                        .align(Alignment.TopEnd)
                        .padding(8.dp)
                ) {
                    Icon(
                        Icons.Rounded.Close,
                        strings.close,
                        tint = Color.White.copy(alpha = 0.62f)
                    )
                }
            }
        }

        lyricsLoading -> {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(104.dp)
                    .background(Color.Black.copy(alpha = 0.22f), RoundedCornerShape(24.dp))
                    .border(BorderStroke(1.dp, Color.White.copy(alpha = 0.10f)), RoundedCornerShape(24.dp)),
                contentAlignment = Alignment.Center
            ) {
                CircularProgressIndicator(
                    color = primaryContent,
                    strokeWidth = 3.dp
                )
            }
        }
    }
}

private const val PLAYER_LONG_PRESS_SPEED_MS = 320L
private const val PLAYER_LONG_PRESS_ARTWORK_MS = 900L

