@Composable
private fun PlayerScreen(
    viewModel: PlayerViewModel,
    state: LevyraUiState,
    morphAnchors: PlayerMorphAnchors,
    morphActive: () -> Boolean,
    collapseActions: PlayerCollapseActions,
    motionSuspended: Boolean
) {
    val track = state.currentTrack
    val strings = LocalLevyraStrings.current
    var playlistTarget by remember(track?.id) { mutableStateOf<Track?>(null) }
    val queuedTrackIds = remember(state.queue) {
        state.queue.mapTo(HashSet(state.queue.size)) { it.id }
    }
    val visibleSimilarSongs = remember(state.similarSongs, state.artistExclusions) {
        state.artistExclusions.filterTracks(state.similarSongs)
    }

    LevyraNowPlaying(
        viewModel = viewModel,
        state = state,
        morphAnchors = morphAnchors,
        morphActive = morphActive,
        collapseActions = collapseActions,
        motionSuspended = motionSuspended,
        modeSwitchContent = {
            if (track != null && (track.videoUrl.isNotBlank() || track.counterpartVideoId.isNotBlank())) {
                PlayerModeSwitch(
                    isVideoMode = state.pendingVideoMode ?: state.isVideoMode,
                    onSong = viewModel::toggleVideoMode,
                    onVideo = viewModel::toggleVideoMode
                )
            }
        },
        videoSurfaceContent = { activeTrack, modifier ->
            LevyraVideoSurface(
                state = state,
                modifier = modifier
            )
        },
        gestureLayerContent = { activeTrack, config, mediaActions, uiActions, videoTransform, modifier ->
            PlayerGestureLayer(
                config = config,
                mediaActions = mediaActions,
                uiActions = uiActions,
                videoTransform = videoTransform,
                modifier = modifier
            )
        },
        engagementContent = { activeTrack ->
            PlayerYoutubeEngagementRow(
                track = activeTrack,
                engagement = state.youtubeEngagement,
                compact = true,
                onComments = viewModel::openYoutubeComments
            )
        },
        similarSongsContent = { activeTrack ->
            PlayerSimilarSongsSection(
                similarSongs = visibleSimilarSongs,
                queuedTrackIds = queuedTrackIds,
                canPlayNow = !state.jam.isActive || state.jam.canControlPlayback,
                canAddToQueue = !state.jam.isActive || state.jam.canAddTracks,
                loading = state.similarSongsLoading,
                radioEnabled = state.radioEnabled,
                accent = Color(activeTrack.accentStart).playerMix(Color.White, 0.48f),
                compact = false,
                strings = strings,
                onPlay = viewModel::playSimilarSong,
                onAddToQueue = viewModel::addToQueue,
                onStartRadio = viewModel::startSongRadio
            )
        },
        errorContent = {
            PlayerError(state.playerError)
        },
        playlistDialogContent = {
            playlistTarget?.let { target ->
                AddToPlaylistDialog(
                    track = target,
                    playlists = state.playlists,
                    onDismiss = { playlistTarget = null },
                    onAddTo = { playlistId ->
                        viewModel.addToPlaylist(playlistId, target)
                        playlistTarget = null
                    },
                    onCreateWith = { name ->
                        viewModel.createPlaylist(name, target)
                        playlistTarget = null
                    }
                )
            }
        },
        onOpenPlaylistDialog = { selected -> playlistTarget = selected }
    )
}

private fun applyBrightnessDrag(
    activity: Activity?,
    deltaPx: Float,
    heightPx: Float,
    label: String,
    onFeedback: (String) -> Unit
) {
    val window = activity?.window ?: return
    val attributes = window.attributes
    val current = attributes.screenBrightness.takeIf { it >= 0f } ?: 0.5f
    val updated = (current - deltaPx / heightPx.coerceAtLeast(1f)).coerceIn(0.05f, 1f)
    attributes.screenBrightness = updated
    window.attributes = attributes
    onFeedback("$label ${(updated * 100f).roundToInt()}%")
}

private fun applyVolumeDrag(
    audioManager: AudioManager?,
    deltaPx: Float,
    heightPx: Float,
    accumulator: Float,
    label: String,
    onFeedback: (String) -> Unit
): Float {
    val manager = audioManager ?: return 0f
    val maximum = manager.getStreamMaxVolume(AudioManager.STREAM_MUSIC).coerceAtLeast(1)
    val pending = accumulator + -deltaPx / heightPx.coerceAtLeast(1f) * maximum
    val steps = pending.roundToInt()
    if (steps == 0) return pending
    val current = manager.getStreamVolume(AudioManager.STREAM_MUSIC)
    val updated = (current + steps).coerceIn(0, maximum)
    manager.setStreamVolume(AudioManager.STREAM_MUSIC, updated, 0)
    onFeedback("$label ${((updated.toFloat() / maximum.toFloat()) * 100f).roundToInt()}%")
    return pending - steps.toFloat()
}

@Composable
private fun PlayerGestureLayer(
    config: PlayerGestureConfig,
    mediaActions: PlayerGestureMediaActions,
    uiActions: PlayerGestureUiActions,
    videoTransform: MutableState<PlayerVideoTransform>? = null,
    modifier: Modifier = Modifier
) {
    val currentPlaybackSpeed by rememberUpdatedState(config.playbackSpeed)
    val volumeAccumulator = remember(config.trackId) { mutableFloatStateOf(0f) }
    val environment = config.environment
    val zoomModifier = if (videoTransform == null) {
        modifier
    } else {
        modifier.playerVideoZoomGestures(
            key = config.trackId,
            enabled = true,
            transform = videoTransform,
            onTakeOver = {
                cancelPlayerGesture(mediaActions, uiActions, volumeAccumulator)
            },
            onTransform = { zoomChange, pan, sizePx ->
                videoTransform.value = videoTransform.value
                    .applyPlayerVideoGesture(zoomChange, pan, sizePx)
            }
        )
    }
    val inputModifier = if (config.settings.playerGesturesEnabled) {
        zoomModifier
            .pointerInput(
                config.trackId,
                config.settings.doubleTapAction,
                config.settings.doubleTapSeekSeconds,
                config.settings.longPressAction,
                config.settings.longPressSpeed,
                environment.rightToLeft,
                uiActions.artworkPreview != null
            ) {
                detectTapGestures(
                    onPress = {
                        val command = playerLongPressCommand(config.settings.longPressAction)
                        if (command != PlayerGestureCommand.None) {
                            val originalSpeed = currentPlaybackSpeed
                            val openArtworkPreview = uiActions.artworkPreview
                            coroutineScope {
                                var boosted = false
                                val actionJob = launch {
                                    delay(PLAYER_LONG_PRESS_SPEED_MS)
                                    if (command == PlayerGestureCommand.TemporarySpeed) {
                                        boosted = true
                                        mediaActions.temporarySpeed(config.settings.longPressSpeed)
                                        uiActions.haptic()
                                        uiActions.feedback(
                                            "${String.format(Locale.US, "%.1f", config.settings.longPressSpeed)}×"
                                        )
                                        if (openArtworkPreview != null) {
                                            delay(PLAYER_LONG_PRESS_ARTWORK_MS - PLAYER_LONG_PRESS_SPEED_MS)
                                            mediaActions.temporarySpeed(originalSpeed)
                                            boosted = false
                                            uiActions.haptic()
                                            openArtworkPreview()
                                        }
                                    } else {
                                        performPlayerGestureCommand(
                                            command = command,
                                            config = config,
                                            mediaActions = mediaActions,
                                            uiActions = uiActions
                                        )
                                    }
                                }
                                try {
                                    tryAwaitRelease()
                                } finally {
                                    actionJob.cancel()
                                    if (boosted) mediaActions.temporarySpeed(originalSpeed)
                                }
                            }
                        }
                    },
                    onDoubleTap = { offset ->
                        val width = size.width.coerceAtLeast(1).toFloat()
                        val side = playerTapSide(offset.x / width)
                        performPlayerGestureCommand(
                            command = playerDoubleTapCommand(config.settings.doubleTapAction, side),
                            config = config,
                            mediaActions = mediaActions,
                            uiActions = uiActions
                        )
                    }
                )
            }
            .playerAxisDragGestures(
                key = "${config.trackId}:${config.settings.swipeTrackChangeEnabled}:${config.settings.verticalSwipeAction}",
                enabled = true,
                rightToLeft = environment.rightToLeft,
                edgeZonesEnabled = config.settings.verticalSwipeAction != PlayerVerticalSwipeAction.Disabled
            ) { event ->
                handlePlayerGestureEvent(
                    event = event,
                    config = config,
                    mediaActions = mediaActions,
                    uiActions = uiActions,
                    volumeAccumulator = volumeAccumulator
                )
            }
    } else {
        zoomModifier
    }
    Box(
        modifier = inputModifier
    )
}

private fun performPlayerGestureCommand(
    command: PlayerGestureCommand,
    config: PlayerGestureConfig,
    mediaActions: PlayerGestureMediaActions,
    uiActions: PlayerGestureUiActions
) {
    when (command) {
        PlayerGestureCommand.SeekLeading -> mediaActions.seekBy(
            playerSeekDeltaMs(
                PlayerTapSide.Leading,
                config.settings.doubleTapSeekSeconds,
                config.environment.rightToLeft
            )
        )
        PlayerGestureCommand.SeekTrailing -> mediaActions.seekBy(
            playerSeekDeltaMs(
                PlayerTapSide.Trailing,
                config.settings.doubleTapSeekSeconds,
                config.environment.rightToLeft
            )
        )
        PlayerGestureCommand.TogglePlayback -> {
            mediaActions.togglePlay()
            uiActions.haptic()
        }
        PlayerGestureCommand.ToggleFavorite -> {
            uiActions.toggleFavorite()
            uiActions.haptic()
        }
        PlayerGestureCommand.OpenQueue -> {
            uiActions.openQueue()
            uiActions.haptic()
        }
        PlayerGestureCommand.OpenLyrics -> {
            uiActions.openLyrics()
            uiActions.haptic()
        }
        PlayerGestureCommand.TemporarySpeed,
        PlayerGestureCommand.None -> Unit
    }
}

private fun handlePlayerGestureEvent(
    event: PlayerDragEvent,
    config: PlayerGestureConfig,
    mediaActions: PlayerGestureMediaActions,
    uiActions: PlayerGestureUiActions,
    volumeAccumulator: MutableState<Float>
) {
    when (event) {
        is PlayerDragEvent.HorizontalOffset -> if (config.settings.swipeTrackChangeEnabled) {
            mediaActions.swipeOffset(event.offsetPx)
        }
        is PlayerDragEvent.HorizontalSettled -> if (config.settings.swipeTrackChangeEnabled) {
            settlePlayerHorizontalGesture(event, mediaActions)
        } else {
            mediaActions.swipeSettled(false)
        }
        is PlayerDragEvent.VerticalStart -> startPlayerVerticalGesture(event, uiActions)
        is PlayerDragEvent.VerticalDrag -> handlePlayerVerticalDrag(
            event,
            config.environment,
            config.settings.verticalSwipeAction,
            uiActions,
            volumeAccumulator
        )
        is PlayerDragEvent.VerticalSettled -> settlePlayerVerticalGesture(
            event,
            uiActions,
            volumeAccumulator
        )
        PlayerDragEvent.Cancelled -> cancelPlayerGesture(
            mediaActions,
            uiActions,
            volumeAccumulator
        )
    }
}

private fun settlePlayerHorizontalGesture(
    event: PlayerDragEvent.HorizontalSettled,
    mediaActions: PlayerGestureMediaActions
) {
    when (event.result) {
        PlayerSwipeResult.Next -> mediaActions.next()
        PlayerSwipeResult.Previous -> mediaActions.previous()
        PlayerSwipeResult.Settle -> Unit
    }
    mediaActions.swipeSettled(event.result != PlayerSwipeResult.Settle)
}

private fun startPlayerVerticalGesture(
    event: PlayerDragEvent.VerticalStart,
    uiActions: PlayerGestureUiActions
) {
    if (event.zone == PlayerGestureZone.Center) uiActions.collapse.dragStart()
}

private fun handlePlayerVerticalDrag(
    event: PlayerDragEvent.VerticalDrag,
    environment: PlayerGestureEnvironment,
    action: PlayerVerticalSwipeAction,
    uiActions: PlayerGestureUiActions,
    volumeAccumulator: MutableState<Float>
) {
    when (event.zone) {
        PlayerGestureZone.BrightnessEdge -> if (action == PlayerVerticalSwipeAction.Volume) {
            volumeAccumulator.value = applyVolumeDrag(
                audioManager = environment.audioManager,
                deltaPx = event.deltaPx,
                heightPx = event.heightPx,
                accumulator = volumeAccumulator.value,
                label = environment.volumeLabel,
                onFeedback = uiActions.feedback
            )
        } else {
            applyBrightnessDrag(
                activity = environment.activity,
                deltaPx = event.deltaPx,
                heightPx = event.heightPx,
                label = environment.brightnessLabel,
                onFeedback = uiActions.feedback
            )
        }
        PlayerGestureZone.VolumeEdge -> volumeAccumulator.value = applyVolumeDrag(
            audioManager = environment.audioManager,
            deltaPx = event.deltaPx,
            heightPx = event.heightPx,
            accumulator = volumeAccumulator.value,
            label = environment.volumeLabel,
            onFeedback = uiActions.feedback
        )
        PlayerGestureZone.Center -> uiActions.collapse.drag(event.deltaPx)
    }
}

private fun settlePlayerVerticalGesture(
    event: PlayerDragEvent.VerticalSettled,
    uiActions: PlayerGestureUiActions,
    volumeAccumulator: MutableState<Float>
) {
    volumeAccumulator.value = 0f
    if (event.zone == PlayerGestureZone.Center) {
        uiActions.collapse.dragEnd(event.velocityPx)
    }
}

private fun cancelPlayerGesture(
    mediaActions: PlayerGestureMediaActions,
    uiActions: PlayerGestureUiActions,
    volumeAccumulator: MutableState<Float>
) {
    volumeAccumulator.value = 0f
    mediaActions.swipeSettled(false)
    uiActions.collapse.dragEnd(0f)
}

@Composable
private fun PlayerTimeline(
    positionMs: Long,
    bufferedPositionMs: Long,
    durationMs: Long,
    activeColor: Color,
    secondaryColor: Color,
    isPlaying: Boolean,
    animationsEnabled: Boolean,
    compact: Boolean,
    onSeek: (Float) -> Unit
) {
    Column(modifier = Modifier.fillMaxWidth()) {
        PremiumSeekbar(
            positionMs = positionMs,
            durationMs = durationMs,
            bufferedPositionMs = bufferedPositionMs,
            isPlaying = isPlaying,
            onSeekTo = { seekMs ->
                if (durationMs > 0L) {
                    onSeek((seekMs.toFloat() / durationMs.toFloat()).coerceIn(0f, 1f))
                }
            },
            activeColor = activeColor,
            trailingColor = secondaryColor,
            inactiveColor = LevyraPlayerDesign.TrackInactive,
            animated = animationsEnabled
        )
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = LevyraPlayerDesign.SpaceXxs),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                text = formatSeekbarMillis(positionMs),
                color = LevyraPlayerDesign.TextSecondary,
                fontSize = if (compact) 11.sp else 11.5.sp,
                fontWeight = FontWeight.Medium,
                letterSpacing = 0.3.sp
            )
            Text(
                text = if (durationMs > 0L) formatSeekbarMillis(durationMs) else formatDuration(durationMs),
                color = LevyraPlayerDesign.TextTertiary,
                fontSize = if (compact) 11.sp else 11.5.sp,
                fontWeight = FontWeight.Medium,
                letterSpacing = 0.3.sp
            )
        }
    }
}

@Composable
private fun PlayerOptionsRow(
    speed: Float,
    sleepMinutes: Int,
    sleepTimerEndOfTrack: Boolean,
    audioNormalization: Boolean,
    activeColor: Color,
    secondaryColor: Color,
    compact: Boolean,
    onSpeed: () -> Unit,
    onSleep: () -> Unit,
    onNormalization: () -> Unit,
    onAmbient: () -> Unit
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(
                top = if (compact) 1.dp else 2.dp,
                bottom = if (compact) 3.dp else 4.dp
            ),
        horizontalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        OptionChip(
            icon = Icons.Rounded.GraphicEq,
            label = LocalLevyraStrings.current.normalizationShort,
            active = audioNormalization,
            activeColor = activeColor,
            modifier = Modifier.weight(1f),
            compact = compact,
            onClick = onNormalization
        )
        OptionChip(
            icon = Icons.Rounded.Speed,
            label = "${trimSpeed(speed)}x",
            active = speed != 1f,
            activeColor = activeColor.playerMix(secondaryColor, 0.35f),
            modifier = Modifier.weight(1f),
            compact = compact,
            onClick = onSpeed
        )
        OptionChip(
            icon = Icons.Rounded.Bedtime,
            label = when {
                sleepTimerEndOfTrack -> LocalLevyraStrings.current.sleepTimerEndOfTrack
                sleepMinutes > 0 -> LocalLevyraStrings.current.formatSleepTimerMinutes(sleepMinutes)
                else -> LocalLevyraStrings.current.timer
            },
            active = sleepMinutes > 0 || sleepTimerEndOfTrack,
            activeColor = secondaryColor,
            modifier = Modifier.weight(1f),
            compact = compact,
            onClick = onSleep
        )
        OptionChip(
            icon = Icons.Rounded.Nightlight,
            label = LocalLevyraStrings.current.ambientMode,
            active = false,
            activeColor = secondaryColor,
            modifier = Modifier.weight(1f),
            compact = compact,
            onClick = onAmbient
        )
    }
}

@Composable
private fun OptionChip(
    icon: ImageVector,
    label: String,
    active: Boolean,
    activeColor: Color,
    modifier: Modifier,
    compact: Boolean,
    enabled: Boolean = true,
    onClick: () -> Unit
) {
    val alpha by animateFloatAsState(
        targetValue = if (enabled) 1f else 0.5f,
        animationSpec = spring(dampingRatio = 0.8f, stiffness = 400f),
        label = "player-option-alpha"
    )
    val background = if (active) activeColor.copy(alpha = 0.28f) else Color.Black.copy(alpha = 0.20f)
    val effectiveBackground = background.playerCompositeOver(PlayerDarkSurface)
    val contentColor = if (active) {
        activeColor.playerContentColor(listOf(effectiveBackground))
    } else {
        Color.White.playerContentColor(listOf(effectiveBackground))
    }
    val borderColor = if (active) activeColor.copy(alpha = 0.58f) else Color.White.copy(alpha = 0.10f)

    Surface(
        color = background,
        border = BorderStroke(LevyraPlayerDesign.Hairline, borderColor),
        shape = LevyraPlayerDesign.ShapeSm,
        modifier = modifier
            .height(if (compact) 40.dp else 42.dp)
            .graphicsLayer { this.alpha = alpha }
            .pressable(enabled = enabled, onClick = onClick)
    ) {
        Row(
            modifier = Modifier.fillMaxSize(),
            horizontalArrangement = Arrangement.Center,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Icon(
                icon,
                null,
                tint = contentColor,
                modifier = Modifier.size(if (compact) 16.dp else 16.dp)
            )
            Spacer(modifier = Modifier.width(if (compact) 6.dp else 6.dp))
            Text(
                text = label,
                color = contentColor,
                fontSize = if (compact) 11.5.sp else 12.sp,
                fontWeight = FontWeight.Bold,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
        }
    }
}

@Composable
private fun ShareOptionChip(track: Track, modifier: Modifier = Modifier) {
    val context = LocalContext.current
    val strings = LocalLevyraStrings.current
    Surface(
        color = Color.White.copy(alpha = 0.06f),
        border = BorderStroke(1.dp, Color.White.copy(alpha = 0.1f)),
        shape = CircleShape,
        modifier = modifier
            .size(48.dp)
            .pressable {
                val link = track.videoUrl.ifBlank { "https://music.youtube.com/watch?v=${track.id}" }
                val intent = Intent(Intent.ACTION_SEND).apply {
                    type = "text/plain"
                    putExtra(Intent.EXTRA_SUBJECT, "${track.title} — ${track.artist}")
                    putExtra(Intent.EXTRA_TEXT, "${track.title} — ${track.artist}\n$link")
                }
                context.startActivity(Intent.createChooser(intent, strings.shareSong))
            }
    ) {
        Box(contentAlignment = Alignment.Center) {
            Icon(Icons.Rounded.Share, null, tint = LevyraText, modifier = Modifier.size(20.dp))
        }
    }
}

private fun trimSpeed(speed: Float): String {
    return if (speed % 1f == 0f) speed.toInt().toString() else speed.toString().trimEnd('0').trimEnd('.')
}

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
private fun SettingsOverlay(
