    networkProxyPasswordSet: Boolean,
    networkTesting: Boolean,
    networkTestOutcome: LevyraNetworkTestOutcome?,
    networkErrors: List<LevyraNetworkSettingsError>,
    videoQualityTarget: VideoQualityTarget,
    lyricsProviderOrdering: LyricsProviderOrdering,
    onNetworkSettings: (LevyraNetworkSettings, String?) -> Unit,
    onTestNetwork: (LevyraNetworkSettings, String?) -> Unit,
    onVideoQualityTarget: (VideoQualityTarget) -> Unit,
    onLyricsProviderOrdering: (LyricsProviderOrdering) -> Unit,
    onOpenJam: () -> Unit,
    onOpenThemeStudio: () -> Unit,
    onOpenLyricsStudio: () -> Unit = {},
    homeStudioStyle: HomeStyle = HomeStyle.Original,
    onOpenHomeStudio: () -> Unit = {},
    miniPlayerStyle: MiniPlayerStyle = MiniPlayerStyle.Original,
    onOpenMiniPlayerStudio: () -> Unit = {},
    navigationStyle: NavStyle = NavStyle.Original,
    onOpenNavigationStudio: () -> Unit = {},
    onOpenAudioSettings: () -> Unit,
    onInterfaceSettings: (LevyraInterfaceSettings) -> Unit,
    onAmbientSettings: (LevyraAmbientSettings) -> Unit,
    onOpenAmbient: () -> Unit,
    onIncludeArtist: (ExcludedArtist) -> Unit,
    onDownloadSettings: (LevyraDownloadSettings) -> Unit,
    onSmartOfflineSettings: (LevyraSmartOfflineSettings) -> Unit,
    onRefreshSmartOffline: () -> Unit,
    onAdvancedQueuePrefetch: (Int) -> Unit,
    onAdvancedQueuePrefetchOnMobileData: (Boolean) -> Unit,
    onSelectDownloadLocation: () -> Unit,
    onClearDownloadLocation: () -> Unit,
    onBackupSettings: (LevyraBackupSettings) -> Unit,
    onAutomationSettings: (LevyraAutomationSettings) -> Unit,
    onAnimations: (Boolean) -> Unit,
    onMotionArtwork: (Boolean) -> Unit,
    onDynamicColor: (Boolean) -> Unit,
    onSponsorBlock: (Boolean) -> Unit,
    onSkipSilence: (Boolean) -> Unit,
    onMusicRegion: (String) -> Unit,
    musicRegionId: String,
    preferredAudioLanguage: String,
    onPreferredAudioLanguage: (String) -> Unit,
    onLanguage: (String) -> Unit,
    onCheckUpdates: () -> Unit,
    onDownloadUpdate: () -> Unit,
    onCreateBackup: () -> Unit,
    onRestoreBackup: () -> Unit,
    onBackupNow: () -> Unit,
    onManageBackups: () -> Unit,
    onSelectBackupLocation: () -> Unit,
    onClearBackupLocation: () -> Unit,
    onPauseDownload: (String) -> Unit,
    onResumeDownload: (String) -> Unit,
    onCancelDownload: (String) -> Unit,
    onShareDiagnostics: () -> Unit,
    onOpenPlaybackDiagnostics: () -> Unit,
    onBeginLastFm: (String, String) -> Unit,
    onCompleteLastFm: () -> Unit,
    onClearLastFm: () -> Unit,
    onSaveListenBrainz: (String) -> Unit,
    onClearListenBrainz: () -> Unit,
    onSaveAudD: (String) -> Unit,
    onClearAudD: () -> Unit,
    onRedoQuestionnaire: () -> Unit,
    profilePhotoSet: Boolean,
    onPickProfilePhoto: () -> Unit,
    onRemoveProfilePhoto: () -> Unit,
    onOpenYoutubeMusic: () -> Unit,
    onClose: () -> Unit
) {
    val strings = LocalLevyraStrings.current
    val automationCopy = strings.automationCopy()
    var activeCategory by rememberSaveable { mutableStateOf<String?>(null) }
    var settingsQuery by rememberSaveable { mutableStateOf("") }
    val batteryContext = LocalContext.current
    val batteryLifecycleOwner = LocalLifecycleOwner.current
    var batteryCheckToken by remember { mutableStateOf(0) }
    val batteryUnrestricted = remember(batteryCheckToken) {
        batteryContext.getSystemService(PowerManager::class.java)
        ?.isIgnoringBatteryOptimizations(batteryContext.packageName) == true
    }
    var selectedDownloadFolderName by remember(downloadSettings.destinationTreeUri) { mutableStateOf<String?>(null) }
    LaunchedEffect(downloadSettings.destinationTreeUri, batteryCheckToken) {
        selectedDownloadFolderName = if (downloadSettings.destinationTreeUri.isBlank()) {
            null
        } else {
            withContext(Dispatchers.IO) {
                DownloadFolderAccess.displayName(batteryContext, downloadSettings.destinationTreeUri)
            }
        }
    }
    DisposableEffect(batteryLifecycleOwner) {
        val observer = LifecycleEventObserver { _, event ->
            if (event == Lifecycle.Event.ON_RESUME) batteryCheckToken++
        }
        batteryLifecycleOwner.lifecycle.addObserver(observer)
        onDispose { batteryLifecycleOwner.lifecycle.removeObserver(observer) }
    }
    BackHandler(enabled = backEnabled && activeCategory != null) { activeCategory = null }
    val categoryLocale = remember(strings.code) { Locale.forLanguageTag(strings.code.replace('_', '-')) }
    fun categoryTitle(value: String): String = settingsCategoryTitle(value, categoryLocale)
    val categories = remember(strings.code, LevyraActivePalette) {
        listOf(
            SettingsCategoryMeta("skins", com.luc4n3x.levyra.ui.i18n.LevyraSkinStrings.forCode(strings.code).title, "Levyra Default · Nocturne 78 · Prism · Torque · Ivory · Spotify Style · Apple Music Style · YouTube Music Style", Icons.Rounded.Style, LevyraViolet, SettingsHubGroup.Appearance),
            SettingsCategoryMeta("design", categoryTitle(strings.design), "${strings.theme} · ${strings.animations} · ${strings.dynamicColor}", Icons.Rounded.Palette, LevyraViolet, SettingsHubGroup.Appearance),
            SettingsCategoryMeta("home", categoryTitle(strings.homeInterfaceSection), "${strings.compactHome} · ${strings.newReleases} · ${strings.top50Charts}", Icons.Rounded.Home, LevyraViolet, SettingsHubGroup.Appearance),
            SettingsCategoryMeta("player", categoryTitle(strings.player), "${strings.advancedGestures} · ${strings.sponsorBlock} · ${strings.skipSilence}", Icons.Rounded.PlayArrow, LevyraPink, SettingsHubGroup.Listening),
            SettingsCategoryMeta("smart_listening", strings.smartListeningCopy().hubTitle, strings.smartListeningCopy().hubSubtitle, Icons.Rounded.AutoAwesome, LevyraPink, SettingsHubGroup.Listening),
            SettingsCategoryMeta("audio", strings.audioEngine, strings.audioEngineSubtitle, Icons.Rounded.GraphicEq, LevyraPink, SettingsHubGroup.Listening),
            SettingsCategoryMeta("lyrics", categoryTitle(strings.lyricsAnalysisSection), strings.lyricsAnalysisCompact, Icons.Rounded.Insights, LevyraPink, SettingsHubGroup.Listening),
            SettingsCategoryMeta("jam", categoryTitle(strings.jamTitle), strings.jamSubtitle, Icons.Rounded.Groups, LevyraPink, SettingsHubGroup.Listening),
            SettingsCategoryMeta("downloads", categoryTitle(strings.downloads), "${strings.wifiOnly} · ${strings.simultaneousDownloads}", Icons.Rounded.Download, LevyraBlue, SettingsHubGroup.Library),
            SettingsCategoryMeta("backup", strings.vaultTitle, "${strings.backupNow} · ${strings.restoreBackup}", Icons.Rounded.History, LevyraBlue, SettingsHubGroup.Library),
            SettingsCategoryMeta("youtube_music", "YouTube Music", com.luc4n3x.levyra.ui.i18n.youtubeMusicCopy(strings.code).introduction, Icons.Rounded.AccountCircle, LevyraCyan, SettingsHubGroup.Accounts),
            SettingsCategoryMeta("integrations", categoryTitle(strings.integrations), "Last.fm · ListenBrainz · AudD", Icons.Rounded.Link, LevyraCyan, SettingsHubGroup.Accounts),
            SettingsCategoryMeta("system", categoryTitle(strings.preferences), "${strings.batteryUnrestricted} · ${strings.language}", Icons.Rounded.Settings, LevyraOrange, SettingsHubGroup.System),
            SettingsCategoryMeta("network", categoryTitle(strings.networkTitle), strings.networkSubtitle, Icons.Rounded.Public, LevyraOrange, SettingsHubGroup.System),
            SettingsCategoryMeta("app", categoryTitle(strings.app), "${strings.updates} · ${BuildConfig.VERSION_NAME}", Icons.Rounded.Info, LevyraOrange, SettingsHubGroup.System)
        )
    }
    val settingsSearchIndex = remember(strings.code) {
        SettingsSearchIndex(
            entries = settingsSearchEntries(
                strings = strings,
                locale = categoryLocale,
                updatesAvailable = BuildConfig.UPSTREAM_UPDATES_ENABLED,
                aaudioOutputAvailable = NativeAudioIntegration.isAaudioOutputSupported()
            ),
            locale = categoryLocale
        )
    }
    val settingsSearchResults = remember(settingsQuery, settingsSearchIndex) {
        settingsSearchIndex.search(settingsQuery)
    }
    Box(
        modifier = Modifier
        .fillMaxSize()
        .background(if (SkinChrome.active) SolidColor(LevyraBlack) else Brush.verticalGradient(listOf(LevyraInk, LevyraBlack)))
        .windowInsetsPadding(LevyraHorizontalSafeInsets)
    ) {
        AnimatedContent(
            targetState = activeCategory,
            label = "settingsNav",
            transitionSpec = {
                if (animationsEnabled) {
                    fadeIn() togetherWith fadeOut()
                } else {
                    EnterTransition.None togetherWith ExitTransition.None
                }
            }
        ) { current ->
            val meta = categories.firstOrNull { it.id == current }
            val settingsListState = remember(current) { LazyListState() }
            val bottomContentInset = animatedBottomContentInset(
                collapsed = LevyraBottomContentGap,
                expanded = LevyraMiniPlayerHeight + LevyraBottomContentGap,
                miniPlayerVisible = miniPlayerVisible,
                animationsEnabled = animationsEnabled
            )
            CompositionLocalProvider(LocalSettingsAccent provides meta?.accent) {
            LazyColumn(
                state = settingsListState,
                modifier = Modifier
                .fillMaxSize()
                .statusBarsPadding()
                .navigationBarsPadding(),
                contentPadding = PaddingValues(start = 18.dp, end = 18.dp, top = 18.dp, bottom = maxOf(40.dp, bottomContentInset)),
                verticalArrangement = Arrangement.spacedBy(if (current == null) 0.dp else SettingsGroupGap)
            ) {
                if (current == null) {
                    item {
                        SettingsHubHeader(onClose)
                        Spacer(modifier = Modifier.height(14.dp))
                    }
                    item {
                        BasicTextField(
                            value = settingsQuery,
                            onValueChange = { settingsQuery = it },
                            singleLine = true,
                            textStyle = TextStyle(color = LevyraText, fontSize = 15.sp, fontWeight = FontWeight.SemiBold),
                            cursorBrush = SolidColor(LevyraCyan),
                            modifier = Modifier
                                .fillMaxWidth()
                                .semantics { contentDescription = strings.settingsSearchPlaceholder }
                                .padding(bottom = 16.dp)
                                .background(LevyraAdaptiveCard, if (SkinChrome.active) SkinChrome.fieldShape else CircleShape)
                                .padding(horizontal = 18.dp, vertical = 16.dp),
                            decorationBox = { innerTextField ->
                                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                                    Icon(Icons.Rounded.Search, null, tint = LevyraCyan, modifier = Modifier.size(20.dp))
                                    Box(modifier = Modifier.weight(1f)) {
                                        if (settingsQuery.isBlank()) Text(strings.settingsSearchPlaceholder, color = LevyraMuted, fontSize = 15.sp)
                                        innerTextField()
                                    }
                                    if (settingsQuery.isNotBlank()) {
                                        IconButton(onClick = { settingsQuery = "" }, modifier = Modifier.size(48.dp)) {
                                            Icon(Icons.Rounded.Close, strings.clear, tint = LevyraMuted)
                                        }
                                    }
                                }
                            }
                        )
                        Spacer(modifier = Modifier.height(10.dp))
                    }
                    if (settingsQuery.isNotBlank()) {
                        if (settingsSearchResults.isEmpty()) {
                            item(key = "settings_search_empty") {
                                Text(
                                    strings.settingsSearchEmpty,
                                    color = LevyraMuted,
                                    fontSize = 14.sp,
                                    fontWeight = FontWeight.SemiBold,
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(vertical = 24.dp),
                                    textAlign = TextAlign.Center
                                )
                            }
                        }
                        items(settingsSearchResults, key = SettingsSearchResult::id) { result ->
                            SettingsSearchResultRow(result.title, result.description, result.categoryLabel) {
                                if (result.categoryId == SETTINGS_CATEGORY_AUDIO) {
                                    onOpenAudioSettings()
                                } else if (result.categoryId == "youtube_music") {
                                    onOpenYoutubeMusic()
                                } else {
                                    activeCategory = result.categoryId
