                                SettingsButton(
                                    icon = Icons.Rounded.AutoAwesome,
                                    title = strings.lyricsStudio,
                                    subtitle = strings.lyricsStudioSubtitle,
                                    onClick = onOpenLyricsStudio
                                )
                            }
                            item {
                                SettingsButton(
                                    icon = Icons.Rounded.Home,
                                    title = strings.homeStudioCopy.title,
                                    subtitle = skinHomeStyleLabel(homeStudioStyle) + " · " + strings.homeStudioCopy.subtitle,
                                    onClick = onOpenHomeStudio
                                )
                            }
                            item {
                                SettingsButton(
                                    icon = Icons.Rounded.SmartDisplay,
                                    title = strings.miniPlayerStudioCopy[MiniStudioText.Title],
                                    subtitle = miniPlayerStyleName(miniPlayerStyle) + " · " + strings.miniPlayerStudioCopy[MiniStudioText.Subtitle],
                                    enabled = interfaceSettings.skin == LevyraSkin.Default,
                                    onClick = onOpenMiniPlayerStudio
                                )
                            }
                            item {
                                SettingsButton(
                                    icon = Icons.Rounded.Dashboard,
                                    title = strings.navigationStudioCopy[NavStudioText.Title],
                                    subtitle = navigationStyleName(navigationStyle) + " · " + strings.navigationStudioCopy[NavStudioText.Subtitle],
                                    enabled = interfaceSettings.skin == LevyraSkin.Default,
                                    onClick = onOpenNavigationStudio
                                )
                            }
                            if (interfaceSettings.skin.supportsDockMorph && interfaceSettings.skin != LevyraSkin.Default) {
                                item { DockScrollEffectSkinRow(interfaceSettings, onInterfaceSettings) }
                            }
                            item {
                                val widgetStudioContext = LocalContext.current
                                SettingsButton(
                                    icon = Icons.Rounded.Widgets,
                                    title = strings.widgetStudioCopy[WidgetStudioText.Title],
                                    subtitle = strings.widgetStudioCopy[WidgetStudioText.Subtitle],
                                    onClick = { widgetStudioContext.startActivity(WidgetStudioActivity.intent(widgetStudioContext)) }
                                )
                            }
                            skinSettingsItems(interfaceSettings.skin, defaults = {
                            item {
                                SettingsChoiceRow(
                                    icon = Icons.Rounded.TextFields,
                                    title = strings.appFont,
                                    subtitle = strings.appFontSubtitle,
                                    options = LevyraFontPreset.entries.map { preset -> preset.name to preset.displayName },
                                    selected = interfaceSettings.fontPreset.name,
                                    onSelect = { value ->
                                        onInterfaceSettings(
                                            interfaceSettings.copy(fontPreset = LevyraFontPreset.from(value))
                                        )
                                    }
                                )
                            }
                            })
                            item {
                                SettingsToggle(
                                    icon = Icons.Rounded.Bolt,
                                    title = strings.animations,
                                    subtitle = strings.animationsSubtitle,
                                    checked = animationsEnabled,
                                    onCheckedChange = onAnimations
                                )
