                                    SettingsChoiceRow(
                                        icon = Icons.Rounded.Schedule,
                                        title = strings.backupFrequency,
                                        subtitle = strings.automaticBackupSubtitle,
                                        options = LevyraBackupFrequency.entries.map { frequency ->
                                            frequency.name to strings.backupFrequencyLabel(frequency.name)
                                        },
                                        selected = backupSettings.frequency.name,
                                        onSelect = { selected ->
                                            onBackupSettings(
                                                backupSettings.copy(frequency = LevyraBackupFrequency.from(selected))
                                            )
                                        }
                                    )
                                }
                                item {
                                    SettingsChoiceRow(
                                        icon = Icons.Rounded.History,
                                        title = strings.backupRetention,
                                        subtitle = strings.automaticBackupSubtitle,
                                        options = listOf(3, 5, 10).map { count ->
                                            count.toString() to strings.backupRetentionLabel(count)
                                        },
                                        selected = backupSettings.retentionCount.toString(),
                                        onSelect = { selected ->
                                            selected.toIntOrNull()?.let { count ->
                                                onBackupSettings(backupSettings.copy(retentionCount = count))
                                            }
                                        }
                                    )
                                }
                                item {
                                    SettingsToggle(
                                        icon = Icons.Rounded.Bolt,
                                        title = strings.backupChargingOnly,
                                        subtitle = strings.backupChargingOnlySubtitle,
                                        checked = backupSettings.chargingOnly,
                                        onCheckedChange = { onBackupSettings(backupSettings.copy(chargingOnly = it)) }
                                    )
                                }
                                item {
                                    SettingsButton(
                                        icon = Icons.Rounded.Source,
                                        title = strings.backupLocation,
                                        subtitle = if (backupLocationUri != null) strings.backupLocationSafSelected else strings.backupLocationSubtitle,
                                        onClick = onSelectBackupLocation
                                    )
                                }
                                if (backupLocationUri != null) {
                                    item {
                                        SettingsButton(
                                            icon = Icons.Rounded.History,
                                            title = strings.backupLocationInternal,
                                            subtitle = strings.backupLocationInternalSubtitle,
                                            onClick = onClearBackupLocation
                                        )
                                    }
                                }
                            }
                            item {
                                SettingsToggle(
                                    icon = Icons.Rounded.Refresh,
                                    title = strings.backupBeforeUpdates,
                                    subtitle = strings.backupBeforeUpdatesSubtitle,
                                    checked = backupSettings.preUpdate,
                                    onCheckedChange = { onBackupSettings(backupSettings.copy(preUpdate = it)) }
                                )
                            }
                            item {
                                SettingsButton(
                                    icon = Icons.Rounded.Download,
                                    title = if (vaultStatus == LevyraVaultStatus.Running) strings.vaultBusy else strings.backupNow,
                                    subtitle = strings.backupNowSubtitle,
                                    onClick = onBackupNow,
                                    enabled = vaultStatus != LevyraVaultStatus.Running
                                )
                            }
                            item {
                                SettingsButton(
                                    icon = Icons.Rounded.Download,
                                    title = strings.createDataBackup,
                                    subtitle = strings.createDataBackupSubtitle,
                                    onClick = onCreateBackup
                                )
                            }
                            item {
                                SettingsButton(
                                    icon = Icons.Rounded.History,
                                    title = strings.restoreBackup,
                                    subtitle = strings.restoreBackupSubtitle,
                                    onClick = onRestoreBackup
                                )
                            }
                            item {
                                SettingsButton(
                                    icon = Icons.Rounded.Source,
                                    title = strings.manageBackups,
                                    subtitle = strings.manageBackupsSubtitle,
                                    onClick = onManageBackups
                                )
                            }
                        }
                        "system" -> {
                            standaloneItem { SettingsSectionLabel(strings.playbackResilienceSection) }
                            item {
                                SettingsButton(
                                    icon = Icons.Rounded.Bolt,
                                    title = strings.batteryUnrestricted,
                                    subtitle = if (batteryUnrestricted) strings.batteryUnrestrictedActive else strings.batteryUnrestrictedSubtitle,
                                    onClick = {
                                        if (!batteryUnrestricted) {
                                            val request = Intent(android.provider.Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS)
                                            .setData(Uri.parse("package:${batteryContext.packageName}"))
                                            runCatching { batteryContext.startActivity(request) }.onFailure {
                                                runCatching {
                                                    batteryContext.startActivity(
                                                        Intent(android.provider.Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS)
                                                    )
                                                }
                                            }
                                        }
                                    }
                                )
                            }
                            item {
                                SettingsButton(
                                    icon = Icons.Rounded.Bolt,
                                    title = strings.playbackDiagnostics,
                                    subtitle = strings.playbackDiagnosticsSubtitle,
                                    onClick = onOpenPlaybackDiagnostics
                                )
                            }
                            item {
                                SettingsButton(
                                    icon = Icons.Rounded.Share,
                                    title = strings.exportSafeDiagnostics,
                                    subtitle = if (playbackDiagnostics.isBlank()) strings.generateResolverTrace else strings.safeDiagnosticsSubtitle,
                                    onClick = onShareDiagnostics
                                )
                            }
                            standaloneItem { SettingsSectionLabel(strings.preferences) }
                            item {
                                SettingsButton(
                                    icon = Icons.Rounded.Settings,
                                    title = strings.redoQuestionnaire,
                                    subtitle = strings.redoQuestionnaireSubtitle,
                                    onClick = onRedoQuestionnaire
                                )
                            }
                            item {
                                SettingsButton(
                                    icon = Icons.Rounded.Person,
                                    title = strings.profilePhoto,
                                    subtitle = if (profilePhotoSet) {
                                        strings.profilePhotoChangeSubtitle
                                    } else {
                                        strings.profilePhotoAddSubtitle
                                    },
                                    onClick = onPickProfilePhoto
                                )
                            }
                            if (profilePhotoSet) {
                                item {
                                    SettingsButton(
                                        icon = Icons.Rounded.Delete,
                                        title = strings.profilePhotoRemove,
                                        subtitle = strings.profilePhoto,
                                        onClick = onRemoveProfilePhoto
                                    )
                                }
                            }
                            standaloneItem {
                                val musicRegionCopy = com.luc4n3x.levyra.ui.i18n.musicRegionCopy(strings.code)
                                var musicRegionSheetOpen by rememberSaveable { mutableStateOf(false) }
                                com.luc4n3x.levyra.ui.regional.RegionalPreferencesCard(
                                    languageCode = strings.code,
                                    appLanguageValue = LevyraLanguageCatalog.displayName(currentLanguageCode),
                                    contentCountryValue = ChartsCatalog.supportedRegion(musicRegionId)
                                        ?.let { region -> "${region.emoji} ${ChartMarketDirectory.displayName(region, currentLanguageCode)}" }
                                        ?: musicRegionCopy.automatic,
                                    preferredAudioLanguage = preferredAudioLanguage,
                                    selectedAppLanguage = currentLanguageCode,
                                    onAppLanguage = onLanguage,
                                    onContentCountryClick = { musicRegionSheetOpen = true },
                                    onPreferredAudioLanguage = onPreferredAudioLanguage
                                )
                                if (musicRegionSheetOpen) {
                                    ChartMarketSheet(
                                        regions = ChartsCatalog.regions,
                                        selectedId = musicRegionId,
                                        languageCode = currentLanguageCode,
                                        onSelect = onMusicRegion,
                                        onDismiss = { musicRegionSheetOpen = false },
                                        title = com.luc4n3x.levyra.ui.i18n.LevyraRegionalStrings.forCode(strings.code).contentCountryTitle,
                                        automaticLabel = musicRegionCopy.automatic
                                    )
                                }
                            }
                        }
                        "app" -> {
                            if (BuildConfig.UPSTREAM_UPDATES_ENABLED) {
                                item {
                                    SettingsUpdateCard(
                                        updateInfo = updateInfo,
                                        isChecking = isCheckingUpdates,
                                        onCheck = onCheckUpdates,
                                        onDownload = onDownloadUpdate
                                    )
                                }
                            }
                            standaloneItem { SettingsHubFooter(onExitApplication) }
                        }
                    } }
                }
            }
            }
        }
    }
}

@Composable
private fun SettingsSearchResultRow(title: String, description: String, category: String, onClick: () -> Unit) {
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .heightIn(min = 48.dp)
            .clickable(onClick = onClick),
        color = LevyraAdaptiveCard,
        shape = RoundedCornerShape(if (SkinChrome.active) SkinChrome.outerCorner else 16.dp)
    ) {
        Column(modifier = Modifier.padding(horizontal = 16.dp, vertical = 14.dp), verticalArrangement = Arrangement.spacedBy(3.dp)) {
            Text(title, color = LevyraText, fontSize = 15.sp, fontWeight = if (SkinChrome.active) FontWeight.Medium else FontWeight.Black)
            if (description.isNotBlank()) {
                Text(
                    description,
                    color = LevyraMuted,
                    fontSize = 12.sp,
                    maxLines = 2,
                    overflow = TextOverflow.Ellipsis
                )
            }
            Text(category, color = LevyraMuted, fontSize = 12.sp, fontWeight = FontWeight.SemiBold)
        }
    }
}

@Composable
private fun IntegrationSettingsPanel(
    lastFmConfigured: Boolean, lastFmAuthorizationPending: Boolean,
    listenBrainzConfigured: Boolean, audDConfigured: Boolean,
    onBeginLastFm: (String, String) -> Unit, onCompleteLastFm: () -> Unit, onClearLastFm: () -> Unit,
    onSaveListenBrainz: (String) -> Unit, onClearListenBrainz: () -> Unit,
    onSaveAudD: (String) -> Unit, onClearAudD: () -> Unit
) {
    val strings = LocalLevyraStrings.current
    var lastFmKey by remember { mutableStateOf("") }
    var lastFmSecret by remember { mutableStateOf("") }
    var listenBrainzToken by remember { mutableStateOf("") }
    var audDToken by remember { mutableStateOf("") }
    Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
        Text("Last.fm", color = LevyraText, fontWeight = FontWeight.Black, fontSize = 17.sp)
        OutlinedTextField(
            lastFmKey,
            { lastFmKey = it },
            label = { Text(strings.apiKeyLabel) },
            visualTransformation = PasswordVisualTransformation(),
            colors = OutlinedTextFieldDefaults.colors(
                focusedTextColor = LevyraText,
                unfocusedTextColor = LevyraText,
                focusedBorderColor = LevyraCyan,
                unfocusedBorderColor = LevyraMuted.copy(alpha = 0.4f),
                cursorColor = LevyraCyan
            ),
            modifier = Modifier.fillMaxWidth()
        )
        OutlinedTextField(
            lastFmSecret,
            { lastFmSecret = it },
            label = { Text(strings.sharedSecretLabel) },
            visualTransformation = PasswordVisualTransformation(),
            colors = OutlinedTextFieldDefaults.colors(
                focusedTextColor = LevyraText,
                unfocusedTextColor = LevyraText,
                focusedBorderColor = LevyraCyan,
                unfocusedBorderColor = LevyraMuted.copy(alpha = 0.4f),
                cursorColor = LevyraCyan
            ),
            modifier = Modifier.fillMaxWidth()
        )
        SettingsButton(Icons.Rounded.Settings, if (lastFmConfigured) strings.delete else strings.save, "Last.fm") {
            if (lastFmConfigured) {
                onClearLastFm()
            } else if (lastFmKey.isNotBlank() && lastFmSecret.isNotBlank()) {
                onBeginLastFm(lastFmKey, lastFmSecret)
                lastFmKey = ""
                lastFmSecret = ""
            }
        }
        if (lastFmAuthorizationPending) {
            Text(strings.lastFmApprovalHint, color = LevyraMuted, fontSize = 13.sp)
            SettingsButton(Icons.Rounded.Check, strings.complete, "Last.fm") { onCompleteLastFm() }
        }
        Text("ListenBrainz", color = LevyraText, fontWeight = FontWeight.Black, fontSize = 17.sp)
        OutlinedTextField(
            listenBrainzToken,
            { listenBrainzToken = it },
            label = { Text(strings.credentialTokenLabel) },
            visualTransformation = PasswordVisualTransformation(),
            colors = OutlinedTextFieldDefaults.colors(
                focusedTextColor = LevyraText,
                unfocusedTextColor = LevyraText,
                focusedBorderColor = LevyraCyan,
                unfocusedBorderColor = LevyraMuted.copy(alpha = 0.4f),
                cursorColor = LevyraCyan
            ),
            modifier = Modifier.fillMaxWidth()
        )
        SettingsButton(Icons.Rounded.Settings, if (listenBrainzConfigured) strings.delete else strings.save, "ListenBrainz") {
            if (listenBrainzConfigured) {
                onClearListenBrainz()
            } else if (listenBrainzToken.isNotBlank()) {
                onSaveListenBrainz(listenBrainzToken)
                listenBrainzToken = ""
            }
        }
        Text("AudD", color = LevyraText, fontWeight = FontWeight.Black, fontSize = 17.sp)
        OutlinedTextField(
            audDToken,
            { audDToken = it },
            label = { Text(strings.credentialTokenLabel) },
            visualTransformation = PasswordVisualTransformation(),
            colors = OutlinedTextFieldDefaults.colors(
                focusedTextColor = LevyraText,
                unfocusedTextColor = LevyraText,
                focusedBorderColor = LevyraCyan,
                unfocusedBorderColor = LevyraMuted.copy(alpha = 0.4f),
                cursorColor = LevyraCyan
            ),
            modifier = Modifier.fillMaxWidth()
        )
        SettingsButton(Icons.Rounded.Settings, if (audDConfigured) strings.delete else strings.save, "AudD") {
            if (audDConfigured) {
                onClearAudD()
            } else if (audDToken.isNotBlank()) {
                onSaveAudD(audDToken)
                audDToken = ""
            }
        }
    }
}

@Composable
private fun SettingsHubFooter(onExitApplication: () -> Unit) {
    val strings = LocalLevyraStrings.current
    val context = LocalContext.current
    val footerVersion = BuildConfig.VERSION_NAME.removeSuffix("-pr-diagnostics")
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(top = 24.dp, bottom = 12.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        TextButton(onClick = onExitApplication) {
            Text(com.luc4n3x.levyra.ui.i18n.settingsFooterExitApplication(strings.code))
        }
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(Dp.Hairline)
                .background(LevyraAdaptiveHairline)
        )
        Spacer(modifier = Modifier.height(18.dp))
        Text(
            "LEVYRA $footerVersion",
            color = LevyraMuted.copy(alpha = 0.86f),
            fontSize = 11.sp,
            fontWeight = FontWeight.Black,
            letterSpacing = 2.sp
        )
        Spacer(modifier = Modifier.height(13.dp))
        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.Center
        ) {
            Text(
                "${strings.madeWithBy} ",
                color = LevyraMuted,
                fontSize = 13.sp,
                fontWeight = FontWeight.Medium
            )
            AsyncImage(
                model = "https://github.com/LUC4N3X.png",
                contentDescription = "LUC4N3X",
                modifier = Modifier
                    .size(24.dp)
                    .clip(CircleShape)
                    .border(1.dp, LevyraCyan.copy(alpha = 0.32f), CircleShape)
            )
            Spacer(modifier = Modifier.width(8.dp))
            Text(
                "LUC4N3X",
                color = LevyraText,
                fontSize = 14.sp,
                fontWeight = FontWeight.Black,
                letterSpacing = 0.3.sp
            )
        }
        Spacer(modifier = Modifier.height(12.dp))
        SupportLevyraSettingsLink(
            languageCode = strings.code,
            modifier = Modifier.fillMaxWidth()
        )
        Row(
            modifier = Modifier
                .heightIn(min = 48.dp)
                .clickable {
                    runCatching {
                        context.startActivity(
                            Intent(
                                Intent.ACTION_VIEW,
                                Uri.parse("https://github.com/LUC4N3X/Levyra-deepsound/blob/main/docs/legal/LEGAL.md")
                            )
                        )
                    }
                }
                .padding(horizontal = 12.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.Center
        ) {
            Icon(
                imageVector = Icons.Rounded.Info,
                contentDescription = null,
                tint = LevyraMuted.copy(alpha = 0.68f),
                modifier = Modifier.size(15.dp)
            )
            Spacer(modifier = Modifier.width(6.dp))
            Text(
                text = strings.legalInformation,
                color = LevyraMuted.copy(alpha = 0.72f),
                fontSize = 11.sp,
                fontWeight = FontWeight.Medium,
                textAlign = TextAlign.Center
            )
        }
    }
}

private data class SettingsCategoryMeta(
    val id: String,
    val title: String,
    val summary: String,
    val icon: ImageVector,
    val accent: Color,
    val group: SettingsHubGroup
)

private enum class SettingsHubGroup { Appearance, Listening, Library, Accounts, System }

private fun settingsHubGroupTitle(group: SettingsHubGroup, strings: LevyraStrings): String = strings.settingsHubCopy[
    when (group) {
        SettingsHubGroup.Appearance -> SettingsHubText.Appearance
        SettingsHubGroup.Listening -> SettingsHubText.Listening
        SettingsHubGroup.Library -> SettingsHubText.Library
        SettingsHubGroup.Accounts -> SettingsHubText.Accounts
        SettingsHubGroup.System -> SettingsHubText.System
    }
]

private class SettingsStudioEntry(
    val id: String,
    val title: String,
    val icon: ImageVector,
    val accent: Color,
    val shape: RoundedPolygon,
    val onClick: () -> Unit
)

@Composable
private fun SettingsHubGroupLabel(text: String) {
    if (LevyraIsQobuz) return QobuzSettingsGroupLabel(text)
    if (LevyraIsAtelier) return AtelierSettingsGroupLabel(text)
    val locale = LocalConfiguration.current.locales[0]
    Text(
        SkinChrome.label(text, locale),
        color = if (SkinChrome.labelsUppercase) LevyraCyan else LevyraMuted,
        fontSize = if (SkinChrome.labelsUppercase) 12.sp else 13.sp,
        fontWeight = if (SkinChrome.active) FontWeight.Medium else FontWeight.Bold,
        letterSpacing = if (SkinChrome.labelsUppercase) 1.6.sp else 0.4.sp,
        modifier = Modifier
            .padding(start = 8.dp, top = 22.dp, bottom = 10.dp)
            .semantics { heading() }
    )
}

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
private fun SettingsStudioShelf(title: String, subtitle: String, entries: List<SettingsStudioEntry>) {
    Column(modifier = Modifier.fillMaxWidth().padding(top = 6.dp)) {
        Text(
            title,
            color = LevyraText,
            fontSize = 20.sp,
            fontWeight = if (SkinChrome.active) FontWeight.Medium else FontWeight.Black,
            modifier = Modifier
                .padding(start = 4.dp)
                .semantics { heading() }
        )
        Text(
            subtitle,
            color = LevyraMuted,
            fontSize = 13.sp,
            fontWeight = FontWeight.Medium,
            modifier = Modifier.padding(start = 4.dp, top = 2.dp, bottom = 12.dp)
        )
        LazyRow(
            modifier = Modifier.recentSearchesBleed(SettingsStudioGutter),
            horizontalArrangement = Arrangement.spacedBy(10.dp),
            contentPadding = PaddingValues(horizontal = SettingsStudioGutter)
        ) {
            items(entries, key = { it.id }) { entry ->
                Surface(
                    onClick = entry.onClick,
                    shape = RoundedCornerShape(if (SkinChrome.active) SkinChrome.outerCorner else 22.dp),
                    color = if (SkinChrome.active) LevyraAdaptiveCard else entry.accent.copy(alpha = 0.12f),
                    modifier = Modifier.width(180.dp).heightIn(min = 80.dp)
                ) {
                    Row(
                        modifier = Modifier.padding(horizontal = 12.dp, vertical = 12.dp),
                        horizontalArrangement = Arrangement.spacedBy(12.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Box(
                            modifier = Modifier
                                .size(42.dp)
                                .clip(if (SkinChrome.active) SkinChrome.iconShape else entry.shape.toShape())
                                .background(if (SkinChrome.active) SkinChrome.iconBackground else entry.accent),
                            contentAlignment = Alignment.Center
                        ) {
                            Icon(entry.icon, null, tint = if (SkinChrome.active) SkinChrome.iconTint else LevyraBlack, modifier = Modifier.size(22.dp))
                        }
                        Text(
                            text = entry.title,
                            color = LevyraText,
                            fontSize = 14.sp,
                            lineHeight = 18.sp,
                            fontWeight = FontWeight.Bold,
                            softWrap = true,
                            modifier = Modifier.weight(1f)
                        )
                    }
                }
            }
        }
    }
}

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
private fun SettingsCategoryCard(meta: SettingsCategoryMeta, index: Int, count: Int, onClick: () -> Unit) {
    if (LevyraIsQobuz) return QobuzSettingsRow(meta.title, meta.icon, index == count - 1, onClick)
    if (LevyraIsAtelier) return AtelierSettingsRow(meta.title, meta.summary, meta.icon, index == count - 1, onClick)
    SettingsTile(
        onClick = onClick,
        groupIndex = index,
        groupCount = count,
        modifier = Modifier.padding(bottom = if (index < count - 1) 2.dp else 0.dp)
    ) {
        Row(
            modifier = Modifier.padding(start = 14.dp, end = 12.dp, top = 14.dp, bottom = 14.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(14.dp)
        ) {
            SettingsTileIcon(icon = meta.icon, accent = meta.accent, shape = MaterialShapes.Cookie4Sided.toShape())
            SettingsTileText(
                title = meta.title,
                subtitle = meta.summary,
                modifier = Modifier.weight(1f),
                maxTitleLines = Int.MAX_VALUE,
                maxSubtitleLines = Int.MAX_VALUE
            )
            Icon(
                Icons.AutoMirrored.Rounded.KeyboardArrowRight,
                null,
                tint = LevyraMuted.copy(alpha = 0.7f),
                modifier = Modifier.size(22.dp)
            )
        }
    }
}

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
internal fun SettingsTile(
    modifier: Modifier = Modifier,
    onClick: (() -> Unit)? = null,
    checked: Boolean? = null,
    onCheckedChange: ((Boolean) -> Unit)? = null,
    enabled: Boolean = true,
    groupIndex: Int? = null,
    groupCount: Int? = null,
    color: Color = if (LevyraIsSpotify || LevyraIsYouTubeMusic) Color.Transparent else if (LevyraIsAppleMusic) AppleMusicDesign.groupedBackground else LevyraAdaptiveCard,
    content: @Composable () -> Unit
) {
    val interactionSource = remember { MutableInteractionSource() }
    val slot = LocalSettingsGroupSlot.current
    val index = groupIndex ?: slot?.index ?: 0
    val count = groupCount ?: slot?.count ?: 1
    val first = index == 0
    val last = index == count - 1
    val shape = settingsTileShape(interactionSource, first, last)
    val tileModifier = modifier.fillMaxWidth().then(if (SkinChrome.active) Modifier.padding(vertical = 1.dp) else Modifier)
    when {
        checked != null && onCheckedChange != null -> Surface(
            checked = checked,
            onCheckedChange = onCheckedChange,
            enabled = enabled,
            shape = shape,
            color = color,
            interactionSource = interactionSource,
            modifier = tileModifier,
            content = content
        )
        onClick != null -> Surface(
            onClick = onClick,
            enabled = enabled,
            shape = shape,
            color = color,
            interactionSource = interactionSource,
            modifier = tileModifier,
            content = content
        )
        else -> Surface(shape = shape, color = color, modifier = tileModifier, content = content)
    }
}

