@Composable
private fun SearchSectionFooter(
    loading: Boolean,
    failed: Boolean,
    canLoadMore: Boolean,
    autoLoadKey: Int,
    onLoadMore: () -> Unit
) {
    val strings = LocalLevyraStrings.current
    val currentOnLoadMore by rememberUpdatedState(onLoadMore)
    val autoLoads by rememberUpdatedState(canLoadMore && !loading && !failed)
    LaunchedEffect(autoLoadKey) {
        if (autoLoads) currentOnLoadMore()
    }
    when {
        loading -> Box(
            modifier = Modifier.fillMaxWidth().padding(vertical = 16.dp),
            contentAlignment = Alignment.Center
        ) {
            CircularProgressIndicator(modifier = Modifier.size(22.dp), strokeWidth = 2.dp, color = LevyraCyan)
        }
        failed -> GlassMessage(strings.searchFailed, LevyraOrange)
        canLoadMore -> Box(
            modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
            contentAlignment = Alignment.Center
        ) {
            TextButton(onClick = onLoadMore) {
                Text(strings.more, color = LevyraCyan, fontSize = 13.sp, fontWeight = FontWeight.Bold)
            }
        }
    }
}

private fun SearchResults.sectionSize(filter: SearchFilter): Int = when (filter) {
    SearchFilter.Songs -> songs.size
    SearchFilter.Videos -> videos.size
    SearchFilter.Albums -> albums.size
    SearchFilter.Artists -> artists.size
    SearchFilter.Playlists -> playlists.size
    SearchFilter.All -> 0
}

