}

@Composable
internal fun CircleIconButton(
    icon: ImageVector,
    tint: Color,
    background: Color,
    onClick: () -> Unit,
    contentDescription: String? = null
) {
    val resolvedBackground = if (LevyraIsLight && background.alpha < 0.2f) LevyraAdaptiveChip else background
    val resolvedBorder = if (LevyraIsLight && background.alpha < 0.2f) LevyraAdaptiveHairline else Color.Transparent
    Box(
        modifier = Modifier
            .size(46.dp)
            .background(resolvedBackground, CircleShape)
            .border(Dp.Hairline, resolvedBorder, CircleShape)
            .pressable(onClick = onClick),
        contentAlignment = Alignment.Center
    ) {
        Icon(icon, contentDescription, tint = tint, modifier = Modifier.size(21.dp))
    }
}

@Suppress("ComplexMethod", "CognitiveComplexMethod")
@Composable
private fun ExploreScreen(
    viewModel: ExploreViewModel,
    state: LevyraUiState,
    liveRadioOpen: Boolean,
    backEnabled: Boolean,
    onLiveRadioOpenChange: (Boolean) -> Unit,
    onOpenJam: () -> Unit
) {
    val strings = LocalLevyraStrings.current
    LaunchedEffect(strings.code) { viewModel.ensureExplore(strings) }
    val context = LocalContext.current
    val listState = rememberLazyListState()
    var addToPlaylistTarget by remember { mutableStateOf<Track?>(null) }
    var samplesStartIndex by rememberSaveable { mutableStateOf<Int?>(null) }
    var exploreDestination by rememberSaveable { mutableStateOf<String?>(null) }
    var exploreMoodReturn by rememberSaveable { mutableStateOf<String?>(null) }
    LaunchedEffect(state.exploreOpenRequest) {
        val requestedZoneId = state.exploreOpenRequest ?: return@LaunchedEffect
        exploreMoodReturn = null
        val samplesIndex = exploreSamplesRequestIndex(requestedZoneId)
        if (samplesIndex != null) {
            exploreDestination = null
            samplesStartIndex = samplesIndex
            viewModel.beginSamplesPlayback()
        } else {
            exploreDestination = exploreMoodDestination(requestedZoneId)
        }
        viewModel.consumeExploreOpenRequest()
    }

    val zones = remember(strings) { ExploreCatalog.getZones(strings) }
    val selectedZone = remember(zones, state.exploreZoneId) {
        zones.firstOrNull { zone -> zone.id == state.exploreZoneId }
    }
    val localFreshTracks = state.exploreFreshTracks
    val worldFreshTracks = state.exploreWorldFreshTracks
    var freshScope by rememberSaveable { mutableStateOf(ExploreFreshScope.Local) }
    val freshScopes = remember(localFreshTracks, worldFreshTracks) {
        exploreFreshScopes(localFreshTracks, worldFreshTracks)
    }
    val freshFeed = remember(freshScope, localFreshTracks, worldFreshTracks) {
        exploreFreshFeed(freshScope, localFreshTracks, worldFreshTracks)
    }
    val freshTracks = remember(freshFeed) { freshFeed.spotlight + freshFeed.moment }
    val momentPages = remember(freshFeed) { exploreMomentPages(freshFeed.moment) }
    val freshRegionLabel = remember(state.languageCode, com.luc4n3x.levyra.domain.LevyraMusicRegion.selectedId) {
        ChartsCatalog.defaultRegionForLanguage(state.languageCode).label
    }
    val samples = remember(state.exploreSamples) {
        exploreSampleTracks(state.exploreSamples, ExploreImmersiveSampleLimit)
    }
    val freshSection = remember(freshScopes, freshFeed, momentPages, freshRegionLabel) {
        ExploreFreshSection(freshScopes, freshFeed, momentPages, freshRegionLabel)
    }
    val spotifyExplore = LevyraIsSpotify
    val moodsInSearch = spotifyExplore || LevyraIsAppleMusic
    val rows = remember(
        zones,
        spotifyExplore,
        moodsInSearch,
        state.isFreshCurrentsLoading,
        freshFeed.spotlight.isNotEmpty(),
        freshScopes.size > 1,
        momentPages.isNotEmpty()
    ) {
        buildExploreRows(
            zones = zones,
            isFreshLoading = state.isFreshCurrentsLoading,
            hasFreshTracks = freshFeed.spotlight.isNotEmpty(),
            hasFreshScopes = freshScopes.size > 1,
            hasFreshMoment = momentPages.isNotEmpty(),
            spotifyStyle = spotifyExplore,
            moodsInSearch = moodsInSearch
        )
    }
    val availableAnchors = remember(rows) { exploreAvailableAnchors(rows) }

    val onShortcut: (ExploreShortcut) -> Unit = { shortcut ->
        when (shortcut) {
            ExploreShortcut.Samples -> {
                exploreDestination = null
                samplesStartIndex = 0
                viewModel.beginSamplesPlayback()
                if (samples.isEmpty()) viewModel.ensureSamples()
            }
            ExploreShortcut.NewReleases -> {
                samplesStartIndex = null
                exploreDestination = ExploreNewReleasesDestination
            }
            ExploreShortcut.Moods -> {
                samplesStartIndex = null
                exploreDestination = ExploreMoodsDestination
            }
        }
    }
    val onPlayFresh: (() -> Unit)? = freshTracks.firstOrNull()?.let { first ->
        { viewModel.playFrom(freshTracks, first) }
    }

    val exploreMixAccent = rememberNowPlayingAccent(state.currentTrack, LevyraCyan)
    val shareFreshTrack: (Track) -> Unit = { track ->
        val shareText = buildString {
            append(track.title)
            if (track.artist.isNotBlank()) append(" - ").append(track.artist)
            val link = track.videoUrl.ifBlank { track.streamUrl }
            if (link.isNotBlank()) append("\n").append(link)
        }
        val intent = Intent(Intent.ACTION_SEND).apply {
            type = "text/plain"
            putExtra(Intent.EXTRA_SUBJECT, track.title)
            putExtra(Intent.EXTRA_TEXT, shareText)
        }
        context.startActivity(Intent.createChooser(intent, strings.shareVia))
    }
    val onPlayFreshTrack: (Track) -> Unit = { track ->
        if (track.id == state.currentTrack?.id) viewModel.togglePlay()
        else viewModel.playFrom(freshTracks, track)
    }
    val freshTrackActions: @Composable (Track) -> Unit = { track ->
        DiscoveryTrackActions(
            trackTitle = track.title,
            isFavorite = track.id in state.favoriteIds,
            onFavorite = { viewModel.toggleFavorite(track) },
            onAddToPlaylist = { addToPlaylistTarget = track },
            onShare = { shareFreshTrack(track) },
            onOpenAlbum = if (track.album.isNotBlank()) {
                { viewModel.openAlbum(trackAlbumHit(track)) }
            } else {
                null
            }
        )
    }
    val exploreBottomInset = tabBarBottomContentInset(
        miniPlayerVisible = state.currentTrack != null && !state.isSamplesOpen,
        animationsEnabled = state.animationsEnabled
    )
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Transparent)
    ) {
        if (LevyraIsAtelier) {
            AtelierExploreEntry(state, viewModel, freshTracks, listState, exploreBottomInset, onShortcut, { addToPlaylistTarget = it }) { category ->
                samplesStartIndex = null
                exploreMoodReturn = null
                exploreDestination = exploreCategoryDestination(category)
            }
        } else if (LevyraIsQobuz) {
            QobuzMagazineEntry(state, viewModel, freshTracks, listState, exploreBottomInset, onShortcut, { addToPlaylistTarget = it }) { category ->
                samplesStartIndex = null
                exploreMoodReturn = null
                exploreDestination = exploreCategoryDestination(category)
            }
        } else if (LevyraIsYouTubeMusic) {
            YouTubeMusicExploreScreen(
                viewModel, listState, state.currentTrack?.id, exploreBottomInset, availableAnchors, onShortcut, onOpenJam, onLiveRadioOpenChange,
                onOpenMood = { title, params ->
                    samplesStartIndex = null
                    exploreMoodReturn = null
                    exploreDestination = exploreCategoryDestination(ExploreCategory(title, params))
                }
            ) { addToPlaylistTarget = it }
        } else LazyColumn(
            state = listState,
            modifier = Modifier.fillMaxSize().statusBarsPadding(),
            contentPadding = PaddingValues(top = 14.dp, bottom = exploreBottomInset),
            verticalArrangement = Arrangement.spacedBy(14.dp)
        ) {
            items(
                items = rows,
                key = { row -> row.key },
                contentType = { row -> row::class }
            ) { row ->
                ExploreContentRow(
                    row = row,
                    state = state,
                    viewModel = viewModel,
                    fresh = freshSection,
                    availableAnchors = availableAnchors,
                    mixAccent = exploreMixAccent,
                    onShortcut = onShortcut,
                    onPlayFresh = onPlayFresh,
                    onSelectFreshScope = { scope -> freshScope = scope },
                    onOpenJam = onOpenJam,
                    onOpenRadio = { onLiveRadioOpenChange(true) },
                    onOpenMoods = {
                        samplesStartIndex = null
                        exploreMoodReturn = null
                        exploreDestination = ExploreMoodsDestination
                    },
                    onOpenZone = { zone ->
                        viewModel.selectExploreZone(zone)
                        exploreMoodReturn = null
                        exploreDestination = exploreMoodDestination(zone.id)
                    },
                    onPlayTrack = onPlayFreshTrack,
                    trackActions = freshTrackActions
                )
            }
        }

        ExploreOverlays(
            state = state,
            viewModel = viewModel,
            strings = strings,
            zones = zones,
            samples = samples,
            backEnabled = backEnabled,
            liveRadioOpen = liveRadioOpen,
            addToPlaylistTarget = addToPlaylistTarget,
            samplesStartIndex = samplesStartIndex,
            exploreDestination = exploreDestination,
            exploreMoodReturn = exploreMoodReturn,
            onAddToPlaylistTargetChange = { addToPlaylistTarget = it },
            onSamplesStartIndexChange = { samplesStartIndex = it },
            onDestinationChange = { exploreDestination = it },
            onMoodReturnChange = { exploreMoodReturn = it },
            onLiveRadioOpenChange = onLiveRadioOpenChange
        )
    }
}

@Immutable
private class ExploreFreshSection(
    val scopes: List<ExploreFreshScope>,
    val feed: ExploreFreshFeed,
    val momentPages: List<List<Track>>,
    val regionLabel: String
)

@Composable
private fun ExploreContentRow(
    row: ExploreRow,
    state: LevyraUiState,
    viewModel: ExploreViewModel,
    fresh: ExploreFreshSection,
    availableAnchors: Set<ExploreAnchor>,
    mixAccent: Color,
    onShortcut: (ExploreShortcut) -> Unit,
    onPlayFresh: (() -> Unit)?,
    onSelectFreshScope: (ExploreFreshScope) -> Unit,
    onOpenJam: () -> Unit,
    onOpenRadio: () -> Unit,
    onOpenMoods: () -> Unit,
    onOpenZone: (ExploreZone) -> Unit,
    onPlayTrack: (Track) -> Unit,
    trackActions: @Composable (Track) -> Unit
) {
    val strings = LocalLevyraStrings.current
    when (row) {
        ExploreRow.Samples -> SpotifyExploreSamples(state, viewModel)
        ExploreRow.Shortcuts -> Column(
            verticalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            ExplorePageHeader(
                title = strings.exploreTitle,
                subtitle = strings.exploreSubtitle,
                modifier = Modifier.padding(horizontal = HomeHorizontalInset)
            )
            ExplorePrimaryShortcuts(
                availableAnchors = availableAnchors,
                onSelect = onShortcut,
                onOpenJam = onOpenJam,
                onOpenRadio = onOpenRadio,
                modifier = Modifier
            )
        }
        ExploreRow.MixTools -> Column(
            verticalArrangement = Arrangement.spacedBy(6.dp)
        ) {
            ExploreSectionHeader(title = strings.levyraMix, subtitle = strings.mixCreate)
            LevyraMixLauncherPanel(
                familiarity = state.mixFamiliarity,
                loading = state.mixLoading,
                accent = mixAccent,
                onFamiliarityChange = viewModel::setMixFamiliarity,
                onStartMix = { kind -> viewModel.startLevyraMix(kind) },
                onOpenYourSound = viewModel::openYourSound,
                onOpenMixLab = { viewModel.openMixLab() },
                modifier = Modifier.padding(horizontal = HomeHorizontalInset)
            )
            com.luc4n3x.levyra.ui.moodjourney.MoodJourneyEntry(
                onOpen = viewModel::openMoodJourney,
                modifier = Modifier.padding(horizontal = HomeHorizontalInset, vertical = 4.dp)
            )
        }
        is ExploreRow.Header -> ExploreAnchorHeader(
            anchor = row.anchor,
            onPlayFresh = onPlayFresh,
            onOpenMoods = onOpenMoods
        )
        ExploreRow.FreshLoading -> Box(
            modifier = Modifier.fillMaxWidth().padding(vertical = 28.dp),
            contentAlignment = Alignment.Center
        ) {
            DiscoveryLoadingIndicator(modifier = Modifier.size(40.dp), color = MaterialTheme.colorScheme.primary)
        }
        ExploreRow.FreshEmpty -> Box(modifier = Modifier.padding(horizontal = HomeHorizontalInset)) {
            EmptyState(strings.exploreEmpty)
        }
        ExploreRow.FreshScopes -> ExploreFreshScopeRail(
            scopes = fresh.scopes,
            selected = fresh.feed.scope,
            localLabel = fresh.regionLabel,
            onSelect = onSelectFreshScope
        )
        ExploreRow.FreshSpotlight -> ExploreFreshSpotlight(
            tracks = fresh.feed.spotlight,
            currentTrackId = state.currentTrack?.id,
            isPlaying = state.isPlaying,
            isResolving = state.isResolving,
            onPlay = onPlayTrack,
            onOpenAlbum = { track -> viewModel.openAlbum(trackAlbumHit(track)) },
            actions = { track -> trackActions(track) }
        )
        ExploreRow.FreshMoment -> Column(
            verticalArrangement = Arrangement.spacedBy(6.dp)
        ) {
            ExploreFreshMomentHeader(
                title = strings.freshMomentTitle,
                onShowAll = { onShortcut(ExploreShortcut.NewReleases) }
            )
            ExploreFreshMomentRail(
                pages = fresh.momentPages,
                currentTrackId = state.currentTrack?.id,
                isPlaying = state.isPlaying,
                isResolving = state.isResolving,
                onPlay = onPlayTrack,
                actions = { track -> trackActions(track) }
            )
        }
        is ExploreRow.MoodRail -> ExploreMoodRailRow(
            zones = row.zones,
            selectedZoneId = state.exploreZoneId,
            onOpenAll = onOpenMoods,
            onOpenZone = onOpenZone,
            onStartZoneMix = { zone ->
                viewModel.startLevyraMix(
                    kind = LevyraMixKind.Genre,
                    seedQuery = zone.query,
                    label = zone.label
                )
            }
        )
    }
}

@Composable
private fun ExploreAnchorHeader(
    anchor: ExploreAnchor,
    onPlayFresh: (() -> Unit)?,
    onOpenMoods: () -> Unit
) {
    val strings = LocalLevyraStrings.current
    when (anchor) {
        ExploreAnchor.Fresh -> ExploreFreshSectionHeader(
            title = strings.exploreFresh,
            onPlayAll = onPlayFresh
        )
        ExploreAnchor.Moods -> ExploreSectionHeader(
            title = strings.exploreMoods,
            onShowAll = onOpenMoods
        )
    }
}

@Composable
private fun ExploreMoodRailRow(
    zones: List<ExploreZone>,
    selectedZoneId: String?,
    onOpenAll: () -> Unit,
    onOpenZone: (ExploreZone) -> Unit,
    onStartZoneMix: (ExploreZone) -> Unit
) {
    val strings = LocalLevyraStrings.current
    val moodZones = remember(zones) {
        val filtered = zones.filter { it.id != ExploreCatalog.NEW_RELEASES_ZONE_ID }
        if (filtered.isNotEmpty()) filtered else zones
    }
    val rows = remember(moodZones) { moodZones.take(ExploreMoodGridLimit).chunked(2) }

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = HomeHorizontalInset),
        verticalArrangement = Arrangement.spacedBy(10.dp)
    ) {
        rows.forEach { row ->
            Row(horizontalArrangement = Arrangement.spacedBy(10.dp)) {
                row.forEach { zone ->
                    key(zone.id) {
                        val artworkUrl = rememberExploreMoodArtworkUrl(zone)
                        ExploreDiscoveryCategoryCard(
                            title = zone.label,
                            identity = zone.id,
                            artworkUrl = artworkUrl,
                            emoji = zone.emoji,
                            accentColors = if (LevyraIsNocturne) LevyraPanel to LevyraPanelSoft else Color(zone.accentStart) to Color(zone.accentEnd),
                            modifier = Modifier
                                .weight(1f)
                                .height(100.dp),
                            onLongClick = { onStartZoneMix(zone) },
                            onClick = { onOpenZone(zone) }
                        )
                    }
                }
                if (row.size == 1) {
                    ExploreDiscoveryCategoryCard(
                        title = strings.showAll,
                        identity = "all-moods",
                        emoji = "↗",
                        accentColors = Color(0xFF343C48) to Color(0xFF202632),
                        modifier = Modifier
                            .weight(1f)
                            .height(100.dp),
                        onClick = onOpenAll
                    )
                }
            }
        }
    }
}

private const val ExploreMoodGridLimit = 8

@Composable
private fun ExploreOverlays(
    state: LevyraUiState,
    viewModel: ExploreViewModel,
    strings: LevyraStrings,
    zones: List<ExploreZone>,
    samples: List<Track>,
    backEnabled: Boolean,
    liveRadioOpen: Boolean,
    addToPlaylistTarget: Track?,
    samplesStartIndex: Int?,
    exploreDestination: String?,
    exploreMoodReturn: String?,
    onAddToPlaylistTargetChange: (Track?) -> Unit,
    onSamplesStartIndexChange: (Int?) -> Unit,
    onDestinationChange: (String?) -> Unit,
    onMoodReturnChange: (String?) -> Unit,
    onLiveRadioOpenChange: (Boolean) -> Unit
) {
    val appleStyle = LevyraIsAppleMusic
    addToPlaylistTarget?.let { target ->
        AddToPlaylistDialog(
            track = target,
            playlists = state.playlists,
            onDismiss = { onAddToPlaylistTargetChange(null) },
            onAddTo = { playlistId ->
                viewModel.addToPlaylist(playlistId, target)
                onAddToPlaylistTargetChange(null)
            },
            onCreateWith = { name ->
                viewModel.createPlaylist(name, target)
                onAddToPlaylistTargetChange(null)
            }
        )
    }

    when (exploreDestination) {
        ExploreNewReleasesDestination -> ExploreNewReleasesDestinationScreen(
            releases = state.exploreNewReleases,
            isLoading = state.isNewReleasesLoading,
            strings = strings,
            backEnabled = backEnabled,
            onBack = { onDestinationChange(null) },
            onOpenRelease = viewModel::openAlbum,
            bottomInset = exploreDestinationBottomInset(state)
        )
        ExploreMoodsDestination -> ExploreMoodsDestinationScreen(
            zones = zones,
            categories = state.exploreCategories,
            categoryArtwork = state.exploreCategoryArtwork,
            isLoading = state.isExploreCategoriesLoading,
            strings = strings,
            backEnabled = backEnabled,
            onBack = { onDestinationChange(null) },
            onOpenZone = { zone ->
                viewModel.selectExploreZone(zone)
                onMoodReturnChange(ExploreMoodsDestination)
                onDestinationChange(exploreMoodDestination(zone.id))
            },
            onOpenCategory = { category ->
                if (!appleStyle) viewModel.selectExploreCategory(category)
                onMoodReturnChange(ExploreMoodsDestination)
                onDestinationChange(exploreCategoryDestination(category))
            },
            onRequestCategoryArtwork = viewModel::ensureExploreCategoryArtwork,
            bottomInset = exploreDestinationBottomInset(state)
        )
        else -> ExploreMoodCollectionDestination(
            destination = exploreDestination,
            returnDestination = exploreMoodReturn,
            zones = zones,
            state = state,
            strings = strings,
            viewModel = viewModel,
            onTrackActions = onAddToPlaylistTargetChange,
            backEnabled = backEnabled,
            onDestinationChange = onDestinationChange
        )
    }

    samplesStartIndex?.let { initialPage ->
            ExploreSamplesScreen(
                samples = samples,
                initialPage = initialPage,
                currentTrack = state.currentTrack,
                isPlaying = state.isPlaying,
                isResolving = state.isResolving,
                isVideoMode = state.isVideoMode,
                isLoading = state.isSamplesLoading,
                loadFailed = state.samplesLoadFailed,
                playbackError = state.playerError,
                favoriteIds = state.favoriteIds,
                strings = strings,
                backEnabled = backEnabled,
                onPlaySample = viewModel::playSample,
                onTogglePlay = viewModel::togglePlay,
                onToggleFavorite = viewModel::toggleFavorite,
                onRequestFeed = viewModel::refreshSamples,
                onDismiss = {
                    viewModel.endSamplesPlayback()
                    onSamplesStartIndexChange(null)
                }
            )
        }

    if (liveRadioOpen) {
        LiveRadioScreen(
            languageCode = state.languageCode,
            currentStationId = state.currentTrack
                ?.takeIf { it.isLiveRadio() }
                ?.id
                ?.removePrefix("live-radio:"),
            isPlaying = state.isPlaying,
            backEnabled = backEnabled,
            onBack = { onLiveRadioOpenChange(false) },
            onPlay = viewModel::playLiveRadio
        )
    }
}

@Composable
private fun ExploreMoodCollectionDestination(
    destination: String?,
    returnDestination: String?,
    zones: List<ExploreZone>,
    state: LevyraUiState,
    strings: LevyraStrings,
    viewModel: ExploreViewModel,
    onTrackActions: (Track) -> Unit,
    backEnabled: Boolean,
    onDestinationChange: (String?) -> Unit
) {
    val providerCategory = exploreCategoryDestinationValue(destination)
    if (providerCategory != null) {
        val activeCategory = state.exploreCategories
            .firstOrNull { category -> category.params == providerCategory.params }
            ?: providerCategory
        val categoryTracks: @Composable () -> Unit = {
            val isActive = state.exploreCategoryParams == providerCategory.params
            val tracks = if (isActive) state.exploreTracks else emptyList()
            LaunchedEffect(providerCategory.params, state.languageCode, isActive) {
                if (!isActive) viewModel.selectExploreCategory(activeCategory)
            }
            ExploreCollectionDestinationScreen(
                identity = providerCategory.params,
                title = activeCategory.title,
                subtitle = activeCategory.section.ifBlank { strings.exploreMoods },
                zone = null,
                tracks = tracks,
                isLoading = state.isExploreLoading || !isActive,
                currentTrackId = state.currentTrack?.id,
                isPlaying = state.isPlaying,
                strings = strings,
                backEnabled = backEnabled,
                onBack = { onDestinationChange(returnDestination) },
                onPlayAll = { tracks.firstOrNull()?.let { viewModel.playFrom(tracks, it) } },
                onPlayTrack = { track -> viewModel.playFrom(tracks, track) },
                onRequestTrackArtwork = viewModel::ensureExploreTrackArtwork,
                bottomInset = exploreDestinationBottomInset(state)
            )
        }
        if (LevyraIsAppleMusic) {
            AppleMusicGenreScreen(
                title = activeCategory.title,
                categoryParams = providerCategory.params,
                languageCode = state.languageCode,
                storefront = ChartsCatalog.region(state.selectedChartId).country,
                currentId = state.currentTrack?.id,
                bottomInset = exploreDestinationBottomInset(state),
                exploreViewModel = viewModel,
                onTrackActions = onTrackActions,
                onOpenPlaylist = viewModel::openPlaylistHit,
                backEnabled = backEnabled,
                onBack = { onDestinationChange(returnDestination) },
                fallback = categoryTracks
            )
        } else if (LevyraIsSpotify) {
            SpotifyGenreScreen(
                title = activeCategory.title,
                params = providerCategory.params,
                languageCode = state.languageCode,
                bottomInset = exploreDestinationBottomInset(state),
                backEnabled = backEnabled,
                onBack = { onDestinationChange(returnDestination) },
                onOpenPlaylist = viewModel::openPlaylistHit,
                fallback = categoryTracks
            )
        } else if (LevyraIsYouTubeMusic) {
            YouTubeMusicGenreScreen(
                title = activeCategory.title,
                params = providerCategory.params,
                languageCode = state.languageCode,
                bottomInset = exploreDestinationBottomInset(state),
                backEnabled = backEnabled,
                onBack = { onDestinationChange(returnDestination) },
                onSearch = viewModel::openSearch,
                onOpenPlaylist = viewModel::openPlaylistHit,
                fallback = categoryTracks
            )
        } else {
            categoryTracks()
        }
        return
    }

    val zoneId = exploreMoodDestinationId(destination) ?: return
    val zone = zones.firstOrNull { candidate -> candidate.id == zoneId } ?: return
    val isActive = state.exploreZoneId == zone.id
    val tracks = if (isActive) state.exploreTracks else emptyList()
    LaunchedEffect(zone.id, state.languageCode, isActive) {
        if (!isActive) viewModel.selectExploreZone(zone)
    }
    ExploreCollectionDestinationScreen(
        identity = zone.id,
        title = zone.label,
        subtitle = strings.exploreMoods,
        zone = zone,
        tracks = tracks,
        isLoading = state.isExploreLoading || !isActive,
        currentTrackId = state.currentTrack?.id,
        isPlaying = state.isPlaying,
        strings = strings,
        backEnabled = backEnabled,
        onBack = { onDestinationChange(returnDestination) },
        onPlayAll = { tracks.firstOrNull()?.let { viewModel.playFrom(tracks, it) } },
        onPlayTrack = { track -> viewModel.playFrom(tracks, track) },
        onRequestTrackArtwork = viewModel::ensureExploreTrackArtwork,
        bottomInset = exploreDestinationBottomInset(state)
    )
}

@Composable
internal fun exploreDestinationBottomInset(state: LevyraUiState): Dp = tabBarBottomContentInset(
    miniPlayerVisible = state.currentTrack != null,
    animationsEnabled = state.animationsEnabled
)

@Composable
private fun ExploreFreshSectionHeader(
    title: String,
    onPlayAll: (() -> Unit)?
) {
    LevyraSectionHeader(
        title = remember(title) { cleanHomeSectionTitle(title) },
        titleColor = MaterialTheme.colorScheme.onSurface,
        modifier = Modifier.padding(horizontal = HomeHorizontalInset, vertical = 2.dp)
    ) {
        onPlayAll?.let { action -> LevyraSectionPlayAll(onClick = action) }
    }
}

@Composable
private fun ExploreSectionHeader(
    title: String,
    subtitle: String? = null,
    onPlayAll: (() -> Unit)? = null,
    onShowAll: (() -> Unit)? = null
) {
    HomeSectionHeader(
        title = title,
        subtitle = subtitle,
        onPlayAll = onPlayAll,
        onShowAll = onShowAll,
        modifier = Modifier.padding(horizontal = HomeHorizontalInset, vertical = 6.dp)
    )
}

@Composable
private fun ExplorePageHeader(
    title: String,
    subtitle: String,
    modifier: Modifier = Modifier
) {
    if (LevyraIsPrism) {
        Box(modifier) { PrismPageHeader(title, subtitle) }
        return
    }
    val colors = MaterialTheme.colorScheme
    Column(
        modifier = modifier.fillMaxWidth(),
        verticalArrangement = Arrangement.spacedBy(6.dp)
    ) {
        Text(
            text = title,
            color = colors.onSurface,
            style = LevyraType.heroTitle,
            modifier = Modifier.semantics { heading() }
        )
        Text(
            text = subtitle,
            color = colors.onSurfaceVariant,
            style = LevyraType.metadata,
            maxLines = 2,
            overflow = TextOverflow.Ellipsis
        )
    }
}

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
internal fun ExplorePrimaryShortcuts(
    availableAnchors: Set<ExploreAnchor>,
    onSelect: (ExploreShortcut) -> Unit,
    onOpenJam: () -> Unit,
    onOpenRadio: () -> Unit,
    modifier: Modifier = Modifier
) {
    val strings = LocalLevyraStrings.current
    val radioStrings = com.luc4n3x.levyra.ui.i18n.LevyraLiveRadioCatalog.forCode(strings.code)
    val colors = MaterialTheme.colorScheme
    val entries = buildList {
        if (ExploreAnchor.Fresh in availableAnchors) {
            add(ExploreShortcutEntry("releases", Icons.Rounded.AutoAwesome, strings.exploreNewReleases, MaterialShapes.Sunny, colors.primaryContainer, colors.onPrimaryContainer) { onSelect(ExploreShortcut.NewReleases) })
        }
        add(ExploreShortcutEntry("samples", Icons.Rounded.PlayArrow, strings.exploreSamples, MaterialShapes.Cookie4Sided, colors.tertiaryContainer, colors.onTertiaryContainer) { onSelect(ExploreShortcut.Samples) })
        if (ExploreAnchor.Moods in availableAnchors) {
            add(ExploreShortcutEntry("moods", Icons.Rounded.Mood, strings.exploreMoods, MaterialShapes.Clover4Leaf, colors.secondaryContainer, colors.onSecondaryContainer) { onSelect(ExploreShortcut.Moods) })
        }
        add(ExploreShortcutEntry("radio", Icons.Rounded.Radio, radioStrings.title, MaterialShapes.SoftBurst, colors.errorContainer, colors.onErrorContainer, onOpenRadio))
        add(ExploreShortcutEntry("jam", Icons.Rounded.PersonAdd, strings.jamTitle, MaterialShapes.Cookie9Sided, colors.inversePrimary, colors.onPrimaryContainer, onOpenJam))
    }
    Column(
        modifier = modifier
            .fillMaxWidth()
            .padding(horizontal = HomeHorizontalInset),
        verticalArrangement = Arrangement.spacedBy(if (LevyraIsAppleMusic) 0.dp else 10.dp)
    ) {
        entries.chunked(if (LevyraIsAppleMusic) 1 else if (LevyraIsYouTubeMusic) 3 else 2).forEach { pair ->
            Row(horizontalArrangement = Arrangement.spacedBy(if (LevyraIsYouTubeMusic) 16.dp else 10.dp)) {
                pair.forEach { entry ->
                    key(entry.key) {
                        ExploreShortcutTile(entry = entry, modifier = Modifier.weight(1f))
                    }
                }
                if (LevyraIsYouTubeMusic) {
                    repeat(3 - pair.size) { Spacer(modifier = Modifier.weight(1f)) }
                } else if (pair.size == 1 && !LevyraIsAppleMusic) {
                    Spacer(modifier = Modifier.weight(1f))
                }
            }
        }
    }
}

@Immutable
private class ExploreShortcutEntry(
    val key: String,
    val icon: ImageVector,
    val label: String,
    val polygon: RoundedPolygon,
    val container: Color,
    val content: Color,
    val onClick: () -> Unit
)

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
private fun ExploreShortcutTile(
    entry: ExploreShortcutEntry,
    modifier: Modifier = Modifier
) {
    if (LevyraIsSpotify) {
        SpotifyExploreTile(entry.label, entry.icon, modifier, entry.onClick)
    } else if (LevyraIsYouTubeMusic) {
        YouTubeMusicShortcutTile(entry.label, entry.icon, entry.onClick, modifier)
    } else if (LevyraIsAppleMusic) {
        AppleMusicLinkRow(entry.label, entry.icon, modifier, entry.onClick)
    } else {
        LevyraExploreShortcutTile(entry, modifier)
    }
}

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
private fun LevyraExploreShortcutTile(
    entry: ExploreShortcutEntry,
    modifier: Modifier
) {
    val colors = MaterialTheme.colorScheme
    val animationsEnabled = LocalAnimationsEnabled.current
    val interaction = remember { MutableInteractionSource() }
    val pressed by interaction.collectIsPressedAsState()
    val rotation by animateFloatAsState(
        targetValue = if (pressed && animationsEnabled) -14f else 0f,
        animationSpec = spring(dampingRatio = Spring.DampingRatioMediumBouncy, stiffness = Spring.StiffnessMedium),
        label = "explore-shortcut-rotation"
    )
    val nocturne = LevyraIsNocturne
    val skinned = LevyraSkinManagesLayout
    val iconShape = if (skinned) SkinChrome.iconShape else entry.polygon.toShape()
    Row(
        modifier = modifier
            .heightIn(min = 68.dp)
            .clip(exploreShortcutShape())
            .background(if (skinned) LevyraPanel else lerp(colors.surfaceContainerHigh, entry.container, 0.32f))
            .levyraPressable(
                onClick = entry.onClick,
                onClickLabel = entry.label,
                role = Role.Button,
                pressedScale = LevyraPressScale.Control,
                interactionSource = interaction
            )
            .padding(start = 10.dp, end = 12.dp, top = 10.dp, bottom = 10.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        Box(
            modifier = Modifier
                .size(46.dp)
                .graphicsLayer { rotationZ = rotation }
                .clip(iconShape)
                .background(if (skinned) SkinChrome.iconBackground else entry.container),
            contentAlignment = Alignment.Center
        ) {
            Icon(
                imageVector = entry.icon,
                contentDescription = null,
                tint = if (skinned) SkinChrome.iconTint else entry.content,
                modifier = Modifier
                    .size(22.dp)
                    .graphicsLayer { rotationZ = -rotation }
            )
        }
        BasicText(
            text = entry.label,
            style = MaterialTheme.typography.titleSmall.copy(fontWeight = if (skinned) FontWeight.Medium else FontWeight.Bold, color = colors.onSurface),
            maxLines = if (nocturne) 2 else 1,
            overflow = TextOverflow.Ellipsis,
            autoSize = TextAutoSize.StepBased(minFontSize = 11.sp, maxFontSize = 14.sp),
            modifier = Modifier.weight(1f)
        )
    }
}

@Composable
private fun TrackGlassCard(
    track: Track,
    isCurrent: Boolean,
    isPlaying: Boolean,
    isFavorite: Boolean,
    onClick: () -> Unit,
    onFavorite: () -> Unit,
    onShare: () -> Unit,
    onAddToPlaylist: () -> Unit
) {
    val scale by animateFloatAsState(if (isCurrent) 1.02f else 1f, label = "scale")
    var menuExpanded by remember { mutableStateOf(false) }
    Column(
        modifier = Modifier
            .width(140.dp)
            .graphicsLayer {
                scaleX = scale
                scaleY = scale
            }
