                        }
                    )
                    DropdownMenuItem(
                        text = { Text(LocalLevyraStrings.current.addToPlaylist, color = Color.White) },
                        onClick = {
                            onAddToPlaylist()
                            menuExpanded = false
                        }
                    )
                }
