    ) {
        val shape = RoundedCornerShape(11.dp)
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .aspectRatio(16f / 9f)
                .clip(shape)
                .background(LevyraPanelSoft)
                .then(
                    if (isCurrent) {
                        Modifier.border(1.5.dp, Color.White.copy(alpha = 0.72f), shape)
                    } else {
                        Modifier
                    }
                )
        ) {
            AsyncImage(
                model = ImageRequest.Builder(LocalContext.current)
                    .data(track.largeThumbnailUrl.ifEmpty { track.thumbnailUrl })
                    .crossfade(true)
                    .build(),
                contentDescription = track.title,
                contentScale = ContentScale.Crop,
                modifier = Modifier.fillMaxSize()
            )
            Box(
                modifier = Modifier
                    .matchParentSize()
                    .background(
                        Brush.verticalGradient(
                            colorStops = arrayOf(
                                0f to Color.Transparent,
                                0.76f to Color.Transparent,
                                1f to Color.Black.copy(alpha = 0.24f)
                            )
                        )
                    )
            )
            if (isCurrent) {
                Box(
                    modifier = Modifier
                        .align(Alignment.BottomStart)
                        .padding(10.dp)
                        .size(32.dp)
                        .background(Color.Black.copy(alpha = 0.58f), CircleShape),
                    contentAlignment = Alignment.Center
                ) {
                    if (isPlaying) {
                        LevyraPlayingIndicator(
                            playing = true,
                            color = Color.White,
                            size = 16.dp,
                            contentDescription = strings.playing
                        )
                    } else {
                        Icon(
                            imageVector = Icons.Rounded.PlayArrow,
                            contentDescription = strings.play,
                            tint = Color.White,
                            modifier = Modifier.size(18.dp)
                        )
                    }
                }
            }
        }
        Text(
            text = track.title,
            color = LevyraText,
            fontSize = 14.5.sp,
            lineHeight = LevyraTypeRhythm.lineHeight(14.5.sp),
            fontWeight = FontWeight.SemiBold,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis
