        if (metadata.isNotBlank()) {
            Text(
                text = metadata,
                color = LevyraMuted,
                fontSize = 12.sp,
                lineHeight = LevyraTypeRhythm.lineHeight(12.sp),
                fontWeight = FontWeight.Normal,
                maxLines = 1,
