private fun progressOf(positionMs: Long, durationMs: Long): Float {
    if (durationMs <= 0L) return 0f
    return (positionMs.toFloat() / durationMs.toFloat()).coerceIn(0f, 1f)
}

private fun formatDuration(ms: Long): String {
    if (ms <= 0L) return "--:--"
    val totalSeconds = ms / 1000L
    val minutes = totalSeconds / 60L
    val seconds = totalSeconds % 60L
    return "$minutes:${seconds.toString().padStart(2, '0')}"
}

private fun SettingsGroupCollector.immersiveModeSettingsItems(
    interfaceSettings: LevyraInterfaceSettings,
    strings: LevyraStrings,
    onInterfaceSettings: (LevyraInterfaceSettings) -> Unit
) {
    val immersive = interfaceSettings.immersive
    fun update(value: LevyraImmersiveSettings) = onInterfaceSettings(interfaceSettings.copy(immersive = value))
    standaloneItem { SettingsSectionLabel(strings.immersiveSection) }
    item {
        SettingsToggle(
            icon = Icons.Rounded.VerticalAlignTop,
            title = strings.immersiveHideStatusBar,
            subtitle = strings.immersiveHideStatusBarSubtitle,
            checked = immersive.statusBarHidden,
            onCheckedChange = { hidden ->
                update(
                    immersive.copy(
                        hideStatusBar = hidden,
                        hideNavigationBar = immersive.navigationBarHidden,
                        fullImmersive = hidden && immersive.fullImmersive
                    )
                )
            }
        )
    }
    item {
        SettingsToggle(
            icon = Icons.Rounded.VerticalAlignBottom,
            title = strings.immersiveHideNavigationBar,
            subtitle = strings.immersiveHideNavigationBarSubtitle,
            checked = immersive.navigationBarHidden,
            onCheckedChange = { hidden ->
                update(
                    immersive.copy(
                        hideStatusBar = immersive.statusBarHidden,
                        hideNavigationBar = hidden,
                        fullImmersive = hidden && immersive.fullImmersive
                    )
                )
            }
        )
    }
    item {
        SettingsToggle(
            icon = Icons.Rounded.Fullscreen,
            title = strings.immersiveFull,
            subtitle = strings.immersiveFullSubtitle,
            checked = immersive.fullImmersive,
            onCheckedChange = { full ->
                update(
                    if (full) {
                        immersive.copy(fullImmersive = true)
                    } else {
                        immersive.copy(fullImmersive = false, hideStatusBar = false, hideNavigationBar = false)
                    }
                )
            }
        )
    }
    item {
        SettingsToggle(
            icon = Icons.Rounded.Apps,
            title = strings.immersiveEverywhere,
            subtitle = strings.immersiveEverywhereSubtitle,
            checked = immersive.everywhere,
            onCheckedChange = { update(immersive.copy(everywhere = it)) }
        )
    }
}

private fun LazyListScope.skinSettingsItems(
    skin: LevyraSkin,
    defaults: LazyListScope.() -> Unit,
    nocturne: LazyListScope.() -> Unit = {}
) {
    if (skin == LevyraSkin.Default) defaults() else nocturne()
}

private fun skinHomeStyleLabel(style: HomeStyle): String =
    if (LevyraSkinManagesLayout) LevyraSkinLabel else homeStyleName(style)

private fun skinManagesStudio(id: String): Boolean =
    LevyraSkinManagesLayout && id in setOf("theme", "mini_player", "navigation")





@Composable
private fun SettingsHubHeader(onClose: () -> Unit) {
    if (LevyraIsQobuz) return QobuzSettingsHeader(onClose)
    if (LevyraIsAtelier) return AtelierSettingsHeader(onClose)
    val strings = LocalLevyraStrings.current
    if (SkinChrome.active) PrismPageHeader(strings.settings, strings.settingsSubtitle) {
        IconButton(onClick = onClose, modifier = Modifier.size(48.dp)) { Icon(Icons.Rounded.Close, strings.close, tint = LevyraText) }
    } else Row(
        modifier = Modifier.fillMaxWidth(),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.SpaceBetween
    ) {
        Column {
            Text(strings.settings, color = LevyraText, fontSize = 28.sp, fontWeight = FontWeight.Black)
            Text(strings.settingsSubtitle, color = LevyraMuted, fontSize = 13.sp, fontWeight = FontWeight.SemiBold)
        }
        CircleIconButton(
            icon = Icons.Rounded.Close,
            tint = LevyraText,
            background = Color.White.copy(alpha = 0.08f),
            onClick = onClose,
            contentDescription = strings.close
        )
    }
}

@Composable
private fun SettingsSkinSelection(interfaceSettings: LevyraInterfaceSettings, onInterfaceSettings: (LevyraInterfaceSettings) -> Unit) {
    SkinSelector(
        selected = interfaceSettings.skin,
        onSelect = { onInterfaceSettings(interfaceSettings.copy(skin = it)) }
    )
    if (interfaceSettings.skin == LevyraSkin.Prism) {
        PrismSettingsPanel(interfaceSettings.prism) { onInterfaceSettings(interfaceSettings.copy(prism = it)) }
    }
    if (interfaceSettings.skin == LevyraSkin.Torque) {
        TorqueSettingsPanel(interfaceSettings.torque) { onInterfaceSettings(interfaceSettings.copy(torque = it)) }
    }
    if (interfaceSettings.skin == LevyraSkin.Ivory) {
        IvorySettingsPanel(interfaceSettings.ivory) { onInterfaceSettings(interfaceSettings.copy(ivory = it)) }
    }
}

@Composable
private fun settingsTileShape(interactionSource: MutableInteractionSource, first: Boolean, last: Boolean): Shape {
    val outer = if (SkinChrome.active) SkinChrome.outerCorner else levyraExpressiveCorner(interactionSource, rest = 24.dp, pressed = 14.dp, label = "settingsTileOuter")
    val inner = if (SkinChrome.active) SkinChrome.innerCorner else levyraExpressiveCorner(interactionSource, rest = 6.dp, pressed = 14.dp, label = "settingsTileInner")
    return RoundedCornerShape(
        topStart = if (first) outer else inner,
        topEnd = if (first) outer else inner,
        bottomEnd = if (last) outer else inner,
        bottomStart = if (last) outer else inner
    )
}

private fun settingsChoiceContainer(active: Boolean): Color =
    if (SkinChrome.active) {
        if (active) SkinChrome.chipSelectedContainer else Color.Transparent
    } else if (active) LevyraCyan else Color.White.copy(alpha = 0.06f)

private fun settingsChoiceContent(active: Boolean): Color =
    if (SkinChrome.active) {
        if (active) SkinChrome.chipSelectedContent else LevyraText
    } else if (active) LevyraBlack else LevyraText

private fun exploreShortcutShape(): Shape = when {
    LevyraIsPrism -> PrismDesign.cut(PrismDesign.surfaceCorner)
    LevyraIsNocturne -> RoundedCornerShape(Nocturne78Design.cardCorner)
    else -> RoundedCornerShape(22.dp)
}

private fun artistPlayBackground(playContainer: Color, playShape: Shape): Modifier =
    when {
        LevyraIsPrism -> Modifier.clip(CircleShape).background(PrismAccent.gradient())
        LevyraIsNocturne -> Modifier.clip(RoundedCornerShape(Nocturne78Design.controlCorner)).background(LevyraPanelSoft)
            .border(1.dp, LevyraCyan, RoundedCornerShape(Nocturne78Design.controlCorner))
        else -> Modifier.background(playContainer, playShape)
    }

private fun albumTrackDownloadStatus(presentation: AlbumTrackRowPresentation, strings: LevyraStrings): String =
    if (presentation.isDownloading && !presentation.isDownloaded) {
        strings.formatDownloadProgress(presentation.downloadProgress ?: 1)
    } else {
        ""
    }

private fun albumTrackSubtitle(artist: String, status: String): String =
    listOf(artist, status).filter { it.isNotBlank() }.joinToString(" · ")

private fun albumTrackDuration(track: Track, spotify: Boolean): String =
    if (spotify) "" else formatDuration(track.durationMs).takeIf { it != "--:--" }.orEmpty()

private fun albumTrackRowBackground(presentation: AlbumTrackRowPresentation, stage: AlbumStageColors, spotify: Boolean): Color = when {
    presentation.selected -> stage.accent.copy(alpha = 0.26f)
    spotify -> Color.Transparent
    presentation.isCurrent -> stage.accent.copy(alpha = 0.16f)
    else -> stage.content.copy(alpha = 0.055f)
}

private fun albumTrackShowsArtist(trackArtist: String, albumArtist: String, spotify: Boolean): Boolean =
    trackArtist.isNotBlank() && (spotify || !trackArtist.trim().equals(albumArtist.trim(), ignoreCase = true))

@Composable
internal fun artistHeroNameSpacing(): TextUnit = when {
    LevyraIsTorque -> 2.sp
    LevyraIsSpotify -> (-1.4).sp
    else -> LevyraType.heroTitle.letterSpacing
}

private fun artistShuffleBackground(highlight: Color): Color = when {
    LevyraIsSpotify -> Color.Transparent
    LevyraSkinManagesLayout -> LevyraPanel
    else -> highlight.copy(alpha = 0.22f)
}

private fun artistShuffleTint(): Color = if (LevyraIsSpotify) SpotifyDesign.subdued else LevyraText

private fun artistShuffleIconSize(): Dp = if (LevyraIsSpotify) 28.dp else 22.dp

private fun artistPlaySize(): Dp = if (LevyraIsSpotify) SpotifyDesign.playButton else 62.dp

private fun searchSectionTitleWeight(): FontWeight = when {
    LevyraIsTorque || LevyraIsSpotify -> FontWeight.Bold
    LevyraIsIvory -> FontWeight.SemiBold
    LevyraSkinManagesLayout -> FontWeight.Normal
    else -> FontWeight.Black
}

private fun searchSectionTitleSpacing(): TextUnit = when {
    LevyraIsTorque || LevyraIsNocturne -> 1.8.sp
    LevyraIsIvory -> 0.2.sp
    LevyraIsSpotify -> (-0.4).sp
    else -> (-0.3).sp
}

private fun artistPlayContent(fallback: Color): Color = when {
    LevyraIsSpotify || LevyraIsYouTubeMusic -> Color.Black
    LevyraIsPrism -> Color.White
    LevyraIsNocturne -> LevyraCyan
    else -> fallback
}

private fun artistBiographyBackground(accentBrush: Brush): Modifier =
    Modifier.clip(if (LevyraSkinManagesLayout) RoundedCornerShape(SkinChrome.outerCorner) else ArtistBiographyShape)
        .background(LevyraPanel)
        .then(if (LevyraSkinManagesLayout) Modifier else Modifier.background(accentBrush))

private fun LazyListScope.studioHomeFilteredSections(c: StudioHomeContext, flowShortcutTracks: List<Track>, statusBarTop: Dp, homeTopPadding: Dp, spotifyFilter: SpotifyHomeFilter, shownOrder: List<HomeSectionId>, youtubeMusicHome: com.luc4n3x.levyra.ui.youtubemusic.YoutubeMusicHomeShelfUi?, homeRadio: HomeRadioState, homeDiscovery: DiscoveryHomeHandle?, spotify: Boolean) {
    if (spotify && spotifyFilter in setOf(SpotifyHomeFilter.Music, SpotifyHomeFilter.Following, SpotifyHomeFilter.Podcasts)) {
        spotifyHomeFilterItems(spotifyFilter, c.state, c.homeAlbums, c.newReleases?.tracks.orEmpty(), c.viewModel, c.onTrackActions)
        return
    }
    studioHomeHeaderItems(c, flowShortcutTracks, statusBarTop, homeTopPadding, spotifyFilter.accepts(HomeSectionId.Spotlight))
    if (c.stagedSpotlight != null && !c.studioLayout.isHidden(HomeSectionId.Discovery) &&
        (!spotify || spotifyFilter.accepts(HomeSectionId.Discovery))
    ) {
        discoverySection(homeDiscovery, c.homeStyle, c.styleSpec, c.homeAnimationsEnabled)
    }
    studioHomeSections(c, shownOrder, youtubeMusicHome, homeRadio, homeDiscovery)
}
